import type { BeatClock } from '../../clock/index.ts';
import type { CardiacPhase } from '../../engine/index.ts';

/**
 * The beat scrubber (SPEC §4/§6) — the shared through-line control that DEBUTS in
 * Act III. A CIRCULAR dial: one full turn is one heartbeat, so the reader can grab
 * the handle and spin it continuously round and round, beat after beat. The five
 * cardiac phases are drawn as coloured arcs from the engine's event timing, with
 * S1/S2 closure ticks; a plain-language caption names the phase the playhead is in.
 *
 * Direct-manipulation contract (SPEC §4): the dial never turns itself — it's a
 * handle on the clock, not a transport. Nothing autoplays.
 *
 * Reusable across Act III: each consumer calls `highlight()` with its own phase and
 * `refresh()` after any re-solve (knob change) so the arcs track the engine.
 */

/**
 * ⚠️ EXPORTED, and deliberately so: §11's Wiggers ribbon paints the same five phases
 * along its flat time axis that this dial paints round its ring, and a reader who has
 * learned "orange means blood is leaving" from the dial must not meet a different
 * orange in the finale. One table, both controls.
 */
export const PHASE_ORDER: CardiacPhase[] = [
  'atrial-systole',
  'isovolumetric-contraction',
  'ejection',
  'isovolumetric-relaxation',
  'filling',
];

/** Plain 8th-grade descriptions — no clinical jargon. */
export const PHASE_LABEL: Record<CardiacPhase, string> = {
  'atrial-systole': 'Top chambers top it off',
  'isovolumetric-contraction': 'Squeeze begins, all doors shut',
  ejection: 'Blood pumps out',
  'isovolumetric-relaxation': 'Relaxing, all doors shut',
  filling: 'Ventricle fills with blood',
};

export const PHASE_COLOR: Record<CardiacPhase, string> = {
  'atrial-systole': '#5b9bd5',
  'isovolumetric-contraction': '#e23a2e',
  ejection: '#ff8a4c',
  'isovolumetric-relaxation': '#e23a2e',
  filling: '#2abfa5',
};

const preventEvent = (e: Event): void => e.preventDefault();

const SVG_NS = 'http://www.w3.org/2000/svg';
const CX = 90;
const CY = 90;
const R = 66; // arc radius
const TWO_PI = Math.PI * 2;

/** Point on the dial for a phase (0→1). 0 = top (12 o'clock), increasing clockwise. */
function pointAt(phase: number, r: number): [number, number] {
  const a = phase * TWO_PI;
  return [CX + r * Math.sin(a), CY - r * Math.cos(a)];
}

/** SVG arc path from phase a→b (clockwise) at radius r. */
function arcPath(a: number, b: number, r: number): string {
  const [x0, y0] = pointAt(a, r);
  const [x1, y1] = pointAt(b, r);
  const large = b - a > 0.5 ? 1 : 0;
  return `M ${x0.toFixed(2)} ${y0.toFixed(2)} A ${r} ${r} 0 ${large} 1 ${x1.toFixed(2)} ${y1.toFixed(2)}`;
}

export class BeatScrubber {
  private readonly clock: BeatClock;
  private readonly root: HTMLDivElement;
  private readonly caption: HTMLDivElement;
  private readonly svg: SVGSVGElement;
  private readonly arcs = new Map<CardiacPhase, SVGPathElement>();
  private readonly ticks: { el: SVGLineElement; phase: () => number }[] = [];
  private readonly handle: SVGGElement;

  private unsub: (() => void) | null = null;
  private highlighted: CardiacPhase[] = [];
  private dragging = false;
  private pointerId: number | null = null;
  private visible = false;

  private readonly onDown: (e: PointerEvent) => void;
  private readonly onMove: (e: PointerEvent) => void;
  private readonly onUp: (e: PointerEvent) => void;

  constructor(clock: BeatClock) {
    this.clock = clock;

    this.root = document.createElement('div');
    this.root.className = 'beat-scrubber';

    this.caption = document.createElement('div');
    this.caption.className = 'beat-scrubber-caption';

    this.svg = document.createElementNS(SVG_NS, 'svg') as SVGSVGElement;
    this.svg.setAttribute('viewBox', '0 0 180 180');
    this.svg.setAttribute('class', 'beat-scrubber-dial');

    // Faint full-circle track.
    const track = document.createElementNS(SVG_NS, 'circle');
    track.setAttribute('cx', String(CX));
    track.setAttribute('cy', String(CY));
    track.setAttribute('r', String(R));
    track.setAttribute('class', 'beat-scrubber-track');
    this.svg.appendChild(track);

    // One coloured arc per phase.
    for (const phase of PHASE_ORDER) {
      const arc = document.createElementNS(SVG_NS, 'path');
      arc.setAttribute('class', 'beat-scrubber-arc');
      arc.setAttribute('stroke', PHASE_COLOR[phase]);
      this.arcs.set(phase, arc);
      this.svg.appendChild(arc);
    }

    // S1 / S2 closure ticks.
    for (const _ of [0, 1]) {
      const line = document.createElementNS(SVG_NS, 'line');
      line.setAttribute('class', 'beat-scrubber-tick');
      this.svg.appendChild(line);
    }
    this.ticks.push({ el: this.svg.querySelectorAll('.beat-scrubber-tick')[0] as SVGLineElement, phase: () => this.clock.getEvents().s1Phase });
    this.ticks.push({ el: this.svg.querySelectorAll('.beat-scrubber-tick')[1] as SVGLineElement, phase: () => this.clock.getEvents().s2Phase });

    // A wide INVISIBLE grab ring over the arcs. The painted arcs are only ~9 units
    // thick, which is a mean target; this gives the ring a generous band to grab
    // without changing the look. Drawn before the handle so the handle stays on top.
    const grab = document.createElementNS(SVG_NS, 'circle');
    grab.setAttribute('cx', String(CX));
    grab.setAttribute('cy', String(CY));
    grab.setAttribute('r', String(R));
    grab.setAttribute('class', 'beat-scrubber-grab');
    this.svg.appendChild(grab);

    // The draggable handle: a glowing knob that orbits the ring.
    this.handle = document.createElementNS(SVG_NS, 'g') as SVGGElement;
    this.handle.setAttribute('class', 'beat-scrubber-handle');
    const halo = document.createElementNS(SVG_NS, 'circle');
    halo.setAttribute('r', '11'); halo.setAttribute('class', 'beat-scrubber-handle-halo');
    const knob = document.createElementNS(SVG_NS, 'circle');
    knob.setAttribute('r', '7'); knob.setAttribute('class', 'beat-scrubber-handle-knob');
    this.handle.append(halo, knob);
    this.svg.appendChild(this.handle);

    this.root.append(this.caption, this.svg);
    document.body.appendChild(this.root);

    // Drag anywhere on the dial → scrub to the pointer's angle. Because the control is
    // a circle, dragging round and round spins through beat after beat continuously.
    //
    // `preventDefault()` on pointerdown is what stops the browser starting a native
    // text-selection drag — without it, dragging the dial smears a selection across the
    // caption and the section copy. `touch-action:none` (CSS) stops it panning the page.
    this.onDown = (e) => {
      if (e.button !== undefined && e.button !== 0) return; // left button / touch only
      this.dragging = true;
      this.pointerId = e.pointerId;
      // Capture keeps the drag alive when the pointer leaves the small dial; the window
      // listeners below are the fallback for when capture isn't available.
      try { this.svg.setPointerCapture(e.pointerId); } catch { /* capture optional */ }
      this.svg.classList.add('is-dragging');
      this.scrubTo(e);
      e.preventDefault();
      e.stopPropagation();
    };
    this.onMove = (e) => {
      if (!this.dragging || (this.pointerId !== null && e.pointerId !== this.pointerId)) return;
      this.scrubTo(e);
      e.preventDefault();
      e.stopPropagation();
    };
    this.onUp = (e) => {
      if (!this.dragging) return;
      this.dragging = false;
      this.pointerId = null;
      this.svg.classList.remove('is-dragging');
      try { this.svg.releasePointerCapture(e.pointerId); } catch { /* already released */ }
    };
    this.svg.addEventListener('pointerdown', this.onDown);
    // Move/up on the WINDOW, not the dial: the dial is only ~150px across, and a spin
    // gesture routinely travels outside it. Bound here the drag survives regardless of
    // whether pointer capture took.
    window.addEventListener('pointermove', this.onMove, { passive: false });
    window.addEventListener('pointerup', this.onUp);
    window.addEventListener('pointercancel', this.onUp);
    // A drag that started on the dial should never leave a stray selection behind.
    this.svg.addEventListener('dragstart', preventEvent);
    this.svg.addEventListener('selectstart', preventEvent);

    this.refresh();
  }

  /**
   * Pointer angle → phase (0 at top, clockwise), driving the clock.
   *
   * Near the centre the angle is meaningless — a pixel of movement swings it wildly —
   * so inside a dead zone we hold the last phase instead of letting the beat snap
   * around. That is the difference between a dial that feels solid and one that feels
   * broken when your finger crosses the middle.
   */
  private scrubTo(e: PointerEvent): void {
    const rect = this.svg.getBoundingClientRect();
    const dx = e.clientX - (rect.left + rect.width / 2);
    const dy = e.clientY - (rect.top + rect.height / 2);
    const deadZone = rect.width * 0.16;
    if (Math.hypot(dx, dy) < deadZone) return;
    let a = Math.atan2(dx, -dy); // 0 = up, clockwise
    if (a < 0) a += TWO_PI;
    this.clock.setPhase(a / TWO_PI);
  }

  /** Re-read the engine's event timing and lay out arcs + ticks. */
  refresh(): void {
    const starts = this.clock.getEvents().phaseStart;
    PHASE_ORDER.forEach((phase, i) => {
      const start = starts[phase];
      const end = i < PHASE_ORDER.length - 1 ? starts[PHASE_ORDER[i + 1]!] : 1;
      // A hair of inset between arcs so the phase boundaries read as distinct.
      this.arcs.get(phase)!.setAttribute('d', arcPath(start + 0.004, Math.max(start + 0.004, end - 0.004), R));
    });
    for (const tick of this.ticks) {
      const [xi, yi] = pointAt(tick.phase(), R - 9);
      const [xo, yo] = pointAt(tick.phase(), R + 9);
      tick.el.setAttribute('x1', xi.toFixed(2)); tick.el.setAttribute('y1', yi.toFixed(2));
      tick.el.setAttribute('x2', xo.toFixed(2)); tick.el.setAttribute('y2', yo.toFixed(2));
    }
    this.syncHandle(this.clock.getPhase());
  }

  /** Emphasize one or more phase bands as the current section's territory (e.g. the
   *  merged "sealed ventricle" view lights BOTH isovolumetric bands). */
  highlight(phase: CardiacPhase | CardiacPhase[] | null): void {
    for (const p of this.highlighted) this.arcs.get(p)?.classList.remove('is-current');
    this.highlighted = phase == null ? [] : Array.isArray(phase) ? phase : [phase];
    for (const p of this.highlighted) this.arcs.get(p)?.classList.add('is-current');
  }

  private syncHandle(phase: number): void {
    const [x, y] = pointAt(phase, R);
    this.handle.setAttribute('transform', `translate(${x.toFixed(2)} ${y.toFixed(2)})`);
    const here = this.clock.sample().phase;
    this.caption.innerHTML =
      `<span class="beat-scrubber-phase">${PHASE_LABEL[here]}</span>` +
      `<span class="beat-scrubber-pct">${Math.round(phase * 100)}%</span>`;
  }

  show(): void {
    if (this.visible) return;
    this.visible = true;
    this.root.classList.add('is-visible');
    this.unsub = this.clock.subscribe((phase) => this.syncHandle(phase));
  }

  hide(): void {
    if (!this.visible) return;
    this.visible = false;
    this.root.classList.remove('is-visible');
    this.unsub?.();
    this.unsub = null;
    this.dragging = false;
  }

  dispose(): void {
    this.hide();
    this.svg.removeEventListener('pointerdown', this.onDown);
    window.removeEventListener('pointermove', this.onMove);
    window.removeEventListener('pointerup', this.onUp);
    window.removeEventListener('pointercancel', this.onUp);
    this.svg.removeEventListener('dragstart', preventEvent);
    this.svg.removeEventListener('selectstart', preventEvent);
    this.root.remove();
  }
}
