import * as THREE from 'three';
import type { HeartScene } from '../index.ts';

/**
 * A closure marker (SPEC §6 — the S1 "lub" / S2 "dub" heart-sound markers, shown
 * NOT heard). A soft glow sits on the valve plane; it lifts gently while its phase
 * window is active and blooms in a one-shot flash the instant the scrub crosses
 * closure, with a small plain caption ("S1 · lub — the valves meeting").
 *
 * The point it makes: the "sound" is the leaflets MEETING, not the muscle squeezing
 * — the misconception §7 kills. It's a calm bloom of light on the doors, not a
 * targeting reticle. Reusable: §9 drops one at the aortic valve for S2.
 *
 * Add `group` to the scene; call `update(dt)` each frame, `setActive()` to hold it
 * lit across a window, `firePulse()` at the closure instant.
 */
export interface ClosureMarkerOptions {
  /** Big label, e.g. "S1 · lub". */
  label: string;
  /** Small under-line, e.g. "the valves meeting". */
  sublabel: string;
  /** Glow radius in world units. */
  radius?: number;
  /** Accent colour (CSS/three string). */
  color?: string;
  /**
   * Where the text card sits.
   *
   * `'fixed'` (the default) parks it in a fixed slot below the text panel, clear of the
   * anatomy entirely. `'anchor'` pins it to the valve, projected each frame.
   *
   * Anchoring to the valve was the original behaviour and it read as clutter: a bright
   * bordered card landing right on top of the heart, competing with the very structure
   * it was labelling. The glow still marks the valve — that is the marker's actual job —
   * and the words no longer fight it for the same pixels.
   */
  caption?: 'fixed' | 'anchor';
}

const PULSE_SECONDS = 0.85;

/** Soft radial glow sprite texture (white; tinted by material colour). */
function glowTexture(): THREE.Texture {
  const S = 128;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = S;
  const ctx = canvas.getContext('2d')!;
  const g = ctx.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.25, 'rgba(255,255,255,0.55)');
  g.addColorStop(0.7, 'rgba(255,255,255,0.12)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, S, S);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

export class ClosureMarker {
  readonly group = new THREE.Group();

  private readonly scene: HeartScene;
  private readonly anchor: THREE.Vector3;
  private readonly glow: THREE.Sprite;   // steady lit-while-sealed glow
  private readonly flash: THREE.Sprite;  // one-shot bloom at the closure instant
  private readonly glowMat: THREE.SpriteMaterial;
  private readonly flashMat: THREE.SpriteMaterial;
  private readonly caption: HTMLDivElement;
  private readonly projected = new THREE.Vector3();
  private readonly radius: number;
  private readonly tex: THREE.Texture;
  private readonly captionFixed: boolean;

  private active = false;
  private pulseT = -1; // < 0 = idle
  private visible = false;

  constructor(scene: HeartScene, anchor: THREE.Vector3, opts: ClosureMarkerOptions) {
    this.scene = scene;
    this.anchor = anchor.clone();
    this.radius = opts.radius ?? 0.55;
    const color = new THREE.Color(opts.color ?? '#ff5a4d');
    this.tex = glowTexture();

    this.glowMat = new THREE.SpriteMaterial({
      map: this.tex, color, transparent: true, opacity: 0, depthWrite: false,
      depthTest: false, blending: THREE.AdditiveBlending, toneMapped: false,
    });
    this.flashMat = new THREE.SpriteMaterial({
      map: this.tex, color, transparent: true, opacity: 0, depthWrite: false,
      depthTest: false, blending: THREE.AdditiveBlending, toneMapped: false,
    });
    this.glow = new THREE.Sprite(this.glowMat);
    this.flash = new THREE.Sprite(this.flashMat);
    this.glow.scale.setScalar(this.radius * 2);
    this.flash.scale.setScalar(this.radius * 2);
    this.glow.renderOrder = 7;
    this.flash.renderOrder = 8;
    this.group.add(this.glow, this.flash);
    this.group.position.copy(this.anchor);
    this.group.visible = false;

    this.captionFixed = (opts.caption ?? 'fixed') === 'fixed';
    this.caption = document.createElement('div');
    this.caption.className = this.captionFixed
      ? 'closure-marker closure-marker--fixed'
      : 'closure-marker';
    this.caption.style.setProperty('--closure-accent', opts.color ?? '#ff5a4d');
    const big = document.createElement('div');
    big.className = 'closure-marker-label';
    big.textContent = opts.label;
    const small = document.createElement('div');
    small.className = 'closure-marker-sub';
    small.textContent = opts.sublabel;
    this.caption.append(big, small);
    this.caption.style.display = 'none';
    document.body.appendChild(this.caption);
  }

  /** Light (active) vs dark (idle) — a section holds this true across its phase. */
  setActive(on: boolean): void {
    this.active = on;
  }

  /** One-shot bloom (call at the closure instant). */
  firePulse(): void {
    this.pulseT = 0;
  }

  /** Ease the glow, advance the flash, place the caption. Once per frame. */
  update(dt: number): void {
    if (!this.visible) return;

    // Steady glow eases toward its active/idle target so nothing pops. Kept gentle so
    // it's a soft halo on the valves, never a white-hot blowout over the cavity.
    const target = this.active ? 0.45 : 0.0;
    this.glowMat.opacity += (target - this.glowMat.opacity) * Math.min(1, dt * 6);
    const gs = (this.active ? 1 : 0.8) * this.radius * 2;
    const cur = this.glow.scale.x + (gs - this.glow.scale.x) * Math.min(1, dt * 6);
    this.glow.scale.setScalar(cur);

    // One-shot flash: a quick bright bloom that expands and fades.
    if (this.pulseT >= 0) {
      this.pulseT += dt;
      const t = this.pulseT / PULSE_SECONDS;
      if (t >= 1) {
        this.pulseT = -1;
        this.flashMat.opacity = 0;
      } else {
        const ease = 1 - (1 - t) * (1 - t);
        this.flash.scale.setScalar(this.radius * 2 * (1 + ease * 1.8));
        this.flashMat.opacity = 0.95 * (1 - t);
      }
    }

    // The card. In fixed mode CSS owns its position entirely, so all that's left is
    // whether it shows — and it does NOT get hidden by the anchor being behind the
    // camera, since it isn't on the anatomy any more.
    if (this.captionFixed) {
      this.caption.style.display = this.active ? 'block' : 'none';
      return;
    }

    // Anchored mode: project the group's WORLD position rather than the raw anchor, so
    // the card still lands on the valve when the marker has been added to the rotating
    // heart frame (see heartOrientation.ts). Identical at rest.
    const cam = this.scene.camera;
    const canvas = this.scene.renderer.domElement;
    const rect = canvas.getBoundingClientRect();
    this.group.getWorldPosition(this.projected).project(cam);
    const behind = this.projected.z > 1;
    const show = this.active && !behind;
    this.caption.style.display = show ? 'block' : 'none';
    if (show) {
      this.caption.style.left = `${rect.left + (this.projected.x * 0.5 + 0.5) * rect.width}px`;
      this.caption.style.top = `${rect.top + (-this.projected.y * 0.5 + 0.5) * rect.height}px`;
    }
  }

  show(): void {
    this.visible = true;
    this.group.visible = true;
  }

  hide(): void {
    this.visible = false;
    this.group.visible = false;
    this.caption.style.display = 'none';
    this.pulseT = -1;
    this.flashMat.opacity = 0;
    this.glowMat.opacity = 0;
  }

  dispose(): void {
    this.hide();
    this.glowMat.dispose();
    this.flashMat.dispose();
    this.tex.dispose();
    this.caption.remove();
  }
}
