import * as THREE from 'three';
import type { SectionConfig, SectionContext, CameraFraming } from './types.ts';
import { scaleFraming } from './cameraFraming.ts';
import { ManometerOverlay } from '../scene/overlays/manometer.ts';
import { BeatScrubber } from '../scene/overlays/beatScrubber.ts';
import { ClosureMarker } from '../scene/overlays/closureMarker.ts';
import { VentricleLiquids, findInnerCaps } from './ventricleLiquid.ts';

/**
 * "The sealed ventricle" — the merged isovolumetric phases (SPEC §7 + §9, Act III).
 * The two emergent showcases, taught as ONE idea seen twice.
 *
 * Twice per beat the ventricle is a SEALED BOX — every valve shut, so the blood
 * volume can't change while the pressure swings hard. Once on the way UP
 * (isovolumetric contraction: it squeezes, pressure ROCKETS, the exit door flies
 * open — the doors meeting is S1 "lub") and once on the way DOWN (isovolumetric
 * relaxation: it relaxes, pressure CRASHES, the exit door slams shut behind the
 * blood that left — S2 "dub"). Same diode rule (§4), opposite directions — the two
 * vertical walls of the future P–V loop.
 *
 * Rather than two near-identical sections, this is ONE scrub-through view of the whole
 * beat: the circular scrubber lights BOTH sealed bands, both closure markers live
 * (S1 at the mitral, S2 at the aortic, each glowing only across its own sealed
 * window), and the reader meets each sealed moment in its natural place in the beat.
 * Driven PURELY by the solver on the ONE clock — the reader scrubs, nothing autoplays.
 */

/**
 * A WIDE, HELD shot — deliberately the opposite of "the doors open", which pushes in
 * tight on a single door. This section's subject is a contradiction you can only see at
 * a distance: the whole chamber sitting perfectly still while the pressure columns beside
 * it swing through their entire range. So the heart is small and calm in frame, and the
 * columns get the room.
 */
const FRAMING: CameraFraming = { position: [0.05, -0.12, 6.55], target: [0.18, -0.55, 0.06] };

/** Authored anterior-wall cutaway — opens the LV cavity so the trapped blood shows. */
const SECTION_CUTAWAY = 0.92;

/**
 * Turn the heart on its vertical axis so the reader looks INTO the cut rather than
 * flat at it. Degrees clockwise-from-above; kept identical to "the doors open" so the
 * two Act III sections hold the same attitude and scrolling between them doesn't lurch.
 */
const HEART_TURN = 20;

/**
 * WHERE TO LOOK: the frozen level ring AND the swinging columns, in one circle — because
 * the CONTRAST between them is the entire lesson. A spotlight on either half alone would
 * teach the opposite of what this section is for.
 *
 * ⚠️ `space: 'world'`, unlike most sections. The subject straddles the heart (which this
 * view turns 20°) and the manometer columns (which are world-space HUD and deliberately
 * do not turn), so a heart-space anchor would swing the circle off the columns. The pool
 * shifts by only ~0.07 under a 20° turn, which is nothing against a 1.6 radius.
 */
const FOCUS = {
  anchor: [1.35, -0.85, 0.05] as [number, number, number],
  space: 'world' as const,
  radius: 1.60,
  strength: 0.34,
  pulse: false,
};

/**
 * Three columns on the right — LA floor, LV (rockets up / crashes down), aortic ceiling.
 * THE PROTAGONIST of this section: run oversized (`COLUMN_SCALE`) and spread wide, because
 * the swinging pressure is the entire point. "The doors open" runs the same three columns
 * small and tucked, so the two views can't be mistaken for each other.
 */
const COLUMN_SCALE = 1.3;
const LA_ANCHOR: [number, number, number] = [1.55, -1.35, 0];
const LV_ANCHOR: [number, number, number] = [2.20, -1.35, 0];
const AO_ANCHOR: [number, number, number] = [2.85, -1.35, 0];

/** Streams kept quiet here — present when the reader scrubs into ejection, but never
 *  competing with the columns. Full strength belongs to "the doors open". */
const JET_INTENSITY = 0.3;
const LA_COLOR = '#7fa8ff';
const LV_COLOR = '#ff5a4d';
const AO_COLOR = '#ffd24a';

/** S1 "lub" bloom on the AV (mitral) plane; S2 "dub" bloom on the aortic valve. */
const S1_ANCHOR = new THREE.Vector3(0.065, -0.458, 0.034);
const S2_ANCHOR = new THREE.Vector3(-0.005, -0.230, -0.018);

/**
 * ⚠️ The two middle sentences used to explain S1 and S2 in full, before the reader had
 * scrubbed to either one — and the two `ClosureMarker` cards already say exactly that,
 * on cue, at the instant the leaflets meet ("the two entry valves meeting, not the
 * muscle"). The blurb was pre-empting its own markers.
 *
 * SPEC §7's *Aha* is that nobody scripted "all four valves shut" — it falls out of the
 * physics. That is now put as a question rather than as a statement, because working
 * out why every door has to be shut at once is the whole reward of the section.
 */
const BLURB =
  'Twice every beat the ventricle seals itself shut. No way in, no way out. The ' +
  'blood trapped inside cannot go anywhere.';

const MORE = [
  'However hard the muscle squeezes, that blood has nowhere to be. So the pressure ' +
    'climbs and the volume does not move.',
  'Scrub through both windows and watch the bright line on the blood. It never ' +
    'shifts. Nothing arranged that.',
  'Work out why every door has to be shut at the same time.',
];

export function createSealedVentricle(): SectionConfig {
  let mano: ManometerOverlay | null = null;
  let scrubber: BeatScrubber | null = null;
  let s1Marker: ClosureMarker | null = null;
  let s2Marker: ClosureMarker | null = null;
  let blood: VentricleLiquids | null = null;
  let unsubFrame: (() => void) | null = null;

  /** The inner cut surface occludes anything inside the cavity — see ventricleLiquid.ts.
   *  Retired while this section is on screen, restored on the way out. */
  let innerCaps: THREE.Object3D[] = [];
  const setInnerCapVisible = (v: boolean): void => {
    for (const o of innerCaps) o.visible = v;
  };

  let active = false;
  let prevPhase = 0;
  // ?phase parks the clock at a chosen instant for headless inspection.
  let parked = false;

  /** Park on the FIRST sealed moment (isovolumetric contraction), caught mid-rocket
   *  (~0.9 through its window, mirroring §7) so the entrance frame reads as a sealed
   *  box; the reader scrubs forward to meet the relaxation mirror. */
  const parkPhase = (ctx: SectionContext): number => {
    const p = ctx.clock.getEvents().phaseStart;
    const start = p['isovolumetric-contraction'];
    return start + 0.9 * (p.ejection - start);
  };

  const inContraction = (ctx: SectionContext, phase: number): boolean => {
    const p = ctx.clock.getEvents().phaseStart;
    return phase >= p['isovolumetric-contraction'] && phase < p.ejection;
  };
  const inRelaxation = (ctx: SectionContext, phase: number): boolean => {
    const p = ctx.clock.getEvents().phaseStart;
    return phase >= p['isovolumetric-relaxation'] && phase < p.filling;
  };

  /** One-shot flash when the scrub crosses a closure phase, either direction, ignoring
   *  big jumps / the beat wrap. */
  const crossed = (target: number, phase: number, prev: number): boolean =>
    Math.abs(phase - prev) < 0.2 &&
    ((prev < target && phase >= target) || (prev > target && phase <= target));

  return {
    id: 'sealed-ventricle',
    title: 'The sealed ventricle',
    blurb: BLURB,
    more: MORE,
    framing: { position: [...FRAMING.position], target: [...FRAMING.target] },
    cutaway: SECTION_CUTAWAY,
    heartRotationY: HEART_TURN,
    focus: FOCUS,

    init: (ctx: SectionContext) => {
      parked = new URLSearchParams(window.location.search).has('phase');

      mano = new ManometerOverlay(ctx.scene, ctx.clock, [
        { compartment: 'LA', anchor: LA_ANCHOR, label: 'LA', color: LA_COLOR, sublabel: 'left atrium' },
        { compartment: 'LV', anchor: LV_ANCHOR, label: 'LV', color: LV_COLOR, showVolume: true, sublabel: 'left ventricle' },
        { compartment: 'SysArt', anchor: AO_ANCHOR, label: 'Ao', color: AO_COLOR, sublabel: 'aorta' },
      ], { scale: COLUMN_SCALE });

      innerCaps = findInnerCaps(ctx.scene);

      // Blood as visible LIQUID in BOTH ventricles (shared with "the doors open"). This
      // is the strongest possible read of the sealed paradox: through each sealed window
      // the liquid body plainly does NOT change size — the volume is locked — while the
      // pressure columns beside it swing violently. Dots could only imply that; a body
      // of liquid holding still says it outright.
      // The LEVEL RING is this section's clincher: a hard geometric line riding the
      // liquid surface, so "the volume is locked" becomes something you can check by eye
      // rather than infer. Through each sealed window it sits dead still while the
      // columns swing; through ejection it slides down. Streams stay quiet (see above).
      blood = new VentricleLiquids(ctx.scene, ctx.clock, {
        levelRing: true,
        jetIntensity: JET_INTENSITY,
      });

      scrubber = new BeatScrubber(ctx.clock);

      // S1 "lub" — the AV valves meeting (up-stroke sealed window).
      s1Marker = new ClosureMarker(ctx.scene, S1_ANCHOR, {
        label: 'S1 · lub',
        sublabel: 'the two entry valves meeting, not the muscle',
        color: '#ff6a58',
        radius: 0.34,
      });
      // In the heart FRAME, not the scene: the blooms sit ON the valves, so they have
      // to turn with the heart (see HEART_TURN / heartOrientation.ts).
      ctx.scene.getHeartFrame().add(s1Marker.group);

      // S2 "dub" — the aortic valve snapping shut (down-stroke sealed window).
      s2Marker = new ClosureMarker(ctx.scene, S2_ANCHOR, {
        label: 'S2 · dub',
        sublabel: 'the aortic valve snapping shut, not the muscle',
        color: '#ffcf6a',
        radius: 0.34,
      });
      ctx.scene.getHeartFrame().add(s2Marker.group);

      unsubFrame = ctx.scene.onFrame((dt) => {
        if (!active) return;
        const phase = ctx.clock.getPhase();

        // Both liquid bodies track their chamber's real mL off the one clock: frozen
        // through each sealed window, moving through ejection and filling.
        blood?.update(dt);

        const ev = ctx.clock.getEvents();
        s1Marker?.setActive(inContraction(ctx, phase));
        s2Marker?.setActive(inRelaxation(ctx, phase));
        if (crossed(ev.s1Phase, phase, prevPhase)) s1Marker?.firePulse();
        if (crossed(ev.s2Phase, phase, prevPhase)) s2Marker?.firePulse();
        prevPhase = phase;
        s1Marker?.update(dt);
        s2Marker?.update(dt);
      });
    },

    enter: (ctx: SectionContext) => {
      const { scene, panel } = ctx;
      const headless = new URLSearchParams(window.location.search).get('intro') === '0';
      panel.classList.add('is-active');
      document.body.classList.add('keystone-active'); // retire the hero-only chrome
      active = true;

      if (!parked) ctx.clock.setPhase(parkPhase(ctx));
      prevPhase = ctx.clock.getPhase();

      mano?.show();
      // Re-read the reference volumes each entrance. §8 lets the reader change the
      // operating point and those changes PERSIST (one heart), so EDV here may not be
      // the EDV this section was constructed with — without this the liquid bodies would
      // be scaled to a beat that no longer exists. Cheap: 120 samples of a cached solve.
      blood?.refresh();
      blood?.show();
      scrubber?.refresh();
      scrubber?.highlight(['isovolumetric-contraction', 'isovolumetric-relaxation']);
      scrubber?.show();
      s1Marker?.show();
      s2Marker?.show();
      s1Marker?.setActive(inContraction(ctx, ctx.clock.getPhase()));
      s2Marker?.setActive(inRelaxation(ctx, ctx.clock.getPhase()));

      scene.getCutaway()?.set(SECTION_CUTAWAY, { animate: !headless });
      // Re-asserted for the same reason as the cutaway: the manager only snaps on the
      // very first activation, and GSAP doesn't advance under headless virtual time.
      scene.getOrientation()?.set(HEART_TURN, { animate: !headless });
      setInnerCapVisible(false); // or the liquid inside the cavity is depth-rejected

      if (headless) {
        {
          // Through `scaleFraming`, or a headless render at a non-reference size would snap to
          // the unscaled pose and disagree with what the live ease produces.
          const snap = scaleFraming(FRAMING);
          scene.camera.position.set(...snap.position);
          scene.controls.target.set(...snap.target);
        }
        scene.controls.enabled = true;
        scene.controls.update();
      }
    },

    exit: (ctx: SectionContext) => {
      active = false;
      ctx.panel.classList.remove('is-active');
      document.body.classList.remove('keystone-active');
      mano?.hide();
      blood?.hide();
      scrubber?.hide();
      s1Marker?.hide();
      s2Marker?.hide();
      setInnerCapVisible(true); // leave the shared heart exactly as we found it
      ctx.scene.getCutaway()?.set(0, { animate: true });
    },

    dispose: (ctx: SectionContext) => {
      active = false;
      setInnerCapVisible(true);
      innerCaps = [];
      unsubFrame?.();
      unsubFrame = null;
      mano?.dispose();
      mano = null;
      blood?.dispose();
      blood = null;
      scrubber?.dispose();
      scrubber = null;
      if (s1Marker) {
        ctx.scene.getHeartFrame().remove(s1Marker.group);
        s1Marker.dispose();
        s1Marker = null;
      }
      if (s2Marker) {
        ctx.scene.getHeartFrame().remove(s2Marker.group);
        s2Marker.dispose();
        s2Marker = null;
      }
    },
  };
}
