import type { BeatClock } from '../../clock/index.ts';
import type { ConductionSegment } from '../../engine/index.ts';

/**
 * The ECG strip — SPEC §5's "the ECG builds below in lockstep (P wave, QRS)".
 *
 * AND THE SECTION'S SCRUBBER. This is deliberately not a read-only trace beside a
 * dial. SPEC §5 asks the reader to "scrub the activation along its path", and the
 * path is a sequence in TIME, so the honest control for it is a time axis you can
 * drag a playhead along — which is what an ECG strip already is. Three things fall
 * out of merging them:
 *
 *   1. The bottom of the screen is fully committed elsewhere (the circular
 *      `BeatScrubber` owns bottom-centre, the hero's zoom buttons own bottom-right,
 *      the pressure columns rise out of the lower right). A separate strip plus a
 *      dial had nowhere to live. Replacing the dial for this one section does.
 *   2. It is the clearest possible read on what the AV delay IS. Drag the delay
 *      knob and the QRS visibly slides along the axis toward the P wave, closing
 *      the PR interval the reader is being told about. A number changing in a knob
 *      panel cannot do that.
 *   3. Act III's dial has to become a linear time axis for §11's Wiggers diagram
 *      eventually. This is where that axis is introduced, one section early, doing
 *      a job that genuinely needs it.
 *
 * DRAWN FROM THE ENGINE'S OWN SCHEDULE. The P wave spans the `atria` landmark
 * window and the QRS is built across `septum` → `apex` → `ventricles`, all read
 * from `engine.getConductionSchedule()`. Nothing here is hand-keyed, so the trace
 * cannot drift out of agreement with the muscle when the operating point moves.
 *
 * NO T WAVE, on purpose. The engine models depolarisation timing only —
 * repolarisation is explicitly out of scope (PHYSICS.md §9, "no cellular
 * electrophysiology"). Drawing a T wave would mean inventing a timing the model
 * does not have and presenting it at the same confidence as the rest, which is the
 * quiet dishonesty this project has rejected before (the clamped manometer bar).
 * The caption says so instead.
 */

const SVG_NS = 'http://www.w3.org/2000/svg';

/** Viewbox of the strip. Width is time (one full beat); height is signal. */
const VIEW_W = 1000;
const VIEW_H = 150;
/** The isoelectric line, in viewbox units. */
const BASELINE = 96;
/** R-wave height in viewbox units. `ecgSignal` returns 1.0 at the R peak. */
const R_HEIGHT = 62;

/**
 * Where the P wave and the QRS sit on the time axis, read out of the engine's own
 * conduction schedule. Phases, 0 → 1.
 *
 * ⚠️ EXPORTED ALONGSIDE `ecgSignal` BECAUSE §11 DRAWS THIS SAME TRACE. The Wiggers
 * diagram's ECG channel is captioned "taught in The electrical wave", which is only
 * honest if it is the identical waveform — and identical is a thing you get by sharing
 * the function, not by copying 40 lines of piecewise curve and hoping. Cardiac timing
 * lives in the engine (CLAUDE.md); its *drawing* lives here, once.
 */
export interface EcgGeometry {
  pStart: number;
  pEnd: number;
  qrsStart: number;
  rPeak: number;
  qrsEnd: number;
}

/** Read the waveform's landmarks off the engine's current conduction schedule. */
export function ecgGeometry(clock: BeatClock): EcgGeometry {
  const schedule = clock.getEngine().getConductionSchedule();
  const seg = (name: string): ConductionSegment | undefined =>
    schedule.find((s) => s.landmark === name);

  const atria = seg('atria');
  const saNode = seg('sa-node');
  const septum = seg('septum');
  const apex = seg('apex');
  const ventricles = seg('ventricles');

  const qrsStart = septum?.start ?? 0.2;
  const rPeak = apex?.end ?? 0.26;
  return {
    pStart: saNode?.start ?? 0,
    pEnd: atria?.end ?? 0.14,
    qrsStart,
    rPeak,
    qrsEnd: Math.min(1, (ventricles?.start ?? 0.27) + (rPeak - qrsStart) * 1.4),
  };
}

/** P-wave height as a fraction of the R wave — atrial mass is a fraction of ventricular. */
const P_FRACTION = 0.145;

/**
 * The ECG signal at one phase, NORMALIZED so the R peak is exactly 1. A consumer
 * multiplies by whatever amplitude its own axis wants.
 *
 * A P wave (broad, low, rounded) and a QRS complex (Q dip, tall narrow R, S
 * undershoot). Both are placed and scaled from the landmark windows in `g`, so the
 * shape follows the engine rather than a hand-keyed table.
 *
 * NO T WAVE, on purpose — see this module's header.
 */
export function ecgSignal(phase: number, g: EcgGeometry): number {
  let y = 0;

  // P wave: a single raised cosine across the atrial depolarisation window.
  if (phase >= g.pStart && phase <= g.pEnd && g.pEnd > g.pStart) {
    const t = (phase - g.pStart) / (g.pEnd - g.pStart);
    y += P_FRACTION * 0.5 * (1 - Math.cos(2 * Math.PI * t));
  }

  // QRS: piecewise, anchored on the septal onset (Q), the apex arrival (R) and the
  // spread through the walls (S, then back to baseline).
  if (phase >= g.qrsStart && phase <= g.qrsEnd && g.qrsEnd > g.qrsStart) {
    const qEnd = g.qrsStart + (g.rPeak - g.qrsStart) * 0.45;
    const sPeak = g.rPeak + (g.qrsEnd - g.rPeak) * 0.35;
    if (phase < qEnd) {
      // Q: small downward deflection as the septum depolarises.
      const t = (phase - g.qrsStart) / Math.max(1e-9, qEnd - g.qrsStart);
      y -= 0.12 * Math.sin(Math.PI * t);
    } else if (phase < g.rPeak) {
      // R: the tall upstroke, apex arrival.
      const t = (phase - qEnd) / Math.max(1e-9, g.rPeak - qEnd);
      y += t * t;
    } else if (phase < sPeak) {
      // Down through baseline into the S trough.
      const t = (phase - g.rPeak) / Math.max(1e-9, sPeak - g.rPeak);
      y += (1 - t) - 0.22 * t;
    } else {
      // S recovering to the isoelectric line as the walls finish.
      const t = (phase - sPeak) / Math.max(1e-9, g.qrsEnd - sPeak);
      y -= 0.22 * (1 - t);
    }
  }
  return y;
}

export interface EcgTraceOptions {
  /**
   * Called when the reader drags the playhead. The section decides what that
   * means; normally `clock.setPhase`.
   */
  onScrub?: (phase01: number) => void;
}

export class EcgTrace {
  private readonly clock: BeatClock;
  private readonly root: HTMLDivElement;
  private readonly svg: SVGSVGElement;
  private readonly trace: SVGPathElement;
  private readonly drawn: SVGPathElement;
  private readonly playhead: SVGGElement;
  private readonly prBracket: SVGGElement;
  private readonly prLine: SVGLineElement;
  private readonly prLabel: SVGTextElement;
  private readonly readout: HTMLSpanElement;
  private readonly onScrub: ((phase01: number) => void) | undefined;

  /** Sampled trace, phase → signal in viewbox y. Rebuilt by `refresh()`. */
  private samples: Array<{ x: number; y: number }> = [];
  private dragging = false;
  private visible = false;

  constructor(clock: BeatClock, opts: EcgTraceOptions = {}) {
    this.clock = clock;
    this.onScrub = opts.onScrub;

    this.root = document.createElement('div');
    this.root.className = 'ecg-strip';

    const caption = document.createElement('div');
    caption.className = 'ecg-caption';
    const title = document.createElement('span');
    title.className = 'ecg-caption-title';
    title.textContent = 'ECG · one beat';
    this.readout = document.createElement('span');
    this.readout.className = 'ecg-caption-readout';
    const note = document.createElement('span');
    note.className = 'ecg-caption-note';
    note.textContent = 'drag to scrub · P and QRS only (this model times the trigger, not the recovery)';
    caption.append(title, this.readout, note);

    this.svg = document.createElementNS(SVG_NS, 'svg') as SVGSVGElement;
    this.svg.setAttribute('viewBox', `0 0 ${VIEW_W} ${VIEW_H}`);
    this.svg.setAttribute('preserveAspectRatio', 'none');
    this.svg.classList.add('ecg-svg');

    const axis = document.createElementNS(SVG_NS, 'line');
    axis.setAttribute('x1', '0');
    axis.setAttribute('x2', String(VIEW_W));
    axis.setAttribute('y1', String(BASELINE));
    axis.setAttribute('y2', String(BASELINE));
    axis.setAttribute('class', 'ecg-axis');
    this.svg.appendChild(axis);

    // The PR interval, drawn as a measured bracket rather than described in words:
    // P-wave onset to QRS onset, with its own millisecond readout.
    this.prBracket = document.createElementNS(SVG_NS, 'g') as SVGGElement;
    this.prBracket.setAttribute('class', 'ecg-pr');
    this.prLine = document.createElementNS(SVG_NS, 'line');
    this.prLine.setAttribute('class', 'ecg-pr-line');
    this.prLabel = document.createElementNS(SVG_NS, 'text');
    this.prLabel.setAttribute('class', 'ecg-pr-label');
    this.prLabel.setAttribute('text-anchor', 'middle');
    this.prBracket.append(this.prLine, this.prLabel);
    this.svg.appendChild(this.prBracket);

    // Two paths over each other: the whole beat faint, and the part up to the
    // playhead bright — so the trace reads as being WRITTEN as the reader scrubs
    // ("the ECG builds below in lockstep") instead of just sitting there.
    this.trace = document.createElementNS(SVG_NS, 'path');
    this.trace.setAttribute('class', 'ecg-trace');
    this.svg.appendChild(this.trace);
    this.drawn = document.createElementNS(SVG_NS, 'path');
    this.drawn.setAttribute('class', 'ecg-trace-drawn');
    this.svg.appendChild(this.drawn);

    this.playhead = document.createElementNS(SVG_NS, 'g') as SVGGElement;
    this.playhead.setAttribute('class', 'ecg-playhead');
    const stem = document.createElementNS(SVG_NS, 'line');
    stem.setAttribute('y1', '8');
    stem.setAttribute('y2', String(VIEW_H - 8));
    stem.setAttribute('class', 'ecg-playhead-stem');
    const bead = document.createElementNS(SVG_NS, 'circle');
    bead.setAttribute('r', '6');
    bead.setAttribute('cy', String(BASELINE));
    bead.setAttribute('class', 'ecg-playhead-bead');
    this.playhead.append(stem, bead);
    this.svg.appendChild(this.playhead);

    this.root.append(caption, this.svg);
    document.body.appendChild(this.root);

    this.svg.addEventListener('pointerdown', this.onPointerDown);
    window.addEventListener('pointermove', this.onPointerMove);
    window.addEventListener('pointerup', this.onPointerUp);

    this.refresh();
  }

  // ---- Pointer → phase -----------------------------------------------------

  /**
   * ⚠️ Mapped through `getScreenCTM()`, never `clientX / rect.width * VIEW_W`.
   * The strip stretches with `preserveAspectRatio: none`, so the naive version
   * drifts with the viewport's aspect ratio — the documented trap that already
   * bit §8's knob panel.
   */
  private phaseFromEvent(e: PointerEvent): number {
    const ctm = this.svg.getScreenCTM();
    if (!ctm) return 0;
    const pt = new DOMPoint(e.clientX, e.clientY).matrixTransform(ctm.inverse());
    return Math.min(1, Math.max(0, pt.x / VIEW_W));
  }

  private onPointerDown = (e: PointerEvent): void => {
    if (!this.visible) return;
    e.preventDefault();
    this.dragging = true;
    this.svg.classList.add('is-dragging');
    this.onScrub?.(this.phaseFromEvent(e));
  };

  private onPointerMove = (e: PointerEvent): void => {
    if (!this.dragging) return;
    this.onScrub?.(this.phaseFromEvent(e));
  };

  private onPointerUp = (): void => {
    if (!this.dragging) return;
    this.dragging = false;
    this.svg.classList.remove('is-dragging');
  };

  // ---- The waveform --------------------------------------------------------

  /**
   * Rebuild the trace from the engine's current conduction schedule.
   *
   * Must be called on `enter` and after any knob change: the AV delay moves the
   * QRS along the axis, and heart rate rescales every landmark's phase window.
   */
  refresh(): void {
    const geom = ecgGeometry(this.clock);
    const { pStart, qrsStart } = geom;

    const N = 900;
    this.samples = [];
    for (let i = 0; i <= N; i++) {
      const phase = i / N;
      this.samples.push({
        x: (phase / 1) * VIEW_W,
        y: BASELINE - R_HEIGHT * ecgSignal(phase, geom),
      });
    }
    const d = this.samples
      .map((s, i) => `${i === 0 ? 'M' : 'L'}${s.x.toFixed(2)},${s.y.toFixed(2)}`)
      .join(' ');
    this.trace.setAttribute('d', d);

    // The PR bracket: atrial onset → ventricular onset, in milliseconds.
    const cycleLength = this.clock.getEngine().getParams().cycleLength;
    const prMs = Math.round((qrsStart - pStart) * cycleLength * 1000);
    const x1 = pStart * VIEW_W;
    const x2 = qrsStart * VIEW_W;
    this.prLine.setAttribute('x1', String(x1));
    this.prLine.setAttribute('x2', String(x2));
    this.prLine.setAttribute('y1', '26');
    this.prLine.setAttribute('y2', '26');
    this.prLabel.setAttribute('x', String((x1 + x2) / 2));
    this.prLabel.setAttribute('y', '19');
    // Below about 40 ms the bracket is too narrow to hold its own label.
    this.prLabel.textContent = prMs >= 40 ? `PR ${prMs} ms` : `PR ${prMs}`;
    this.prBracket.classList.toggle('is-collapsed', prMs < 12);
  }

  // ---- Per-frame -----------------------------------------------------------

  /** Move the playhead and extend the bright "written so far" path. */
  update(): void {
    if (!this.visible) return;
    const phase = this.clock.getPhase();
    const x = phase * VIEW_W;
    this.playhead.setAttribute('transform', `translate(${x.toFixed(2)},0)`);

    const upto = Math.max(1, Math.round(phase * (this.samples.length - 1)));
    const d = this.samples
      .slice(0, upto + 1)
      .map((s, i) => `${i === 0 ? 'M' : 'L'}${s.x.toFixed(2)},${s.y.toFixed(2)}`)
      .join(' ');
    this.drawn.setAttribute('d', d);

    const cycleLength = this.clock.getEngine().getParams().cycleLength;
    this.readout.textContent = `${Math.round(phase * cycleLength * 1000)} ms`;
  }

  show(): void {
    this.visible = true;
    this.refresh();
    this.root.classList.add('is-visible');
  }

  hide(): void {
    this.visible = false;
    this.dragging = false;
    this.root.classList.remove('is-visible');
  }

  dispose(): void {
    this.hide();
    this.svg.removeEventListener('pointerdown', this.onPointerDown);
    window.removeEventListener('pointermove', this.onPointerMove);
    window.removeEventListener('pointerup', this.onPointerUp);
    this.root.remove();
  }
}
