import * as THREE from 'three';

/**
 * THE HEART SEEN FROM TOO FAR AWAY TO BE GEOMETRY — a soft additive bloom standing in for
 * the model while the model is smaller than a pixel.
 *
 * WHY THIS EXISTS, and it is the technical crux of Act 0. The opener's premise is that the
 * dot of the i in "alive" really IS the heart, and that scrolling dollies the actual camera
 * in until it resolves. That premise has a hard problem in it: at the distance where the
 * heart is dot-sized it is also SUB-PIXEL, and a sub-pixel triangle mesh does not render as
 * a clean glowing dot — it renders as a flickering speck that aliases differently every
 * frame, or as nothing at all. The model is ~2.45 world units tall and this camera puts
 * ~1453 pixels on a world unit at distance 1, so at distance 1600 the whole organ is 2.2
 * pixels. There is no lighting or material trick that makes 2.2 pixels look intentional.
 *
 * So the dot is drawn, not rendered: a billboard whose SCREEN size at the start distance is
 * whatever a dot should be, which then grows with perspective exactly as the real heart
 * does, and which fades out as the real geometry becomes legible. Because both are at the
 * same world point and both grow at the same rate, the handover has no seam — the glow
 * tightens onto the organ and dies, and the organ was always underneath it.
 *
 * ⚠️ NOT A `THREE.Sprite`. `SpriteMaterial` takes no custom shader, and a canvas-texture
 * radial gradient bands visibly once it is scaled to a few hundred pixels across, which is
 * exactly the size this thing reaches mid-crossfade. It is a plane with an analytic falloff,
 * billboarded by copying the camera's quaternion.
 *
 * ⚠️ `depthTest: false` AND `depthWrite: false`. It has to be visible before the heart is
 * (nothing to sort against at distance) and must not punch a hole in anything as it fades
 * out over the resolving anatomy.
 */

const VERT = /* glsl */ `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const FRAG = /* glsl */ `
  precision mediump float;
  uniform vec3  uColor;      // the halo's hue
  uniform vec3  uCoreColor;  // the white-hot middle
  uniform float uOpacity;
  uniform float uCore;       // radius of the solid centre, as a fraction of the glow's radius
  uniform float uIntensity;
  varying vec2  vUv;

  void main() {
    // Distance from the billboard's centre, 0 at the middle and 1 at the edge of the
    // inscribed circle. Everything past 1 is discarded so the plane never shows corners.
    float r = length(vUv - 0.5) * 2.0;
    if (r > 1.0) discard;

    // TWO falloffs summed, which is what makes this read as a light source rather than as a
    // blurred disc: a solid bright core, plus a wide dim halo reaching most of the way to the
    // edge. A single gaussian gives you either a hard dot with a visible edge or an even
    // smudge with no centre; a lit gas tube's dot has both at once.
    //
    // ⚠️ uCore IS A FRACTION OF THE RADIUS, AND IT MUST NOT BE SMALL. This started at 0.16,
    // which at the size the dot actually renders — about ten pixels across, so five of
    // radius — made the bright core 0.8 px wide, i.e. SUB-PIXEL. Everything the eye could
    // actually see was the dim outer halo, and the dot read as a faint smudge next to the
    // neon type's white-hot letters. The core has to be a real, visible disc.
    float core = 1.0 - smoothstep(0.0, max(uCore, 0.02), r);
    float halo = pow(max(0.0, 1.0 - r), 2.2);

    // White-hot in the middle, falling to the hue outward — the way a neon tube's own dot
    // photographs. core² keeps the white confined to the very centre.
    vec3 col = mix(uColor, uCoreColor, core * core);

    float a = uOpacity * clamp(core + 0.75 * halo, 0.0, 1.0);
    if (a < 0.004) discard;
    // Additive: colour carries the energy, alpha gates how much of it lands.
    gl_FragColor = vec4(col * uIntensity * (0.45 + 0.55 * (core + halo)), a);
  }
`;

export interface HeartGlowOptions {
  /** World point the glow sits on — put it where the real heart is. */
  at: THREE.Vector3;
  /** Neon hue of the dot. */
  color: string;
  /** Diameter in world units. Set this so the SCREEN size is dot-sized at the far end. */
  size: number;
  /** The white-hot centre's colour. Defaults to a warm white. */
  coreColor?: string;
  /**
   * Radius of the bright core as a fraction of the glow's radius. ⚠️ Keep this well above
   * zero — see the shader: a small fraction of a ten-pixel dot is a sub-pixel core, and the
   * glow then has no visible centre at all.
   */
  core?: number;
  /** Additive energy multiplier. Above 1 clips the core to white, which is the point. */
  intensity?: number;
}

export class HeartGlow {
  readonly mesh: THREE.Mesh;
  private readonly geom: THREE.PlaneGeometry;
  private readonly mat: THREE.ShaderMaterial;

  constructor(opts: HeartGlowOptions) {
    this.geom = new THREE.PlaneGeometry(1, 1);
    this.mat = new THREE.ShaderMaterial({
      vertexShader: VERT,
      fragmentShader: FRAG,
      uniforms: {
        uColor: { value: new THREE.Color(opts.color) },
        uCoreColor: { value: new THREE.Color(opts.coreColor ?? '#fff2f5') },
        uOpacity: { value: 0 },
        uCore: { value: opts.core ?? 0.40 },
        uIntensity: { value: opts.intensity ?? 1.6 },
      },
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthTest: false,
      depthWrite: false,
      toneMapped: false,
      side: THREE.DoubleSide,
    });
    this.mesh = new THREE.Mesh(this.geom, this.mat);
    this.mesh.position.copy(opts.at);
    this.mesh.scale.setScalar(opts.size);
    // Over everything: this is a light in front of the scene, not part of it.
    this.mesh.renderOrder = 20;
    this.mesh.frustumCulled = false;
    this.mesh.visible = false;
  }

  /** Billboard it. Must run every frame the glow is visible. */
  faceCamera(camera: THREE.Camera): void {
    this.mesh.quaternion.copy(camera.quaternion);
  }

  setOpacity(o: number): void {
    const v = THREE.MathUtils.clamp(o, 0, 1);
    (this.mat.uniforms.uOpacity as { value: number }).value = v;
    this.mesh.visible = v > 0.004;
  }

  /** World diameter. Act 0 shrinks this as it closes, so the halo tightens onto the organ. */
  setSize(size: number): void {
    this.mesh.scale.setScalar(Math.max(0.0001, size));
  }

  /**
   * Additive energy. Act 0 drives this above its resting value for the moment between the
   * reader pressing the button and the camera letting go — the sign gathering power.
   *
   * ⚠️ A SURGE MUST NOT OUTLAST THE CROSSFADE. Brightening the dot while the real geometry
   * is resolving underneath it is the swamping failure this file's own header describes: the
   * organ ends up inside an opaque core. Act 0 decays the surge back to rest early in the
   * fall, long before `glowFullUntil()`. Keep any other caller to the same discipline.
   */
  setIntensity(i: number): void {
    (this.mat.uniforms.uIntensity as { value: number }).value = Math.max(0, i);
  }

  dispose(): void {
    this.geom.dispose();
    this.mat.dispose();
  }
}
