import * as THREE from 'three';
import gsap from 'gsap';

/**
 * Authored cutaway (SPEC §5, MODEL_FIT.md Phase B). The base model ships a
 * detachable anterior wall — the `CutawayDoor` mesh — seated closed in the rest
 * pose; hiding it exposes the cross-sectioned interior (chambers, septum, valves
 * with chordae). This controller dissolves that wall in/out so each section can
 * open the heart to a chosen degree, choreographed into its entrance:
 *   0 = wall closed (whole heart)   1 = wall gone (full cross-section)
 *
 * The door shares the one HEART_ANATOMY material with every other mesh, so we
 * clone it here and fade only the door — the rest of the heart stays opaque.
 */
const isDoor = (name: string): boolean => name.toLowerCase().replace(/[^a-z0-9]/g, '') === 'cutawaydoor';

export class CutawayController {
  private door: THREE.Mesh | null = null;
  private mat: THREE.MeshStandardMaterial | null = null;
  private tween: gsap.core.Tween | null = null;
  private readonly state = { open: 0 };

  constructor(heart: THREE.Group) {
    heart.traverse((obj) => {
      const mesh = obj as THREE.Mesh;
      if (mesh.isMesh && isDoor(mesh.name)) this.door = mesh;
    });
    if (this.door) {
      // Own material instance so fading the door doesn't fade the whole heart.
      const orig = this.door.material as THREE.MeshStandardMaterial;
      this.mat = orig.clone();
      this.door.material = this.mat;
    }
  }

  /** True once the door mesh was found (diagnostics / guards). */
  get available(): boolean {
    return this.door !== null;
  }

  /** Current openness, 0 (closed) → 1 (fully cut away). */
  get open(): number {
    return this.state.open;
  }

  /**
   * Set the cutaway openness. `animate:false` snaps (headless / initial framing);
   * otherwise it dissolves over `duration` seconds so the wall fades on entrance.
   */
  set(open: number, opts: { animate?: boolean; duration?: number } = {}): void {
    open = THREE.MathUtils.clamp(open, 0, 1);
    if (!this.door || !this.mat) return;
    this.tween?.kill();

    const apply = (): void => {
      const o = this.state.open;
      const transparent = o > 0.001;
      // Toggling `transparent` changes the material's program state; without a
      // needsUpdate the switch can fail to take visual effect (esp. after the
      // material has already been toggled by a prior section's transition).
      if (this.mat!.transparent !== transparent) {
        this.mat!.transparent = transparent;
        this.mat!.needsUpdate = true;
      }
      this.mat!.opacity = 1 - o;
      this.mat!.depthWrite = o < 0.5; // stop the fading wall from z-fighting the interior
      this.door!.visible = o < 0.999; // fully open → skip drawing it entirely
    };

    if (opts.animate === false) {
      this.state.open = open;
      apply();
      return;
    }
    this.tween = gsap.to(this.state, {
      open,
      duration: opts.duration ?? 0.9,
      ease: 'power2.inOut',
      onUpdate: apply,
    });
  }

  dispose(): void {
    this.tween?.kill();
  }
}
