import * as THREE from 'three';
import type { SectionConfig, SectionContext, CameraFraming } from './types.ts';
import { scaleFraming } from './cameraFraming.ts';
import { scaleDistance } from '../ui/uiScale.ts';
import { DEFAULT_MIN_DISTANCE } from '../scene/controls.ts';
import {
  ManometerOverlay,
  MANOMETER_PMAX,
  MANOMETER_COLUMN_HEIGHT,
} from '../scene/overlays/manometer.ts';
import { StatusBadge } from '../scene/overlays/statusBadge.ts';
import { findValveMorphs, setValvePose, type ValveMorphs } from '../scene/heartRig.ts';
import { LiquidVolume } from '../scene/overlays/liquidVolume.ts';
import type { LiquidJet } from '../scene/overlays/liquidJet.ts';
import {
  LV_CAVITY,
  LV_TO_MITRAL,
  PRESSURE_SCALE,
  createValveJet,
  findInnerCaps,
} from './ventricleLiquid.ts';

/**
 * Section 4 — "Pressure is the driver" (SPEC §6, Act I; the KEYSTONE).
 *
 * Teaches the one rule the rest of the piece runs on: blood flows down pressure
 * gradients, and every valve is opened or shut by nothing but the pressure
 * difference across it. An authored cutaway frames the mitral valve; two manometer
 * columns (LA, LV) stand beside it; a gradient arrow crosses the valve.
 *
 * Two modes:
 *   A · RUNNING (default) — the solver drives a continuous beat, advancing the ONE
 *       clock, so the valve opens and closes on its own with correct timing while the
 *       pool fills and empties for real. The solver's live on-stage debut.
 *   B · "Take the controls" — the clock is HELD on a diastolic instant and the reader
 *       drags the tops of the LA/LV columns. The mitral leaflet is driven each frame by
 *       the DIODE RULE on those two pressures (open iff LA>LV, slams shut iff LV≥LA).
 *       Rule-driven, not canned — DRIVEN MOTION holds; the reader is simply supplying
 *       the pressures the engine normally would.
 *
 * ⚠️ THE DEFAULT IS "RUNNING", AND THAT IS DELIBERATE. It used to open frozen in manual
 * mode, which made the reader's first sight of the keystone section a still heart they
 * had to work out how to operate. Opening with it beating shows the claim being made
 * before asking anyone to test it, and the button then reads as *taking* control rather
 * than surrendering it. The teaching order is: watch the rule hold, then go break it.
 *
 * A *view*: it owns no heart and no cardiac timing. The interior is exposed via the
 * shared CutawayController (declared through `cutaway`); the columns/arrow read the
 * one clock in machine mode and the reader's handles in manual mode. The only
 * geometry it drives directly is the single mitral leaflet in manual mode — the
 * section's whole teaching act — released the moment the machine takes over.
 */

/**
 * Pushed IN onto the left ventricle — the only chamber this section puts blood in, so
 * the wide framing was spending most of the frame on anatomy that had nothing to show.
 * Target sits between the LV cavity centre and the mitral orifice, along the same view
 * direction the wider framing used (so it reads as a push-in, not a new shot).
 *
 * ⚠️ THE DISTANCE HERE IS 2.9 AND `controls.minDistance` IS 3. `OrbitControls.update()`
 * re-clamps EVERY frame, so without lowering the floor this framing is silently dragged
 * back out and renders identically to the old one — the trap that made two deliberately
 * different §3 framings come out byte-identical. Lowered on `enter`, restored on `exit`
 * AND `dispose`.
 */
const FRAMING: CameraFraming = { position: [-0.089, -0.038, 3.252], target: [-0.05, -0.74, 0.08] };

/** Floor this section needs, and the shared default it has to put back. */
const KEYSTONE_MIN_DISTANCE = 1.8;

/** How far open the anterior-wall cutaway sits (exposes the LV cavity, septum, and
 *  the mitral valve with its chordae). */
const KEYSTONE_CUTAWAY = 0.92;

/**
 * WHERE TO LOOK: the span from the mitral door across to the two pressure columns.
 *
 * ⚠️ A tight spotlight would be actively WRONG here. This section's control surface is
 * the pair of draggable column handles out at x = 1.10 and 1.46, and its result is the
 * stream through the mitral door back at x ≈ 0.2 — the reader's job is to hold both in
 * one glance and watch cause meet effect. So the circle is wide enough to hold the whole
 * causal chain and the darkening is light; what it removes is only the empty frame
 * around it. No pulse, for the same reason as the four-chamber view.
 */
const FOCUS = {
  anchor: [0.60, -0.62, 0.05] as [number, number, number],
  radius: 1.20,
  strength: 0.38,
  pulse: false,
};

/** Diastolic instant the manual mode holds the clock on (mitral naturally open,
 *  ventricle full — the pose the cutaway framing was chosen against). */
const FREEZE_PHASE = 0.9;

/** Seconds per beat once the solver takes over (machine mode). Calm and legible. */
const MACHINE_PERIOD = 1.2;

/**
 * The two columns, side-by-side on the right so their heights compare directly.
 *
 * Pulled inward and scaled down from their original spacing: this section's camera sits
 * close (z ≈ 4.05), and at full size a systolic LV column ran off BOTH the top and the
 * right edge of the frame with its readout clipped. `COLUMN_SCALE` must be applied to the
 * drag-handle mapping too (see `handleWorldY` / `dragPressure`) or the grab-points would
 * part company with the rendered liquid tops.
 */
const COLUMN_SCALE = 0.62;
const COLUMN_H = MANOMETER_COLUMN_HEIGHT * COLUMN_SCALE;
// Pulled further in with the closer framing: at the old x the LV column sat on the very
// edge of the frame and its readout clipped. These are world-space HUD, not heart-frame,
// so they do not move with the anatomy and have to be re-fitted whenever the camera does.
const LA_ANCHOR: [number, number, number] = [1.10, -1.05, 0];
const LV_ANCHOR: [number, number, number] = [1.46, -1.05, 0];
const LA_COLOR = '#7fa8ff'; // cool blue — the low-pressure upstream chamber
const LV_COLOR = '#ff5a4d'; // scarlet — the working ventricle

/** Half-width (mmHg) of the smooth ramp around a zero gradient where the leaflet
 *  transitions open↔shut, so the valve eases rather than snapping on a knife-edge. */
const DIODE_RAMP = 3;
/** How near the pointer ray must pass a column top to grab it (world units). Generous,
 *  because there is no drawn handle to aim at — the column top itself is the target. */
const HANDLE_GRAB_RADIUS = 0.34;

/** Valve-state badge, pinned to the LV exterior beside the cut. Re-measured against the
 *  diastolic base pose — see the base-pose note in ventricleLiquid.ts. */
const BADGE_ANCHOR = new THREE.Vector3(0.50, -0.50, 0.05);
const OPEN_COLOR = '#54e6b0'; // teal — flow allowed
const SHUT_COLOR = '#ff6a58'; // scarlet — flow blocked

/**
 * THE DIODE, MADE VISIBLE AS REAL FLUID.
 *
 * This section used to show blood as 16 dots drifting along the inflow path. It now
 * shares Act III's liquid system: a body of blood sitting in the LV cavity, and a real
 * stream through the mitral door whose strength comes from the reader's own gradient
 * pushed through the ENGINE'S OWN VALVE LAW — Q = (P_LA − P_LV) / R_valve, with R read
 * live off `engine.getParams().valveResistance`, not copied. So dragging the columns
 * produces genuine flow by exactly the rule the solver obeys; reverse the gradient and
 * the stream dies because the law says it must. Rule-driven, never keyframed.
 *
 * ⚠️ The POOL DELIBERATELY DOES NOT CHANGE SIZE in manual mode. Dragging pressure must
 * not move chamber volume — that coupling was ruled out here on purpose so §2 and the
 * Act III sections stay honest about what causes what. Your gradient controls FLOW;
 * volume only moves once the machine takes over and the solver is running the beat.
 */
const MANUAL_POOL_PRESSURE_REF = PRESSURE_SCALE;

const normalize = (name: string): string => name.toLowerCase().replace(/[^a-z0-9]/g, '');

/**
 * ⚠️ THE INSTRUCTION LIVES HERE; THE OUTCOME DOES NOT.
 *
 * The manual hint used to end "Push LV above LA and it slams shut — the blood just
 * piles up, blocked. You can’t force it open against the gradient." That is the
 * section's entire discovery, handed over before the reader has touched a column, and
 * it turned the drag into a demonstration of something they had already been told. It
 * now issues the challenge and lets the valve and its badge answer.
 */
const MANUAL_HINT =
  'The beat is paused and the two columns are yours. Drag the top of either one and ' +
  'watch the valve. Then try to make blood flow the wrong way, back up into the atrium.';
const MACHINE_HINT =
  'A real beat is running, and none of it is keyframed. The valve is obeying the ' +
  'pressure difference across it, moment to moment. Take the controls to make the ' +
  'columns yours.';

type Mode = 'manual' | 'machine';

export function createSection4(): SectionConfig {
  let mano: ManometerOverlay | null = null;
  let unsubFrame: (() => void) | null = null;

  // The single mitral leaflet we drive by hand in manual mode. Posed through the SAME
  // two morphs the rig uses, so the hand-driven leaflet and the solver-driven one can
  // never diverge (see heartRig.ts on why a valve needs both `open` and `closed`).
  let mitralMesh: THREE.Mesh | null = null;
  let mitralMorphs: ValveMorphs | null = null;

  /**
   * Draggable grab-points at the column tops (manual mode).
   *
   * These are PURE MATH — a live world position per column, with no mesh of their own.
   * They used to be glowing knob meshes, and that was a bug factory: the knobs were
   * built `depthTest:false` so they drew on top of everything unconditionally, and
   * `exit` never hid them (only `setMode` did), so scrolling away from this section
   * left two bright spheres floating over every later view. The column's own bobbing
   * meniscus already marks where the top is, so nothing needed to be drawn here at all
   * — and with no object in the scene there is nothing left to leak.
   */
  const handles: { pos: THREE.Vector3; anchor: THREE.Vector3; get: () => number; set: (p: number) => void }[] = [];

  // Reader-set pressures (mmHg) for manual mode. Start with a gentle forward
  // gradient so the valve begins open, matching the frozen diastolic pose.
  let laManual = 12;
  let lvManual = 6;

  let mode: Mode = 'machine';
  let active = false;
  let time = 0;
  // Dev: ?phase parks the beat (so machine-mode columns can be inspected at a chosen
  // instant instead of free-running); ?keystone=machine opens straight in machine
  // mode (headless can't click the toggle). Both default off — normal load is manual.
  let parked = false;

  // Valve-state HUD badge (on the chamber exterior) + the shared liquid system: a
  // body of blood in the LV and a real stream through the mitral door.
  let badge: StatusBadge | null = null;
  let pool: LiquidVolume | null = null;
  let jet: LiquidJet | null = null;
  /** LV volume the pool holds at in manual mode, and the beat's fullest volume. */
  let heldVolumeMl = 120;
  let lvRefMl = 120;
  /** Forward resistance of an open valve, mmHg·s/mL — read from the live engine. */
  let valveR = 0.006;

  /**
   * `InnerCap` (the always-seated inner cut surface) sits just in front of the LV
   * cavity and depth-rejects anything inside it, so any section showing blood in the
   * chamber must retire it — and restore it on the way out, since the heart is shared.
   * Same hard-won requirement as the Act III views (see ventricleLiquid.ts).
   */
  let innerCaps: THREE.Object3D[] = [];
  const setInnerCapVisible = (v: boolean): void => {
    for (const o of innerCaps) o.visible = v;
  };

  // Panel controls (built once in init).
  let hintEl: HTMLParagraphElement | null = null;
  let toggleBtn: HTMLButtonElement | null = null;

  /** Diode rule → leaflet closedness (0 open, 1 shut): open while LA out-pressures
   *  LV, shut once LV catches up, eased over DIODE_RAMP. */
  const closedness = (la: number, lv: number): number =>
    1 - THREE.MathUtils.smoothstep(la - lv, -DIODE_RAMP, DIODE_RAMP);

  const setMitral = (closed: number): void => {
    if (mitralMesh && mitralMorphs) setValvePose(mitralMesh, mitralMorphs, closed);
  };

  const handleWorldY = (anchor: THREE.Vector3, pressure: number): number =>
    anchor.y + THREE.MathUtils.clamp(pressure / MANOMETER_PMAX, 0, 1) * COLUMN_H;

  /** Track each grab-point to its column's current liquid top. */
  const positionHandles = (): void => {
    for (const h of handles) {
      h.pos.set(h.anchor.x, handleWorldY(h.anchor, h.get()), h.anchor.z);
    }
  };

  /** The mitral leaflet's live closedness (0 open → 1 shut): reflects the reader's
   *  hand in manual mode and the solver in machine mode (same morph either way). */
  const mitralClosed = (): number => {
    const infl = mitralMesh?.morphTargetInfluences;
    return infl && mitralMorphs ? infl[mitralMorphs.closedIndex]! : 0;
  };

  const updateBadge = (closed: number): void => {
    if (!badge) return;
    if (closed < 0.5) badge.setState('▸ OPEN · blood fills the LV', OPEN_COLOR);
    else badge.setState('■ SHUT · backflow blocked', SHUT_COLOR);
    badge.update();
  };

  /**
   * Mitral flow, mL/s, by the engine's own valve law. In manual mode the pressures are
   * the reader's; in machine mode we just read the solver's answer directly. `openness`
   * gates it so the stream ramps with the leaflet instead of switching on a knife-edge.
   */
  const mitralFlow = (ctx: SectionContext, openness: number): number => {
    if (mode === 'machine') return ctx.clock.sample().valves.mitral.flow;
    const gradient = Math.max(0, laManual - lvManual);
    return openness * (gradient / Math.max(1e-6, valveR));
  };

  /** Drive the pool + the stream. See MANUAL_POOL_PRESSURE_REF on why volume is held. */
  const updateLiquid = (dt: number, ctx: SectionContext, openness: number): void => {
    const flow = mitralFlow(ctx, openness);
    jet?.update(dt, flow);

    const machine = mode === 'machine';
    const s = machine ? ctx.clock.sample() : null;
    pool?.update(dt, {
      // Manual: held at the frozen diastolic volume — your gradient moves FLOW, not
      // volume. Machine: the solver's real mL, so the pool fills and empties for real.
      volumeMl: s ? s.volumes.LV : heldVolumeMl,
      refVolumeMl: lvRefMl,
      pressure01: THREE.MathUtils.clamp(
        (s ? s.pressures.LV : lvManual) / MANUAL_POOL_PRESSURE_REF, 0, 1,
      ),
      // Lean toward the mitral door it is being fed through, scaled by that same flow.
      lean: { dir: LV_TO_MITRAL, amount01: THREE.MathUtils.clamp(flow / 1300, 0, 1) },
      // Ride the wall in BOTH modes. In manual the pool's volume is deliberately frozen
      // while the muscle keeps moving, so this is the only thing keeping the held blood
      // inside the chamber rather than sliding out through it.
      wall01: ctx.scene.getWallInfluence(),
    });
  };

  const setMode = (next: Mode, ctx: SectionContext): void => {
    mode = next;
    if (hintEl) hintEl.textContent = next === 'manual' ? MANUAL_HINT : MACHINE_HINT;
    if (toggleBtn) {
      toggleBtn.textContent =
        next === 'manual' ? '▶  Let it run again' : '✋  Take the controls';
    }
    if (next === 'manual') {
      // Re-hold the diastolic pose; the reader's handles resume driving the leaflet.
      ctx.clock.setPhase(FREEZE_PHASE);
      setMitral(closedness(laManual, lvManual));
      positionHandles();
    }
    // In machine mode we simply stop overriding; the rig (subscribed to the clock)
    // takes the mitral leaflet back as the beat advances in onFrame.
  };

  /** Ray ↔ vertical column-line closest point → the pressure the reader is dragging
   *  to. View-independent, so it works from any orbit angle. */
  const dragPressure = (ray: THREE.Ray, anchor: THREE.Vector3): number => {
    // Closest point on the line {anchor + t·Y} to the ray {O + s·D}.
    const O = ray.origin;
    const D = ray.direction; // unit
    const b = D.y; // D · Yhat
    const wy = O.y - anchor.y; // (O − L0) · Yhat  (only y component matters)
    const denom = 1 - b * b; // a·c − b² with a=c=1
    const t = Math.abs(denom) < 1e-5 ? wy : (D.dot(new THREE.Vector3(O.x - anchor.x, wy, O.z - anchor.z)) * b - wy) / -denom;
    const clampedT = THREE.MathUtils.clamp(t, 0, COLUMN_H);
    return (clampedT / COLUMN_H) * MANOMETER_PMAX;
  };

  let detachDrag: (() => void) | null = null;

  const enableDrag = (ctx: SectionContext): void => {
    const dom = ctx.scene.renderer.domElement;
    const camera = ctx.scene.camera;
    const controls = ctx.scene.controls;
    const raycaster = new THREE.Raycaster();
    const ndc = new THREE.Vector2();
    let dragging: (typeof handles)[number] | null = null;

    const setRay = (e: PointerEvent): void => {
      const r = dom.getBoundingClientRect();
      ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
      raycaster.setFromCamera(ndc, camera);
    };
    const onDown = (e: PointerEvent): void => {
      if (!active || mode !== 'manual') return;
      setRay(e);
      // Grab whichever handle the ray passes nearest, if close enough.
      let best: (typeof handles)[number] | null = null;
      let bestD = HANDLE_GRAB_RADIUS;
      for (const h of handles) {
        const d = raycaster.ray.distanceToPoint(h.pos);
        if (d < bestD) { bestD = d; best = h; }
      }
      if (best) {
        dragging = best;
        controls.enabled = false;
        e.stopPropagation();
        dom.setPointerCapture?.(e.pointerId);
      }
    };
    const onMove = (e: PointerEvent): void => {
      if (!dragging) return;
      setRay(e);
      dragging.set(dragPressure(raycaster.ray, dragging.anchor));
      setMitral(closedness(laManual, lvManual));
      positionHandles();
    };
    const onUp = (): void => {
      if (!dragging) return;
      dragging = null;
      controls.enabled = true;
    };
    dom.addEventListener('pointerdown', onDown, { capture: true });
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    detachDrag = () => {
      dom.removeEventListener('pointerdown', onDown, { capture: true } as EventListenerOptions);
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
    };
  };

  /**
   * The volume the manual pool holds at, and the beat's fullest volume — both read off
   * the engine rather than guessed.
   *
   * Called on every entrance, not just at init: §8 hands the reader contractility and
   * afterload knobs whose changes PERSIST across sections (one heart, one operating
   * point). A reader who raises contractility and scrolls back here would otherwise see
   * a pool scaled to a beat the engine no longer has — EDV moves 172 → 101 mL across
   * that knob's travel, so the error is large, not cosmetic.
   */
  const readPoolVolumes = (ctx: SectionContext): void => {
    const engine = ctx.clock.getEngine();
    heldVolumeMl = engine.sample(FREEZE_PHASE).volumes.LV;
    let lvMax = 1;
    for (let i = 0; i < 120; i++) {
      const v = engine.sample(i / 120).volumes.LV;
      if (v > lvMax) lvMax = v;
    }
    lvRefMl = lvMax;
  };

  const buildPanelControls = (ctx: SectionContext): void => {
    // `.section-extra`, not `.section-content` — the panel's `More` reveal is appended
    // after that slot, and the mode toggle must not end up below it.
    const content = ctx.panel.querySelector('.section-extra');
    if (!content || content.querySelector('.keystone-controls')) return;
    const wrap = document.createElement('div');
    wrap.className = 'keystone-controls';
    hintEl = document.createElement('p');
    hintEl.className = 'keystone-hint';
    hintEl.textContent = MACHINE_HINT;
    toggleBtn = document.createElement('button');
    toggleBtn.className = 'keystone-toggle';
    toggleBtn.type = 'button';
    toggleBtn.textContent = '✋  Take the controls';
    toggleBtn.addEventListener('click', () => setMode(mode === 'manual' ? 'machine' : 'manual', ctx));
    wrap.append(hintEl, toggleBtn);
    content.appendChild(wrap);
  };

  return {
    id: 'keystone',
    title: 'Pressure is the driver',
    /**
     * The keystone is the one section where stating the rule outright is right: the rule
     * is the PREMISE, not the payoff. The discovery here is that you cannot break it,
     * and that is left to the reader's hands and the valve badge.
     *
     * The blurb still opens on the SETUP (there is no decider) rather than the rule,
     * because the missing decider is the question the rest of the panel answers.
     */
    blurb:
      'Nothing in the heart decides when a valve should open. A valve is just a flap ' +
      'in a doorway. So something else must be doing it.',
    more: [
      'There is no signal, no trigger and no timer. That leaves one candidate: the ' +
        'pressure on either side of the flap.',
      'One rule, running all beat long. Watch it work, then see if you can break it.',
    ],
    framing: { position: [...FRAMING.position], target: [...FRAMING.target] },
    cutaway: KEYSTONE_CUTAWAY,
    focus: FOCUS,

    init: (ctx: SectionContext) => {
      parked = new URLSearchParams(window.location.search).has('phase');
      const heart = ctx.scene.getHeart();
      if (heart) {
        heart.traverse((obj) => {
          const mesh = obj as THREE.Mesh;
          if (!mesh.isMesh || normalize(mesh.name) !== 'mitralvalve') return;
          const morphs = findValveMorphs(mesh);
          if (morphs) {
            mitralMesh = mesh;
            mitralMorphs = morphs;
          }
        });
      }

      // LA + LV manometer columns, driven by the reader's handles in manual mode and
      // by the clock in machine mode (the volume line shows only once the machine runs).
      mano = new ManometerOverlay(ctx.scene, ctx.clock, [
        {
          compartment: 'LA', anchor: LA_ANCHOR, label: 'LA', color: LA_COLOR,
          sublabel: 'left atrium',
          pressure: () => (mode === 'manual' ? laManual : ctx.clock.sample().pressures.LA),
        },
        {
          compartment: 'LV', anchor: LV_ANCHOR, label: 'LV', color: LV_COLOR,
          sublabel: 'left ventricle',
          pressure: () => (mode === 'manual' ? lvManual : ctx.clock.sample().pressures.LV),
          volume: () => (mode === 'manual' ? null : ctx.clock.sample().volumes.LV),
        },
      ], { scale: COLUMN_SCALE });

      // Column-top grab-points (positions only — nothing is drawn; see `handles`).
      const mkHandle = (anchor: [number, number, number], get: () => number, set: (p: number) => void) => {
        handles.push({ pos: new THREE.Vector3(), anchor: new THREE.Vector3(...anchor), get, set });
      };
      mkHandle(LA_ANCHOR, () => laManual, (p) => { laManual = p; });
      mkHandle(LV_ANCHOR, () => lvManual, (p) => { lvManual = p; });
      positionHandles();

      // Valve-state badge on the chamber exterior.
      badge = new StatusBadge(ctx.scene, BADGE_ANCHOR, 'Mitral valve', {
        frame: ctx.scene.getHeartFrame(),
      });

      // The shared liquid system. Added to the heart frame (identity here — this
      // section declares no turn — but correct if it ever gets one).
      innerCaps = findInnerCaps(ctx.scene);
      valveR = ctx.clock.getEngine().getParams().valveResistance;
      pool = new LiquidVolume({ ...LV_CAVITY });
      ctx.scene.getHeartFrame().add(pool.mesh);
      jet = createValveJet('mitral');
      if (jet) ctx.scene.getHeartFrame().add(jet.mesh);

      readPoolVolumes(ctx);

      buildPanelControls(ctx);
      enableDrag(ctx);

      // One per-frame driver, gated on being the active view. Manual: hold the pose
      // and drive the leaflet + handles from the reader's pressures. Machine: advance
      // the ONE clock (solver debut). The gradient reads off the two column heights +
      // the blood flow (through when open, blocked when shut) — no separate arrow.
      unsubFrame = ctx.scene.onFrame((dt) => {
        if (!active) return;
        time += dt;
        if (mode === 'machine') {
          if (!parked) ctx.clock.setPhase(ctx.clock.getPhase() + dt / MACHINE_PERIOD);
        } else {
          setMitral(closedness(laManual, lvManual));
          positionHandles();
        }
        const closed = mitralClosed();
        updateBadge(closed);
        updateLiquid(dt, ctx, 1 - closed);
      });
    },

    enter: (ctx: SectionContext) => {
      const { scene, panel } = ctx;
      const search = new URLSearchParams(window.location.search);
      const headless = search.get('intro') === '0';
      panel.classList.add('is-active');
      document.body.classList.add('keystone-active'); // suppress the hero-only chrome
      active = true;
      // Always open RUNNING — the reader sees the rule hold before being asked to test
      // it. `?keystone=manual` is a dev shortcut into the drag mode (headless can't
      // click the toggle).
      const start: Mode = search.get('keystone') === 'manual' ? 'manual' : 'machine';
      setMode(start, ctx);
      readPoolVolumes(ctx); // the operating point may have moved since init — see above
      // Let the camera actually reach this section's push-in. Without this
      // OrbitControls silently drags it back out to 3 on the very next frame.
      scene.controls.minDistance = scaleDistance(KEYSTONE_MIN_DISTANCE);
      mano?.show();
      badge?.show();
      pool?.show();
      setInnerCapVisible(false); // or the blood inside the cavity is depth-rejected

      // Own the reveal: dissolve the anterior wall on entrance so the mitral valve is
      // exposed (the section can't teach a valve behind a closed wall). Animated live;
      // snapped for headless, where Edge can't advance the GSAP tween. §4 asserts this
      // itself so the reveal never depends on the manager's activation timing.
      scene.getCutaway()?.set(KEYSTONE_CUTAWAY, { animate: !headless });

      // ?intro=0 also snaps the camera; live, the manager's eased camera entrance plays.
      if (headless) {
        {
          // Through `scaleFraming`, or a headless render at a non-reference size would snap to
          // the unscaled pose and disagree with what the live ease produces.
          const snap = scaleFraming(FRAMING);
          scene.camera.position.set(...snap.position);
          scene.controls.target.set(...snap.target);
        }
        scene.controls.enabled = true;
        scene.controls.update();
      }
    },

    exit: (ctx: SectionContext) => {
      active = false;
      ctx.panel.classList.remove('is-active');
      document.body.classList.remove('keystone-active');
      mano?.hide();
      badge?.hide();
      pool?.hide();
      jet?.hide();
      setInnerCapVisible(true); // leave the shared heart exactly as we found it
      ctx.scene.controls.minDistance = scaleDistance(DEFAULT_MIN_DISTANCE); // the floor is shared
      ctx.scene.getCutaway()?.set(0, { animate: true }); // close the wall back up on the way out
    },

    dispose: (ctx: SectionContext) => {
      active = false;
      unsubFrame?.();
      unsubFrame = null;
      detachDrag?.();
      detachDrag = null;
      mano?.dispose();
      mano = null;
      badge?.dispose();
      badge = null;
      setInnerCapVisible(true); // never leave the shared heart missing a wall piece
      ctx.scene.controls.minDistance = scaleDistance(DEFAULT_MIN_DISTANCE); // restored on BOTH paths
      innerCaps = [];
      const frame = ctx.scene.getHeartFrame();
      if (pool) {
        frame.remove(pool.mesh);
        pool.dispose();
        pool = null;
      }
      if (jet) {
        frame.remove(jet.mesh);
        jet.dispose();
        jet = null;
      }
      handles.length = 0; // plain positions — nothing in the scene to remove
    },
  };
}
