import * as THREE from 'three';
import type { HeartScene } from '../index.ts';
import type { ConductionLandmark } from '../../engine/index.ts';

/**
 * The conduction system, lit landmark by landmark as the wave passes — SPEC §5.
 *
 * ⚠️⚠️ WHY THIS IS A DRAWN PATH AND NOT A GLOWING MESH. The obvious plan, and the
 * one the previous handoff proposed, was to generalise `AtrialGlow`'s
 * borrow-a-material-clone trick along the conduction path. IT CANNOT WORK. This
 * model has twelve meshes (see MODEL_FIT.md) and FOUR of the six conduction
 * landmarks have no mesh at all: there is no SA node, no AV node, no septum and no
 * apex — `Ventricles` is a single mesh with the septum buried inside it. Swapping
 * materials can therefore light exactly two of the six landmarks. This is the §5
 * analogue of §3's impossible base-of-heart view and §7's un-openable RV: the model
 * decides what is showable.
 *
 * So the conduction system is drawn as what it actually is — a distinct tissue
 * threaded through the muscle, anatomically a network of specialised fibres rather
 * than part of the wall. Each landmark is its own glowing segment driven by
 * `EngineState.electricalWave.levels[landmark]`, so the wave sweeps as a real
 * travelling front with a tail behind it, and the two landmarks that DO have meshes
 * are lit by `AtrialGlow` on top of this (the section wires that up), which is what
 * makes the muscle read as contracting just behind the light.
 *
 * ⚠️ PARENTED TO `scene.getHeartFrame()`, never `scene.scene` — this is an in-heart
 * overlay and it must follow a section's heart turn (see heartOrientation.ts). The
 * documented trap.
 *
 * ⚠️ THE COORDINATES BELOW ARE ANATOMICAL ESTIMATES — the model has no conduction
 * geometry to measure — but they are no longer freehand. The ventricular runs are laid
 * on the chamber's REAL subendocardial surface: `.work/probe_purkinje.py` walks the
 * ventricular long axis apex → base and reports, at each height, how far the wall
 * reaches toward the left heart (+X/−Z), the right heart (−X/+Z) and posteriorly. Each
 * waypoint sits at 0.72 of that reach, so the Purkinje network hugs the inside of the
 * chambers instead of cutting through them.
 *
 * ⚠️ THEY ALL MOVED when the model's base pose was corrected from source frame 10 (peak
 * systole) to frame 5 (end-diastole). The measured apex is now [0.382,−1.150,0.460].
 *
 * ⚠️⚠️ AND DO NOT TRY TO RE-DERIVE THE APP FRAME BY REASONING — MEASURE IT. Two separate
 * Blender-side attempts at reproducing `heartModel.ts`'s fit both disagreed with what the
 * app renders, and the second failure left this entire path visibly dangling BELOW the
 * heart. The cause: three's `computeBoundingBox()` inflates a geometry's box once per
 * morph target, so `Box3.getBoundingSphere()` — and therefore the model's fit scale —
 * DEPENDS ON HOW MANY MORPH TARGETS THE MODEL HAS. The exact transform was solved against
 * the app's own reported bounds instead (`.work/probe_appframe.py`):
 *
 *     app = (gltf_three − C) * S    C = (−0.08839, 0.18193, 0.07500)   S = 6.39455
 *
 * If the model is ever re-exported with a different morph count, re-solve it the same way
 * (there is a temporary `?probe=1` hook documented in HANDOFF) rather than assuming.
 */

/** Cycle-phase-independent geometry of the path, in model space. */
const NODES = {
  /** SA node — high right atrium at the superior cavoatrial junction. */
  sa: new THREE.Vector3(-0.38, -0.10, 0.02),
  /** AV node — low interatrial septum, just above the measured tricuspid annulus. */
  av: new THREE.Vector3(-0.18, -0.50, 0.04),
} as const;

/**
 * Per-landmark polylines. Each is swept into a tube and lit independently.
 * `atria` fans from the SA node across both atrial walls toward the AV node;
 * `ventricles` is the Purkinje spread running back UP the walls from the apex.
 *
 * ⚠️ EVERY POLYLINE OF A LANDMARK IS TRAVELLED, not just the first. The spark used to
 * be a single mesh placed by `curves.find(...)`, which returns the FIRST match — so of
 * the ventricles' runs only the left free wall ever lit up, and the right ventricle
 * looked like it had been left out of the beat. There is now one spark per run, which
 * is also the physiologically honest picture: the bundle branches fire in PARALLEL, so
 * the wave should be seen racing up both sides at once, not queuing.
 */
const SEGMENTS: Record<Exclude<ConductionLandmark, 'sa-node' | 'av-node'>, THREE.Vector3[][]> = {
  // Both atria depolarise from the node outward — drawn as two arcs so the sweep
  // reads as spreading through tissue rather than following a single wire.
  atria: [
    [
      new THREE.Vector3(-0.38, -0.10, 0.02),
      new THREE.Vector3(-0.40, -0.24, 0.14),
      new THREE.Vector3(-0.31, -0.39, 0.14),
      new THREE.Vector3(-0.18, -0.50, 0.04),
    ],
    [
      new THREE.Vector3(-0.38, -0.10, 0.02),
      new THREE.Vector3(-0.30, -0.22, -0.10),
      new THREE.Vector3(-0.19, -0.37, -0.10),
      new THREE.Vector3(-0.18, -0.50, 0.04),
    ],
  ],
  // His bundle: a short common trunk descending from the AV node into the
  // interventricular septum, straight down the chamber's own long axis.
  septum: [
    [
      new THREE.Vector3(-0.180, -0.500, 0.040),
      new THREE.Vector3(-0.068, -0.630, 0.124),
      new THREE.Vector3(0.045, -0.760, 0.208),
    ],
  ],
  // Left and right bundle branches, straddling the septum down to their own apices.
  // The right branch ends on the RV side (its real termination near the moderator
  // band), not at the LV apex — which is why it can then wrap the right ventricle.
  apex: [
    [
      new THREE.Vector3(0.045, -0.760, 0.208),
      new THREE.Vector3(0.306, -0.970, 0.260),
      new THREE.Vector3(0.382, -1.150, 0.460),
    ],
    [
      new THREE.Vector3(0.045, -0.760, 0.208),
      new THREE.Vector3(0.120, -0.940, 0.408),
      new THREE.Vector3(0.203, -1.083, 0.554),
    ],
  ],
  // Purkinje network: apex → base, up BOTH ventricles. This is the direction that
  // surprises readers, so it is drawn generously — four runs, two per chamber, so
  // each free wall is genuinely wrapped rather than traced by a single line.
  ventricles: [
    // LV free wall (lateral)
    [
      new THREE.Vector3(0.464, -1.124, 0.345),
      new THREE.Vector3(0.490, -0.950, 0.099),
      new THREE.Vector3(0.410, -0.751, -0.073),
      new THREE.Vector3(0.318, -0.566, -0.216),
    ],
    // LV posterior wall
    [
      new THREE.Vector3(0.352, -1.122, 0.416),
      new THREE.Vector3(0.154, -1.036, 0.152),
      new THREE.Vector3(-0.009, -0.907, -0.078),
      new THREE.Vector3(-0.081, -0.716, -0.207),
    ],
    // RV free wall
    [
      new THREE.Vector3(0.203, -1.083, 0.554),
      new THREE.Vector3(-0.053, -0.864, 0.532),
      new THREE.Vector3(-0.186, -0.656, 0.403),
      new THREE.Vector3(-0.272, -0.472, 0.255),
    ],
    // RV wrap — spirals from the right free wall around toward the posterior septum,
    // so the right ventricle is enclosed rather than brushed down one edge.
    [
      new THREE.Vector3(0.203, -1.083, 0.554),
      new THREE.Vector3(-0.063, -1.008, 0.395),
      new THREE.Vector3(-0.126, -0.964, 0.057),
      new THREE.Vector3(-0.078, -0.774, -0.164),
    ],
  ],
};

/** Most polylines any one landmark has — the size of the spark pool. */
const MAX_RUNS = 4;

/** Order the spark travels, and the order `progress` indexes. */
const PATH_ORDER: ConductionLandmark[] = [
  'sa-node',
  'atria',
  'av-node',
  'septum',
  'apex',
  'ventricles',
];

/**
 * ⚠️ 0.016, between the 0.012 that was invisible and the 0.022 that was too fat.
 * At 0.022 the tubes read as PIPES — the same apparent weight as the chordae
 * tendineae a few pixels away in the same frame, which is the one thing this overlay
 * must not look like. A conduction fibre should read as a wire, not as plumbing.
 */
const TUBE_RADIUS = 0.016;
const NODE_RADIUS = 0.042;
/**
 * Always-on level so the path reads as anatomy that is present before it fires.
 *
 * ⚠️ 0.20, after 0.14 (invisible) and 0.34 (too hot). Additive blending over
 * brightly-lit red myocardium needs far more signal than it does over a dark
 * background, and most of this path lies over exactly that — but pushed too high the
 * resting state is nearly as bright as the fired one, which throws away the whole
 * point of a travelling wave. Judge any change against a frame where the wave has
 * already passed (late ejection), when every segment sits at this level and nothing
 * is firing.
 */
const RESTING_LEVEL = 0.24;

/**
 * ⚠️ AN ELECTRIC CYAN, DELIBERATELY THE ONE COOL THING IN A WARM FRAME — and this
 * started as a warm gold (#ffd479), which failed for a specific, instructive reason.
 * Additive blending drove the gold to near-white over lit myocardium, at which point
 * the path was indistinguishable from the CHORDAE TENDINEAE visible in the same shot:
 * pale, tube-shaped, threaded through the chamber. A reader cannot be asked to tell a
 * nerve-like signal path from a tendon by shape alone.
 *
 * Cool separates it from every other thing on screen — the myocardium's red, the
 * atria's mauve, the vessels' crimson and blue-purple, the valves' bone white — so it
 * reads as what it is: not tissue, but a signal moving through tissue. It also agrees
 * with the section's own blue AV-stall badge. If a warm palette is preferred on the
 * live pass this is a one-constant change, but re-check it against the chordae.
 */
const PATH_COLOR = '#8fe3ff';
const SPARK_COLOR = '#f2ffff';

/**
 * A lightning-bolt glyph marking each NODE, so the two pacemaker sites read as
 * electrical rather than as two more anatomical lumps on a pale tube.
 *
 * The path is drawn as tissue-coloured tubing because that is what it anatomically is,
 * which leaves the reader nothing that says "this is a SIGNAL" except the colour. A
 * bolt is the one symbol that needs no caption. Drawn to a canvas rather than shipped as
 * an asset: it is nine line segments, and an external file would need a CREDITS entry
 * and a load path for something we can draw in twenty lines.
 *
 * ⚠️ Sprites, so they always face the reader. A flat plane would edge-on to nothing at
 * the framings §5 uses, and the nodes are exactly where the reader is being told to look.
 */
const BOLT_SIZE = 0.30;

function boltTexture(): THREE.CanvasTexture {
  const S = 128;
  const canvas = document.createElement('canvas');
  canvas.width = S;
  canvas.height = S;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    // Classic bolt, in a 0–1 box then scaled — drawn white so the material's colour
    // (and the additive blend) decides how it actually reads.
    const pts: Array<[number, number]> = [
      [0.58, 0.06], [0.26, 0.54], [0.46, 0.54],
      [0.38, 0.94], [0.74, 0.42], [0.52, 0.42],
    ];
    ctx.beginPath();
    ctx.moveTo(pts[0]![0] * S, pts[0]![1] * S);
    for (const [x, y] of pts.slice(1)) ctx.lineTo(x * S, y * S);
    ctx.closePath();
    // A soft outer glow first, then the solid bolt, so it survives being drawn over
    // brightly-lit myocardium (the same signal problem the tubes had).
    ctx.shadowColor = 'rgba(255,255,255,0.95)';
    ctx.shadowBlur = S * 0.14;
    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.fill();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

interface Lit {
  landmark: ConductionLandmark;
  material: THREE.MeshBasicMaterial;
  /** The bright, correctly-occluded copy's material, when the x-ray pass is on. */
  ghost: THREE.MeshBasicMaterial | null;
}

export interface ConductionPathOptions {
  /**
   * Strength of the depth-IGNORING copy, which is what actually carries this overlay.
   *
   * ⚠️⚠️ 0.9 BY DEFAULT — this is the primary read, not a supplement, and two renders
   * were needed to understand why. The conduction system is INTRAMURAL: the His bundle
   * and both bundle branches run inside the septum, and the Purkinje network runs
   * inside the ventricular walls. So a depth-tested path is correctly occluded almost
   * everywhere, which means it is invisible almost everywhere — at 0.3 the section's
   * named subject could not be seen even at the instant the badge said it was firing.
   *
   * Turning it up is not a cheat, it is the honest depiction: this is how cardiac
   * activation is always shown, and how it has to be shown, because the structure is
   * buried by nature. The depth-tested pass is still drawn on top, so where the path
   * genuinely is exposed (the atrial runs, across the open cutaway) it reads as solid
   * and correctly in front of / behind the anatomy.
   *
   * ⚠️ This is the section's top open question for a live pass — an x-ray overlay at
   * this strength can start to read as floating in front of the heart rather than
   * threaded through it. Set 0 for a purely occluded path if that is preferred.
   */
  xray?: number;
}

export class ConductionPath {
  private readonly group = new THREE.Group();
  private readonly lit: Lit[] = [];
  /** One spark per concurrent run — see MAX_RUNS and the SEGMENTS note. */
  private readonly sparks: THREE.Mesh[] = [];
  private readonly sparkMaterials: THREE.MeshBasicMaterial[] = [];
  /** Landmark → all of its polylines, so every branch can be travelled at once. */
  private readonly runs = new Map<ConductionLandmark, THREE.CatmullRomCurve3[]>();
  /** The two node bolts, brightened by their own landmark's excitation. */
  private readonly bolts: Array<{ landmark: ConductionLandmark; material: THREE.SpriteMaterial }> =
    [];
  private readonly xray: number;
  private readonly disposables: Array<{ dispose(): void }> = [];
  private shown = false;
  /** Smoothed levels, so a scrub jump eases instead of strobing. */
  private readonly smoothed = new Map<ConductionLandmark, number>();

  constructor(scene: HeartScene, opts: ConductionPathOptions = {}) {
    this.xray = opts.xray ?? 0.9;
    const color = new THREE.Color(PATH_COLOR);

    const addPiece = (landmark: ConductionLandmark, geometry: THREE.BufferGeometry): void => {
      this.disposables.push(geometry);
      const material = new THREE.MeshBasicMaterial({
        color: color.clone(),
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      });
      this.disposables.push(material);
      this.group.add(new THREE.Mesh(geometry, material));

      let ghost: THREE.MeshBasicMaterial | null = null;
      if (this.xray > 0) {
        ghost = new THREE.MeshBasicMaterial({
          color: color.clone(),
          transparent: true,
          opacity: 0,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
          depthTest: false,
        });
        this.disposables.push(ghost);
        const ghostMesh = new THREE.Mesh(geometry, ghost);
        // Behind the solid pass, so the bright copy always wins where both show.
        ghostMesh.renderOrder = -1;
        this.group.add(ghostMesh);
      }
      this.lit.push({ landmark, material, ghost });
    };

    const addRun = (landmark: ConductionLandmark, curve: THREE.CatmullRomCurve3): void => {
      const list = this.runs.get(landmark);
      if (list) list.push(curve);
      else this.runs.set(landmark, [curve]);
    };

    // The two nodes are points, not runs — a small sphere plus a bolt glyph.
    const boltMap = boltTexture();
    this.disposables.push(boltMap);
    for (const [landmark, position] of [
      ['sa-node', NODES.sa],
      ['av-node', NODES.av],
    ] as Array<[ConductionLandmark, THREE.Vector3]>) {
      const geometry = new THREE.SphereGeometry(NODE_RADIUS, 20, 14);
      geometry.translate(position.x, position.y, position.z);
      addPiece(landmark, geometry);
      addRun(landmark, new THREE.CatmullRomCurve3([position.clone(), position.clone()]));

      const boltMaterial = new THREE.SpriteMaterial({
        map: boltMap,
        color: color.clone(),
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        // Same reasoning as the tubes' x-ray pass: both nodes are buried in the
        // atrial wall, so a depth-tested bolt is occluded exactly when it matters.
        depthTest: false,
      });
      this.disposables.push(boltMaterial);
      const sprite = new THREE.Sprite(boltMaterial);
      sprite.position.copy(position);
      sprite.scale.setScalar(BOLT_SIZE);
      sprite.renderOrder = 3;
      this.group.add(sprite);
      this.bolts.push({ landmark, material: boltMaterial });
    }

    for (const [landmark, polylines] of Object.entries(SEGMENTS) as Array<
      [ConductionLandmark, THREE.Vector3[][]]
    >) {
      for (const points of polylines) {
        const curve = new THREE.CatmullRomCurve3(points.map((p) => p.clone()));
        addPiece(landmark, new THREE.TubeGeometry(curve, 48, TUBE_RADIUS, 8, false));
        addRun(landmark, curve);
      }
    }

    // A pool of sparks, one per branch that can be live at the same instant.
    const sparkGeometry = new THREE.SphereGeometry(NODE_RADIUS * 1.25, 18, 12);
    this.disposables.push(sparkGeometry);
    for (let i = 0; i < MAX_RUNS; i++) {
      const material = new THREE.MeshBasicMaterial({
        color: new THREE.Color(SPARK_COLOR),
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        depthTest: false,
      });
      this.disposables.push(material);
      const mesh = new THREE.Mesh(sparkGeometry, material);
      mesh.renderOrder = 2;
      mesh.visible = false;
      this.group.add(mesh);
      this.sparks.push(mesh);
      this.sparkMaterials.push(material);
    }

    this.group.visible = false;
    // ⚠️ The heart FRAME, not the scene — an in-heart overlay has to follow the
    // section's heart turn.
    scene.getHeartFrame().add(this.group);
  }

  show(): void {
    this.shown = true;
    this.group.visible = true;
  }

  hide(): void {
    this.shown = false;
    this.group.visible = false;
    this.smoothed.clear();
  }

  /**
   * Light each landmark from the engine's per-landmark excitation, and slide the
   * spark along the path by the wave's overall progress.
   *
   * Eased per landmark: the reader can jump the playhead anywhere on the ECG, and a
   * step from 0 to 1 between two frames reads as a flash rather than as a wave
   * arriving.
   */
  update(dt: number, levels: Record<ConductionLandmark, number>, progress: number): void {
    if (!this.shown) return;

    for (const piece of this.lit) {
      const target = THREE.MathUtils.clamp(levels[piece.landmark] ?? 0, 0, 1);
      const previous = this.smoothed.get(piece.landmark) ?? 0;
      // Fast toward a bright target (depolarisation is abrupt), gentler away from it.
      const rate = target > previous ? 22 : 8;
      const next = THREE.MathUtils.lerp(previous, target, Math.min(1, dt * rate));
      this.smoothed.set(piece.landmark, next);
      const level = RESTING_LEVEL + (1 - RESTING_LEVEL) * next;
      piece.material.opacity = level;
      if (piece.ghost) piece.ghost.opacity = level * this.xray;
    }

    // The node bolts flare with their own landmark, so the SA node visibly fires the
    // beat and the AV node visibly sits holding.
    for (const bolt of this.bolts) {
      const level = this.smoothed.get(bolt.landmark) ?? 0;
      bolt.material.opacity = 0.30 + 0.70 * level;
    }

    // The sparks ride whichever landmark the front is in, so they track the same
    // schedule the segments do rather than interpolating along a separate arc.
    //
    // ⚠️ ALL of that landmark's runs get one, not just the first. The bundle branches
    // conduct in parallel, so the wave has to be seen going up both ventricles at once.
    const n = PATH_ORDER.length;
    const scaled = THREE.MathUtils.clamp(progress, 0, 1) * n;
    const index = Math.min(n - 1, Math.floor(scaled));
    const within = THREE.MathUtils.clamp(scaled - index, 0, 1);
    const landmark = PATH_ORDER[index] as ConductionLandmark;
    const active = this.runs.get(landmark) ?? [];
    // Bright only while the front is actually moving through the path; it should not
    // sit parked at the end of the ventricles for half the beat.
    const frontLevel = this.smoothed.get(landmark) ?? 0;
    const opacity = progress >= 1 ? 0 : frontLevel;
    for (let i = 0; i < this.sparks.length; i++) {
      const curve = active[i];
      const spark = this.sparks[i]!;
      if (!curve || opacity <= 0.001) {
        spark.visible = false;
        continue;
      }
      spark.visible = true;
      spark.position.copy(curve.getPointAt(within));
      this.sparkMaterials[i]!.opacity = opacity;
    }
  }

  dispose(): void {
    this.hide();
    this.group.removeFromParent();
    for (const d of this.disposables) d.dispose();
    this.disposables.length = 0;
    this.lit.length = 0;
    this.sparks.length = 0;
    this.sparkMaterials.length = 0;
    this.bolts.length = 0;
    this.runs.clear();
  }
}
