import * as THREE from 'three';
import type { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { createRenderer, createCamera } from './renderer.ts';
import { createLighting } from './lighting.ts';
import { createHeartEnvironment } from './environment.ts';
import { createControls } from './controls.ts';
import { createPlaceholderHeart } from './heartPlaceholder.ts';
import { loadHeartModel } from './heartModel.ts';
import { CutawayController } from './cutaway.ts';
import { HeartOrientation } from './heartOrientation.ts';

/**
 * The one persistent scene (BUILD_PLAN §2, "The scene" pillar).
 *
 * Owns the single renderer, camera, lighting rig, controls, and — for now — the
 * placeholder heart. Exposes `start()` / `stop()` so the render loop can be
 * paused: today there is one always-visible scene, but the section framework
 * (Phase 4) will lazy-init and pause off-screen views, and this is the seam it
 * hooks into (PERFORMANCE invariant).
 */
export class HeartScene {
  readonly renderer: THREE.WebGLRenderer;
  readonly scene: THREE.Scene;
  readonly camera: THREE.PerspectiveCamera;
  readonly controls: OrbitControls;

  /** Resolves once the heart model has loaded (or fallen back). */
  readonly ready: Promise<void>;

  /** Diagnostics (Phase 3 troubleshooting): populated by loadHeart(). */
  loadError: unknown = null;
  usingPlaceholder = false;

  /**
   * A rotation-only companion to the heart group: no scale, no translation, just the
   * same turn (see `heartOrientation.ts`). In-heart overlays — the blood bodies, the
   * liquid jets, the closure blooms — are added HERE rather than straight to the
   * scene, so their hand-measured world anchors stay valid when a section turns the
   * heart. World-space HUD furniture (the manometer columns) must NOT go in here.
   */
  readonly heartFrame = new THREE.Group();

  private readonly canvas: HTMLCanvasElement;
  private heartGroup: THREE.Group | null = null;
  private wallInfluence: (() => number) | null = null;
  private cutawayCtl: CutawayController | null = null;
  private orientation: HeartOrientation | null = null;
  private rafId: number | null = null;
  private running = false;
  private lastFrameTime = 0;
  private readonly frameCallbacks = new Set<(dt: number) => void>();
  private readonly onResize = () => this.resize();

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.scene = new THREE.Scene();

    this.renderer = createRenderer(canvas);
    this.camera = createCamera(this.aspect());
    this.controls = createControls(this.camera, canvas);

    // Warm image-based environment for moist PBR speculars (Cinematic Anatomical).
    this.scene.environment = createHeartEnvironment(this.renderer);
    this.scene.add(createLighting());
    // Exists from the start (overlays may be built before/independently of the model
    // load) and simply sits at identity until a section asks for a turn.
    this.heartFrame.name = 'heart-frame';
    this.scene.add(this.heartFrame);
    this.ready = this.loadHeart();

    this.resize();
    window.addEventListener('resize', this.onResize);
  }

  /** The loaded heart group, or null until `ready` resolves. */
  getHeart(): THREE.Group | null {
    return this.heartGroup;
  }

  /** The authored-cutaway controller, or null (placeholder / not yet loaded). */
  getCutaway(): CutawayController | null {
    return this.cutawayCtl;
  }

  /**
   * The rotation-only frame that mirrors the heart's turn. In-heart overlays add
   * themselves here so their world-measured anchors survive a section's rotation.
   */
  getHeartFrame(): THREE.Group {
    return this.heartFrame;
  }

  /** Per-section heart turn, or null (placeholder / not yet loaded). */
  getOrientation(): HeartOrientation | null {
    return this.orientation;
  }

  /**
   * Publish the rig's ventricular wall weight so overlays living INSIDE the ventricle
   * can move with the muscle. `bindHeartToClock` computes it (0 at end-diastole → 1 at
   * end-systole) as the weight it feeds the `ventricle_systole` morph; main.ts hands it
   * over here once the binding exists.
   *
   * ⚠️ Anything that has to stay inside a contracting chamber must read THIS rather than
   * re-deriving the same normalization from the clock. The blood pools did not have it,
   * so the wall came in and the liquid stayed put and slid out through the muscle. One
   * number, one source — the same discipline the engine gets for timing.
   */
  setWallInfluence(fn: () => number): void {
    this.wallInfluence = fn;
  }

  /** How far the ventricular wall is through its contraction, 0 → 1. */
  getWallInfluence(): number {
    return this.wallInfluence?.() ?? 0;
  }

  /** Load the real anatomical heart; fall back to the placeholder on failure. */
  private async loadHeart(): Promise<void> {
    try {
      const heart = await loadHeartModel();
      this.heartGroup = heart;
      this.scene.add(heart);
      this.cutawayCtl = new CutawayController(heart);
      this.orientation = new HeartOrientation(heart, this.heartFrame);
    } catch (err) {
      console.error('Failed to load heart model; using placeholder.', err);
      this.loadError = err;
      this.usingPlaceholder = true;
      this.scene.add(createPlaceholderHeart());
    }
  }

  /**
   * Register a per-frame callback (receives the frame delta in seconds). Overlays
   * that animate independently of the beat — flowing blood, particle motion — hook
   * here rather than owning their own render loop. Returns an unsubscribe.
   */
  onFrame(cb: (dt: number) => void): () => void {
    this.frameCallbacks.add(cb);
    return () => this.frameCallbacks.delete(cb);
  }

  /** Begin the render loop. Idempotent. */
  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastFrameTime = performance.now();
    const loop = (now: number) => {
      if (!this.running) return;
      this.rafId = requestAnimationFrame(loop);
      const dt = Math.min(0.05, (now - this.lastFrameTime) / 1000); // clamp tab-away gaps
      this.lastFrameTime = now;
      for (const cb of this.frameCallbacks) cb(dt);
      this.controls.update(); // damping needs a per-frame update
      this.renderer.render(this.scene, this.camera);
    };
    this.rafId = requestAnimationFrame(loop);
  }

  /** Pause the render loop and stop consuming the GPU. Idempotent. */
  stop(): void {
    this.running = false;
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }

  /** Tear down listeners and GPU resources. */
  dispose(): void {
    this.stop();
    window.removeEventListener('resize', this.onResize);
    this.controls.dispose();
    this.renderer.dispose();
  }

  private aspect(): number {
    return this.canvas.clientWidth / Math.max(1, this.canvas.clientHeight);
  }

  private resize(): void {
    const width = this.canvas.clientWidth;
    const height = this.canvas.clientHeight;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = this.aspect();
    this.camera.updateProjectionMatrix();
  }
}
