import * as THREE from 'three';
import gsap from 'gsap';
import { GlowZone } from './glowZone.ts';
import { buildVaryingTube } from './varyingTube.ts';

/**
 * Section 1 circuit overlay (SPEC §6 Section 1) — the §1/home-page hero graphic.
 *
 * CURRENT DESIGN (2026-07-27, after many live art-direction rounds): the
 * circulation is drawn as a single symmetric HEART SILHOUETTE (♥) of glassy
 * blue/red vessels around the real 3D heart, which nests in the ♥'s top cleft.
 * The ♥ is an OPEN curve, not a closed loop: its two top ends are glass tubes
 * that emerge from the real model's two SVC cups (the brachiocephalic prong
 * openings) as extensions of the vessel, trace the two lobes and the bottom
 * point, and terminate inside the cups. Blue/red blood coding (venous blue →
 * arterial red), flowing beads inside the glass, a draggable bolus, and two
 * glow-zone organ icons (lungs left, body right) at the side lobes. The right
 * tube's SVC-cup seating was dialled in by eye and is now baked (TOP_ROUTE below);
 * see HANDOFF.md "SECTION 1 CIRCUIT" for the full design history.
 *
 * REJECTED directions (do NOT retry): Valentine-bead ♥, text labels, capillary
 * blooms, asymmetric double-loops, a closed ♥ with a hidden through-heart
 * connector ("jolts out" / "still connected looks weird"), tubes that stop
 * ABOVE the cups (leave a visible open end / see into the empty cup), a fat/
 * flared/funnel tube calibre, and a uniform (non-centripetal) spline (kinked).
 */

// Blue/red coding (reader's request): a rich venous blue → arterial red, chosen
// to read unmistakably as the deox/ox convention without going neon. (A tasteful
// departure from SPEC §3's realistic crimson→scarlet.)
/** Deoxygenated venous blue. */
const DEOX = new THREE.Color('#2f6ad0');
/** Oxygenated arterial red. */
const OX = new THREE.Color('#ff3326');

/** Colour for an oxygenation fraction (0 = blue/deox, 1 = red/ox). */
export function bloodColor(ox: number, out = new THREE.Color()): THREE.Color {
  return out.copy(DEOX).lerp(OX, THREE.MathUtils.clamp(ox, 0, 1));
}

/**
 * Placement of the ♥ silhouette in world space (heart at origin, radius ≈ 1.9,
 * +Y up, viewer toward +Z). `offsetX` (−0.306) centres the ♥ so its midline sits
 * BETWEEN the two SVC cups (their x-midpoint ≈ −0.306), so a symmetric top cut
 * lands each arc end above its cup. `z` (−0.10) pulls the ♥ nearly coplanar with
 * the cups (which sit at z ≈ −0.03) so the tubes don't jump backward at the top.
 * `scale` 0.2 sizes the ♥ so the model nests in the top cleft and the lobes clear
 * its sides. Classic heart parametric curve (see heartShapePoint).
 */
const HEART_SHAPE = { samples: 240, scale: 0.2, offsetX: -0.306, offsetY: 0.0, z: -0.1 };

/**
 * Top-of-♥ routing — how the OPEN ♥'s two ends plug into the real SVC cups
 * (reader directive 2026-07-27).
 *
 * The parametric ♥ is sampled with a notch WINDOW omitted at the top (`rightGap`/
 * `leftGap`, radians), leaving two free ends. Each end is a straight STUB seated at
 * the cup opening (`*Tip`) and running PARALLEL to the cup axis (measured via the
 * `?svc` probe: each prong's opening centre + PCA axis):
 *   `*Deep` = tip − axis·d  — terminus DOWN the bore (fills the cup, follows the lean)
 *   `*Tip`  = the opening centre  (the seating anchor)
 *   `*Em`   = tip + axis·d  — leaves the cup COLLINEAR with the prong, then the
 *                             centripetal spline eases up into the lobe.
 * The LEFT uses the full stub (deep/tip/em); the RIGHT is CUT at the tip (no deep
 * bore segment) so no glass shows around its small cup — see buildCurvePoints().
 * The curve is a CENTRIPETAL Catmull-Rom (uniform
 * kinks across the bunched cup points → the old "crack above the SVC"). The prongs
 * are ASYMMETRIC: the RIGHT axis is shallow (~33° from horizontal), the LEFT steeper
 * (~63°). Measured values:
 *   right cup: centre[0.005,1.307,-0.023]  pcaAxis[0.828,0.538,-0.155]
 *   left  cup: centre[-0.617,1.362,-0.028] pcaAxis[-0.429,0.892,-0.138]
 *
 * The RIGHT seating (`rightCupTip` here) was dialled in by eye and baked.
 */
const D_DEEP = 0.35; // stub terminus depth down the bore (both cups)
const D_EM = 0.2; // stub emergence length, collinear with the cup axis (both cups)
const AXIS_R = new THREE.Vector3(0.828, 0.538, -0.155).normalize();
const AXIS_L = new THREE.Vector3(-0.429, 0.892, -0.138).normalize();
const TOP_ROUTE = {
  rightGap: 0.6,
  leftGap: 0.6,
  rightCupTip: new THREE.Vector3(-0.216, 1.085, -0.162), // seated by eye via ?tune (2026-07-27)
  leftCupTip: new THREE.Vector3(-0.652, 1.265, -0.166),
};

/** The three stub points that seat one end into its cup: deep terminus, opening
 *  anchor, collinear emergence — all parallel to the cup `axis`. */
function cupStub(tip: THREE.Vector3, axis: THREE.Vector3): THREE.Vector3[] {
  return [
    tip.clone().addScaledVector(axis, -D_DEEP),
    tip.clone(),
    tip.clone().addScaledVector(axis, D_EM),
  ];
}

/** Point on the heart silhouette at parameter t ∈ [0, 2π). */
function heartShapePoint(t: number, out = new THREE.Vector3()): THREE.Vector3 {
  const x = 16 * Math.sin(t) ** 3;
  const y = 13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t);
  return out.set(
    x * HEART_SHAPE.scale + HEART_SHAPE.offsetX,
    y * HEART_SHAPE.scale + HEART_SHAPE.offsetY,
    HEART_SHAPE.z,
  );
}

/** Fresnel-rimmed glass shell material — a clear vessel wall over the blood. */
function makeGlassMaterial(tint: THREE.Color): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: { uColor: { value: tint }, uOpacity: { value: 1 } },
    vertexShader: /* glsl */ `
      varying vec3 vWorldNormal;
      varying vec3 vViewDir;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorldNormal = normalize(mat3(modelMatrix) * normal);
        vViewDir = normalize(cameraPosition - wp.xyz);
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: /* glsl */ `
      uniform vec3 uColor;
      uniform float uOpacity;
      varying vec3 vWorldNormal;
      varying vec3 vViewDir;
      void main() {
        float ndv = abs(dot(normalize(vWorldNormal), normalize(vViewDir)));
        float fres = pow(1.0 - ndv, 2.3);
        float a = (fres * 0.6 + 0.05) * uOpacity;
        vec3 col = mix(uColor, vec3(1.0), fres * 0.55);
        gl_FragColor = vec4(col, a);
      }`,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
}

export class Circuit {
  /** World-space group holding the conduit (added to the scene, not the heart). */
  readonly group: THREE.Group;
  /** The flow path the beat-dots ride. */
  readonly curve: THREE.CatmullRomCurve3;
  /** World positions of the two organ nodes. */
  readonly nodes: { body: THREE.Vector3; lungs: THREE.Vector3 };

  // Blood core + glass shell (two concentric tubes = a glassy vessel).
  private readonly blood: THREE.Mesh;
  private readonly bloodGeom: THREE.BufferGeometry;
  private readonly shell: THREE.Mesh;
  private readonly shellGeom: THREE.BufferGeometry;
  private readonly bloodIndexCount: number;
  private readonly shellIndexCount: number;
  private revealTween: gsap.core.Tween | null = null;

  private readonly glows: GlowZone[] = [];
  private time = 0;

  // Oxygenation switches at these arc-length positions (BODY, LUNGS).
  private uBody: number;
  private uLungs: number;
  private static readonly OX_EDGE = 0.02; // smoothing half-width around a switch

  // Two beat-driven dots: launched from the two SVC cups, they ride down each side
  // of the ♥ to the bottom point on every beat — pulsed by the master clock, so the
  // symbolic ♥ comes alive with the real heartbeat. ([0] = right cup, [1] = left cup.)
  private readonly dots: THREE.Mesh[] = [];
  private readonly haloOf = new WeakMap<THREE.Mesh, THREE.Mesh>();
  private uBottom = 0.5; // curve param of the ♥ bottom point (both dots' destination)
  private readonly tmpVec = new THREE.Vector3();
  private readonly tmpColor = new THREE.Color();

  /** Beat-dot pulse: launches when the ventricle starts to squeeze, then glides
   *  cups→bottom at a steady, followable rate over PULSE_TRAVEL seconds (decoupled
   *  from the fast ejection so it doesn't zoom). `armed` re-arms after the heart
   *  relaxes → one clean pulse per beat, synced to the squeeze. */
  private pulseP = 1; // travel progress 0→1; 1 = no pulse in flight (starts idle)
  private armed = true;

  private static readonly TUBULAR = 600;
  private static readonly RADIAL = 14;
  private static readonly BLOOD_RADIUS = 0.065;
  private static readonly SHELL_RADIUS = 0.11; // ≈ SVC cup calibre (~0.08–0.10) so it fits, not overhangs
  private static readonly DOT_RADIUS = 0.12;
  /** Seconds for a beat-dot to glide from its cup to the ♥ bottom (slow = followable). */
  private static readonly PULSE_TRAVEL = 0.9;

  constructor() {
    this.group = new THREE.Group();
    this.group.name = 'circuit';

    // An OPEN ♥ that plugs into both SVC cups: it starts AT the right cup opening
    // (tip → collinear emergence), rises and traces the ♥ the long way (right lobe →
    // bottom point → left lobe), then runs collinear back down into the LEFT cup
    // (emergence → tip → deep) and terminates inside it. The top window (rightGap/
    // leftGap) is omitted so each inner edge rises straight from its cup. The right
    // end is CUT at the opening (no deep segment). See buildCurvePoints().
    this.curve = new THREE.CatmullRomCurve3(this.buildCurvePoints(), false, 'centripetal');

    // Organ nodes at the ♥'s two side lobes (widest points): body right, lungs left.
    this.nodes = {
      body: heartShapePoint(Math.PI / 2),
      lungs: heartShapePoint((3 * Math.PI) / 2),
    };
    this.uBody = this.nearestU(this.nodes.body);
    this.uLungs = this.nearestU(this.nodes.lungs);
    this.uBottom = this.nearestU(heartShapePoint(Math.PI));

    // UNIFORM calibre, matched to the SVC cup (~0.15 shell) so the tube is a true
    // PARALLEL, constant-width extension that plugs straight into each cup and
    // fills the opening — no funnel/flare. (The deep terminus + the opaque vessel
    // wall hide the open end and keep the cup from reading hollow.)
    const radiusAt = (base: number) => (): number => base;

    // Blood core: a semi-opaque gradient tube (blue↔red along the loop).
    this.bloodGeom = buildVaryingTube(
      this.curve, Circuit.TUBULAR, Circuit.RADIAL, radiusAt(Circuit.BLOOD_RADIUS), false,
    );
    this.applyOxygenationColors(this.bloodGeom);
    this.bloodIndexCount = this.bloodGeom.index ? this.bloodGeom.index.count : 0;
    this.blood = new THREE.Mesh(
      this.bloodGeom,
      new THREE.MeshBasicMaterial({
        vertexColors: true, transparent: true, opacity: 0.9,
        toneMapped: false, depthWrite: false,
      }),
    );
    this.blood.name = 'circuit-blood';
    this.blood.renderOrder = 1;
    this.group.add(this.blood);

    // Glass shell: a fresnel-rimmed clear tube enclosing the blood (same taper).
    this.shellGeom = buildVaryingTube(
      this.curve, Circuit.TUBULAR, Circuit.RADIAL, radiusAt(Circuit.SHELL_RADIUS), false,
    );
    this.shellIndexCount = this.shellGeom.index ? this.shellGeom.index.count : 0;
    this.shell = new THREE.Mesh(this.shellGeom, makeGlassMaterial(new THREE.Color('#ffd9cf')));
    this.shell.name = 'circuit-glass';
    this.shell.renderOrder = 3;
    this.group.add(this.shell);

    this.buildGlows();

    // The two beat-driven dots (built + placed by the clock in update()).
    this.buildDots();

    this.group.visible = false;
  }

  /** The full ordered control-point list for the ♥ curve: right cup stub → the ♥
   *  body (right lobe → bottom point → left lobe) → left cup stub. Both cup stubs
   *  are built the same way (seated at the tip, parallel to the cup axis). */
  private buildCurvePoints(): THREE.Vector3[] {
    const { rightGap, leftGap, rightCupTip } = TOP_ROUTE;
    const span = Math.PI * 2 - rightGap - leftGap;
    // RIGHT end is CUT at the cup opening: the tube TERMINATES at the tip (no deep
    // bore segment), so no glass shell shows below/around the small right SVC cup
    // — its short prong left the deep segment sticking out over the heart, and the
    // circuit draws over the model so that glass rim was visible. The emergence
    // point keeps the stub parallel to the cup axis before it curves to the lobe.
    const pts: THREE.Vector3[] = [
      rightCupTip.clone(),
      rightCupTip.clone().addScaledVector(AXIS_R, D_EM),
    ];
    for (let i = 0; i <= HEART_SHAPE.samples; i++) {
      pts.push(heartShapePoint(rightGap + (i / HEART_SHAPE.samples) * span));
    }
    // LEFT end keeps its deep bore segment (its long prong hides it): emergence →
    // tip → deep, reversed so the stub runs INTO the left cup.
    pts.push(...cupStub(TOP_ROUTE.leftCupTip, AXIS_L).reverse());
    return pts;
  }

  /** Place a soft glow-zone just beyond each organ node — offset outward into
   *  clean space so the vessel doesn't cross the icon — each carrying a faint
   *  luminous organ outline so it reads as a place (body large, lungs small). */
  private buildGlows(): void {
    // Push each glow just outward from its lobe, in the view plane, so it sits
    // clear of the ♥ outline. Equal sizes — the shape is symmetric.
    const out = (n: THREE.Vector3, d: number) => {
      const dir = new THREE.Vector3(n.x, n.y, 0).normalize();
      return new THREE.Vector3(n.x + dir.x * d, n.y + dir.y * d, 0.05);
    };
    // Glow tinted by the blood the organ *produces*: the BODY spends oxygen
    // (→ blue), the LUNGS load it (→ red) — reinforcing the blue/red coding.
    const body = new GlowZone(out(this.nodes.body, 0.55), 2.1, '#3f7ad8', { opacity: 0.8, phase: 0, shape: 'body' });
    const lungs = new GlowZone(out(this.nodes.lungs, 0.55), 2.1, '#ff5236', { opacity: 0.85, phase: 2.0, shape: 'lungs' });
    this.glows.push(body, lungs);
    this.glows.forEach((z) => this.group.add(z.group));
  }

  /** Arc-length parameter u whose curve point is nearest `target` (coarse scan). */
  private nearestU(target: THREE.Vector3): number {
    let bestU = 0;
    let bestD = Infinity;
    const N = 400;
    for (let i = 0; i <= N; i++) {
      const u = i / N;
      const d = this.curve.getPointAt(u, this.tmpVec).distanceToSquared(target);
      if (d < bestD) { bestD = d; bestU = u; }
    }
    return bestU;
  }

  /** Build the two beat-driven dots (right + left), each with a soft halo. */
  private buildDots(): void {
    for (let i = 0; i < 2; i++) {
      const dot = new THREE.Mesh(
        new THREE.SphereGeometry(Circuit.DOT_RADIUS, 20, 20),
        new THREE.MeshBasicMaterial({ toneMapped: false, transparent: true, depthWrite: false }),
      );
      dot.name = `circuit-dot-${i === 0 ? 'right' : 'left'}`;
      dot.renderOrder = 4;
      dot.frustumCulled = false;
      const halo = new THREE.Mesh(
        new THREE.SphereGeometry(Circuit.DOT_RADIUS * 1.9, 20, 20),
        new THREE.MeshBasicMaterial({ toneMapped: false, transparent: true, opacity: 0, depthWrite: false }),
      );
      halo.name = 'circuit-dot-halo';
      dot.add(halo);
      this.haloOf.set(dot, halo);
      this.dots.push(dot);
      this.group.add(dot);
    }
  }

  /** Drive the two dots off the beat phase (0→1): each shoots out of its cup and
   *  rides to the ♥ bottom, easing out so it launches on the beat and settles. They
   *  fade in at the cup and dissolve at the bottom, so it reads as a pulse of blood
   *  ejected each beat (and the phase-wrap reset is never seen). */
  private updateDots(dt: number, contraction: number): void {
    // Launch a pulse when the ventricle STARTS to squeeze (contraction rising past a
    // threshold), then glide it from the cups to the ♥ bottom at a STEADY rate over
    // PULSE_TRAVEL seconds — decoupled from the fast ejection so it reads as flow, not
    // a zoom. Re-arm only once the heart has fully relaxed → one clean pulse per beat,
    // still launched on the squeeze. (Thresholds have hysteresis; all three constants
    // are the tuning levers if it feels too fast/slow or mistimed.)
    if (this.armed && contraction > 0.3) { this.pulseP = 0; this.armed = false; }
    if (contraction < 0.1) this.armed = true;
    this.pulseP = Math.min(1, this.pulseP + dt / Circuit.PULSE_TRAVEL);
    const p = this.pulseP;
    const env = THREE.MathUtils.smoothstep(p, 0, 0.08) * (1 - THREE.MathUtils.smoothstep(p, 0.82, 1));
    this.placeDot(this.dots[0]!, this.uBottom * p, env); // right cup → bottom
    this.placeDot(this.dots[1]!, 1 - (1 - this.uBottom) * p, env); // left cup → bottom
  }

  /** Position a dot at curve param `u`, recolour by oxygenation, set its opacity. */
  private placeDot(dot: THREE.Mesh, u: number, opacity: number): void {
    this.curve.getPointAt(THREE.MathUtils.clamp(u, 0, 1), this.tmpVec);
    dot.position.copy(this.tmpVec);
    const mat = dot.material as THREE.MeshBasicMaterial;
    mat.color.copy(bloodColor(this.oxygenationAt(u), this.tmpColor));
    mat.opacity = opacity;
    const halo = this.haloOf.get(dot);
    if (halo) {
      const hmat = halo.material as THREE.MeshBasicMaterial;
      hmat.color.copy(mat.color);
      hmat.opacity = opacity * 0.28;
    }
  }

  /** Per frame: `dt` seconds since last frame, `contraction` the ventricular
   *  contraction weight (0 relaxed → 1 fully contracted). The two dots ride the
   *  squeeze; the glows breathe. */
  update(dt: number, contraction: number): void {
    if (!this.group.visible) return;
    this.time += dt;
    this.updateDots(dt, contraction);
    for (const z of this.glows) z.update(this.time);
  }

  /**
   * Oxygenation at curve parameter u ∈ [0,1]. Red/arterial (1) on the two oxygenated
   * legs (the upper arcs toward the LUNGS and BODY nodes) and blue/venous (0) on the
   * deoxygenated leg between the BODY and LUNGS organ nodes. The switch is smoothed
   * over a short window at each node so the tube gradient and beads don't hard-edge.
   */
  oxygenationAt(u: number): number {
    const w = Circuit.OX_EDGE;
    const afterBody = THREE.MathUtils.smoothstep(u, this.uBody - w, this.uBody + w);
    const afterLungs = THREE.MathUtils.smoothstep(u, this.uLungs - w, this.uLungs + w);
    // 1 before BODY, 0 between BODY and LUNGS, 1 after LUNGS (u_body < u_lungs).
    return 1 - (afterBody - afterLungs);
  }

  /** Per-vertex blue→red gradient down the length of the blood tube. */
  private applyOxygenationColors(geom: THREE.BufferGeometry): void {
    const pos = geom.getAttribute('position');
    const colors = new Float32Array(pos.count * 3);
    const rings = Circuit.TUBULAR + 1;
    const perRing = Circuit.RADIAL + 1;
    const c = new THREE.Color();
    for (let i = 0; i < rings; i++) {
      bloodColor(this.oxygenationAt(i / Circuit.TUBULAR), c);
      for (let j = 0; j < perRing; j++) {
        const idx = (i * perRing + j) * 3;
        colors[idx] = c.r;
        colors[idx + 1] = c.g;
        colors[idx + 2] = c.b;
      }
    }
    geom.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  }

  /**
   * Draw the vessels in — they grow along the direction of flow from the aortic
   * root, tracing the blood's journey out through the body and lungs and back
   * (SPEC entrance: "circuit paths draw in"). Returns the tween.
   */
  reveal(duration = 2.2): gsap.core.Tween {
    this.revealTween?.kill();
    this.group.visible = true;
    const state = { t: 0 };
    this.bloodGeom.setDrawRange(0, 0);
    this.shellGeom.setDrawRange(0, 0);
    this.revealTween = gsap.to(state, {
      t: 1,
      duration,
      ease: 'power1.inOut',
      onUpdate: () => {
        this.bloodGeom.setDrawRange(0, Math.floor(state.t * this.bloodIndexCount));
        this.shellGeom.setDrawRange(0, Math.floor(state.t * this.shellIndexCount));
      },
      onComplete: () => {
        this.bloodGeom.setDrawRange(0, Infinity);
        this.shellGeom.setDrawRange(0, Infinity);
      },
    });
    return this.revealTween;
  }

  /** Show the whole conduit at once (no reveal) — dev/headless + re-entry. */
  showInstant(): void {
    this.revealTween?.kill();
    this.revealTween = null;
    this.bloodGeom.setDrawRange(0, Infinity);
    this.shellGeom.setDrawRange(0, Infinity);
    this.group.visible = true;
  }

  /** Hide the conduit (section scroll-out). */
  hide(): void {
    this.revealTween?.kill();
    this.revealTween = null;
    this.group.visible = false;
  }

  dispose(): void {
    this.revealTween?.kill();
    this.bloodGeom.dispose();
    (this.blood.material as THREE.Material).dispose();
    this.shellGeom.dispose();
    (this.shell.material as THREE.Material).dispose();
    this.glows.forEach((z) => z.dispose());
    for (const dot of this.dots) {
      dot.geometry.dispose();
      (dot.material as THREE.Material).dispose();
      const halo = this.haloOf.get(dot);
      if (halo) {
        halo.geometry.dispose();
        (halo.material as THREE.Material).dispose();
      }
    }
    this.group.clear();
  }
}
