import type { BeatClock } from '../clock/index.ts';
import { KNOB_RANGES, type EngineState, type Knobs } from '../engine/index.ts';

/**
 * THROWAWAY DEV HUD (BUILD_PLAN §3, Phase 2).
 *
 * A proto-Wiggers instrument for confirming the engine behaves before any 3D
 * depends on it: a scrubber drives the master clock, knob sliders re-solve the
 * engine live, numeric readouts show the current frame, and a 2D plot draws the
 * pressure and volume channels across the beat with a time-cursor tracking the
 * scrub position. This is a *dev tool*, not the finished Wiggers diagram
 * (Section 11) — it exists to be deleted.
 */

interface Channel {
  key: keyof EngineState['pressures'];
  color: string;
  label: string;
}

const PRESSURE_CHANNELS: Channel[] = [
  { key: 'LV', color: '#e0554b', label: 'LV' },
  { key: 'SysArt', color: '#ff8a4c', label: 'Aortic' },
  { key: 'LA', color: '#5b9bd5', label: 'LA' },
];

const VOLUME_COLOR = '#2abfa5';
const SAMPLES = 260;

// Fixed axes so scrubbing/knob changes don't make the plot jump around.
const P_MIN = 0;
const P_MAX = 140;
const V_MIN = 20;
const V_MAX = 140;

const KNOB_LABELS: Record<keyof Knobs, string> = {
  contractility: 'Contractility (E_es)',
  preload: 'Preload (filling P)',
  afterload: 'Afterload (R_sys)',
  heartRate: 'Heart rate',
  avDelay: 'AV delay (PR)',
};

export class DevHud {
  private readonly clock: BeatClock;

  private root!: HTMLDivElement;
  private canvas!: HTMLCanvasElement;
  private ctx!: CanvasRenderingContext2D;
  private readouts!: HTMLDivElement;
  private scrubber!: HTMLInputElement;
  private readonly knobValueLabels = new Map<keyof Knobs, HTMLSpanElement>();

  /** Cached channel data for the current solve, sampled across the beat. */
  private beat: EngineState[] = [];
  private cssWidth = 520;
  private cssHeight = 300;

  constructor(clock: BeatClock) {
    this.clock = clock;
  }

  mount(parent: HTMLElement): void {
    this.injectStyles();
    this.buildDom(parent);
    this.resample();
    this.clock.subscribe(() => this.render());
    window.addEventListener('resize', () => this.resizeCanvas());
    this.resizeCanvas();
  }

  /** Re-sample the beat into the channel cache (after a solve/knob change). */
  private resample(): void {
    const beat: EngineState[] = [];
    for (let i = 0; i < SAMPLES; i++) {
      beat.push(this.clock.getEngine().sample(i / SAMPLES));
    }
    this.beat = beat;
  }

  // ---- DOM ------------------------------------------------------------------

  private buildDom(parent: HTMLElement): void {
    this.root = el('div', 'devhud');

    const header = el('div', 'devhud-header');
    header.textContent = 'DEV HUD · proto-Wiggers';
    const toggle = el('button', 'devhud-toggle');
    toggle.textContent = '–';
    toggle.addEventListener('click', () => {
      const collapsed = this.root.classList.toggle('devhud-collapsed');
      toggle.textContent = collapsed ? '+' : '–';
    });
    header.appendChild(toggle);
    this.root.appendChild(header);

    const body = el('div', 'devhud-body');

    this.canvas = document.createElement('canvas');
    this.canvas.className = 'devhud-canvas';
    const ctx = this.canvas.getContext('2d');
    if (!ctx) throw new Error('2D canvas context unavailable');
    this.ctx = ctx;
    body.appendChild(this.canvas);

    this.readouts = el('div', 'devhud-readouts');
    body.appendChild(this.readouts);

    // Scrubber (drives the master clock).
    const scrubRow = el('div', 'devhud-row');
    const scrubLabel = el('label', 'devhud-label');
    scrubLabel.textContent = 'beat';
    this.scrubber = document.createElement('input');
    this.scrubber.type = 'range';
    this.scrubber.min = '0';
    this.scrubber.max = '1';
    this.scrubber.step = '0.001';
    this.scrubber.value = '0';
    this.scrubber.className = 'devhud-range';
    this.scrubber.addEventListener('input', () => {
      this.clock.setPhase(parseFloat(this.scrubber.value));
    });
    scrubRow.append(scrubLabel, this.scrubber);
    body.appendChild(scrubRow);

    // Knob sliders (re-solve the engine live).
    for (const knob of Object.keys(KNOB_RANGES) as (keyof Knobs)[]) {
      body.appendChild(this.buildKnobRow(knob));
    }

    this.root.appendChild(body);
    parent.appendChild(this.root);
  }

  private buildKnobRow(knob: keyof Knobs): HTMLDivElement {
    const range = KNOB_RANGES[knob];
    const row = el('div', 'devhud-row');

    const label = el('label', 'devhud-label');
    label.textContent = KNOB_LABELS[knob];

    const input = document.createElement('input');
    input.type = 'range';
    input.min = String(range.min);
    input.max = String(range.max);
    input.step = String((range.max - range.min) / 100);
    input.value = String(range.default);
    input.className = 'devhud-range';

    const value = el('span', 'devhud-value');
    value.textContent = range.default.toFixed(2);
    this.knobValueLabels.set(knob, value);

    input.addEventListener('input', () => {
      const v = parseFloat(input.value);
      value.textContent = v.toFixed(2);
      this.clock.getEngine().setKnobs({ [knob]: v });
      this.clock.resolve(); // re-solve to a new steady state
      this.resample();
      this.render();
    });

    row.append(label, input, value);
    return row;
  }

  // ---- Rendering ------------------------------------------------------------

  private resizeCanvas(): void {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(this.cssWidth * dpr);
    this.canvas.height = Math.round(this.cssHeight * dpr);
    this.canvas.style.width = `${this.cssWidth}px`;
    this.canvas.style.height = `${this.cssHeight}px`;
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.render();
  }

  private render(): void {
    const phase = this.clock.getPhase();
    this.scrubber.value = String(phase);
    this.drawPlot(phase);
    this.drawReadouts();
  }

  private drawPlot(phase: number): void {
    const ctx = this.ctx;
    const w = this.cssWidth;
    const h = this.cssHeight;
    ctx.clearRect(0, 0, w, h);

    const padL = 34;
    const padR = 10;
    const padT = 26;
    const padB = 16;
    const gap = 14;
    const innerW = w - padL - padR;
    const plotTop = padT;
    const plotBottom = h - padB;
    const totalH = plotBottom - plotTop - gap;
    const pH = totalH * 0.62; // pressure panel
    const vTop = plotTop + pH + gap;
    const vH = plotBottom - vTop; // volume panel

    const x = (p: number) => padL + p * innerW;
    const yP = (p: number) => plotTop + (1 - (p - P_MIN) / (P_MAX - P_MIN)) * pH;
    const yV = (v: number) => vTop + (1 - (v - V_MIN) / (V_MAX - V_MIN)) * vH;

    // Phase bands (background) from the event timing.
    this.drawPhaseBands(x, plotTop, plotBottom);

    // Gridlines + axis labels.
    ctx.font = '10px system-ui, sans-serif';
    ctx.fillStyle = '#8a9099';
    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 1;
    for (const p of [0, 40, 80, 120]) {
      ctx.beginPath();
      ctx.moveTo(padL, yP(p));
      ctx.lineTo(w - padR, yP(p));
      ctx.stroke();
      ctx.fillText(String(p), 6, yP(p) + 3);
    }
    for (const v of [40, 80, 120]) {
      ctx.beginPath();
      ctx.moveTo(padL, yV(v));
      ctx.lineTo(w - padR, yV(v));
      ctx.stroke();
      ctx.fillText(String(v), 6, yV(v) + 3);
    }

    // Panel titles.
    ctx.fillStyle = '#aeb4bd';
    ctx.fillText('mmHg', padL, plotTop - 8);
    ctx.fillText('mL (LV)', padL, vTop - 4);

    // Pressure curves.
    for (const ch of PRESSURE_CHANNELS) {
      ctx.strokeStyle = ch.color;
      ctx.lineWidth = 1.75;
      ctx.beginPath();
      this.beat.forEach((s, i) => {
        const px = x(i / SAMPLES);
        const py = yP(s.pressures[ch.key]);
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      });
      ctx.stroke();
    }

    // Volume curve.
    ctx.strokeStyle = VOLUME_COLOR;
    ctx.lineWidth = 1.75;
    ctx.beginPath();
    this.beat.forEach((s, i) => {
      const px = x(i / SAMPLES);
      const py = yV(s.volumes.LV);
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    });
    ctx.stroke();

    // S1 / S2 markers.
    const ev = this.clock.getEvents();
    this.drawMarker(x(ev.s1Phase), plotTop, plotBottom, 'S1');
    this.drawMarker(x(ev.s2Phase), plotTop, plotBottom, 'S2');

    // Time cursor.
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x(phase), plotTop);
    ctx.lineTo(x(phase), plotBottom);
    ctx.stroke();

    // Legend.
    let lx = padL + 2;
    ctx.textBaseline = 'alphabetic';
    for (const ch of [...PRESSURE_CHANNELS, { color: VOLUME_COLOR, label: 'LV vol' }]) {
      ctx.fillStyle = ch.color;
      ctx.fillRect(lx, plotTop - 20, 9, 9);
      ctx.fillStyle = '#c3c8d0';
      ctx.fillText(ch.label, lx + 12, plotTop - 12);
      lx += 20 + ctx.measureText(ch.label).width + 14;
    }
  }

  private drawPhaseBands(
    x: (p: number) => number,
    top: number,
    bottom: number,
  ): void {
    const ev = this.clock.getEvents();
    const bands: Array<[number, number, string]> = [
      [0, ev.valve.mitral.close, 'rgba(91,155,213,0.05)'], // atrial systole
      [ev.valve.mitral.close, ev.valve.aortic.open, 'rgba(224,85,75,0.10)'], // isovol contraction
      [ev.valve.aortic.open, ev.valve.aortic.close, 'rgba(255,138,76,0.08)'], // ejection
      [ev.valve.aortic.close, ev.valve.mitral.open, 'rgba(224,85,75,0.10)'], // isovol relaxation
      [ev.valve.mitral.open, 1, 'rgba(42,191,165,0.05)'], // filling
    ];
    for (const [a, b, color] of bands) {
      this.ctx.fillStyle = color;
      this.ctx.fillRect(x(a), top, x(b) - x(a), bottom - top);
    }
  }

  private drawMarker(px: number, top: number, bottom: number, label: string): void {
    const ctx = this.ctx;
    ctx.strokeStyle = 'rgba(255,225,150,0.55)';
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(px, top);
    ctx.lineTo(px, bottom);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = 'rgba(255,225,150,0.9)';
    ctx.font = '9px system-ui, sans-serif';
    ctx.fillText(label, px + 2, top + 9);
  }

  private drawReadouts(): void {
    const s = this.clock.sample();
    const m = this.clock.getMetrics();
    const valve = (open: boolean) => (open ? '●' : '○');
    const rows: Array<[string, string]> = [
      ['phase', `${s.phase}  (${(s.cyclePhase * 100).toFixed(0)}%)`],
      ['P  LV / Ao / LA', `${s.pressures.LV.toFixed(0)} / ${s.pressures.SysArt.toFixed(0)} / ${s.pressures.LA.toFixed(0)} mmHg`],
      ['V  LV', `${s.volumes.LV.toFixed(1)} mL`],
      ['valves M/A/T/P', `${valve(s.valves.mitral.open)} ${valve(s.valves.aortic.open)} ${valve(s.valves.tricuspid.open)} ${valve(s.valves.pulmonary.open)}`],
      ['S1 / S2', `${s.markers.s1 ? 'S1 ' : '—'} ${s.markers.s2 ? 'S2' : ''}`.trim()],
      ['wave', `${s.electricalWave.landmark} (${(s.electricalWave.progress * 100).toFixed(0)}%)`],
      ['EDV / ESV / SV', `${m.edv.toFixed(0)} / ${m.esv.toFixed(0)} / ${m.strokeVolume.toFixed(0)} mL`],
      ['EF / CO', `${(m.ejectionFraction * 100).toFixed(0)}% / ${m.cardiacOutput.toFixed(1)} L/min`],
    ];
    this.readouts.innerHTML = rows
      .map(([k, v]) => `<span class="devhud-k">${k}</span><span class="devhud-v">${v}</span>`)
      .join('');
  }

  private injectStyles(): void {
    if (document.getElementById('devhud-styles')) return;
    const style = document.createElement('style');
    style.id = 'devhud-styles';
    style.textContent = `
    .devhud{position:fixed;left:12px;bottom:12px;width:544px;max-width:calc(100vw - 24px);
      background:rgba(14,16,20,0.86);backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,0.08);
      border-radius:10px;color:#dfe3e8;font:12px/1.4 system-ui,-apple-system,'Segoe UI',sans-serif;
      z-index:10;box-shadow:0 8px 30px rgba(0,0,0,0.45);user-select:none}
    .devhud-header{display:flex;justify-content:space-between;align-items:center;padding:7px 10px;
      font-weight:600;letter-spacing:0.04em;font-size:11px;color:#aeb4bd;border-bottom:1px solid rgba(255,255,255,0.06)}
    .devhud-toggle{background:transparent;border:1px solid rgba(255,255,255,0.15);color:#dfe3e8;
      width:20px;height:20px;border-radius:5px;cursor:pointer;line-height:1}
    .devhud-body{padding:10px 12px 12px}
    .devhud-collapsed .devhud-body{display:none}
    .devhud-canvas{display:block;width:100%;border-radius:6px;background:rgba(0,0,0,0.25)}
    .devhud-readouts{display:grid;grid-template-columns:auto 1fr;gap:1px 10px;margin:8px 0;
      font-variant-numeric:tabular-nums;font-size:11px}
    .devhud-k{color:#8a9099}
    .devhud-v{color:#eef1f4;text-align:right}
    .devhud-row{display:flex;align-items:center;gap:8px;margin-top:5px}
    .devhud-label{width:130px;color:#9aa0a8;font-size:11px;flex:0 0 auto}
    .devhud-range{flex:1 1 auto;accent-color:#e0554b}
    .devhud-value{width:42px;text-align:right;color:#eef1f4;font-variant-numeric:tabular-nums;font-size:11px}
    `;
    document.head.appendChild(style);
  }
}

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  className: string,
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  node.className = className;
  return node;
}
