import type {
  ActiveChamber,
  Compartment,
  EngineParams,
  Valve,
} from './types.ts';
import { chamberElastance } from './activation.ts';

/** Blood volume per compartment, mL — the ODE state vector (PHYSICS.md §1). */
export type Volumes = Record<Compartment, number>;

/** All eight compartments, in ring order. */
export const COMPARTMENTS: readonly Compartment[] = [
  'LA', 'LV', 'SysArt', 'SysVein', 'RA', 'RV', 'PulArt', 'PulVein',
] as const;

/** The four active (elastance) chambers. */
export const ACTIVE_CHAMBERS: readonly ActiveChamber[] = ['LA', 'LV', 'RA', 'RV'] as const;

/** The four valves, with the compartments they connect (up → down). */
const VALVE_CONNECTIONS: Record<Valve, { up: Compartment; down: Compartment }> = {
  mitral: { up: 'LA', down: 'LV' },
  aortic: { up: 'LV', down: 'SysArt' },
  tricuspid: { up: 'RA', down: 'RV' },
  pulmonary: { up: 'RV', down: 'PulArt' },
};

/** Derived quantities at one instant (everything but the raw volumes). */
export interface DerivedState {
  pressures: Record<Compartment, number>;
  activation: Record<ActiveChamber, number>;
  valveFlow: Record<Valve, number>;
  valveOpen: Record<Valve, boolean>;
}

/**
 * Pressures from the constitutive laws (PHYSICS.md §2, §3, §5): elastance for
 * active chambers, linear compliance for passive compartments. The systemic
 * arterial characteristic impedance Z_c is handled at the aortic valve (below),
 * so SysArt here is just its compliance chamber.
 */
export function computePressures(
  volumes: Volumes,
  params: EngineParams,
  cyclePhase: number,
): { pressures: Record<Compartment, number>; activation: Record<ActiveChamber, number> } {
  const activation = {} as Record<ActiveChamber, number>;
  const pressures = {} as Record<Compartment, number>;

  for (const chamber of ACTIVE_CHAMBERS) {
    const cp = params.chambers[chamber];
    const { elastance, activation: en } = chamberElastance(cp, cyclePhase);
    activation[chamber] = en;
    pressures[chamber] = elastance * (volumes[chamber] - cp.v0);
  }

  pressures.SysArt = (volumes.SysArt - params.sysArt.v0) / params.sysArt.ca;
  pressures.SysVein = (volumes.SysVein - params.sysVein.v0) / params.sysVein.compliance;
  pressures.PulArt = (volumes.PulArt - params.pulArt.v0) / params.pulArt.compliance;
  pressures.PulVein = (volumes.PulVein - params.pulVein.v0) / params.pulVein.compliance;

  return { pressures, activation };
}

/** Ideal-diode valve flow: forward only, else zero (PHYSICS.md §4). */
function diodeFlow(pUp: number, pDown: number, resistance: number): number {
  const gradient = pUp - pDown;
  return gradient > 0 ? gradient / resistance : 0;
}

/**
 * Flows through the four valves. The aortic and pulmonary valves add the
 * characteristic impedance Z_c in series with the valve resistance during
 * forward flow — this is the resistive element of the three-element Windkessel
 * the ventricle first meets on ejection (PHYSICS.md §3).
 */
export function computeValves(
  pressures: Record<Compartment, number>,
  params: EngineParams,
): { valveFlow: Record<Valve, number>; valveOpen: Record<Valve, boolean> } {
  const valveFlow = {} as Record<Valve, number>;
  const valveOpen = {} as Record<Valve, boolean>;

  for (const valve of ['mitral', 'aortic', 'tricuspid', 'pulmonary'] as Valve[]) {
    const { up, down } = VALVE_CONNECTIONS[valve];
    // Only the aortic valve carries the systemic characteristic impedance Z_c
    // (PHYSICS.md §3); the pulmonary side is a simpler compartment (§9).
    const seriesZc = valve === 'aortic' ? params.sysArt.zc : 0;
    const flow = diodeFlow(pressures[up], pressures[down], params.valveResistance + seriesZc);
    valveFlow[valve] = flow;
    valveOpen[valve] = flow > 0;
  }

  return { valveFlow, valveOpen };
}

/** Everything derived from the raw volumes at one instant. */
export function derive(
  volumes: Volumes,
  params: EngineParams,
  cyclePhase: number,
): DerivedState {
  const { pressures, activation } = computePressures(volumes, params, cyclePhase);
  const { valveFlow, valveOpen } = computeValves(pressures, params);
  return { pressures, activation, valveFlow, valveOpen };
}

/**
 * dV/dt for every compartment (PHYSICS.md §5). Valve flows are gated diodes;
 * the vascular beds (systemic runoff, venous return, pulmonary runoff,
 * pulmonary venous return) are linear resistances. By construction ΣdV/dt = 0,
 * so total blood volume is conserved around the closed ring (PHYSICS.md §1).
 */
export function derivatives(
  volumes: Volumes,
  params: EngineParams,
  cyclePhase: number,
): Volumes {
  const { pressures, valveFlow } = derive(volumes, params, cyclePhase);

  // Non-valve resistive flows around the loop.
  const sysRunoff = (pressures.SysArt - pressures.SysVein) / params.sysArt.rSys;
  const venousReturn = (pressures.SysVein - pressures.RA) / params.venousReturnResistance;
  const pulRunoff = (pressures.PulArt - pressures.PulVein) / params.pulResistance;
  const pulVenousReturn = (pressures.PulVein - pressures.LA) / params.pulVenousReturnResistance;

  return {
    LA: pulVenousReturn - valveFlow.mitral,
    LV: valveFlow.mitral - valveFlow.aortic,
    SysArt: valveFlow.aortic - sysRunoff,
    SysVein: sysRunoff - venousReturn,
    RA: venousReturn - valveFlow.tricuspid,
    RV: valveFlow.tricuspid - valveFlow.pulmonary,
    PulArt: valveFlow.pulmonary - pulRunoff,
    PulVein: pulRunoff - pulVenousReturn,
  };
}

/** volumes + scale · delta, componentwise. */
function axpy(volumes: Volumes, delta: Volumes, scale: number): Volumes {
  const out = {} as Volumes;
  for (const c of COMPARTMENTS) out[c] = volumes[c] + scale * delta[c];
  return out;
}

/**
 * One fixed-step RK4 integration step of duration `dt` seconds, advancing the
 * volumes. `cyclePhase0` is the normalized phase at the start of the step;
 * `dPhase` is dt / cycleLength (activation timing is phase-based, PHYSICS.md §8).
 */
export function rk4Step(
  volumes: Volumes,
  params: EngineParams,
  dt: number,
  cyclePhase0: number,
  dPhase: number,
): Volumes {
  const k1 = derivatives(volumes, params, cyclePhase0);
  const k2 = derivatives(axpy(volumes, k1, dt / 2), params, cyclePhase0 + dPhase / 2);
  const k3 = derivatives(axpy(volumes, k2, dt / 2), params, cyclePhase0 + dPhase / 2);
  const k4 = derivatives(axpy(volumes, k3, dt), params, cyclePhase0 + dPhase);

  const out = {} as Volumes;
  for (const c of COMPARTMENTS) {
    out[c] = volumes[c] + (dt / 6) * (k1[c] + 2 * k2[c] + 2 * k3[c] + k4[c]);
  }
  return out;
}
