import * as THREE from 'three';
import type { HeartScene } from '../scene/index.ts';

/**
 * TEMPORARY dev inspector (opt-in via `?inspect`). A live feedback aid while we
 * reconfigure the model: lists every mesh part, lets you show/hide/solo each, and
 * click any part in the 3D view to identify + highlight it by name. Lets the
 * reviewer point at exactly which structure is wrong. Delete once the model is
 * settled (alongside the other Phase-3 dev affordances in main.ts).
 */
interface PartRow {
  mesh: THREE.Mesh;
  row: HTMLElement;
  toggle: HTMLInputElement;
}

const STYLE = `
.insp{position:fixed;top:10px;right:10px;z-index:30;width:270px;max-height:calc(100vh - 20px);
  display:flex;flex-direction:column;background:rgba(12,15,19,.94);color:#e7ecf0;
  border:1px solid #2a3540;border-radius:10px;font:12px/1.4 ui-monospace,Consolas,monospace;
  box-shadow:0 12px 40px -12px #000;backdrop-filter:blur(6px)}
.insp-h{display:flex;align-items:center;gap:6px;padding:9px 11px;border-bottom:1px solid #223}
.insp-h b{font-size:12px;letter-spacing:.04em}
.insp-n{color:#7f8b96;margin-right:auto}
.insp-h button{font:inherit;color:#cfe;background:#1b2530;border:1px solid #2f3d4a;border-radius:6px;
  padding:3px 8px;cursor:pointer}
.insp-h button:hover{background:#243141}
.insp-label{padding:8px 11px;font-size:12px;color:#ffcf8a;border-bottom:1px solid #223;
  word-break:break-word;min-height:18px}
.insp-list{overflow-y:auto;padding:4px 4px 8px}
.insp-row{display:flex;align-items:center;gap:7px;padding:3px 7px;border-radius:6px;cursor:default}
.insp-row:hover{background:#1a222c}
.insp-row.sel{background:#3a2c12;outline:1px solid #b9822f}
.insp-nm{flex:1;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.insp-solo{font:inherit;color:#9fb;background:transparent;border:1px solid #2f3d4a;border-radius:5px;
  padding:1px 6px;cursor:pointer;opacity:.7}
.insp-row:hover .insp-solo{opacity:1}
.insp-hint{padding:7px 11px;border-top:1px solid #223;color:#7f8b96;font-size:11px}
`;

export function mountInspector(scene: HeartScene): void {
  const heart = scene.getHeart();
  if (!heart) return;

  const meshes: THREE.Mesh[] = [];
  heart.traverse((o) => {
    if ((o as THREE.Mesh).isMesh) meshes.push(o as THREE.Mesh);
  });
  meshes.sort((a, b) => (a.name || '').localeCompare(b.name || ''));

  const style = document.createElement('style');
  style.textContent = STYLE;
  document.head.appendChild(style);

  const HILITE = new THREE.MeshStandardMaterial({
    color: 0xffb020,
    emissive: 0xff7a00,
    emissiveIntensity: 0.85,
    roughness: 0.45,
  });
  let selected: THREE.Mesh | null = null;
  let selectedOrig: THREE.Material | THREE.Material[] | null = null;

  const rows = new Map<THREE.Mesh, PartRow>();

  const panel = document.createElement('div');
  panel.className = 'insp';
  panel.innerHTML =
    '<div class="insp-h"><b>Parts</b>' +
    `<span class="insp-n">${meshes.length}</span>` +
    '<button data-act="all">Show all</button>' +
    '<button data-act="reset">Reset</button></div>' +
    '<div class="insp-label">Click a part in the view, or a name below.</div>' +
    '<div class="insp-list"></div>' +
    '<div class="insp-hint">drag = orbit · click = identify · solo = isolate</div>';
  document.body.appendChild(panel);
  const list = panel.querySelector('.insp-list') as HTMLElement;
  const label = panel.querySelector('.insp-label') as HTMLElement;

  const clearHi = (): void => {
    if (selected && selectedOrig) selected.material = selectedOrig;
    selected = null;
    selectedOrig = null;
    rows.forEach((pr) => pr.row.classList.remove('sel'));
  };
  const highlight = (m: THREE.Mesh): void => {
    clearHi();
    selected = m;
    selectedOrig = m.material;
    m.material = HILITE;
    label.textContent = m.name || '(unnamed mesh)';
    const pr = rows.get(m);
    if (pr) {
      pr.row.classList.add('sel');
      pr.row.scrollIntoView({ block: 'nearest' });
    }
  };
  const setAllVisible = (): void => {
    meshes.forEach((m) => (m.visible = true));
    rows.forEach((pr) => (pr.toggle.checked = true));
  };

  for (const m of meshes) {
    const row = document.createElement('div');
    row.className = 'insp-row';
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.checked = m.visible;
    cb.addEventListener('change', () => (m.visible = cb.checked));
    const nm = document.createElement('span');
    nm.className = 'insp-nm';
    nm.textContent = m.name || '(unnamed)';
    nm.title = m.name || '(unnamed)';
    nm.addEventListener('click', () => highlight(m));
    const solo = document.createElement('button');
    solo.className = 'insp-solo';
    solo.textContent = 'solo';
    solo.addEventListener('click', () => {
      meshes.forEach((x) => (x.visible = x === m));
      rows.forEach((pr) => (pr.toggle.checked = pr.mesh === m));
      highlight(m);
    });
    row.append(cb, nm, solo);
    list.appendChild(row);
    rows.set(m, { mesh: m, row, toggle: cb });
  }

  (panel.querySelector('[data-act="all"]') as HTMLElement).addEventListener('click', setAllVisible);
  (panel.querySelector('[data-act="reset"]') as HTMLElement).addEventListener('click', () => {
    setAllVisible();
    clearHi();
    label.textContent = 'Click a part in the view, or a name below.';
  });

  // Raycast pick on the canvas — but only on a click, not a drag (so orbit still works).
  const canvas = scene.renderer.domElement;
  const ray = new THREE.Raycaster();
  const ndc = new THREE.Vector2();
  let downX = 0;
  let downY = 0;
  let downT = 0;
  canvas.addEventListener('pointerdown', (e) => {
    downX = e.clientX;
    downY = e.clientY;
    downT = performance.now();
  });
  canvas.addEventListener('pointerup', (e) => {
    if (Math.hypot(e.clientX - downX, e.clientY - downY) > 5) return; // dragged → orbit
    if (performance.now() - downT > 500) return; // held
    const rect = canvas.getBoundingClientRect();
    ndc.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    ndc.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    ray.setFromCamera(ndc, scene.camera);
    const hits = ray.intersectObjects(
      meshes.filter((m) => m.visible),
      false,
    );
    const hit = hits[0];
    if (hit) highlight(hit.object as THREE.Mesh);
    else clearHi();
  });

  // Frame the camera on the whole heart so it's centered and orbitable, regardless
  // of whether a section framed it (in ?inspect mode the sections are skipped).
  const box = new THREE.Box3().setFromObject(heart);
  const center = box.getCenter(new THREE.Vector3());
  const radius = Math.max(1e-4, box.getSize(new THREE.Vector3()).length() / 2);
  scene.controls.target.copy(center);
  scene.camera.position.copy(center).add(new THREE.Vector3(0.5, 0.25, 1).normalize().multiplyScalar(radius * 3));
  scene.camera.near = radius * 0.01;
  scene.camera.far = radius * 100;
  scene.camera.updateProjectionMatrix();
  scene.controls.update();
}
