import * as THREE from 'three';

/**
 * A soft luminous glow-zone (SPEC §6 Section 1) — a billboarded radial bloom of
 * light that marks where an exchange happens (the LUNGS, the BODY) without a hard
 * object or a plain text label. A faint luminous organ silhouette sits inside the
 * glow so it reads as a *place* (a lung-pair, a body) — a whisper, not a caption.
 * Blood in the glassy vessels changes colour as it passes through the zone.
 * Camera-facing sprites, so they always read as soft light, never as geometry.
 */

export type OrganShape = 'lungs' | 'body';

let glowTex: THREE.CanvasTexture | null = null;
const shapeTex: Partial<Record<OrganShape, THREE.CanvasTexture>> = {};

/** A soft white radial-gradient sprite texture (generated once, tinted per zone). */
function glowTexture(): THREE.CanvasTexture {
  if (glowTex) return glowTex;
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d')!;
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0.0, 'rgba(255,255,255,1)');
  g.addColorStop(0.28, 'rgba(255,255,255,0.5)');
  g.addColorStop(0.6, 'rgba(255,255,255,0.12)');
  g.addColorStop(1.0, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  glowTex = new THREE.CanvasTexture(canvas);
  glowTex.colorSpace = THREE.SRGBColorSpace;
  return glowTex;
}

/** A glowing engraved organ outline (white stroke on transparent). */
function organTexture(shape: OrganShape): THREE.CanvasTexture {
  const cached = shapeTex[shape];
  if (cached) return cached;
  const s = 256;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = s;
  const ctx = canvas.getContext('2d')!;
  ctx.strokeStyle = '#ffffff';
  ctx.fillStyle = '#ffffff';
  ctx.lineWidth = s * 0.02;
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  ctx.shadowColor = '#ffffff';
  ctx.shadowBlur = s * 0.045; // soft glow around the stroke
  const cx = s / 2;
  if (shape === 'lungs') {
    // Trachea + bronchi (stroked).
    ctx.beginPath();
    ctx.moveTo(cx, s * 0.16);
    ctx.lineTo(cx, s * 0.34);
    ctx.moveTo(cx, s * 0.34);
    ctx.lineTo(cx - s * 0.1, s * 0.42);
    ctx.moveTo(cx, s * 0.34);
    ctx.lineTo(cx + s * 0.1, s * 0.42);
    ctx.stroke();
    // Two lobes (mirrored, clean kidney/lung outlines).
    for (const sgn of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(cx + sgn * s * 0.07, s * 0.37);
      ctx.quadraticCurveTo(cx + sgn * s * 0.34, s * 0.37, cx + sgn * s * 0.3, s * 0.62);
      ctx.quadraticCurveTo(cx + sgn * s * 0.26, s * 0.83, cx + sgn * s * 0.12, s * 0.8);
      ctx.quadraticCurveTo(cx + sgn * s * 0.07, s * 0.62, cx + sgn * s * 0.07, s * 0.37);
      ctx.closePath();
      ctx.stroke();
    }
  } else {
    // A simple person outline: head + tapered torso.
    ctx.beginPath();
    ctx.arc(cx, s * 0.24, s * 0.1, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(cx - s * 0.19, s * 0.42);
    ctx.quadraticCurveTo(cx, s * 0.36, cx + s * 0.19, s * 0.42);
    ctx.lineTo(cx + s * 0.13, s * 0.82);
    ctx.quadraticCurveTo(cx, s * 0.86, cx - s * 0.13, s * 0.82);
    ctx.closePath();
    ctx.stroke();
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  shapeTex[shape] = tex;
  return tex;
}

export class GlowZone {
  readonly group: THREE.Group;
  private readonly glowMat: THREE.SpriteMaterial;
  private readonly iconMat: THREE.SpriteMaterial | null = null;
  private readonly baseGlow: number;
  private readonly baseIcon: number;
  private readonly phase: number;

  constructor(
    center: THREE.Vector3,
    size: number,
    color: THREE.ColorRepresentation,
    opts: { opacity?: number; phase?: number; shape?: OrganShape } = {},
  ) {
    const { opacity = 0.85, phase = 0, shape } = opts;
    this.group = new THREE.Group();
    this.group.position.copy(center);
    this.baseGlow = opacity;
    this.phase = phase;

    this.glowMat = new THREE.SpriteMaterial({
      map: glowTexture(),
      color: new THREE.Color(color),
      transparent: true,
      opacity,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    const glow = new THREE.Sprite(this.glowMat);
    glow.scale.set(size, size, 1);
    glow.renderOrder = 0;
    this.group.add(glow);

    if (shape) {
      // Warm-white engraved organ outline inside the glow — the "place" hint.
      this.baseIcon = 0.95;
      this.iconMat = new THREE.SpriteMaterial({
        map: organTexture(shape),
        color: new THREE.Color('#fff2ea'),
        transparent: true,
        opacity: this.baseIcon,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      });
      const icon = new THREE.Sprite(this.iconMat);
      const iconSize = size * 0.62;
      icon.scale.set(iconSize, iconSize, 1);
      icon.position.set(0, 0, 0.01);
      icon.renderOrder = 1;
      this.group.add(icon);
    } else {
      this.baseIcon = 0;
    }
  }

  /** Gentle perfusion breathing (call per frame; `t` in seconds). */
  update(t: number): void {
    const b = 0.82 + 0.18 * Math.sin(t * 1.5 + this.phase);
    this.glowMat.opacity = this.baseGlow * b;
    if (this.iconMat) this.iconMat.opacity = this.baseIcon * b;
  }

  dispose(): void {
    this.glowMat.dispose();
    this.iconMat?.dispose();
    // Shared textures intentionally not disposed (reused across zones).
  }
}
