import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import type { BeatClock } from '../clock/index.ts';
import type { HeartScene } from '../scene/index.ts';
import { FocusOverlay } from '../scene/overlays/focus.ts';
import { Reveal } from '../scene/overlays/reveal.ts';
import { easeCameraTo } from './cameraFraming.ts';
import type { SectionConfig, SectionContext } from './types.ts';

gsap.registerPlugin(ScrollTrigger);

/**
 * The view system (BUILD_PLAN §2/§4, Phase 4). Builds one scrollable panel per
 * section over the fixed shared canvas, and uses ScrollTrigger to drive the
 * section lifecycle:
 *   scroll-in  → lazy init() once → ease camera to framing → enter()
 *   scroll-out → exit()  (per-section overlays/work pause)
 * The heart, renderer, and clock are shared; sections only *view* them.
 */
export class SectionManager {
  private readonly scene: HeartScene;
  private readonly clock: BeatClock;
  private readonly sections: SectionConfig[];
  private readonly container: HTMLElement;

  /** The one focus overlay, shared like the heart and driven from `SectionConfig.focus`. */
  private readonly focus: FocusOverlay;
  private readonly unsubFocus: () => void;

  /** One per section that declares `more`. Held only so `dispose` can tear them down. */
  private readonly reveals: Reveal[] = [];

  private readonly panels = new Map<string, HTMLElement>();
  private readonly inited = new Set<string>();
  private readonly triggers: ScrollTrigger[] = [];
  private active: SectionConfig | null = null;
  private tween: gsap.core.Tween | null = null;
  private firstActivation = true;

  constructor(
    scene: HeartScene,
    clock: BeatClock,
    sections: SectionConfig[],
    container: HTMLElement,
  ) {
    this.scene = scene;
    this.clock = clock;
    this.sections = sections;
    this.container = container;
    this.focus = new FocusOverlay(scene);
    // On the scene's own frame callback rather than a private loop: the overlay has to
    // re-project its anchor every frame to survive orbiting, zooming and a heart turn.
    this.unsubFocus = scene.onFrame((dt) => this.focus.update(dt));
    this.buildDom();
    this.wireScroll();
  }

  private ctx(section: SectionConfig): SectionContext {
    return { scene: this.scene, clock: this.clock, panel: this.panels.get(section.id)! };
  }

  /**
   * One panel per section, in a fixed order every section can rely on:
   *
   *   h2 headline · p.section-blurb (~25 words) · div.section-extra · More ↓ · long copy
   *
   * ⚠️ `.section-extra` IS A CONTRACT. Sections that mount their own hints and buttons
   * (§2's turn prompt, §3's compare line, §4's mode toggle) must append THERE, not to
   * `.section-content`, or they land underneath the reveal. The order is deliberate: an
   * instruction the reader needs outranks the long version of the prose, which is why
   * the reveal is always last in the panel.
   */
  private buildDom(): void {
    for (const s of this.sections) {
      const panel = document.createElement('section');
      panel.className = 'section';
      panel.id = `section-${s.id}`;

      const content = document.createElement('div');
      content.className = 'section-content';
      const h = document.createElement('h2');
      h.textContent = s.title;
      content.appendChild(h);
      if (s.blurb) {
        const p = document.createElement('p');
        p.className = 'section-blurb';
        p.textContent = s.blurb;
        content.appendChild(p);
      }

      const extra = document.createElement('div');
      extra.className = 'section-extra';
      content.appendChild(extra);

      // Progressive disclosure (the reader's own choice over a hard cut): the long copy
      // survives, one tap down. One Reveal per panel, the same widget the knob panels use.
      if (s.more?.length) {
        const reveal = new Reveal({ moreLabel: 'More', lessLabel: 'Less' });
        const body = reveal.createBody('section-more');
        for (const para of s.more) body.content.appendChild(reveal.addParagraph(para));
        content.append(reveal.button, body.mount);
        this.reveals.push(reveal);
      }

      panel.appendChild(content);
      this.container.appendChild(panel);
      this.panels.set(s.id, panel);
    }
  }

  private wireScroll(): void {
    for (const s of this.sections) {
      const trigger = ScrollTrigger.create({
        trigger: `#section-${s.id}`,
        start: 'top 55%',
        end: 'bottom 45%',
        onToggle: (self) => {
          if (self.isActive) this.activate(s);
        },
      });
      this.triggers.push(trigger);
    }
  }

  /** Make `section` the active view: lifecycle + camera ease. Idempotent. */
  private activate(section: SectionConfig): void {
    if (this.active === section) return;

    if (this.active) this.active.exit?.(this.ctx(this.active));

    // Lazy-init once (PERFORMANCE invariant).
    if (!this.inited.has(section.id)) {
      section.init?.(this.ctx(section));
      this.inited.add(section.id);
    }

    this.active = section;
    this.scene.start(); // ensure the render loop runs while a section is in view

    const immediate = this.firstActivation;
    this.tween?.kill();
    this.tween = easeCameraTo(this.scene, section.framing, { immediate });
    // Authored cutaway: dissolve the anterior wall to this section's openness,
    // choreographed into the entrance (snap on the very first framing).
    this.scene.getCutaway()?.set(section.cutaway ?? 0, { animate: !immediate });
    // Authored heart turn, choreographed into the same entrance. Sections that don't
    // declare one get 0, which is what restores the shared heart to upright on the way
    // out — no section has to remember to undo it.
    this.scene.getOrientation()?.set(section.heartRotationY ?? 0, { animate: !immediate });
    // Where to look. Passing `null` for a section that declares none is deliberate: it
    // is what hands the whole frame back, so no view has to undo another view's focus.
    this.focus.set(section.focus ?? null);
    this.firstActivation = false;

    section.enter?.(this.ctx(section));
  }

  /**
   * Programmatic navigation. With `scroll` (default) it scrolls the page to the
   * section; the dev jump (?section=id) passes scroll:false to reframe in place.
   */
  goTo(id: string, opts: { scroll?: boolean } = {}): void {
    const section = this.sections.find((s) => s.id === id);
    if (!section) return;
    if (opts.scroll !== false) this.panels.get(id)?.scrollIntoView({ behavior: 'auto' });
    this.activate(section);
  }

  /**
   * Re-apply the LIVE section's framing, without re-running its entrance.
   *
   * ⚠️ EXISTS FOR THE RESOLUTION SCALE, and only that. A framing is turned into a camera pose
   * once, on entrance, and the scale multiplies its distance — so when the scale changes the
   * pose on screen is stale and nothing in the ordinary flow will correct it. Deliberately does
   * NOT touch cutaway, the heart turn, focus or `enter`: a resize is not a re-entrance, and
   * replaying `enter` would restart entrances and re-arm latches.
   */
  reframe(opts: { immediate?: boolean } = {}): void {
    if (!this.active) return;
    this.tween?.kill();
    this.tween = easeCameraTo(this.scene, this.active.framing, {
      immediate: opts.immediate ?? true,
    });
  }

  refresh(): void {
    ScrollTrigger.refresh();
  }

  dispose(): void {
    this.tween?.kill();
    this.unsubFocus();
    this.focus.dispose();
    for (const r of this.reveals) r.dispose();
    for (const t of this.triggers) t.kill();
    if (this.active) this.active.dispose?.(this.ctx(this.active));
  }
}
