import * as THREE from 'three';

/**
 * Creates the one persistent WebGL renderer for the whole page.
 *
 * BUILD_PLAN §2: there is exactly one renderer, shared across every section.
 * This module owns its construction and colour/tone-mapping configuration only.
 */
export function createRenderer(canvas: HTMLCanvasElement): THREE.WebGLRenderer {
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    alpha: true,
    powerPreference: 'high-performance',
  });

  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  // Filmic tone mapping + sRGB output: matte and calm, never blown-out.
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  return renderer;
}

/**
 * Creates the perspective camera framing the heart in the void. A moderate
 * FOV keeps perspective distortion low so anatomy reads honestly.
 */
export function createCamera(aspect: number): THREE.PerspectiveCamera {
  const camera = new THREE.PerspectiveCamera(38, aspect, 0.1, 100);
  camera.position.set(0, 0.4, 6);
  return camera;
}
