import * as THREE from 'three';

/**
 * A tube geometry with a per-length varying radius — so a vessel can flare thick
 * where it leaves the heart and taper toward the organ, reading as a real vessel
 * rather than a uniform pipe. Mirrors THREE.TubeGeometry's Frenet-frame sweep but
 * takes a `radiusFn(u)` (u = arc-length fraction 0→1) and also writes true outward
 * normals so a fresnel glass shell can light its rim.
 *
 * Vertex layout matches TubeGeometry: (tubular+1) rings × (radial+1) verts, ring
 * index outer / radial index inner — so a caller can paint a per-ring colour
 * gradient the same way.
 */
export function buildVaryingTube(
  curve: THREE.Curve<THREE.Vector3>,
  tubular: number,
  radial: number,
  radiusFn: (u: number) => number,
  closed: boolean,
): THREE.BufferGeometry {
  const frames = curve.computeFrenetFrames(tubular, closed);
  const positions: number[] = [];
  const normals: number[] = [];
  const indices: number[] = [];

  const P = new THREE.Vector3();
  const N = new THREE.Vector3();
  const B = new THREE.Vector3();
  const normal = new THREE.Vector3();

  for (let i = 0; i <= tubular; i++) {
    const u = i / tubular;
    curve.getPointAt(u, P);
    N.copy(frames.normals[i]!);
    B.copy(frames.binormals[i]!);
    const r = radiusFn(u);
    for (let j = 0; j <= radial; j++) {
      const v = (j / radial) * Math.PI * 2;
      const sin = Math.sin(v);
      const cos = -Math.cos(v);
      normal.set(cos * N.x + sin * B.x, cos * N.y + sin * B.y, cos * N.z + sin * B.z).normalize();
      positions.push(P.x + r * normal.x, P.y + r * normal.y, P.z + r * normal.z);
      normals.push(normal.x, normal.y, normal.z);
    }
  }

  for (let i = 1; i <= tubular; i++) {
    for (let j = 1; j <= radial; j++) {
      const a = (radial + 1) * (i - 1) + (j - 1);
      const b = (radial + 1) * i + (j - 1);
      const c = (radial + 1) * i + j;
      const d = (radial + 1) * (i - 1) + j;
      indices.push(a, b, d, b, c, d);
    }
  }

  const geom = new THREE.BufferGeometry();
  geom.setIndex(indices);
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  return geom;
}
