import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

/**
 * Loads the canonical anatomical heart (3D4SCI base, rebuilt per MODEL_FIT.md:
 * closed rest pose baked, cutaway cover as a separate mesh, beat + valve morph
 * targets authored, textures downscaled to 2K) and prepares it for the void.
 *
 * The model ships its own realistic PBR material (one shared 2K albedo / AO+
 * roughness / normal set) — we KEEP it here (unlike the old untextured base,
 * which we recoloured). Per-structure color-coding and flow tint come with the
 * section overlays (Phase B+). Morph targets are driven in heartRig.ts.
 */
// Base-aware, NOT root-absolute. Vite rewrites the URLs it generates when you build
// with --base, but it cannot rewrite a hardcoded string in source. A literal
// '/models/...' therefore keeps pointing at the domain root — correct on
// samfrausto.com, but a 404 anywhere the site is served from a subdirectory, e.g.
// the portfolio copy at /projects/heart-valve/app/, where the model silently failed
// to load and the scene rendered without it.
// BASE_URL is '/' in dev and for a default build, so nothing changes there.
const MODEL_URL = `${import.meta.env.BASE_URL}models/heart-base-v2.glb`;
const TARGET_RADIUS = 1.9;

export async function loadHeartModel(): Promise<THREE.Group> {
  const loader = new GLTFLoader();
  // Cache-bust in dev so re-exported geometry (new morph targets) is never
  // served stale from the browser cache while we iterate on the model.
  const url = import.meta.env.DEV ? `${MODEL_URL}?t=${Date.now()}` : MODEL_URL;
  const gltf = await loader.loadAsync(url);
  const root = gltf.scene;

  root.traverse((obj) => {
    const mesh = obj as THREE.Mesh;
    if (!mesh.isMesh) return;
    // Keep the model's own PBR material; just ensure it lights and shadows well.
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    const mat = mesh.material as THREE.MeshStandardMaterial | undefined;
    if (mat) mat.side = THREE.FrontSide;
    if (!mesh.geometry.getAttribute('normal')) {
      mesh.geometry.computeVertexNormals();
    }
  });

  // Recentre the content on the origin, then scale to fit the void.
  const box = new THREE.Box3().setFromObject(root);
  const center = box.getCenter(new THREE.Vector3());
  const radius = box.getBoundingSphere(new THREE.Sphere()).radius || 1;
  root.position.sub(center);

  const group = new THREE.Group();
  group.name = 'heart-model';
  group.add(root);
  group.scale.setScalar(TARGET_RADIUS / radius);

  // ⚠ THE FIT SCALE IS THE PIECE'S WHOLE COORDINATE SYSTEM, AND IT IS NOT A CONSTANT.
  // `radius` above comes from a box that three INFLATES once per morph target (glTF
  // morphs are relative, so `computeBoundingBox` expands cumulatively by each
  // target's own extremes), so re-exporting the model with a different number of
  // morphs — or with morph deltas that reach further — silently moves every
  // world-space anchor in every section. It has happened once already. Expose it so
  // the next re-export can be checked against a rendered number instead of being
  // re-derived by reasoning; `?diag` prints it.
  group.userData.fitScale = TARGET_RADIUS / radius;
  group.userData.fitRadius = radius;

  // The model exports Y-up with the apex toward −Y (sits apex-down, as in the
  // chest). Orientation is otherwise left upright; section cameras frame it, and
  // any anatomical tilt is tuned live once viewed in the app.
  group.rotation.set(0, 0, 0);

  return group;
}
