import * as THREE from 'three';
import type { BeatClock } from '../../clock/index.ts';
import type { Compartment } from '../../engine/index.ts';
import type { HeartScene } from '../index.ts';

/**
 * Manometer columns (SPEC §5, §4 keystone; MODEL_FIT.md Phase B). Pressure-as-
 * height: each chamber/vessel gets an in-scene 3D column whose fill rises with
 * its live pressure, plus a crisp DOM readout (mmHg, and mL for chambers) pinned
 * to the fill top — the hybrid overlay approach. Everything reads the one clock,
 * so the columns and numbers are the same beat the heart is dancing, drawn as
 * height. This is the Wiggers y-axis in embryo.
 */
export interface ManometerSpec {
  /** Which compartment's pressure this column shows. */
  compartment: Compartment;
  /** World-space base of the column (the section places it beside its chamber). */
  anchor: [number, number, number];
  /** Short label, e.g. "LV". */
  label: string;
  /** Optional plain-language descriptor shown small under the value, e.g.
   *  "upstream — fills the pump". Says what the column IS, in human terms. */
  sublabel?: string;
  /** Also show this compartment's volume in mL (ventricles / atria). */
  showVolume?: boolean;
  /** Fill colour (CSS/three colour string). */
  color?: string;
  /**
   * Optional pressure source (mmHg) that overrides the clock read — so a section
   * can drive a column from the reader's own handle in a "you are the pressure"
   * manual mode, then hand it back to the clock. When absent the column reads the
   * live clock (the default behaviour).
   */
  pressure?: () => number;
  /**
   * Optional volume source (mL) overriding the clock read; return `null` to hide
   * the mL line (e.g. while a manual mode makes volume undefined). When absent the
   * column falls back to `showVolume` reading the clock.
   */
  volume?: () => number | null;
}

interface Column {
  spec: ManometerSpec;
  fill: THREE.Mesh;
  meniscus: THREE.Sprite;
  /** Over-range chevron above the tube — see `overRange`. */
  over: THREE.Mesh;
  base: THREE.Vector3;
  readout: HTMLDivElement;
  color: THREE.Color;
  bobPhase: number;
}

/** Soft radial glow sprite (white; tinted by material colour) for the liquid surface. */
let _glowTex: THREE.Texture | null = null;
function glowTexture(): THREE.Texture {
  if (_glowTex) return _glowTex;
  const S = 64;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = S;
  const ctx = canvas.getContext('2d')!;
  const g = ctx.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.5, 'rgba(255,255,255,0.5)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, S, S);
  _glowTex = new THREE.CanvasTexture(canvas);
  _glowTex.needsUpdate = true;
  return _glowTex;
}

/** A unit-height cylinder (base at y=0, top at y=1) with a vertical colour gradient
 *  baked into vertex colours: deep at the bottom → bright toward the surface. Scaling
 *  Y keeps the gradient mapped base→surface, so it reads as a glowing liquid column. */
function gradientColumn(radius: number, color: THREE.Color): THREE.BufferGeometry {
  const geo = new THREE.CylinderGeometry(radius, radius, 1, 28, 1, true);
  geo.translate(0, 0.5, 0);
  const pos = geo.getAttribute('position');
  const deep = color.clone().multiplyScalar(0.32);
  const bright = color.clone().lerp(new THREE.Color('#ffffff'), 0.22);
  const colors = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = THREE.MathUtils.clamp(pos.getY(i), 0, 1);
    c.copy(deep).lerp(bright, t * t); // ease so the glow concentrates near the surface
    colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return geo;
}

/** mmHg mapped to a full-scale column. Exported so a section can map its own drag
 *  handles pressure↔height identically to the rendered fill. */
export const MANOMETER_PMAX = 130;
/** World-units height of a full-scale (PMAX) column. */
export const MANOMETER_COLUMN_HEIGHT = 1.7;
const DEFAULT_PMAX = MANOMETER_PMAX;
const COLUMN_HEIGHT = MANOMETER_COLUMN_HEIGHT;
const COLUMN_W = 0.13;

export class ManometerOverlay {
  private readonly scene: HeartScene;
  private readonly clock: BeatClock;
  private readonly pmax: number;
  /** This instance's full-scale column height, world units (see the `scale` option). */
  private readonly colHeight: number;
  private readonly group = new THREE.Group();
  private readonly dom: HTMLDivElement;
  private readonly columns: Column[] = [];
  private unframe: (() => void) | null = null;
  private visible = false;

  constructor(
    scene: HeartScene,
    clock: BeatClock,
    specs: ManometerSpec[],
    /**
     * `scale` sizes this whole set of columns (height AND width together) so a section
     * can make the pressure story its visual PROTAGONIST or push it into a quiet
     * supporting role — the two Act III views deliberately differ this way.
     *
     * It is presentational only: `pmax` is untouched, and height stays exactly
     * proportional to pressure within the set, so heights remain directly comparable.
     * Sections that map their own drag handles through `MANOMETER_COLUMN_HEIGHT` (§4)
     * must leave this at 1, or the handles would part company with the rendered fill.
     */
    opts: { pmax?: number; scale?: number } = {},
  ) {
    this.scene = scene;
    this.clock = clock;
    this.pmax = opts.pmax ?? DEFAULT_PMAX;
    const scale = opts.scale ?? 1;
    this.colHeight = COLUMN_HEIGHT * scale;
    const width = COLUMN_W * scale;
    this.group.name = 'manometers';

    this.dom = document.createElement('div');
    this.dom.className = 'manometer-layer';
    this.dom.style.cssText =
      'position:fixed;inset:0;pointer-events:none;z-index:5;display:none;' +
      "font:600 12px/1.25 ui-monospace,Menlo,Consolas,monospace";
    document.body.appendChild(this.dom);

    const R = width * 0.5;
    // A faint glass tube showing the full scale the liquid rises against.
    const trackGeo = new THREE.CylinderGeometry(R * 1.05, R * 1.05, 1, 28, 1, true);
    trackGeo.translate(0, 0.5, 0);

    let phase = 0;
    for (const spec of specs) {
      const color = new THREE.Color(spec.color ?? '#e8b24a');
      const base = new THREE.Vector3(...spec.anchor);

      const track = new THREE.Mesh(
        trackGeo,
        new THREE.MeshBasicMaterial({
          color, transparent: true, opacity: 0.1, side: THREE.DoubleSide,
          depthWrite: false, toneMapped: false,
        }),
      );
      track.position.copy(base);
      track.scale.y = this.colHeight;
      this.group.add(track);

      // The rising liquid column — a glowing vertical gradient (unlit so it reads as
      // luminous liquid rather than a shaded solid).
      const fill = new THREE.Mesh(
        gradientColumn(R, color),
        new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, opacity: 0.95, toneMapped: false }),
      );
      fill.position.copy(base);
      fill.scale.y = 0.001;
      this.group.add(fill);

      // The bright liquid surface (meniscus) — a soft glow that bobs gently, the
      // liquid-fill-gauge wave read as a single luminous surface line.
      // OVER-RANGE CHEVRON. A column's fill is clamped to `pmax`, so a pressure past
      // full scale would otherwise leave the bar sitting still at the top while its
      // mmHg readout kept climbing — a bar that stops moving while its number rises is
      // exactly the quiet dishonesty this piece avoids, and it was rejected outright
      // once already (the doors section chose a higher ceiling instead).
      //
      // A higher ceiling is not available to every section: §6 runs a deliberately
      // ZOOMED ~15 mmHg scale, because the atrial 'a' wave it exists to show is only
      // ~1.7 mmHg and is invisible at the shared 130. That scale is right for its own
      // phase and cannot hold a scrub into ejection (LV 123–171 mmHg). So instead of
      // hiding the overflow, the column says so: this chevron lights above the tube
      // whenever the true pressure is off the top of the scale, and the readout labels
      // it. The reader is told the instrument ran out of range rather than being shown
      // a frozen bar.
      const overGeo = new THREE.ConeGeometry(R * 1.5, R * 2.2, 4);
      overGeo.translate(0, R * 1.1, 0);
      const over = new THREE.Mesh(
        overGeo,
        new THREE.MeshBasicMaterial({
          color: color.clone().lerp(new THREE.Color('#ffffff'), 0.5),
          transparent: true, opacity: 0, depthWrite: false, toneMapped: false,
          blending: THREE.AdditiveBlending,
        }),
      );
      over.position.set(base.x, base.y + this.colHeight + R * 1.2, base.z);
      over.renderOrder = 6;
      over.visible = false;
      this.group.add(over);

      const meniscus = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: glowTexture(),
          color: color.clone().lerp(new THREE.Color('#ffffff'), 0.35),
          transparent: true, opacity: 0, depthWrite: false, depthTest: false,
          blending: THREE.AdditiveBlending, toneMapped: false,
        }),
      );
      meniscus.scale.set(width * 2.6, width * 1.5, 1);
      meniscus.renderOrder = 6;
      this.group.add(meniscus);

      const readout = document.createElement('div');
      readout.style.cssText =
        'position:absolute;transform:translate(-50%,-150%);white-space:pre;text-align:center;' +
        `color:#${color.getHexString()};text-shadow:0 1px 3px rgba(0,0,0,.85)`;
      this.dom.appendChild(readout);

      this.columns.push({ spec, fill, meniscus, over, base, readout, color, bobPhase: phase });
      phase += 1.7;
    }

    this.group.visible = false;
    this.scene.scene.add(this.group);
  }

  show(): void {
    if (this.visible) return;
    this.visible = true;
    this.group.visible = true;
    this.dom.style.display = 'block';
    this.unframe = this.scene.onFrame(() => this.update());
    this.update();
  }

  hide(): void {
    if (!this.visible) return;
    this.visible = false;
    this.group.visible = false;
    this.dom.style.display = 'none';
    this.unframe?.();
    this.unframe = null;
  }

  private update(): void {
    const state = this.clock.sample();
    const camera = this.scene.camera;
    const canvas = this.scene.renderer.domElement;
    const rect = canvas.getBoundingClientRect();
    const top = new THREE.Vector3();

    const now = performance.now() / 1000;
    for (const col of this.columns) {
      const p = col.spec.pressure ? col.spec.pressure() : state.pressures[col.spec.compartment];
      const frac = THREE.MathUtils.clamp(p / this.pmax, 0, 1);
      const h = Math.max(frac * this.colHeight, 0.001);
      col.fill.scale.y = h;

      // Off the top of the scale: light the chevron and pulse it, so a saturated bar
      // is never mistaken for a settled one.
      const over = p > this.pmax;
      col.over.visible = over;
      if (over) {
        (col.over.material as THREE.MeshBasicMaterial).opacity =
          0.55 + 0.35 * Math.sin(now * 5.5 + col.bobPhase);
      }

      // Bob the liquid surface gently (the animated meniscus), scaled by how much
      // liquid there is so an empty column doesn't shimmer.
      const bob = Math.sin(now * 2.4 + col.bobPhase) * 0.012 * (0.4 + frac) * (this.colHeight / COLUMN_HEIGHT);
      col.meniscus.position.set(col.base.x, col.base.y + h + bob, col.base.z);
      (col.meniscus.material as THREE.SpriteMaterial).opacity = 0.35 + 0.5 * frac;

      // Project the fill top to screen for the readout.
      top.set(col.base.x, col.base.y + h, col.base.z).project(camera);
      const behind = top.z > 1;
      col.readout.style.display = behind ? 'none' : 'block';
      if (!behind) {
        col.readout.style.left = `${rect.left + (top.x * 0.5 + 0.5) * rect.width}px`;
        col.readout.style.top = `${rect.top + (-top.y * 0.5 + 0.5) * rect.height}px`;
        // Lifted clear of the over-range chevron, which occupies exactly the space the
        // readout normally sits in: both are pinned to the fill top, and past full scale
        // the fill top IS the tube top. Without this the "off this scale" note prints
        // straight over the marker it is explaining.
        col.readout.style.transform = over
          ? 'translate(-50%,-270%)'
          : 'translate(-50%,-150%)';
        let value = `${col.spec.label}  ${Math.round(p)} mmHg`;
        if (col.spec.volume) {
          const v = col.spec.volume();
          if (v !== null) value += `  ·  ${Math.round(v)} mL`;
        } else if (col.spec.showVolume) {
          value += `  ·  ${Math.round(state.volumes[col.spec.compartment])} mL`;
        }
        // Value line + an optional dim plain-language descriptor saying what it is.
        // When the true pressure is past full scale the value line says so, so the
        // number and the (clamped) bar can never disagree silently.
        col.readout.innerHTML =
          `<div>${value}${over ? '  ▲' : ''}</div>` +
          (over
            ? `<div style="margin-top:2px;font:400 9.5px/1.3 var(--font-body,sans-serif);` +
              `letter-spacing:.02em;opacity:.85">off this scale</div>`
            : '') +
          (col.spec.sublabel
            ? `<div style="margin-top:2px;font:400 9.5px/1.3 var(--font-body,sans-serif);` +
              `letter-spacing:.02em;opacity:.72">${col.spec.sublabel}</div>`
            : '');
      }
    }
  }

  dispose(): void {
    this.hide();
    this.scene.scene.remove(this.group);
    this.group.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (mesh.geometry) mesh.geometry.dispose();
      const mat = (o as THREE.Mesh | THREE.Sprite).material as THREE.Material | THREE.Material[] | undefined;
      if (Array.isArray(mat)) mat.forEach((m) => m.dispose());
      else mat?.dispose();
    });
    this.dom.remove();
  }
}
