import type {
  CardiacEngine,
  CycleEvents,
  CycleMetrics,
  EngineState,
} from '../engine/index.ts';

export type ClockListener = (phase: number) => void;

/**
 * The master beat clock (BUILD_PLAN §2, SPEC.md §4) — the single through-line.
 *
 * It holds one normalized position in the beat, `phase ∈ [0, 1)`, and reads the
 * engine at that phase. It does NOT own cardiac timing: the engine is the source
 * of truth (ONE HEART, ONE CLOCK). Every view — the dev HUD now, the 3D scene
 * and Wiggers diagram later — binds to this one clock, so they all move together.
 *
 * Direct-manipulation contract (SPEC.md §4): the clock never advances itself.
 * The reader scrubs `phase`; nothing autoplays. Freezing on an instant is just
 * holding the phase still — a first-class, supported state.
 */
export class BeatClock {
  private readonly engine: CardiacEngine;
  private phase = 0;
  private readonly listeners = new Set<ClockListener>();

  constructor(engine: CardiacEngine) {
    this.engine = engine;
  }

  /** Current normalized position in the beat, 0 → 1. */
  getPhase(): number {
    return this.phase;
  }

  /** Set the position; wraps into [0, 1) so scrubbing past the end loops. */
  setPhase(phase: number): void {
    this.phase = ((phase % 1) + 1) % 1;
    this.emit();
  }

  /** The engine frame at the current phase (the "clock frame"). */
  sample(): EngineState {
    return this.engine.sample(this.phase);
  }

  getEvents(): CycleEvents {
    return this.engine.getEvents();
  }

  getMetrics(): CycleMetrics {
    return this.engine.getCycleMetrics();
  }

  getEngine(): CardiacEngine {
    return this.engine;
  }

  /**
   * Re-solve the engine after a parameter/knob change, then notify listeners so
   * every bound view refreshes together. Keeps the current phase.
   */
  resolve(): void {
    this.engine.runToSteadyState();
    this.emit();
  }

  /** Subscribe to phase changes; fires immediately with the current phase. */
  subscribe(listener: ClockListener): () => void {
    this.listeners.add(listener);
    listener(this.phase);
    return () => this.listeners.delete(listener);
  }

  private emit(): void {
    for (const listener of this.listeners) listener(this.phase);
  }
}
