import gsap from 'gsap';
import type { SectionConfig, SectionContext } from './types.ts';
import { AmbientBeat } from './ambientBeat.ts';
import { Circuit } from '../scene/overlays/circuit.ts';
import { FlowTintOverlay } from '../scene/overlays/flowTint.ts';
import { arrivedThroughAct0 } from './section0.ts';

/**
 * Section 1 — "The pump and the circuit" (SPEC §6, Act I).
 *
 * Teaches: the heart is two pumps in series sharing one beat — the right side
 * drives the short pulmonary loop (to the lungs for oxygen), the left side the
 * vast systemic loop (out to the whole body) — and the systemic loop dwarfs the
 * pulmonary one, which is why the left ventricle is the heavyweight.
 *
 * View: opens TIGHT on the real beating heart (the "realistic, not cartoon"
 * promise in the first second), then the camera pulls back and the double
 * circuit draws in — blood flowing through the real great vessels and out around
 * two loops, turning scarlet at the lungs and crimson out in the body. The
 * reader drags a bolus around the whole figure-eight at their own pace.
 *
 * This is a *view*: it owns no heart, no timing, no animation of its own — only
 * a camera choreography, the circuit + label + flow overlays, and the hero-beat
 * handoff. The heart rides the ONE master clock (see AmbientBeat).
 */

/** Tight hero framing the entrance opens on (heart fills the frame). */
const HERO_FRAMING = { position: [0, 0.15, 3.7] as const, target: [0, -0.05, 0] as const };
/** Pulled-back resting framing that reveals the whole ♥ around the heart. Centred
 *  on the ♥ midline (x ≈ −0.306, between the two SVC cups) and vertically so the ♥
 *  bottom point lines up above the centre scroll-cue arrow — the hero composition. */
const WIDE_FRAMING = { position: [-0.306, -0.5, 10.5], target: [-0.306, -0.72, 0] } as const;

export function createSection1(): SectionConfig {
  let ambient: AmbientBeat | null = null;
  let entrance: gsap.core.Timeline | null = null;
  let circuit: Circuit | null = null;
  let flow: FlowTintOverlay | null = null;
  let unsubFrame: (() => void) | null = null;

  const startAmbient = (ctx: SectionContext): void => {
    ambient?.stop();
    ambient = new AmbientBeat(ctx.clock, { periodSeconds: 1.1 });
    ambient.start();
  };

  /**
   * The LV volume range the beat-dots normalize their contraction signal against.
   *
   * Re-read on every entrance rather than captured once, because §8 hands the reader
   * contractility and afterload knobs whose changes PERSIST for the whole session (one
   * heart). A reader who strengthens the squeeze and scrolls back up to the hero would
   * otherwise be normalizing against a beat that no longer exists — across that knob's
   * travel the LV range moves from 48–119 mL to 26–101 mL, enough to push the signal
   * against its clamp and desynchronize the dot launches from the visible squeeze.
   */
  let lvMin = 0;
  let lvMax = 1;
  const readLvRange = (ctx: SectionContext): void => {
    const engine = ctx.clock.getEngine();
    lvMin = Infinity;
    lvMax = -Infinity;
    for (let i = 0; i < 200; i++) {
      const v = engine.sample(i / 200).volumes.LV;
      lvMin = Math.min(lvMin, v);
      lvMax = Math.max(lvMax, v);
    }
  };

  return {
    id: 'pump-circuit',
    title: 'The pump and the circuit',
    // ⚠️ This is the one section allowed to STATE its idea rather than set it up. The
    // §1 visual became a symmetric ♥ silhouette in art direction, so the
    // "two loops, and one dwarfs the other" aha no longer has a shape to land on —
    // SPEC's own BUILD NOTE hands it to the copy. Everywhere else the prose sets up
    // and the interactive pays off; here there is nothing to spoil. What changed in
    // the density pass is only WHERE it is stated: the short version opens, the two
    // journeys and the asymmetry moved behind `more`.
    blurb:
      'One muscle. One beat. But the blood takes two separate journeys, and one ' +
      'of them is far longer than the other. Watch a pulse leave.',
    more: [
      'The short trip runs through the lungs and straight back. The long one goes ' +
        'out to your head, your hands and your feet.',
      'So one side of this pump does most of the work. Which side, and how much ' +
        'harder it has to push, is what the rest of this is about.',
    ],
    // Resting framing is the pulled-back view; the entrance eases here from tight.
    framing: { position: [...WIDE_FRAMING.position], target: [...WIDE_FRAMING.target] },

    init: (ctx: SectionContext) => {
      // Lazy, once: build the double circuit into the shared scene and drive its
      // blood flow off the shared render loop (it no-ops while hidden, so it's
      // free when the section is off-screen).
      circuit = new Circuit();
      ctx.scene.scene.add(circuit.group);
      // Drive the beat-dots off the SAME normalized ventricular contraction the rig
      // feeds the red-muscle morph (0 relaxed → 1 fully contracted), so the dots
      // eject from the SVC cups exactly as the red part squeezes. Precompute the LV
      // volume range over one beat to normalize against (mirrors heartRig.ts).
      readLvRange(ctx);
      const contraction = (): number => {
        const span = lvMax - lvMin;
        return span > 1e-6
          ? Math.min(1, Math.max(0, (lvMax - ctx.clock.sample().volumes.LV) / span))
          : 0;
      };
      unsubFrame = ctx.scene.onFrame((dt) => circuit?.update(dt, contraction()));

      // Route flow through the REAL vessels: oxygenated out the aorta, deox out
      // the pulmonary artery, deox back down the cavae — so the blood visibly
      // leaves and re-enters the real anatomy into the schematic loops.
      flow = new FlowTintOverlay(ctx.scene, [
        { mesh: 'Aorta', oxygenation: 'ox', direction: 1 },
        { mesh: 'PulmonaryArtery', oxygenation: 'deox', direction: 1 },
        { mesh: 'SVC', oxygenation: 'deox', direction: -1 },
        { mesh: 'IVC', oxygenation: 'deox', direction: -1 },
      ]);

      /**
       * ⚠️ RE-HOMED BECAUSE ACT 0 KILLED ITS OLD HOME. This disclaimer used to live in
       * `#scroll-cue`, which hides itself once the reader is 30% of a viewport down the
       * page. Act 0 is 260vh tall, so by the time anyone reaches §1 that test has long since
       * passed and the cue can never appear again — silently taking a deliberately-worded
       * reader-facing line with it. The words are unchanged: they exist because the ♥ is a
       * symbol and saying so up front is what buys the licence to draw it.
       *
       * ⚠️ `.section-extra` IS THE CONTRACT for panel furniture. Appending to
       * `.section-content` would put this underneath the `More` link.
       */
      const note = document.createElement('p');
      note.className = 'section-note';
      note.textContent = 'A symbol, not a diagram. The real route is stranger than this one.';
      ctx.panel.querySelector('.section-extra')?.appendChild(note);
    },

    enter: (ctx: SectionContext) => {
      const { scene, panel } = ctx;
      const cam = scene.camera;
      const ctrl = scene.controls;
      const search = new URLSearchParams(window.location.search);
      panel.classList.add('is-active');
      readLvRange(ctx); // the operating point may have moved since init — see above
      // Ambient hero beat until first input — but if the clock is parked on an
      // instant for inspection (?phase), hold there instead of advancing off it
      // (so the beat-driven dots can be inspected at a known phase).
      if (search.get('phase') === null) startAmbient(ctx);
      flow?.show();

      // Dev affordance: ?intro=0 skips the entrance and rests at the wide framing
      // (headless screenshots can't advance GSAP, so this is how the composed
      // resting view is verified). The manager has already snapped to WIDE.
      /**
       * ⚠️ THE PULL-BACK AND ACT 0'S ZOOM ARE THE SAME GESTURE, so only one of them may
       * play. Act 0 falls from the neon dot all the way to this section's resting framing;
       * if the hero entrance then fired, the camera would rush in to 3.7, snap back out and
       * pull in again — three moves where the reader was promised one. So a reader who
       * arrived by scrolling through Act 0 gets the composed view they already flew to.
       *
       * A reader who lands here another way still gets the original entrance: a direct load
       * at §1, a `?section` jump, or scrolling up from below without ever having fallen
       * through the opener. That is why this is a latched flag from Act 0 and not simply
       * "is Act 0 in the spine".
       */
      if (search.get('intro') === '0' || arrivedThroughAct0.value) {
        ctrl.enabled = true;
        circuit?.showInstant();
        return;
      }

      // Open tight on the hero heart, then choreograph the pull-back. The manager
      // has just set the camera to the resting (wide) framing; override to tight
      // in the same tick so the first rendered frame is the hero close-up.
      entrance?.kill();
      ctrl.enabled = false;
      cam.position.set(...HERO_FRAMING.position);
      ctrl.target.set(...HERO_FRAMING.target);
      ctrl.update();

      const cp = cam.position;
      const ct = ctrl.target;
      const tgt = WIDE_FRAMING;
      entrance = gsap
        .timeline({
          onComplete: () => {
            ctrl.enabled = true; // hand control to the reader
          },
        })
        // Hold the hero beat for a moment before pulling back.
        .to({}, { duration: 0.9 })
        .to(
          cp,
          {
            x: tgt.position[0], y: tgt.position[1], z: tgt.position[2],
            duration: 2.6, ease: 'power2.inOut',
            onUpdate: () => ctrl.update(),
          },
          '<',
        )
        .to(
          ct,
          {
            x: tgt.target[0], y: tgt.target[1], z: tgt.target[2],
            duration: 2.6, ease: 'power2.inOut',
          },
          '<',
        )
        // Trace the circuit in as the camera settles back (SPEC: "circuit paths
        // draw in"); the blooms come alive with it.
        .add(() => circuit?.reveal(2.2), '<0.6');
    },

    exit: (ctx: SectionContext) => {
      ctx.panel.classList.remove('is-active');
      ambient?.stop();
      ambient = null;
      entrance?.kill();
      entrance = null;
      circuit?.hide();
      flow?.hide();
    },

    dispose: (ctx: SectionContext) => {
      ambient?.stop();
      entrance?.kill();
      unsubFrame?.();
      unsubFrame = null;
      flow?.dispose();
      flow = null;
      if (circuit) {
        ctx.scene.scene.remove(circuit.group);
        circuit.dispose();
        circuit = null;
      }
    },
  };
}
