import * as THREE from 'three';
import type { HeartScene } from '../index.ts';
import { scalePx } from '../../ui/uiScale.ts';

/**
 * Valve labels (SPEC §3 "The four valves") — a DOM tag pinned to each valve's
 * world anchor, carrying the valve's NAME, its LIVE open/shut state, and (when
 * shut) the pressure it is holding back.
 *
 * Why this exists rather than reusing `ChamberLabels`: those tags are static text
 * that fades by surface normal, because a chamber's identity never changes. A
 * valve's whole point is that its state changes twice a beat, so the tag has to
 * be a live readout — and it is the readout, not the geometry, that makes an OPEN
 * semilunar legible at all (its cusps flatten against the vessel wall and very
 * nearly disappear, which is the honest anatomy; see HANDOFF §3).
 *
 * Two presentation states, because SPEC §3 asks the reader to isolate one valve
 * and compare two:
 *  - `full`   — name, state chip, load, and the mechanism sentence.
 *  - `dim`    — name + state chip only, faded back, so three other valves can
 *               stay on screen as context without competing.
 *
 * Anchors are expressed in the heart frame (see `heartOrientation.ts`) so they
 * survive a section's heart turn, exactly as `StatusBadge` does.
 */

export interface ValveLabelSpec {
  /** Stable key, matching the engine's Valve union where applicable. */
  key: string;
  /** Display name, e.g. "Mitral valve". */
  name: string;
  /** Short mechanism sentence, shown only in the `full` state. */
  mechanism: string;
  /**
   * The structure the tag NAMES, world space — the valve's own centre. A leader
   * line is drawn from the tag back to this point; without one, spreading the tags
   * far enough apart to stop them colliding just trades one unreadable layout for
   * another.
   */
  point: [number, number, number];
  /**
   * Where the tag sits RELATIVE TO its projected valve, in SCREEN PIXELS.
   *
   * ⚠️ This is deliberately screen-space, and the first version of this overlay got
   * it wrong by being world-space. Placing tags by hand-solved world anchors means
   * re-deriving the camera basis, the fov and the aspect ratio by hand for every
   * tag — which put two of the four cleanly off the top of the screen, and then put
   * two off the right edge on the next attempt. Offsetting in pixels after
   * projection is exact by construction, survives any viewport aspect, and keeps
   * working if FRAMING is ever re-tuned. The tag is also clamped into the viewport,
   * so a tag can never again leave the frame.
   */
  offsetPx: [number, number];
  /**
   * The valve this one should be COMPARED against. When a valve is isolated its
   * counterpart stays on screen (dimmed) while the other two hide — so isolating
   * the mitral leaves the aortic beside it, which is the whole point of SPEC §3's
   * "set mitral vs aortic side by side and compare the two sealing strategies".
   * Hiding all three others would isolate the valve from its own argument.
   */
  counterpart?: string;
  /** Leader-dot accent (CSS). Left heart scarlet, right heart venous blue. */
  accent: string;
}

/** Optional screen-space box tags are kept inside, in CSS pixels. */
export interface ValveLabelBounds {
  left?: number;
  right?: number;
  top?: number;
  bottom?: number;
}

/** What the section tells each label to show, per frame. */
export interface ValveLabelState {
  /** True while the valve is open (flow allowed). */
  open: boolean;
  /** Pressure difference across the valve, mmHg. Shown while shut. */
  loadMmHg: number;
}

type Emphasis = 'full' | 'dim' | 'hidden';

const OPEN_COLOR = '#54e6b0'; // teal — flow allowed (matches §4's badge)
const SHUT_COLOR = '#ff6a58'; // scarlet — flow blocked

interface Label {
  spec: ValveLabelSpec;
  point: THREE.Vector3;
  el: HTMLDivElement;
  stateEl: HTMLSpanElement;
  loadEl: HTMLSpanElement;
  mechEl: HTMLDivElement;
  /** Leader line from the tag back to the structure it names. */
  leader: SVGLineElement;
  /** Small ring marking the structure itself. */
  pin: SVGCircleElement;
  emphasis: Emphasis;
}

const SVG_NS = 'http://www.w3.org/2000/svg';

export class ValveLabels {
  private readonly scene: HeartScene;
  private readonly frame: THREE.Object3D | null;
  private readonly dom: HTMLDivElement;
  private readonly svg: SVGSVGElement;
  private readonly labels = new Map<string, Label>();
  private readonly projected = new THREE.Vector3();
  private unframe: (() => void) | null = null;
  private visible = false;
  private showAt = 0;

  private readonly bounds: ValveLabelBounds;

  constructor(
    scene: HeartScene,
    specs: ValveLabelSpec[],
    opts: { frame?: THREE.Object3D; bounds?: ValveLabelBounds } = {},
  ) {
    this.scene = scene;
    this.frame = opts.frame ?? null;
    this.bounds = opts.bounds ?? {};

    this.dom = document.createElement('div');
    this.dom.className = 'valve-label-layer';
    this.dom.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:6;display:none';
    document.body.appendChild(this.dom);

    // Leader lines live in one SVG sized to the viewport, BEHIND the cards (the
    // cards are later siblings) so a line never draws over its own text.
    this.svg = document.createElementNS(SVG_NS, 'svg');
    this.svg.setAttribute('width', '100%');
    this.svg.setAttribute('height', '100%');
    this.svg.style.cssText = 'position:absolute;inset:0;overflow:visible;pointer-events:none';
    this.dom.appendChild(this.svg);

    for (const spec of specs) {
      const el = document.createElement('div');
      el.style.cssText =
        'position:absolute;transform:translate(-50%,-50%);white-space:nowrap;' +
        'will-change:left,top,opacity;transition:opacity .25s ease';

      const card = document.createElement('div');
      card.style.cssText =
        'display:inline-block;padding:6px 11px 7px;border-radius:9px;' +
        'background:rgba(10,7,6,.66);backdrop-filter:blur(3px);' +
        `border:1px solid ${spec.accent}66;box-shadow:0 4px 16px rgba(0,0,0,.55)`;

      const head = document.createElement('div');
      head.style.cssText = 'display:flex;align-items:center;gap:7px';
      const dot = document.createElement('span');
      dot.style.cssText =
        `flex:0 0 auto;width:8px;height:8px;border-radius:50%;background:${spec.accent};` +
        `box-shadow:0 0 9px ${spec.accent}`;
      const nameEl = document.createElement('span');
      nameEl.style.cssText =
        'color:#f7f1ea;font:600 14px/1.15 var(--font-display,Georgia,serif);letter-spacing:.01em';
      nameEl.textContent = spec.name;
      head.append(dot, nameEl);

      const line = document.createElement('div');
      line.style.cssText =
        'margin-top:3px;display:flex;align-items:baseline;gap:7px;' +
        'font:600 11px/1.3 var(--font-body,sans-serif);letter-spacing:.06em';
      const stateEl = document.createElement('span');
      const loadEl = document.createElement('span');
      loadEl.style.cssText = 'color:#f7f1ea;opacity:.68;font-weight:400;letter-spacing:.02em';
      line.append(stateEl, loadEl);

      const mechEl = document.createElement('div');
      mechEl.style.cssText =
        'margin-top:5px;max-width:23ch;white-space:normal;color:#f7f1ea;opacity:.8;' +
        'font:400 11.5px/1.42 var(--font-body,sans-serif);display:none';
      mechEl.textContent = spec.mechanism;

      card.append(head, line, mechEl);
      el.appendChild(card);
      this.dom.appendChild(el);

      const leader = document.createElementNS(SVG_NS, 'line');
      leader.setAttribute('stroke', spec.accent);
      leader.setAttribute('stroke-width', '1');
      leader.setAttribute('stroke-dasharray', '3 3');
      this.svg.appendChild(leader);

      const pin = document.createElementNS(SVG_NS, 'circle');
      pin.setAttribute('r', '3.5');
      pin.setAttribute('fill', 'none');
      pin.setAttribute('stroke', spec.accent);
      pin.setAttribute('stroke-width', '1.5');
      this.svg.appendChild(pin);

      this.labels.set(spec.key, {
        spec,
        point: new THREE.Vector3(...spec.point),
        el,
        stateEl,
        loadEl,
        mechEl,
        leader,
        pin,
        emphasis: 'dim',
      });
    }
  }

  /**
   * Set one valve's live readout. Called per frame by the section from the
   * solver — never from a timer, so the chip flips exactly when the diode does.
   */
  setState(key: string, state: ValveLabelState): void {
    const lbl = this.labels.get(key);
    if (!lbl) return;
    lbl.stateEl.textContent = state.open ? '▸ OPEN' : '■ SHUT';
    lbl.stateEl.style.color = state.open ? OPEN_COLOR : SHUT_COLOR;
    // The load is the point of the SHUT state — it is what the sealing strategy
    // has to survive. Open, there is no gradient worth naming.
    lbl.loadEl.textContent = state.open ? '' : `holding ${state.loadMmHg.toFixed(0)} mmHg`;
  }

  /**
   * Which valve is being studied. `null` shows all four, equally weighted. Otherwise
   * the studied valve goes `full` (mechanism text and all), its declared counterpart
   * stays `dim` for the comparison, and the remaining two hide so they cannot crowd
   * a pushed-in framing.
   */
  setEmphasis(key: string | null): void {
    const partner = key === null ? null : (this.labels.get(key)?.spec.counterpart ?? null);
    for (const [k, lbl] of this.labels) {
      const em: Emphasis =
        key === null ? 'dim' : k === key ? 'full' : k === partner ? 'dim' : 'hidden';
      lbl.emphasis = em;
      lbl.mechEl.style.display = em === 'full' ? 'block' : 'none';
    }
  }

  show(): void {
    if (this.visible) return;
    this.visible = true;
    this.showAt = performance.now();
    this.dom.style.display = 'block';
    this.unframe = this.scene.onFrame(() => this.update());
    this.update();
  }

  hide(): void {
    if (!this.visible) return;
    this.visible = false;
    this.dom.style.display = 'none';
    this.unframe?.();
    this.unframe = null;
  }

  /** Project every anchor and place its tag + leader. Runs per frame while shown. */
  private update(): void {
    const reveal = THREE.MathUtils.clamp((performance.now() - this.showAt) / 600, 0, 1);
    const cam = this.scene.camera;
    const rect = this.scene.renderer.domElement.getBoundingClientRect();

    const toScreen = (v: THREE.Vector3): { x: number; y: number; behind: boolean } => {
      this.projected.copy(v);
      if (this.frame) this.frame.localToWorld(this.projected);
      this.projected.project(cam);
      return {
        x: rect.left + (this.projected.x * 0.5 + 0.5) * rect.width,
        y: rect.top + (-this.projected.y * 0.5 + 0.5) * rect.height,
        behind: this.projected.z > 1,
      };
    };

    // Keep every tag fully inside the canvas — half a generous card, so the clamp
    // bites before an edge can crop the text. `bounds` narrows it further; §3 pushes
    // the left edge in to clear its text panel, which a pushed-in isolate framing
    // would otherwise drag a tag straight on top of.
    const MARGIN_X = 130;
    const MARGIN_Y = 60;
    const minX = Math.max(rect.left + MARGIN_X, this.bounds.left ?? -Infinity);
    const maxX = Math.min(rect.left + rect.width - MARGIN_X, this.bounds.right ?? Infinity);
    const minY = Math.max(rect.top + MARGIN_Y, this.bounds.top ?? -Infinity);
    const maxY = Math.min(rect.top + rect.height - MARGIN_Y, this.bounds.bottom ?? Infinity);

    for (const lbl of this.labels.values()) {
      const pt = toScreen(lbl.point);

      // 0.82 rather than 0.5 for the un-studied tags: at 0.5 the SHUT/OPEN chip and
      // its mmHg reading were too faint to actually read against the myocardium, and
      // those numbers are the section's argument, not decoration.
      const opacity = (lbl.emphasis === 'full' ? 1 : 0.82) * reveal;
      const hidden = pt.behind || lbl.emphasis === 'hidden';

      lbl.el.style.display = hidden ? 'none' : 'block';
      lbl.leader.style.display = hidden ? 'none' : 'block';
      lbl.pin.style.display = hidden ? 'none' : 'block';
      if (hidden) continue;

      // ⚠️ `offsetPx` IS MEASURED AT THE REFERENCE WINDOW, so it scales like any other tuned
      // pixel. These offsets are large (up to 360 px) and were chosen to land tags in specific
      // empty corners of a 1600 × 1000 frame; unscaled, a smaller window flings them into the
      // reading column or off the edge, and the clamp then stacks them all on one side.
      const tag = {
        x: THREE.MathUtils.clamp(pt.x + scalePx(lbl.spec.offsetPx[0]), minX, Math.max(minX, maxX)),
        y: THREE.MathUtils.clamp(pt.y + scalePx(lbl.spec.offsetPx[1]), minY, Math.max(minY, maxY)),
      };

      lbl.el.style.opacity = `${opacity}`;
      lbl.el.style.left = `${tag.x}px`;
      lbl.el.style.top = `${tag.y}px`;
      // Stop the line short of the tag centre so it meets the card's edge rather
      // than vanishing under it.
      const dx = tag.x - pt.x;
      const dy = tag.y - pt.y;
      const len = Math.hypot(dx, dy) || 1;
      const stop = Math.max(0, len - 46);
      lbl.leader.setAttribute('x1', `${pt.x}`);
      lbl.leader.setAttribute('y1', `${pt.y}`);
      lbl.leader.setAttribute('x2', `${pt.x + (dx / len) * stop}`);
      lbl.leader.setAttribute('y2', `${pt.y + (dy / len) * stop}`);
      lbl.leader.setAttribute('opacity', `${opacity * 0.7}`);
      lbl.pin.setAttribute('cx', `${pt.x}`);
      lbl.pin.setAttribute('cy', `${pt.y}`);
      lbl.pin.setAttribute('opacity', `${opacity * 0.85}`);
    }
  }

  dispose(): void {
    this.hide();
    this.dom.remove();
    this.labels.clear();
  }
}
