import type { BeatClock } from '../../clock/index.ts';

/**
 * A TWO-POSITION SWITCH ON THE BEAT — the right instrument for a section whose subject
 * is not "where am I in the cycle" but "which of two states is the heart in".
 *
 * WHY THIS EXISTS INSTEAD OF THE DIAL. §3's whole thesis is the RECIPROCAL ALTERNATION of
 * the two valve pairs: the AV pair opens exactly when the semilunar pair shuts, and there
 * is no moment when both are open. A scrubber invites the reader to hunt through 100
 * positions for that, and 98 of them are not the point. The reader's verdict on the live
 * build was that §3 wanted "some kind of satisfying switch that opens/closes the valves
 * since that makes more sense", and they are right: a two-state control IS the lesson,
 * because throwing it and finding that you can never get all four doors open is the
 * discovery. The instrument and the idea are the same shape.
 *
 * ⚠️ NOTHING HERE ANIMATES A LEAFLET. The switch eases `clock.setPhase`, the engine
 * re-samples, and `heartRig` moves the valve morphs off the solver's own valve states.
 * That is the DRIVEN MOTION invariant and it is the whole reason the switch can be trusted:
 * the doors are not being told to open, they are being shown the pressures at that instant
 * and opening on their own.
 *
 * ⚠️⚠️ IT ALWAYS EASES *FORWARD*, WRAPPING THROUGH THE END OF THE BEAT, AND THAT IS
 * LOAD-BEARING. Mid-filling sits at phase ≈ 0.79 and mid-ejection at ≈ 0.34, so the
 * shorter path from filling to ejection is BACKWARD. Taking it would run the beat in
 * reverse: blood would flow back through the valves, the leaflets would open on the wrong
 * side, and a section whose first sentence is "four one-way doors" would spend half its
 * time contradicting itself. So both throws run forward and the reader sees the real
 * sequence of valve events in the real order every time. The two throws therefore cover
 * different fractions of a beat (≈0.55 one way, ≈0.45 the other); they are normalized to
 * the same wall-clock duration so both feel like one gesture.
 *
 * The positions are declared as PHASE-PICKING FUNCTIONS, not numbers, because a section
 * must never hand-key cardiac timing (CLAUDE.md: timing lives in exactly one place). Each
 * position asks the engine's own `phaseStart` table where it wants to be, so the switch
 * follows the reader's knobs — at a stiff afterload the ejection window moves and the
 * switch moves with it.
 */

export interface PhaseSwitchPosition {
  /** Short all-caps label, e.g. "THE WAY IN". */
  label: string;
  /** One quiet line under the label naming what is open and what is shut. */
  detail: string;
  /** Accent for this side's active state. */
  color: string;
  /**
   * Which phase this position parks on, derived from the clock's own events. Called on
   * every throw and on `refresh`, never cached — the knobs are global and persist, so a
   * cached phase is wrong the moment the reader moves one.
   */
  phase: (clock: BeatClock) => number;
}

export interface PhaseSwitchOptions {
  positions: [PhaseSwitchPosition, PhaseSwitchPosition];
  /** Which position to open on. Default 0. */
  initial?: 0 | 1;
  /** Seconds for a full throw. Both directions take this long regardless of arc length. */
  throwSeconds?: number;
  /** Fired when a throw completes, with the new index. */
  onSettle?: (index: number) => void;
}

/** Ease that starts and ends still — a thrown switch should not arrive at speed. */
const easeInOut = (t: number): number =>
  t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

export class PhaseSwitch {
  private readonly clock: BeatClock;
  private readonly opts: PhaseSwitchOptions;
  private readonly root: HTMLDivElement;
  private readonly sides: HTMLButtonElement[] = [];
  private readonly details: HTMLSpanElement[] = [];
  private readonly lever: HTMLDivElement;

  private index: 0 | 1;
  private visible = false;

  /** In-flight throw. `from`/`to` are absolute phases; `span` is always forward. */
  private travel: { from: number; span: number; t: number; dur: number; to: 0 | 1 } | null = null;

  constructor(clock: BeatClock, opts: PhaseSwitchOptions) {
    this.clock = clock;
    this.opts = opts;
    this.index = opts.initial ?? 0;

    this.root = document.createElement('div');
    this.root.className = 'phase-switch';

    const track = document.createElement('div');
    track.className = 'phase-switch-track';

    // The lever is a single element sliding between two halves, rather than two
    // independently-lit lamps: a reader has to be able to see that the two states are
    // exclusive, and one object that can only be in one place says that by itself.
    this.lever = document.createElement('div');
    this.lever.className = 'phase-switch-lever';
    track.appendChild(this.lever);

    opts.positions.forEach((pos, i) => {
      const side = document.createElement('button');
      side.type = 'button';
      side.className = 'phase-switch-side';
      side.style.setProperty('--pos-accent', pos.color);

      const label = document.createElement('span');
      label.className = 'phase-switch-label';
      label.textContent = pos.label;

      const detail = document.createElement('span');
      detail.className = 'phase-switch-detail';
      detail.textContent = pos.detail;

      side.append(label, detail);
      side.addEventListener('click', () => this.throwTo(i as 0 | 1));
      track.appendChild(side);
      this.sides.push(side);
      this.details.push(detail);
    });

    this.root.appendChild(track);
    document.body.appendChild(this.root);
    this.syncFaces();
  }

  /**
   * Throw the switch. Idempotent on the position already held, and re-throwing
   * mid-travel just retargets — a reader flicking it back and forth must never be told
   * to wait.
   */
  throwTo(next: 0 | 1): void {
    if (next === this.index && !this.travel) return;
    const from = this.clock.getPhase();
    const target = this.wrap(this.opts.positions[next].phase(this.clock));
    // ALWAYS FORWARD. See the class doc: a backward ease runs the beat in reverse and
    // makes the one-way doors flow the wrong way.
    let span = target - from;
    while (span <= 1e-6) span += 1;
    this.index = next;
    this.travel = {
      from,
      span,
      t: 0,
      dur: Math.max(0.15, this.opts.throwSeconds ?? 1.15),
      to: next,
    };
    this.syncFaces();
  }

  /** Which position is held (or being thrown to). */
  getIndex(): 0 | 1 {
    return this.index;
  }

  /** Drive the in-flight throw. Call from the scene's frame callback. */
  update(dt: number): void {
    const tr = this.travel;
    if (!tr) return;
    tr.t = Math.min(1, tr.t + dt / tr.dur);
    this.clock.setPhase(tr.from + tr.span * easeInOut(tr.t));
    if (tr.t >= 1) {
      this.travel = null;
      this.opts.onSettle?.(tr.to);
    }
  }

  /**
   * Snap to the held position with no travel. For an entrance, and for headless: a
   * throw cannot complete in the ~13 frames a screenshot gets.
   */
  settleNow(): void {
    this.travel = null;
    this.clock.setPhase(this.opts.positions[this.index].phase(this.clock));
    this.syncFaces();
  }

  /**
   * Re-read the positions after a re-solve. The phases are functions of the engine's
   * events, so a knob move relocates both of them.
   */
  refresh(): void {
    if (!this.travel) this.settleNow();
  }

  show(): void {
    if (this.visible) return;
    this.visible = true;
    this.root.classList.add('is-visible');
  }

  hide(): void {
    if (!this.visible) return;
    this.visible = false;
    this.root.classList.remove('is-visible');
    this.travel = null;
  }

  dispose(): void {
    this.travel = null;
    this.root.remove();
    this.sides.length = 0;
    this.details.length = 0;
  }

  private wrap(p: number): number {
    return ((p % 1) + 1) % 1;
  }

  private syncFaces(): void {
    this.lever.classList.toggle('is-right', this.index === 1);
    this.lever.style.setProperty('--pos-accent', this.opts.positions[this.index].color);
    this.sides.forEach((s, i) => s.classList.toggle('is-on', i === this.index));
  }
}
