import * as THREE from 'three';
import type { HeartScene } from '../index.ts';

/**
 * Flow tint (SPEC §5, §6 §1; MODEL_FIT.md Phase B). Blood flowing *inside the
 * real vessels*, coloured by oxygenation — deep crimson (deoxygenated) → bright
 * scarlet (oxygenated) — with travelling emissive bands that read as motion and
 * direction. Deoxygenated: SVC, IVC, pulmonary artery (blue-blood to the lungs);
 * oxygenated: aorta, pulmonary veins (red-blood to the body).
 *
 * Implemented by injecting a moving pulse into each vessel material's emissive
 * (onBeforeCompile) along the vessel's outward axis, so the tint travels through
 * the actual geometry rather than a symbolic path. The one clock can later
 * modulate speed/intensity per phase; for now it flows continuously.
 */
export type Oxygenation = 'deox' | 'ox';

export interface FlowSpec {
  /** Mesh name (Aorta / PulmonaryArtery / SVC / IVC …). */
  mesh: string;
  oxygenation: Oxygenation;
  /** +1 flows outward from the heart (arteries), −1 inward (veins/cavae). */
  direction?: 1 | -1;
}

// Blue/red coding, matching the circuit overlay (venous blue / arterial red).
const COLOR: Record<Oxygenation, THREE.Color> = {
  deox: new THREE.Color('#2f6ad0'),
  ox: new THREE.Color('#ff3326'),
};

interface FlowMat {
  uniforms: { uTime: { value: number }; uColor: { value: THREE.Color }; uAxis: { value: THREE.Vector3 }; uDir: { value: number } };
}

export class FlowTintOverlay {
  private readonly scene: HeartScene;
  private readonly mats: FlowMat[] = [];
  private unframe: (() => void) | null = null;
  private visible = false;
  private t = 0;

  constructor(scene: HeartScene, specs: FlowSpec[]) {
    this.scene = scene;
    const heart = scene.getHeart();
    if (!heart) return;

    const byName = new Map<string, THREE.Mesh>();
    heart.traverse((o) => {
      const m = o as THREE.Mesh;
      if (m.isMesh) byName.set(m.name.toLowerCase().replace(/[^a-z0-9]/g, ''), m);
    });

    for (const spec of specs) {
      const mesh = byName.get(spec.mesh.toLowerCase().replace(/[^a-z0-9]/g, ''));
      if (!mesh) continue;

      // Outward axis ≈ from the heart centre (origin) to the vessel's centroid,
      // in world space. Cheap, robust, and good enough to read as flow direction.
      const box = new THREE.Box3().setFromObject(mesh);
      const axis = box.getCenter(new THREE.Vector3()).normalize();

      const base = mesh.material as THREE.MeshStandardMaterial;
      const mat = base.clone();
      const uniforms = {
        uTime: { value: 0 },
        uColor: { value: COLOR[spec.oxygenation].clone() },
        uAxis: { value: axis },
        uDir: { value: spec.direction ?? 1 },
      };
      mat.onBeforeCompile = (shader) => {
        Object.assign(shader.uniforms, uniforms);
        shader.vertexShader =
          'varying vec3 vWPosFlow;\n' +
          shader.vertexShader.replace(
            '#include <project_vertex>',
            '#include <project_vertex>\n vWPosFlow = (modelMatrix * vec4(transformed, 1.0)).xyz;',
          );
        shader.fragmentShader =
          'uniform float uTime;\nuniform vec3 uColor;\nuniform vec3 uAxis;\nuniform float uDir;\nvarying vec3 vWPosFlow;\n' +
          shader.fragmentShader.replace(
            '#include <emissivemap_fragment>',
            '#include <emissivemap_fragment>\n' +
              'float coordFlow = dot(vWPosFlow, normalize(uAxis)) * uDir;\n' +
              'float band = 0.5 + 0.5 * sin(coordFlow * 26.0 - uTime * 2.4);\n' +
              'band = pow(band, 3.0);\n' +
              'totalEmissiveRadiance += uColor * (0.15 + 0.75 * band);',
          );
      };
      mat.needsUpdate = true;
      mesh.material = mat;
      this.mats.push({ uniforms });
    }
  }

  get tinted(): number {
    return this.mats.length;
  }

  show(): void {
    if (this.visible) return;
    this.visible = true;
    this.unframe = this.scene.onFrame((dt) => {
      this.t += dt;
      for (const m of this.mats) m.uniforms.uTime.value = this.t;
    });
  }

  hide(): void {
    if (!this.visible) return;
    this.visible = false;
    this.unframe?.();
    this.unframe = null;
    // Freeze the pulse where it is (materials stay tinted but static).
  }

  dispose(): void {
    this.hide();
  }
}
