import * as THREE from 'three';
import type { HeartScene } from '../index.ts';
import { scalePx } from '../../ui/uiScale.ts';

/**
 * A small HUD badge pinned to a point on the heart, projected to screen each frame
 * (the same hybrid approach as the manometer readouts). Section 4 uses it to call
 * the valve's state on the outside of the chamber — OPEN vs SHUT and which way flow
 * is (or isn't) allowed — so what the pressure gradient is doing reads instantly,
 * without having to parse the arrow. Reusable by any section that wants to label a
 * live state at a world anchor.
 */
export interface StatusBadgeOptions {
  /**
   * Transform the anchor is expressed in. Pass `scene.getHeartFrame()` for a badge
   * pinned to ANATOMY, so it follows the heart when a section turns it (the anchor
   * stays the same world-measured number — see `heartOrientation.ts`). Omit for a
   * badge pinned to a fixed point in the world.
   */
  frame?: THREE.Object3D;
  /**
   * Push the card this many SCREEN PIXELS off its anchor, and draw a leader line back
   * to the structure it names.
   *
   * ⚠️ SCREEN SPACE, NOT WORLD SPACE — the same hard-won rule `ValveLabels` encodes.
   * Offsetting a card by nudging its world anchor sends it wherever the current camera
   * happens to point that vector, which flung two earlier attempts clean off the frame.
   * A pixel offset applied AFTER projection is stable at every orbit angle and distance.
   *
   * Exists because §5's AV-node badge sat exactly on the AV node — i.e. squarely on top
   * of the heart it was asking the reader to look at.
   */
  offsetPx?: [number, number];
}

const SVG_NS = 'http://www.w3.org/2000/svg';

export class StatusBadge {
  private readonly scene: HeartScene;
  private readonly anchor: THREE.Vector3;
  private readonly frame: THREE.Object3D | null;
  private readonly el: HTMLDivElement;
  private readonly titleEl: HTMLDivElement;
  private readonly stateEl: HTMLDivElement;
  private readonly projected = new THREE.Vector3();
  private readonly offsetPx: [number, number];
  /** Leader line + its pin, only built when the card is offset. */
  private readonly svg: SVGSVGElement | null = null;
  private readonly leader: SVGLineElement | null = null;
  private readonly pin: SVGCircleElement | null = null;
  private visible = false;

  constructor(
    scene: HeartScene,
    anchor: THREE.Vector3,
    title: string,
    opts: StatusBadgeOptions = {},
  ) {
    this.scene = scene;
    this.anchor = anchor.clone();
    this.frame = opts.frame ?? null;
    this.offsetPx = opts.offsetPx ?? [0, 0];

    this.el = document.createElement('div');
    this.el.className = 'status-badge';
    this.el.style.display = 'none';
    this.titleEl = document.createElement('div');
    this.titleEl.className = 'status-badge-title';
    this.titleEl.textContent = title;
    this.stateEl = document.createElement('div');
    this.stateEl.className = 'status-badge-state';
    this.el.append(this.titleEl, this.stateEl);
    document.body.appendChild(this.el);

    if (this.offsetPx[0] !== 0 || this.offsetPx[1] !== 0) {
      // A full-viewport overlay BEHIND the card, so the line runs under it rather than
      // across its face. Never interactive.
      this.svg = document.createElementNS(SVG_NS, 'svg');
      this.svg.setAttribute('width', '100%');
      this.svg.setAttribute('height', '100%');
      this.svg.style.cssText =
        'position:fixed;inset:0;overflow:visible;pointer-events:none;display:none';
      this.leader = document.createElementNS(SVG_NS, 'line');
      this.leader.setAttribute('stroke-width', '1');
      this.leader.setAttribute('stroke-dasharray', '3 3');
      this.pin = document.createElementNS(SVG_NS, 'circle');
      this.pin.setAttribute('r', '3');
      this.pin.setAttribute('fill', 'none');
      this.pin.setAttribute('stroke-width', '1.2');
      this.svg.append(this.leader, this.pin);
      document.body.appendChild(this.svg);
    }
  }

  /** Set the state line + accent colour (CSS colour string). */
  setState(text: string, color: string): void {
    this.stateEl.textContent = text;
    this.stateEl.style.color = color;
    this.el.style.borderColor = color;
    this.el.style.boxShadow = `0 0 18px -6px ${color}`;
    // The leader is part of the card, so it carries the same state colour.
    this.leader?.setAttribute('stroke', color);
    this.pin?.setAttribute('stroke', color);
  }

  /** Project the anchor and place the badge (call once per frame while shown). */
  update(): void {
    if (!this.visible) return;
    const cam = this.scene.camera;
    const canvas = this.scene.renderer.domElement;
    const rect = canvas.getBoundingClientRect();
    this.projected.copy(this.anchor);
    if (this.frame) this.frame.localToWorld(this.projected);
    this.projected.project(cam);
    const behind = this.projected.z > 1;
    this.el.style.display = behind ? 'none' : 'block';
    if (this.svg) this.svg.style.display = behind ? 'none' : 'block';
    if (behind) return;

    // Where the structure actually is on screen…
    const ax = rect.left + (this.projected.x * 0.5 + 0.5) * rect.width;
    const ay = rect.top + (-this.projected.y * 0.5 + 0.5) * rect.height;
    // …and where the card sits, pushed clear of it in pixels. Scaled, because the offset was
    // measured at the reference window and is part of the same tuned layout as any CSS width
    // it was chosen to clear (§5's is [350, −400], reasoned from "x ≈ 50% − 330px rightward").
    const cx = ax + scalePx(this.offsetPx[0]);
    const cy = ay + scalePx(this.offsetPx[1]);
    this.el.style.left = `${cx}px`;
    this.el.style.top = `${cy}px`;

    if (!this.leader || !this.pin) return;
    // Stop the line short of the card so it meets an edge rather than running beneath
    // the text, and short of the anchor so the pin ring stays legible.
    const dx = cx - ax;
    const dy = cy - ay;
    const len = Math.hypot(dx, dy) || 1;
    const from = Math.min(8, len * 0.25);
    const to = Math.max(from, len - 10);
    this.leader.setAttribute('x1', `${ax + (dx / len) * from}`);
    this.leader.setAttribute('y1', `${ay + (dy / len) * from}`);
    this.leader.setAttribute('x2', `${ax + (dx / len) * to}`);
    this.leader.setAttribute('y2', `${ay + (dy / len) * to}`);
    this.leader.setAttribute('opacity', '0.65');
    this.pin.setAttribute('cx', `${ax}`);
    this.pin.setAttribute('cy', `${ay}`);
    this.pin.setAttribute('opacity', '0.8');
  }

  show(): void {
    this.visible = true;
    this.el.style.display = 'block';
    if (this.svg) this.svg.style.display = 'block';
    this.update();
  }

  hide(): void {
    this.visible = false;
    this.el.style.display = 'none';
    if (this.svg) this.svg.style.display = 'none';
  }

  dispose(): void {
    this.el.remove();
    this.svg?.remove();
  }
}
