import type { BeatClock } from '../clock/index.ts';

/**
 * Ambient hero beat (SPEC §6 Section 1: "opens tight on the real beating heart").
 *
 * The direct-manipulation contract says nothing autoplays and the clock never
 * self-advances — the reader scrubs. Act I has no scrubber yet, so this is the
 * one scoped exception: a gentle idle beat gives the hero heart life on load,
 * then hands control back the instant the reader does anything (orbit, drag, key,
 * or scroll). It advances the SAME master clock every other view reads, so it is
 * still one heart, one clock — just wound by a timer instead of a finger, briefly.
 */
export interface AmbientBeatOptions {
  /** Seconds per beat. A calm ~1.1 s (≈55 bpm) reads as alive, not racing. */
  periodSeconds?: number;
  /** Called once when the reader takes over (or the beat is stopped). */
  onHandoff?: () => void;
}

const HANDOFF_EVENTS = ['pointerdown', 'wheel', 'keydown', 'touchstart'] as const;

export class AmbientBeat {
  private readonly clock: BeatClock;
  private readonly period: number;
  private readonly onHandoff: (() => void) | undefined;
  private raf: number | null = null;
  private lastT = 0;
  private running = false;

  constructor(clock: BeatClock, opts: AmbientBeatOptions = {}) {
    this.clock = clock;
    this.period = opts.periodSeconds ?? 1.1;
    this.onHandoff = opts.onHandoff;
  }

  /** Start the idle beat and arm the first-input handoff. Idempotent. */
  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastT = performance.now();
    for (const e of HANDOFF_EVENTS) {
      window.addEventListener(e, this.handoff, { passive: true });
    }
    this.raf = requestAnimationFrame(this.tick);
  }

  private readonly tick = (now: number): void => {
    if (!this.running) return;
    const dt = Math.min(0.05, (now - this.lastT) / 1000); // clamp tab-away gaps
    this.lastT = now;
    this.clock.setPhase(this.clock.getPhase() + dt / this.period);
    this.raf = requestAnimationFrame(this.tick);
  };

  /** First reader input: stop advancing and hand over. */
  private readonly handoff = (): void => {
    if (!this.running) return;
    this.stop();
    this.onHandoff?.();
  };

  /** Stop the beat and detach listeners. Idempotent; does not fire onHandoff. */
  stop(): void {
    this.running = false;
    if (this.raf !== null) cancelAnimationFrame(this.raf);
    this.raf = null;
    for (const e of HANDOFF_EVENTS) window.removeEventListener(e, this.handoff);
  }

  get isRunning(): boolean {
    return this.running;
  }
}
