import type { BeatClock } from '../../clock/index.ts';
import type { CardiacPhase, Valve } from '../../engine/index.ts';
import { PHASE_ORDER, PHASE_COLOR, PHASE_LABEL } from './beatScrubber.ts';
import { ecgGeometry, ecgSignal } from './ecgTrace.ts';

/**
 * The Wiggers diagram — SPEC §11, the finale, and the one place the whole piece is
 * visible at once.
 *
 * NOTHING NEW IS TAUGHT HERE, and the build reflects that literally: every channel is
 * read from the same engine the sections read, drawn in the same colour that section
 * used, and captioned with the name of the section that taught it. The ECG is not a
 * lookalike of §5's trace, it is §5's trace — `ecgSignal()` was extracted out of
 * `ecgTrace.ts` so the two cannot drift. The phase ribbon is not a lookalike of the
 * scrubber's coloured arcs, it is the same `PHASE_COLOR` table unrolled from a circle
 * onto a line. A reader who learned "orange means blood is leaving" from the dial in
 * Act III must meet exactly that orange here.
 *
 * THIS IS ALSO THE MASTER SCRUBBER, which resolves the question the project has carried
 * since Act III: how does the circular dial become the Wiggers time axis? It does not —
 * the axis replaces it. Drag anywhere in the plot and the playhead, all six channels'
 * live value beads, and the 3D heart move together off one `clock.setPhase`. §5's ECG
 * strip introduced that pattern one section early on a single channel; this generalises
 * it to the whole beat. The dial is deliberately not shown alongside: two controls on
 * one clock would make the reader ask which one is real.
 *
 * ⚠️ CURVES ARE SAMPLED, NOT LIVE-PLOTTED. `refresh()` walks `engine.sample(phase)`
 * across a whole beat and bakes six SVG paths. It MUST be called after every re-solve
 * (any knob) — the knobs are global and persist, so a stale path is a chart that
 * disagrees with the heart above it. `update()` is per-frame and only moves the
 * playhead and the beads; it never rebuilds geometry.
 *
 * ⚠️ THE PROGRESSIVE STACK IS GATED ON `?focus=now`. SPEC asks channels to land one at
 * a time; headless gives the page about 13 rAF frames, so the review render would
 * otherwise show an empty chart forever. Same escape hatch as the focus system, read
 * the same way.
 */

const SVG_NS = 'http://www.w3.org/2000/svg';

/** Viewbox. Width is one full beat; height is the stack of channels. */
const VIEW_W = 1000;
const VIEW_H = 512;
/** Left gutter for axis numbers and valve names; right margin for the last tick label. */
const PLOT_X0 = 88;
const PLOT_X1 = 986;
const PLOT_W = PLOT_X1 - PLOT_X0;

/** The four stacked panels, in viewbox y. */
const RIBBON = { top: 0, h: 17 };
const PRESSURE = { top: 30, h: 188 };
const VOLUME = { top: 244, h: 92 };
const ECG = { top: 350, h: 62 };
const VALVES = { top: 424, rowH: 15, barH: 9 };
const VALVE_ORDER: Valve[] = ['aortic', 'mitral', 'pulmonary', 'tricuspid'];
const VALVE_BAND_H = VALVE_ORDER.length * VALVES.rowH;
/** The time axis, below everything. */
const AXIS_Y = VALVES.top + VALVE_BAND_H + 16;

/** How many points each curve is sampled at. 300 is smooth at this width and costs ~4 ms. */
const SAMPLES = 300;

export type WiggersChannel = 'lv' | 'ao' | 'la' | 'vol' | 'ecg' | 'valves';

interface ChannelDef {
  id: WiggersChannel;
  /** What the legend chip says it is. */
  name: string;
  /**
   * The section that taught it — SPEC §11's "each named back to the section that
   * taught it". This is the payoff line: the most feared figure in the field turns out
   * to be six things the reader already met.
   */
  origin: string;
  color: string;
}

/**
 * Stack order, and it is the order SPEC §11 asks for: ventricular pressure → aortic →
 * atrial → volume → ECG → valve bars. It builds from the protagonist outward. The LV
 * pressure curve alone is the §4 rule drawn as a line; the aorta arriving explains when
 * the exit door can open; the atrium arriving explains when the inlet can; volume then
 * says what all that pressure actually moved; the ECG says what started it; and the
 * valve bars are the summary that ties the four crossings to the four doors.
 *
 * Colours are the ones each section already used — LV crimson-scarlet, aorta gold,
 * atrium blue (the §4/§6/doors manometer palette), volume the filling phase's teal.
 */
const CHANNELS: ChannelDef[] = [
  { id: 'lv', name: 'Ventricular pressure', origin: 'Pressure is the driver', color: '#ff5a4d' },
  { id: 'ao', name: 'Aortic pressure', origin: 'The doors open', color: '#ffd24a' },
  { id: 'la', name: 'Atrial pressure', origin: 'The atrial kick', color: '#7fa8ff' },
  { id: 'vol', name: 'Ventricular volume', origin: 'The doors open', color: '#59c9b0' },
  { id: 'ecg', name: 'ECG', origin: 'The electrical wave', color: '#f4ede6' },
  { id: 'valves', name: 'Valves · S1 / S2', origin: 'The four valves', color: '#ffd9b8' },
];

/** Seconds between channels landing during the entrance. */
const STACK_STAGGER = 0.42;

/**
 * Short names for the phase ribbon, and they are NOT a second wording of the scrubber's.
 *
 * ⚠️ THE SHARED `PHASE_LABEL` DOES NOT FIT HERE and the first render proved it: at
 * 8.5px mono, "Squeeze begins — all doors shut" is about 165 viewbox units wide and its
 * band is 143, so consecutive labels overlapped into an unreadable smear across the top
 * of the chart. The dial has a whole caption line to itself; this ribbon has five slots
 * on one line. These are the same claims in the same register — plain, no jargon — cut
 * to fit, and each one is still only drawn when it actually fits its band.
 */
const PHASE_TAB: Record<CardiacPhase, string> = {
  'atrial-systole': 'TOPPING OFF',
  'isovolumetric-contraction': 'ALL DOORS SHUT',
  ejection: 'PUMPING OUT',
  'isovolumetric-relaxation': 'ALL DOORS SHUT',
  filling: 'FILLING',
};

/** Advance width of one character of `.wig-phase-name`, in viewbox units. */
const TAB_CHAR_W = 5.7;

const el = <K extends keyof SVGElementTagNameMap>(
  tag: K,
  attrs: Record<string, string | number> = {},
): SVGElementTagNameMap[K] => {
  const node = document.createElementNS(SVG_NS, tag) as unknown as SVGElementTagNameMap[K];
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, String(v));
  return node;
};

const xOf = (phase: number): number => PLOT_X0 + phase * PLOT_W;

/** Round an axis bound out to a clean step. */
const ceilTo = (v: number, step: number): number => Math.ceil(v / step) * step;
const floorTo = (v: number, step: number): number => Math.floor(v / step) * step;

export interface WiggersChartOptions {
  /** Called when the reader drags the playhead — normally `clock.setPhase`. */
  onScrub?: (phase01: number) => void;
}

export class WiggersChart {
  private readonly clock: BeatClock;
  private readonly root: HTMLDivElement;
  private readonly svg: SVGSVGElement;
  private readonly onScrub: ((phase01: number) => void) | undefined;

  private readonly readoutTime: HTMLSpanElement;
  private readonly readoutPhase: HTMLSpanElement;
  private readonly readoutValues: HTMLSpanElement;
  private readonly legend: HTMLDivElement;
  private readonly chips = new Map<WiggersChannel, HTMLButtonElement>();

  /** One group per channel, so the entrance and the isolate control have a handle. */
  private readonly groups = new Map<WiggersChannel, SVGGElement>();
  private readonly ribbon: SVGGElement;
  private readonly frame: SVGGElement;
  private readonly curves = new Map<Exclude<WiggersChannel, 'valves'>, SVGPathElement>();
  private readonly beads = new Map<Exclude<WiggersChannel, 'valves'>, SVGCircleElement>();
  private readonly valveBars = new Map<Valve, SVGGElement>();
  private readonly valveDots = new Map<Valve, SVGCircleElement>();
  private readonly playhead: SVGGElement;

  /** Baked series, index 0…SAMPLES over one beat. */
  private series: Record<Exclude<WiggersChannel, 'valves'>, number[]> = {
    lv: [],
    ao: [],
    la: [],
    vol: [],
    ecg: [],
  };
  /** Value → viewbox y, per channel. Rebuilt with the axes in `refresh()`. */
  private toY: Record<Exclude<WiggersChannel, 'valves'>, (v: number) => number> = {
    lv: () => 0,
    ao: () => 0,
    la: () => 0,
    vol: () => 0,
    ecg: () => 0,
  };
  private valveOpenAt: Record<Valve, (phase: number) => boolean> = {
    mitral: () => false,
    aortic: () => false,
    tricuspid: () => false,
    pulmonary: () => false,
  };

  private dragging = false;
  private visible = false;
  private isolated: WiggersChannel | null = null;
  /** Entrance: which channels have landed, and how long since `show()`. */
  private landed = 0;
  private stackT = 0;
  private stacking = false;
  private readonly instant =
    new URLSearchParams(window.location.search).get('focus') === 'now';

  constructor(clock: BeatClock, opts: WiggersChartOptions = {}) {
    this.clock = clock;
    this.onScrub = opts.onScrub;

    this.root = document.createElement('div');
    this.root.className = 'wiggers';
    if (this.instant) this.root.classList.add('is-instant');

    // ---- Caption row -------------------------------------------------------
    const caption = document.createElement('div');
    caption.className = 'wiggers-caption';
    const title = document.createElement('span');
    title.className = 'wiggers-title';
    title.textContent = 'The whole beat, one timeline';
    this.readoutTime = document.createElement('span');
    this.readoutTime.className = 'wiggers-time';
    this.readoutPhase = document.createElement('span');
    this.readoutPhase.className = 'wiggers-phase';
    this.readoutValues = document.createElement('span');
    this.readoutValues.className = 'wiggers-values';
    caption.append(title, this.readoutTime, this.readoutPhase, this.readoutValues);

    // ---- The plot ----------------------------------------------------------
    this.svg = el('svg', {
      viewBox: `0 0 ${VIEW_W} ${VIEW_H}`,
      preserveAspectRatio: 'none',
      class: 'wiggers-svg',
    });

    // Painted back to front: phase ribbon, then the static frame (gridlines, axis
    // numbers, panel titles), then each channel, then the playhead on top.
    this.ribbon = el('g', { class: 'wig-ribbon' });
    this.frame = el('g', { class: 'wig-frame' });
    this.svg.append(this.ribbon, this.frame);

    for (const ch of CHANNELS) {
      const g = el('g', { class: 'wig-channel' });
      g.dataset.channel = ch.id;
      this.groups.set(ch.id, g);
      this.svg.appendChild(g);

      if (ch.id === 'valves') {
        this.buildValveBand(g);
      } else {
        const curve = el('path', { class: 'wig-curve', stroke: ch.color });
        const bead = el('circle', { class: 'wig-bead', r: 4.6, fill: ch.color, cx: -50, cy: -50 });
        g.append(curve, bead);
        this.curves.set(ch.id, curve);
        this.beads.set(ch.id, bead);
      }
    }

    this.playhead = el('g', { class: 'wig-playhead' });
    // ⚠️ x1/x2 are 0 and the whole group is translated to the playhead's absolute
    // viewbox x. A first pass translated by `x − PLOT_X0` instead, which drew the
    // playhead 88 units left of its own value beads — visible only because the beads
    // are on screen next to it.
    const stem = el('line', {
      class: 'wig-playhead-stem',
      x1: 0,
      x2: 0,
      y1: RIBBON.top,
      y2: AXIS_Y - 6,
    });
    this.playhead.appendChild(stem);
    this.svg.appendChild(this.playhead);

    // ---- Legend, which is also the isolate control --------------------------
    this.legend = document.createElement('div');
    this.legend.className = 'wiggers-legend';
    for (const ch of CHANNELS) {
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'wig-chip';
      chip.style.setProperty('--chip', ch.color);
      const swatch = document.createElement('i');
      const name = document.createElement('b');
      name.textContent = ch.name;
      const origin = document.createElement('em');
      // The one line that makes this a synthesis rather than a new figure.
      origin.textContent = ch.origin;
      chip.append(swatch, name, origin);
      chip.addEventListener('click', () => this.toggleIsolate(ch.id));
      this.chips.set(ch.id, chip);
      this.legend.appendChild(chip);
    }
    const note = document.createElement('span');
    note.className = 'wiggers-note';
    note.textContent = 'drag anywhere to scrub · click a channel to isolate it';
    this.legend.appendChild(note);

    this.root.append(caption, this.svg, this.legend);
    document.body.appendChild(this.root);

    this.svg.addEventListener('pointerdown', this.onPointerDown);
    window.addEventListener('pointermove', this.onPointerMove);
    window.addEventListener('pointerup', this.onPointerUp);

    this.refresh();
  }

  /** Four open/shut bars plus the S1 and S2 markers that punctuate them. */
  private buildValveBand(g: SVGGElement): void {
    for (let i = 0; i < VALVE_ORDER.length; i++) {
      const valve = VALVE_ORDER[i]!;
      const y = VALVES.top + i * VALVES.rowH;
      const label = el('text', {
        class: 'wig-valve-label',
        x: PLOT_X0 - 8,
        y: y + VALVES.barH - 1,
        'text-anchor': 'end',
      });
      label.textContent = valve.toUpperCase();
      // The shut rail: a thin line the open span sits on top of, so "shut" is a
      // visible state rather than an absence.
      const rail = el('line', {
        class: 'wig-valve-rail',
        x1: PLOT_X0,
        x2: PLOT_X1,
        y1: y + VALVES.barH / 2,
        y2: y + VALVES.barH / 2,
      });
      const bars = el('g', { class: 'wig-valve-bars' });
      const dot = el('circle', { class: 'wig-valve-dot', r: 3.4, cx: -50, cy: y + VALVES.barH / 2 });
      this.valveBars.set(valve, bars);
      this.valveDots.set(valve, dot);
      g.append(label, rail, bars, dot);
    }
  }

  // ---- Pointer → phase -----------------------------------------------------

  /**
   * ⚠️ Mapped through `getScreenCTM()`, never `clientX / rect.width * VIEW_W` — the plot
   * stretches with `preserveAspectRatio: none`, so the naive version drifts with the
   * viewport's aspect ratio. Documented trap; it has bitten two widgets already.
   */
  private phaseFromEvent(e: PointerEvent): number {
    const ctm = this.svg.getScreenCTM();
    if (!ctm) return 0;
    const pt = new DOMPoint(e.clientX, e.clientY).matrixTransform(ctm.inverse());
    return Math.min(1, Math.max(0, (pt.x - PLOT_X0) / PLOT_W));
  }

  private onPointerDown = (e: PointerEvent): void => {
    if (!this.visible) return;
    e.preventDefault();
    this.dragging = true;
    this.svg.classList.add('is-dragging');
    this.onScrub?.(this.phaseFromEvent(e));
  };

  private onPointerMove = (e: PointerEvent): void => {
    if (!this.dragging) return;
    this.onScrub?.(this.phaseFromEvent(e));
  };

  private onPointerUp = (): void => {
    if (!this.dragging) return;
    this.dragging = false;
    this.svg.classList.remove('is-dragging');
  };

  // ---- Isolate / restack ---------------------------------------------------

  /**
   * SPEC §11's "optionally isolate a channel to declutter, then restack". Nothing is
   * removed — the others recede — because the point of the figure is that they are
   * simultaneous, and hiding them would let the reader forget that.
   */
  private toggleIsolate(id: WiggersChannel): void {
    this.isolated = this.isolated === id ? null : id;
    for (const ch of CHANNELS) {
      const muted = this.isolated !== null && this.isolated !== ch.id;
      this.groups.get(ch.id)?.classList.toggle('is-muted', muted);
      this.chips.get(ch.id)?.classList.toggle('is-muted', muted);
      this.chips.get(ch.id)?.classList.toggle('is-isolated', this.isolated === ch.id);
    }
  }

  // ---- Baking the curves ---------------------------------------------------

  /**
   * Re-sample every channel from the engine and rebuild the paths, the axes, the phase
   * ribbon and the valve bars.
   *
   * ⚠️ Call after EVERY re-solve. The knobs are global and persist; a chart baked at
   * init and never rebuilt would quietly disagree with the heart beating above it,
   * which is the one failure this section cannot survive.
   */
  refresh(): void {
    const engine = this.clock.getEngine();
    const geom = ecgGeometry(this.clock);

    const lv: number[] = [];
    const ao: number[] = [];
    const la: number[] = [];
    const vol: number[] = [];
    const ecg: number[] = [];
    for (let i = 0; i <= SAMPLES; i++) {
      const phase = i / SAMPLES;
      const s = engine.sample(phase);
      lv.push(s.pressures.LV);
      ao.push(s.pressures.SysArt);
      la.push(s.pressures.LA);
      vol.push(s.volumes.LV);
      ecg.push(ecgSignal(phase, geom));
    }
    this.series = { lv, ao, la, vol, ecg };

    // Pressure axis: one shared mmHg scale for all three pressures, which is the whole
    // point — the crossings between them are what open and shut the doors, and you
    // cannot see a crossing between two curves on two different scales.
    //
    // ⚠️ ADAPTIVE, because the knobs move peak LV from ~93 to ~171 mmHg. A fixed
    // ceiling either wastes half the panel at rest or clips at high afterload; the same
    // defect the manometer columns had to fix twice.
    const pMax = ceilTo(Math.max(...lv, ...ao) * 1.08, 20);
    const vMin = floorTo(Math.min(...vol) - 6, 10);
    const vMax = ceilTo(Math.max(...vol) + 6, 10);

    const pressureY = (v: number): number =>
      PRESSURE.top + PRESSURE.h * (1 - v / pMax);
    this.toY = {
      lv: pressureY,
      ao: pressureY,
      la: pressureY,
      vol: (v) => VOLUME.top + VOLUME.h * (1 - (v - vMin) / (vMax - vMin)),
      // The ECG's baseline sits low in its panel: the R wave is tall and one-sided, and
      // the S trough only needs a little room beneath.
      ecg: (v) => ECG.top + ECG.h * 0.78 - v * ECG.h * 0.72,
    };

    for (const id of ['lv', 'ao', 'la', 'vol', 'ecg'] as const) {
      this.curves.get(id)?.setAttribute('d', this.pathFor(id));
    }

    const events = this.clock.getEvents();
    this.valveOpenAt = {} as Record<Valve, (phase: number) => boolean>;
    for (const valve of VALVE_ORDER) {
      const { open, close } = events.valve[valve];
      // A window that wraps the end of the beat (close < open) is normal — the mitral
      // opens late in one beat and shuts early in the next.
      this.valveOpenAt[valve] =
        close >= open
          ? (p) => p >= open && p <= close
          : (p) => p >= open || p <= close;
      this.drawValveBar(valve, open, close);
    }

    this.drawRibbon(events.phaseStart);
    this.drawFrame(pMax, vMin, vMax, events.s1Phase, events.s2Phase);
  }

  private pathFor(id: Exclude<WiggersChannel, 'valves'>): string {
    const values = this.series[id];
    const toY = this.toY[id];
    let d = '';
    for (let i = 0; i < values.length; i++) {
      const x = xOf(i / SAMPLES);
      const y = toY(values[i]!);
      d += `${i === 0 ? 'M' : 'L'}${x.toFixed(2)},${y.toFixed(2)}`;
    }
    return d;
  }

  private drawValveBar(valve: Valve, open: number, close: number): void {
    const g = this.valveBars.get(valve);
    if (!g) return;
    g.replaceChildren();
    const row = VALVE_ORDER.indexOf(valve);
    const y = VALVES.top + row * VALVES.rowH;
    // Wrapped windows become two rectangles, one at each end of the axis.
    const spans: Array<[number, number]> =
      close >= open ? [[open, close]] : [[open, 1], [0, close]];
    for (const [a, b] of spans) {
      if (b - a < 1e-4) continue;
      g.appendChild(
        el('rect', {
          class: 'wig-valve-open',
          x: xOf(a),
          y,
          width: Math.max(1.5, (b - a) * PLOT_W),
          height: VALVES.barH,
          rx: 2,
        }),
      );
    }
  }

  /** The five phases as coloured bands down the full height of the plot. */
  private drawRibbon(phaseStart: Record<CardiacPhase, number>): void {
    this.ribbon.replaceChildren();
    const bottom = VALVES.top + VALVE_BAND_H + 4;
    for (let i = 0; i < PHASE_ORDER.length; i++) {
      const phase = PHASE_ORDER[i]!;
      const start = phaseStart[phase];
      const next = PHASE_ORDER[(i + 1) % PHASE_ORDER.length]!;
      const end = i === PHASE_ORDER.length - 1 ? 1 : phaseStart[next];
      const w = (end - start) * PLOT_W;
      if (w <= 0.2) continue;
      // A wash down the whole stack, so a reader tracing a curve can see which phase
      // they are in without looking away from it.
      this.ribbon.appendChild(
        el('rect', {
          class: 'wig-phase-wash',
          x: xOf(start),
          y: RIBBON.top,
          width: w,
          height: bottom - RIBBON.top,
          fill: PHASE_COLOR[phase],
        }),
      );
      // The saturated header strip, plus the plain-language name if it fits.
      this.ribbon.appendChild(
        el('rect', {
          class: 'wig-phase-tab',
          x: xOf(start),
          y: RIBBON.top,
          width: w,
          height: RIBBON.h,
          fill: PHASE_COLOR[phase],
        }),
      );
      // Only if it genuinely fits, with a little air each side. A knob can squeeze any
      // of these bands (heart rate rescales all five), so this is a measurement rather
      // than a fixed threshold — an overflowing label is worse than no label.
      const label = PHASE_TAB[phase];
      if (label.length * TAB_CHAR_W + 10 <= w) {
        const t = el('text', {
          class: 'wig-phase-name',
          x: xOf(start) + w / 2,
          y: RIBBON.top + 12,
          'text-anchor': 'middle',
        });
        t.textContent = label;
        this.ribbon.appendChild(t);
      }
    }
  }

  /** Gridlines, axis numbers, panel unit chips, the time axis, and the S1/S2 markers. */
  private drawFrame(
    pMax: number,
    vMin: number,
    vMax: number,
    s1: number,
    s2: number,
  ): void {
    this.frame.replaceChildren();

    const gridline = (y: number): void => {
      this.frame.appendChild(
        el('line', { class: 'wig-grid', x1: PLOT_X0, x2: PLOT_X1, y1: y, y2: y }),
      );
    };
    const tick = (y: number, text: string): void => {
      const t = el('text', { class: 'wig-tick', x: PLOT_X0 - 8, y: y + 3.5, 'text-anchor': 'end' });
      t.textContent = text;
      this.frame.appendChild(t);
    };
    /**
     * ⚠️ FAR LEFT of the gutter and left-anchored, NOT tucked against the plot edge.
     * The first version put the unit label at the same x as the numbers, and it landed
     * squarely on top of each panel's topmost tick — "ML" over "130", "ECG" over "0".
     * The gutter is 88 units wide and a 3-digit number is about 24, so the two survive
     * only by taking opposite ends of it.
     */
    const unitChip = (y: number, text: string): void => {
      const t = el('text', { class: 'wig-unit', x: 2, y, 'text-anchor': 'start' });
      t.textContent = text;
      this.frame.appendChild(t);
    };

    // Pressure panel: 0 and then every 40 mmHg up to the adaptive ceiling.
    unitChip(PRESSURE.top + 4, 'mmHg');
    for (let v = 0; v <= pMax; v += 40) {
      const y = PRESSURE.top + PRESSURE.h * (1 - v / pMax);
      gridline(y);
      tick(y, String(v));
    }

    // Volume panel: just the two bounds and the midpoint. EDV and ESV are the numbers
    // that matter and the curve's own flat tops announce them.
    unitChip(VOLUME.top + 4, 'mL');
    for (const v of [vMax, (vMin + vMax) / 2, vMin]) {
      const y = VOLUME.top + VOLUME.h * (1 - (v - vMin) / (vMax - vMin));
      gridline(y);
      tick(y, String(Math.round(v)));
    }

    // The ECG gets an isoelectric line rather than a scale — it has no calibrated units
    // in this model, and inventing a mV axis would claim a precision we do not have.
    const iso = this.toY.ecg(0);
    gridline(iso);
    unitChip(ECG.top + 4, 'ECG');

    // S1 / S2: the beat's two audible punctuation marks, drawn where the doors slam.
    // No sound in this piece (CLAUDE.md) — these are the visual stand-in, same as §7's.
    for (const [phase, label] of [
      [s1, 'S1'],
      [s2, 'S2'],
    ] as const) {
      const x = xOf(phase);
      this.frame.appendChild(
        el('line', {
          class: 'wig-sound-line',
          x1: x,
          x2: x,
          y1: RIBBON.top + RIBBON.h,
          y2: VALVES.top + VALVE_BAND_H + 2,
        }),
      );
      const t = el('text', {
        class: 'wig-sound-label',
        x: x + 4,
        y: VALVES.top + VALVE_BAND_H + 12,
      });
      t.textContent = label;
      this.frame.appendChild(t);
    }

    // Time axis, in milliseconds off the engine's own cycle length.
    const cycleMs = this.clock.getEngine().getParams().cycleLength * 1000;
    this.frame.appendChild(
      el('line', { class: 'wig-axis', x1: PLOT_X0, x2: PLOT_X1, y1: AXIS_Y, y2: AXIS_Y }),
    );
    for (let ms = 0; ms <= cycleMs + 1; ms += 100) {
      const x = xOf(Math.min(1, ms / cycleMs));
      this.frame.appendChild(
        el('line', { class: 'wig-axis-tick', x1: x, x2: x, y1: AXIS_Y, y2: AXIS_Y + 5 }),
      );
      const t = el('text', { class: 'wig-tick', x, y: AXIS_Y + 17, 'text-anchor': 'middle' });
      t.textContent = String(ms);
      this.frame.appendChild(t);
    }
    const unit = el('text', { class: 'wig-unit', x: PLOT_X1, y: AXIS_Y + 17, 'text-anchor': 'end' });
    unit.textContent = 'ms into the beat';
    this.frame.appendChild(unit);
  }

  // ---- Per-frame -----------------------------------------------------------

  /**
   * Move the playhead and every live value bead, and advance the entrance stack.
   *
   * Geometry is never rebuilt here — only transforms and two attributes per bead — so
   * this stays cheap enough to run alongside a beating heart.
   */
  update(dt: number): void {
    if (!this.visible) return;

    if (this.stacking) {
      this.stackT += dt;
      const want = Math.min(CHANNELS.length, Math.floor(this.stackT / STACK_STAGGER) + 1);
      while (this.landed < want) {
        this.groups.get(CHANNELS[this.landed]!.id)?.classList.add('is-landed');
        this.chips.get(CHANNELS[this.landed]!.id)?.classList.add('is-landed');
        this.landed++;
      }
      if (this.landed >= CHANNELS.length) this.stacking = false;
    }

    const phase = this.clock.getPhase();
    const x = xOf(phase);
    this.playhead.setAttribute('transform', `translate(${x.toFixed(2)},0)`);

    const i = Math.round(phase * SAMPLES);
    for (const id of ['lv', 'ao', 'la', 'vol', 'ecg'] as const) {
      const bead = this.beads.get(id);
      const v = this.series[id][i];
      if (!bead || v === undefined) continue;
      bead.setAttribute('cx', x.toFixed(2));
      bead.setAttribute('cy', this.toY[id](v).toFixed(2));
    }
    for (const valve of VALVE_ORDER) {
      const dot = this.valveDots.get(valve);
      if (!dot) continue;
      const open = this.valveOpenAt[valve](phase);
      dot.setAttribute('cx', x.toFixed(2));
      dot.classList.toggle('is-open', open);
    }

    const cycleMs = this.clock.getEngine().getParams().cycleLength * 1000;
    const s = this.clock.sample();
    this.readoutTime.textContent = `${Math.round(phase * cycleMs)} ms`;
    this.readoutPhase.textContent = PHASE_LABEL[s.phase];
    this.readoutValues.textContent =
      `LV ${Math.round(s.pressures.LV)} · Ao ${Math.round(s.pressures.SysArt)} · ` +
      `LA ${s.pressures.LA.toFixed(1)} mmHg · ${Math.round(s.volumes.LV)} mL`;
  }

  /**
   * Reveal, and run SPEC §11's progressive stack: the axis is already drawn, then the
   * channels land one at a time.
   *
   * ⚠️ Under `?focus=now` everything lands on the first frame. Headless gives the page
   * roughly 13 rAF frames, so a staggered entrance is simply invisible in a review
   * render — and CSS transitions do not advance under virtual time either, which is why
   * `is-instant` kills them rather than just shortening them.
   */
  show(): void {
    this.visible = true;
    this.refresh();
    this.root.classList.add('is-visible');
    this.stackT = 0;
    if (this.instant) {
      for (const ch of CHANNELS) {
        this.groups.get(ch.id)?.classList.add('is-landed');
        this.chips.get(ch.id)?.classList.add('is-landed');
      }
      this.landed = CHANNELS.length;
      this.stacking = false;
    } else {
      this.landed = 0;
      this.stacking = true;
      for (const ch of CHANNELS) {
        this.groups.get(ch.id)?.classList.remove('is-landed');
        this.chips.get(ch.id)?.classList.remove('is-landed');
      }
    }
  }

  hide(): void {
    this.visible = false;
    this.dragging = false;
    this.stacking = false;
    this.root.classList.remove('is-visible');
  }

  dispose(): void {
    this.hide();
    this.svg.removeEventListener('pointerdown', this.onPointerDown);
    window.removeEventListener('pointermove', this.onPointerMove);
    window.removeEventListener('pointerup', this.onPointerUp);
    this.root.remove();
  }
}
