/**
 * THE ONE REVEAL CONTROL. Progressive disclosure, used in exactly two places and
 * deliberately not two widgets:
 *
 *   - the section text panel, as a `More` link under a short opening sentence, hiding
 *     the long version of the copy;
 *   - the knob panel, as a `?` beside the title, hiding the per-knob explanations.
 *
 * WHY ONE CLASS. The reader's verdict on the finished spine was that the left-hand text
 * boxes were "way too dense" and read "like your average ai response that nobody would
 * read through", and separately that two of the knob panels were "way too dense". Those
 * are the same complaint about the same failure, so they get the same fix and the same
 * affordance. A reader who learns that a small quiet control opens the long version has
 * learned it for the whole piece.
 *
 * The long copy is NOT deleted. That was the reader's explicit choice when offered a hard
 * cut: keep it, put it behind a tap. So the default state is short and the depth is one
 * gesture away, everywhere.
 *
 * ⚠️ HOW THE COLLAPSE IS DONE, AND WHY NOT `max-height`. Every body here is prose whose
 * height depends on the panel's width, so a hand-picked `max-height` is either a clipping
 * bug at one viewport or a jumpy animation at another. `grid-template-rows: 0fr → 1fr`
 * animates to the content's OWN height with no magic number. The body must therefore be a
 * grid with `overflow: hidden` and its child `min-height: 0`; see `style.css`.
 *
 * ⚠️ HEADLESS ESCAPE HATCH — `?reveal=open`. Headless renders get about 13 rAF frames and
 * CSS transitions do not advance under virtual time, so a reveal caught mid-fade renders
 * as nothing at all and there is no way to click a button in a screenshot. The flag opens
 * every reveal on construction AND kills the transitions (`is-instant`), which is the same
 * bargain `?focus=now` strikes for the focus entrances and §11's channel stack.
 */

/** `link` renders a word ("More"); `glyph` renders a single mark ("?"). */
export type RevealKind = 'link' | 'glyph';

export interface RevealOptions {
  kind?: RevealKind;
  /** Button text when closed / open. Ignored by `glyph`, which never changes its mark. */
  moreLabel?: string;
  lessLabel?: string;
  /** Accessible name. Required in practice for `glyph`, where the mark says nothing. */
  ariaLabel?: string;
  /** Extra class on the button, for a per-host tweak without a new widget. */
  className?: string;
  onToggle?: (open: boolean) => void;
}

/** Unique ids for `aria-controls`, which needs a real id per body. */
let seq = 0;

const instantFlag = (): boolean =>
  new URLSearchParams(window.location.search).get('reveal') === 'open';

export class Reveal {
  /** The control itself. The caller places it; this class never decides layout. */
  readonly button: HTMLButtonElement;

  private readonly bodies: HTMLElement[] = [];
  private readonly opts: RevealOptions;
  private readonly kind: RevealKind;
  private readonly instant: boolean;
  private open: boolean;

  constructor(opts: RevealOptions = {}) {
    this.opts = opts;
    this.kind = opts.kind ?? 'link';
    this.instant = instantFlag();
    this.open = this.instant;

    this.button = document.createElement('button');
    this.button.type = 'button';
    this.button.className = `reveal-btn reveal-btn--${this.kind}${
      opts.className ? ` ${opts.className}` : ''
    }`;
    if (opts.ariaLabel) this.button.setAttribute('aria-label', opts.ariaLabel);
    this.button.addEventListener('click', () => this.toggle());
    this.syncButton();
  }

  /**
   * A collapsible container, already registered with this control. One reveal may own
   * several: the knob panel's `?` opens one body per knob row, each staying under the
   * slider it describes rather than collecting into a block of prose at the top.
   *
   * ⚠️ RETURNS BOTH HALVES ON PURPOSE, and an earlier version returning only the inner
   * one shipped a silent bug: a caller appended what it was handed, the animating grid
   * wrapper never entered the DOM, and every reveal rendered permanently open with no
   * error anywhere. `mount` is the element to put in the page; `content` is the element
   * to fill. Do not collapse this back into a single return value.
   */
  createBody(className?: string): { mount: HTMLDivElement; content: HTMLDivElement } {
    const mount = document.createElement('div');
    mount.className = `reveal-body${className ? ` ${className}` : ''}`;
    const content = document.createElement('div');
    content.className = 'reveal-body-inner';
    mount.appendChild(content);
    this.register(mount);
    return { mount, content };
  }

  /** Register an element built elsewhere. It must carry `.reveal-body` markup itself. */
  register(body: HTMLElement): void {
    body.id = body.id || `reveal-body-${++seq}`;
    if (this.instant) body.classList.add('is-instant');
    this.bodies.push(body);
    this.syncBodies();
    this.button.setAttribute('aria-controls', this.bodies.map((b) => b.id).join(' '));
  }

  /** Convenience: a paragraph in a fresh body, the section panel's whole use case. */
  addParagraph(text: string, className = 'section-more-p'): HTMLParagraphElement {
    const p = document.createElement('p');
    p.className = className;
    p.textContent = text;
    return p;
  }

  toggle(next: boolean = !this.open): void {
    if (next === this.open) return;
    this.open = next;
    this.syncButton();
    this.syncBodies();
    this.opts.onToggle?.(next);
  }

  isOpen(): boolean {
    return this.open;
  }

  private syncButton(): void {
    this.button.setAttribute('aria-expanded', this.open ? 'true' : 'false');
    this.button.classList.toggle('is-open', this.open);
    if (this.kind === 'glyph') {
      this.button.textContent = '?';
      return;
    }
    const more = this.opts.moreLabel ?? 'More';
    const less = this.opts.lessLabel ?? 'Less';
    this.button.textContent = this.open ? `${less}  ↑` : `${more}  ↓`;
  }

  private syncBodies(): void {
    for (const body of this.bodies) {
      body.classList.toggle('is-open', this.open);
      body.setAttribute('aria-hidden', this.open ? 'false' : 'true');
    }
  }

  dispose(): void {
    this.button.remove();
    for (const body of this.bodies) body.remove();
    this.bodies.length = 0;
  }
}
