import * as THREE from 'three';
import type { SectionConfig, SectionContext, CameraFraming } from './types.ts';
import { scaleFraming } from './cameraFraming.ts';
import { ManometerOverlay } from '../scene/overlays/manometer.ts';
import { BeatScrubber } from '../scene/overlays/beatScrubber.ts';
import { TrappedBlood } from '../scene/overlays/trappedBlood.ts';
import { StatusBadge } from '../scene/overlays/statusBadge.ts';
import { KnobPanel } from '../scene/overlays/knobPanel.ts';
import { VentricleLiquids, LV_CAVITY, findInnerCaps } from './ventricleLiquid.ts';

/**
 * "The doors open" — the merged open phases (SPEC §8 ejection + §10 filling, Act III).
 * The second conceptual pair of Act III, and the deliberate complement of "the sealed
 * ventricle".
 *
 * That section taught: twice per beat EVERY door is shut, so pressure swings hard and
 * the volume cannot move. This one is its mirror: twice per beat ONE door opens, and
 * the blood actually goes somewhere. The aortic opens and the squeeze throws the
 * contents out (EDV → ESV); later the mitral opens and the chamber refills
 * (ESV → EDV). The gap between those two numbers *is* the stroke volume — the beat's
 * whole output. Same diode rule from §4, opposite doors.
 *
 * Together the two sections have now built all four walls of the future P–V loop:
 * two vertical (sealed, volume flat) and two horizontal (open, volume moving).
 *
 * A teaching beat falls out of the pairing: the openings are SILENT. S1/S2 live in the
 * sealed section because heart sounds come from doors slamming shut — not from blood
 * moving and not from muscle contracting. So there is deliberately no closure marker
 * here.
 *
 * VOLUME IS SHOWN AS LIQUID, not as a bar: `LiquidVolume` puts a real body of blood in
 * the LV cavity whose size tracks the solver's mL (cube-root scaled, so apparent volume
 * is honest). The dots are demoted to what they do best — flow THROUGH the open doorway
 * — via `chamberAlpha`. Nothing to read; you just watch it empty and fill.
 *
 * Driven purely by the solver on the ONE clock. The reader scrubs; nothing autoplays.
 */

/**
 * A TIGHT shot, right in on the two left-side doors — deliberately the opposite of the
 * sealed view's wide, held composition. Here the subject is blood physically moving
 * through an opening, which is a close-up event: the streams and the doors should fill
 * the frame, and the reader should be near enough to see into the orifice the blood is
 * leaving through (which is also what the extra turn below buys).
 */
const FRAMING: CameraFraming = { position: [0.34, -0.40, 4.05], target: [0.26, -0.64, 0.10] };

/** Same authored anterior-wall cutaway as the sealed view — opens the LV cavity. */
const SECTION_CUTAWAY = 0.92;

/**
 * Turned LESS than the sealed view (20°), which is the opposite of what it seems it
 * should be — and the reason is worth keeping.
 *
 * ⚠️ TURNING FURTHER CLOSES THIS DOOR RATHER THAN OPENING IT. The aortic and pulmonary
 * valves sit at x/z ≈ (0.10, 0.12) and (0.31, 0.38), so their separation in SCREEN x goes
 * as 0.21·cos θ − 0.26·sin θ — which collapses to zero at θ ≈ 39°. A render at 34° put the
 * pulmonary trunk almost exactly in front of the aortic orifice, burying the very stream
 * this section is about. Less turn separates them (0.14 at 14° vs 0.03 at 34°), so the
 * close-up gets a clear line on the exit door.
 *
 * It still differentiates the two Act III views — this one is tight and front-on, the
 * sealed one wide and turned — it just does it in the direction the geometry allows.
 * Degrees clockwise-from-above; override live with `?turn=`.
 */
const HEART_TURN = 14;

/**
 * WHERE TO LOOK: the exit door and the pool it empties. Anchored midway between the
 * measured aortic annulus and the left ventricular cavity, so both ends of the ejection —
 * the leaflets swinging apart and the blood body visibly losing half of itself — sit
 * inside the clear circle along with the scarlet stream connecting them.
 *
 * HEART space, so it rides the 14° turn. The three pressure columns fall in the falloff
 * and dim to supporting evidence, which is right for this section: "the doors open" is
 * about blood MOVING, and the columns are here to say what it cost.
 */
const FOCUS = {
  anchor: [0.15, -0.50, 0.01] as [number, number, number],
  radius: 0.62,
  strength: 0.50,
  feather: 2.4,
};

/** Exit directions: LV→aorta (ejection out) and LV→LA (the mitral doorway). */
const AORTIC_AXIS = new THREE.Vector3(-0.28, 1.09, -0.51).normalize();
const MITRAL_AXIS = new THREE.Vector3(0.66, -0.66, 0.35).normalize(); // LA→LV
const LV_TO_LA = MITRAL_AXIS.clone().negate();

/**
 * Pressure columns, run SMALL and tucked low-right. They still earn their place — they
 * explain WHY each door opens — but here they are support, not subject: the streams are
 * what this section is about. (The sealed view does the reverse, running them oversized.)
 * Volume is NOT a column in either view; the liquid body carries it.
 */
const COLUMN_SCALE = 0.62;
/**
 * Pulled LEFT (from 1.30/1.62/1.94) to clear the knob panel, which docks in the upper
 * right — the only empty corner left once the scrubber has centre and the zoom buttons
 * have bottom-right. At the stiffest afterload setting the aortic column reaches high
 * enough to enter the panel's band, so the clearance has to hold at the knobs' extreme,
 * not just at rest.
 */
const LA_ANCHOR: [number, number, number] = [1.00, -1.30, 0];
const LV_ANCHOR: [number, number, number] = [1.28, -1.30, 0];
const AO_ANCHOR: [number, number, number] = [1.56, -1.30, 0];
const LA_COLOR = '#7fa8ff';
const LV_COLOR = '#ff5a4d';
const AO_COLOR = '#ffd24a';

/**
 * HEADROOM FOR THE KNOBS — this section runs a higher ceiling than the shared default
 * (130 mmHg), and it has to.
 *
 * Measured across the afterload knob's travel: peak LV pressure runs 93 → 162 mmHg and
 * the aorta 90/45 → 158/118, and the strong-squeeze-plus-high-resistance corner peaks at
 * 171. At the shared 130 the LV and aortic columns would both saturate and clip out of
 * frame over the top half of the knob — the same defect that had to be fixed in §4, but
 * now reachable by a deliberate reader action rather than by accident.
 *
 * The alternative (capping the bar while its mmHg readout keeps climbing) was rejected:
 * a bar that stops moving while its number rises is exactly the quiet dishonesty this
 * piece avoids. Resting columns therefore sit a little shorter here than in the sealed
 * view, which is harmless — the two sections already run different column scales (0.62
 * vs 1.3), and it's the proportions WITHIN a set that carry the teaching.
 */
const PMAX = 175;

/** Badge anchors — the aortic door up and screen-left, the mitral door low and clear
 *  of the columns (which occupy y ≥ −1.15). */
const AORTIC_BADGE = new THREE.Vector3(-0.549, -0.019, -0.054);
/** Dropped from y −1.35 so it stops clipping the LA column's "left atrium" sublabel,
 *  which moved when the columns were pulled left to clear the knob panel. */
const MITRAL_BADGE = new THREE.Vector3(0.548, -1.196, -0.097);

const OPEN_COLOR = '#5fd6c0';
const SHUT_COLOR = '#ff5a4d';

/** In-chamber dots stay faint so the LIQUID reads as the volume and the dots read as
 *  flow through the doorway. */
const CHAMBER_DOT_ALPHA = 0.12;

/** Right-heart streams held back in this tight left-side close-up — see the note where
 *  it's applied. The LEFT streams run at full strength; they're the subject here. */
const RV_JET_INTENSITY = 0.4;

/**
 * The two knobs (SPEC §8's "two live anchors"), with the reader-facing names this piece
 * uses instead of the clinical ones. Both are clamped by the engine to the
 * physiological ranges in PHYSICS.md §6, so no drag can produce an impossible heart.
 */
const CONTRACTILITY_COLOR = '#ff7a5c';
const AFTERLOAD_COLOR = '#ffd24a';

/**
 * The knob teaching lives HERE, in the panel, not in the blurb — the blurb had already
 * been trimmed hard once for becoming a wall of text, and appending two more sentences
 * about the controls put it straight back there. Copy belongs next to the thing it
 * describes anyway.
 *
 * ⚠️ BUT IT IS NOW BEHIND THE `?`. THIS IS THE SECOND PANEL THE READER NAMED BY NAME:
 * "the change the squeeze and the load section also is way too dense like the earlier
 * side card I mentioned". `KNOB_HINT` is the one line that stays visible, and it is an
 * instruction; everything that explains moved into `KNOB_ABOUT`.
 */
const KNOB_HINT = 'Drag either one, then let go. The whole heart re-solves.';

const KNOB_ABOUT = [
  'These two change what kind of beat this is, not where you are in it.',
  'The numbers below describe the new beat, not this instant. Change the heart, then ' +
    'scrub it again.',
];

/**
 * ⚠️ Removed "Each moves the same amount every beat — about 70 mL — but the left one
 * pushes roughly five times harder to do it". That is the section's *Aha*, and both
 * halves of it are already on screen, live: the two pools visibly shift by the same
 * amount, and the LV and Ao columns stand about five times taller than the right
 * heart's. Stating it first turns the whole display into a caption for a sentence.
 *
 * "Then take the controls, top right" moved into `KNOB_HINT` — it is an instruction,
 * and it belongs beside the controls it names.
 */
const BLURB =
  'Now the blood actually moves. When a ventricle out-pushes the artery above it, ' +
  'the exit door is forced open and the pool drains.';

const MORE = [
  'Later the entry door opens and the pool fills again. Both ventricles do all of ' +
    'this at the same moment.',
  'The red pool feeds your whole body. The blue one only feeds the lungs. Compare ' +
    'how much each one shifts, and how hard each has to push to shift it.',
];

export function createDoorsOpen(): SectionConfig {
  let mano: ManometerOverlay | null = null;
  let scrubber: BeatScrubber | null = null;
  let blood: TrappedBlood | null = null;
  let liquid: VentricleLiquids | null = null;
  let aorticBadge: StatusBadge | null = null;
  let mitralBadge: StatusBadge | null = null;
  let knobs: KnobPanel | null = null;
  let unsubFrame: (() => void) | null = null;

  let active = false;
  // ?phase parks the clock at a chosen instant for headless inspection.
  let parked = false;

  /**
   * The `InnerCap` mesh — the always-seated inner cut surface — sits just in FRONT of
   * the LV cavity, so with it in place a coherent liquid body inside the chamber is
   * entirely depth-rejected (verified: hiding it makes the liquid appear, along with
   * the mitral leaflets, chordae and papillary detail behind it). The standard
   * `CutawayController` only dissolves `CutawayDoor`, so this section — whose whole
   * subject is the blood *inside* the chamber — also retires the inner cap while it is
   * on screen, and puts it back on exit so every other section is unaffected.
   */
  let innerCaps: THREE.Object3D[] = [];
  const setInnerCapVisible = (v: boolean): void => {
    for (const o of innerCaps) o.visible = v;
  };

  /**
   * Park inside EJECTION, caught mid-throw. Measured against the solver rather than
   * guessed: over the window [0.266, 0.421] the LV empties 119 → 48 mL, and most of
   * that fall happens in the first half. At 0.30 through (≈ phase 0.3125) the volume
   * is 80 mL — visibly mid-fall, roughly the midpoint between EDV and ESV — with LV
   * 118 clearly above the aorta's 103, so the forward gradient holding the door open
   * reads at a glance. Parking later (the "columns kiss" moment) would catch the
   * volume already bottomed out, which is the wrong frame for a section about volume
   * MOVING.
   */
  const parkPhase = (ctx: SectionContext): number => {
    const p = ctx.clock.getEvents().phaseStart;
    const start = p.ejection;
    return start + 0.3 * (p['isovolumetric-relaxation'] - start);
  };

  return {
    id: 'doors-open',
    title: 'The doors open',
    blurb: BLURB,
    more: MORE,
    framing: { position: [...FRAMING.position], target: [...FRAMING.target] },
    cutaway: SECTION_CUTAWAY,
    heartRotationY: HEART_TURN,
    focus: FOCUS,

    init: (ctx: SectionContext) => {
      const search = new URLSearchParams(window.location.search);
      parked = search.has('phase');

      // DEV FLAGS `?contractility=` / `?afterload=` — set the operating point from the
      // URL, since a headless render can't drag a slider (the same reason ?keystone=
      // exists for §4's mode toggle). Values are clamped by the engine, so a silly
      // number is harmless. Applied before the panel is built so it opens showing them.
      const flagged: Record<string, number> = {};
      for (const key of ['contractility', 'afterload'] as const) {
        const raw = search.get(key);
        if (raw === null) continue;
        const v = Number(raw);
        if (Number.isFinite(v)) flagged[key] = v;
      }
      if (Object.keys(flagged).length) {
        ctx.clock.getEngine().setKnobs(flagged);
        ctx.clock.resolve();
      }

      innerCaps = findInnerCaps(ctx.scene);

      // Pressure columns only — they explain WHY each door opens (LV rises past the
      // aorta; LV falls below the atrium). The volume story is the liquid.
      mano = new ManometerOverlay(ctx.scene, ctx.clock, [
        { compartment: 'LA', anchor: LA_ANCHOR, label: 'LA', color: LA_COLOR, sublabel: 'left atrium' },
        { compartment: 'LV', anchor: LV_ANCHOR, label: 'LV', color: LV_COLOR, sublabel: 'left ventricle' },
        { compartment: 'SysArt', anchor: AO_ANCHOR, label: 'Ao', color: AO_COLOR, sublabel: 'aorta' },
      ], { scale: COLUMN_SCALE, pmax: PMAX });

      // The blood itself, as bodies of liquid — BOTH ventricles (the RV does all of
      // this at the same instant; see ventricleLiquid.ts).
      liquid = new VentricleLiquids(ctx.scene, ctx.clock);
      // Dim the RIGHT-heart streams for this close-up. The pulmonary trunk genuinely
      // crosses in front of the aortic root — real anatomy, not a placement error — so
      // its blue stream lands right on the aortic leaflets no matter how the heart is
      // turned. In a tight shot whose badges read "exit door · aortic", a blue stream
      // there invites precisely the wrong conclusion. The blue POOL still carries "the
      // right ventricle does all of this too"; only its jets step back.
      liquid.jets.get('pulmonary')?.setIntensity(RV_JET_INTENSITY);
      liquid.jets.get('tricuspid')?.setIntensity(RV_JET_INTENSITY);

      // Dots kept ONLY as doorway flow on the left side (see CHAMBER_DOT_ALPHA).
      blood = new TrappedBlood({
        center: LV_CAVITY.center,
        centerSystole: LV_CAVITY.centerSystole,
        radius: LV_CAVITY.radius,
        aorticDir: AORTIC_AXIS,
        mitralDir: LV_TO_LA,
        count: 56,
        chamberAlpha: CHAMBER_DOT_ALPHA,
      });
      // In the heart FRAME (not the scene) so the dots turn with the heart —
      // this section turns it (see HEART_TURN / heartOrientation.ts).
      ctx.scene.getHeartFrame().add(blood.points);

      scrubber = new BeatScrubber(ctx.clock);

      // SPEC §8's two live anchors. This is the first point in the piece where the reader
      // stops scrubbing through a fixed beat and starts changing WHICH BEAT IT IS.
      //
      // ⚠️ THE KNOBS ARE GLOBAL AND THEIR CHANGES PERSIST across sections — deliberately,
      // because there is only ever ONE heart (CLAUDE.md). Scroll back to the sealed
      // ventricle after strengthening the squeeze and you see YOUR heart sealing, not the
      // textbook one. The cost is that every section caching an engine-derived number has
      // to re-read it on entrance; §4 and the sealed view were both updated to do so, and
      // the Reset button below is the way back to resting.
      knobs = new KnobPanel(
        ctx.clock,
        [
          {
            key: 'contractility',
            label: 'Squeeze strength',
            loLabel: 'weaker',
            hiLabel: 'stronger',
            track: 'band',
            color: CONTRACTILITY_COLOR,
            // ⚠️ The reading guidance STAYS, even though it is closest to an outcome.
            // Sweeping this knob moves ESV fourfold while stroke volume barely budges,
            // so a reader watching the wrong line concludes the engine is broken. This
            // tells them where to look, not what they will find. (Quotes now match the
            // ledger labels exactly — they were lower-cased before.)
            explain:
              'How hard the ventricular muscle can squeeze, whatever it is holding. ' +
              'Watch “Empties down to” rather than “Pumped per beat”. In a closed loop ' +
              'the heart can only pump what comes back to it.',
          },
          {
            key: 'afterload',
            label: 'Artery stiffness',
            loLabel: 'relaxed',
            hiLabel: 'stiff',
            track: 'pipe',
            color: AFTERLOAD_COLOR,
            explain:
              'How hard the arteries push back. The stiffer they are, the higher the ' +
              'ventricle has to climb before the exit door will open at all.',
          },
        ],
        {
          // A literal label naming the two things this panel actually moves, replacing
          // the old shared "Your hands on the heart" — a mood, not a function.
          title: 'Change the squeeze and the load',
          hint: KNOB_HINT,
          about: KNOB_ABOUT,
          // LEADS WITH ESV, not stroke volume — and that ordering is a physics finding,
          // not a design preference. Sweeping contractility across its full range moves
          // ESV 110 → 26 mL (a factor of four, plainly visible as the pool bottoming out)
          // and ejection fraction 36% → 75%, while stroke volume moves only 62 → 75 mL.
          // The engine is right and SPEC's phrasing ("stronger squeeze → bigger SV") is
          // the loose part: in a CLOSED loop you can only pump what comes back, so a
          // stronger squeeze mostly empties the chamber further rather than raising
          // output. Headlining SV would have pointed the reader at the one number that
          // barely moves, and made a correct engine look broken.
          readouts: [
            { label: 'Empties down to', value: (c) => c.getMetrics().esv, unit: 'mL', hero: true },
            { label: 'Fills up to', value: (c) => c.getMetrics().edv, unit: 'mL' },
            { label: 'Pumped per beat', value: (c) => c.getMetrics().strokeVolume, unit: 'mL' },
            {
              label: 'Share emptied',
              value: (c) => c.getMetrics().ejectionFraction * 100,
              unit: '%',
            },
          ],
          // ONE re-solve per gesture, on release. `runToSteadyState()` costs 209–506 ms
          // measured, so this can never run per-frame (see knobPanel.ts). Order matters:
          // the engine must be re-solved BEFORE anything reads it.
          onCommit: (next) => {
            ctx.clock.getEngine().setKnobs(next);
            ctx.clock.resolve();
            // Everything holding a cached read of the old beat, refreshed together.
            scrubber?.refresh(); // phase boundaries move: ejection starts 0.24 → 0.31
            liquid?.refresh(); // EDV moves 172 → 101 mL, so the bodies must re-scale
          },
        },
      );

      // Both badges are pinned to ANATOMY, so they ride the frame too.
      const frame = ctx.scene.getHeartFrame();
      aorticBadge = new StatusBadge(ctx.scene, AORTIC_BADGE, 'Exit door · aortic', { frame });
      mitralBadge = new StatusBadge(ctx.scene, MITRAL_BADGE, 'Entry door · mitral', { frame });

      unsubFrame = ctx.scene.onFrame((dt) => {
        if (!active) return;
        const s = ctx.clock.sample();
        const m = ctx.clock.getMetrics();

        // Both liquid bodies read the real mL straight off the clock.
        liquid?.update(dt);
        // The rubber band's per-beat snap + the metric numbers easing to a new operating
        // point. No engine call beyond the sample this frame already took.
        knobs?.update(dt);

        const span = Math.max(1, m.edv - m.esv);
        blood?.update(dt, {
          fill01: THREE.MathUtils.clamp((s.volumes.LV - m.esv) / span, 0, 1),
          pressure01: THREE.MathUtils.clamp(s.pressures.LV / 120, 0, 1),
          aorticOpen: s.valves.aortic.open,
          mitralOpen: s.valves.mitral.open,
          wall01: ctx.scene.getWallInfluence(),
        });

        // Each door calls its own state, driven off the live valve.
        if (s.valves.aortic.open) {
          aorticBadge?.setState('▸ OPEN · blood leaving', OPEN_COLOR);
        } else {
          aorticBadge?.setState('■ SHUT', SHUT_COLOR);
        }
        if (s.valves.mitral.open) {
          mitralBadge?.setState('▸ OPEN · blood pouring in', OPEN_COLOR);
        } else {
          mitralBadge?.setState('■ SHUT', SHUT_COLOR);
        }
        aorticBadge?.update();
        mitralBadge?.update();
      });
    },

    enter: (ctx: SectionContext) => {
      const { scene, panel } = ctx;
      const headless = new URLSearchParams(window.location.search).get('intro') === '0';
      panel.classList.add('is-active');
      document.body.classList.add('keystone-active'); // retire the hero-only chrome
      active = true;

      if (!parked) ctx.clock.setPhase(parkPhase(ctx));

      mano?.show();
      // Re-read reference volumes on every entrance: the operating point is global and
      // persists, so the fullest volume may have moved since this section last ran.
      liquid?.refresh();
      liquid?.show();
      blood?.show();
      knobs?.show();
      scrubber?.refresh();
      // Both OPEN-door bands lit — the exact mirror of the sealed view lighting both
      // sealed bands.
      scrubber?.highlight(['ejection', 'filling']);
      scrubber?.show();
      aorticBadge?.show();
      mitralBadge?.show();

      scene.getCutaway()?.set(SECTION_CUTAWAY, { animate: !headless });
      // Re-assert the turn the same way the cutaway is re-asserted: the manager only
      // snaps on the very first activation, so a ?section= jump would otherwise leave
      // the heart mid-GSAP-tween — and GSAP doesn't advance under headless virtual time.
      scene.getOrientation()?.set(HEART_TURN, { animate: !headless });
      setInnerCapVisible(false);

      if (headless) {
        {
          // Through `scaleFraming`, or a headless render at a non-reference size would snap to
          // the unscaled pose and disagree with what the live ease produces.
          const snap = scaleFraming(FRAMING);
          scene.camera.position.set(...snap.position);
          scene.controls.target.set(...snap.target);
        }
        scene.controls.enabled = true;
        scene.controls.update();
      }
    },

    exit: (ctx: SectionContext) => {
      active = false;
      ctx.panel.classList.remove('is-active');
      document.body.classList.remove('keystone-active');
      mano?.hide();
      liquid?.hide();
      blood?.hide();
      // Hidden, NOT reset: the reader's operating point survives leaving the section
      // (one heart). `Reset the heart` in the panel is the way back to resting.
      knobs?.hide();
      scrubber?.hide();
      aorticBadge?.hide();
      mitralBadge?.hide();
      setInnerCapVisible(true); // leave the shared heart exactly as we found it
      ctx.scene.getCutaway()?.set(0, { animate: true });
    },

    dispose: (ctx: SectionContext) => {
      active = false;
      setInnerCapVisible(true); // never leave the shared heart missing a wall piece
      innerCaps = [];
      unsubFrame?.();
      unsubFrame = null;
      mano?.dispose();
      mano = null;
      liquid?.dispose();
      liquid = null;
      if (blood) {
        ctx.scene.getHeartFrame().remove(blood.points);
        blood.dispose();
        blood = null;
      }
      scrubber?.dispose();
      scrubber = null;
      knobs?.dispose();
      knobs = null;
      aorticBadge?.dispose();
      aorticBadge = null;
      mitralBadge?.dispose();
      mitralBadge = null;
    },
  };
}
