import * as THREE from 'three';
import type { SectionConfig, SectionContext, CameraFraming } from './types.ts';
import type { Valve } from '../engine/index.ts';
import { ValveLabels, type ValveLabelSpec } from '../scene/overlays/valveLabels.ts';
import { PhaseSwitch } from '../scene/overlays/phaseSwitch.ts';
import type { BeatClock } from '../clock/index.ts';
import { easeCameraTo, scaleFraming } from './cameraFraming.ts';
import { scaleDistance } from '../ui/uiScale.ts';

/**
 * Section 3 — "The four valves" (SPEC §6 §3).
 *
 * Teaches that valves are passive, one-way, pressure-operated doors — and that the
 * heart solves that one problem TWO different ways. The reader turns the beat dial
 * and watches four doors take their turns, then clicks one to study it.
 *
 * ── WHAT THE MODEL FORCED (measured, not assumed) ────────────────────────────
 * SPEC §3 asks for "a base-of-heart view of all four orifices on the clock". That
 * view is NOT ACHIEVABLE with this model and the alternative was user-confirmed:
 * the purchased heart is a CROSS-SECTION specimen, so there is no intact valve
 * plane to look down onto, and from above the great vessels occlude it completely
 * (rendered and confirmed — `.work/phaseC_review/w2_base_down.png`,
 * `x1_plane_fill.png`). What the model gives instead is better for the actual
 * lesson: with the atria lifted off and the anterior wall dissolved, ONE fixed
 * framing shows both AV valves with their full chordae AND a semilunar above them,
 * so the RECIPROCAL ALTERNATION reads without moving the camera —
 *   at ejection  the AV valves are tented shut, chordae taut, semilunar open;
 *   at filling    exactly reversed.
 * Compare `x4_mitral_open.png` (filling) with `y6_pair_cut.png` (ejection).
 *
 * ── WHAT THE SOLVER FORCED ───────────────────────────────────────────────────
 * The section leads with MITRAL vs AORTIC, and the reason is a measurement: the
 * shut mitral holds back ~116 mmHg and the shut aortic ~104 — essentially the SAME
 * load. So this is a pure DESIGN contrast (same job, same pressure, two mechanisms),
 * which is exactly SPEC's "one problem solved two ways" and is now numerically
 * rigorous rather than asserted. (The left-vs-right story — left valves hold ~7×
 * what the right ones do — is real and survives every knob, but it answers §2's
 * question, not this one.)
 *
 * A *view*: it owns no heart, no animation and no cardiac timing. Everything moves
 * because the solver moved it; the labels' OPEN/SHUT chips flip when the engine's
 * diode flips, never on a timer.
 *
 * ── THREE PIECES OF SHARED STATE IT BORROWS AND MUST PUT BACK ────────────────
 *  1. the `Atria` mesh — hidden, because the atria roof the AV valves;
 *  2. `controls.minDistance` — lowered, because the shared floor of 3 is FARTHER
 *     than this section's framing and would silently pull the camera back;
 *  3. the cutaway — opened, then closed on the way out.
 * All three are restored on `exit` AND `dispose`; the heart is shared.
 */

/**
 * The verified framing. Direction and distance were settled by rendering a sweep
 * (`.work/phaseC_review/z1_dist305` → `n3_d280`): at the shared floor of 3.0 the
 * chordae shrink to invisible threads, at 1.5 the frame is a texture study with no
 * anatomy left, and 2.4 is the window where both AV valves, the septum and the
 * pulmonary cusps all read. Then panned so the heart sits RIGHT of centre, because
 * the section text panel occupies the left third of the screen (`.section`,
 * `padding: 0 8vw`) — the pan shifts camera and target by the SAME world vector,
 * so the view direction (and therefore everything measured above) is preserved.
 */
const FRAMING: CameraFraming = { position: [1.604, 0.192, 1.817], target: [-0.122, -0.66, 0.383] };

/** Fully dissolve the anterior wall — the valves are the subject. */
const VALVES_CUTAWAY = 1;

/**
 * WHERE TO LOOK: the valve plane, all four doors at once.
 *
 * The anchor is the mean of the four MEASURED annulus centres (not the mesh centroids —
 * an AV valve's centroid hangs well below its orifice, down where the chordae reach the
 * papillary muscles), and the radius is set so the furthest of the four, the tricuspid at
 * 0.449 out, sits comfortably inside the clear area. At this section's close 2.40 framing
 * that circle is about two thirds of the frame height, which leaves the reciprocal
 * alternation — the pair that is open is never the pair that is shut — as the only thing
 * with any brightness on it.
 */
const FOCUS = {
  anchor: [0.005, -0.300, -0.014] as [number, number, number],
  radius: 0.55,
  strength: 0.55,
};

/**
 * Distance floor while this section is active. The shared default is 3, which is
 * BEYOND this section's 2.4 framing: OrbitControls.update() clamps
 * |camera − target| to minDistance on every frame, so without this the entrance
 * would ease toward 2.4 and be quietly dragged back to 3. Discovered the hard way
 * — two deliberately different close framings rendered BYTE-IDENTICAL.
 */
const VALVES_MIN_DISTANCE = 1.8;
/**
 * Camera distance used by the per-valve isolate framings. 1.35 was tried first and
 * pushed in so far the frame became a myocardium texture study with no sense of a
 * valve sitting inside a heart — the same failure the wide framing sweep hit at 1.5.
 */
const ISOLATE_DISTANCE = 2.0;

/**
 * Tags are kept right of this screen x while this section is active, so a pushed-in
 * isolate framing cannot park one on top of the section's text panel (`.section` has
 * `padding: 0 8vw` and the card runs to roughly 36ch beyond that).
 */
const LABEL_LEFT_BOUND = 480;

const normalize = (name: string): string => name.toLowerCase().replace(/[^a-z0-9]/g, '');

/** Valve mesh name (normalized) → engine valve. */
const VALVE_BY_MESH: Record<string, Valve> = {
  aorticvalve: 'aortic',
  pulmonaryvalve: 'pulmonary',
  mitralvalve: 'mitral',
  tricuspidvalve: 'tricuspid',
};

/** World centres from the HANDOFF anatomy probe — the isolate framings look here. */
/**
 * Measured valve-mesh centres in the app frame — re-read after the model's base pose
 * was corrected to end-diastole (see the base-pose note in ventricleLiquid.ts; the
 * app's fit scale moved too, from 7.28187 to 6.39455, because three's bounding box
 * inflates once per morph target and this model gained several).
 */
const VALVE_CENTER: Record<Valve, [number, number, number]> = {
  aortic: [-0.022, -0.204, -0.039],
  pulmonary: [0.174, 0.015, 0.220],
  mitral: [0.146, -0.543, -0.269],
  tricuspid: [-0.204, -0.615, 0.167],
};

const LEFT_ACCENT = '#ff5a4d'; // scarlet — left heart (the §1 through-line)
const RIGHT_ACCENT = '#7fa8ff'; // venous blue — right heart

/**
 * Each tag names a valve centre (world, from the HANDOFF anatomy probe) and sits at
 * a fixed SCREEN offset from it.
 *
 * ⚠️ The offsets are MEASURED from a render, not derived. Two earlier attempts to
 * place these by hand-solved world anchors both failed — the first put the aortic and
 * pulmonary tags off the top of the screen, the second put the aortic and mitral tags
 * off the right edge — because doing it that way means re-deriving the camera basis,
 * fov and aspect by hand per tag. In this framing all four valves project into a
 * cluster only a few hundred pixels across, so the tags must fan well clear of it and
 * of each other; a pixel offset after projection is exact, and `ValveLabels` clamps
 * it into the viewport as a backstop.
 *
 * The fan direction is chosen so the two LEFT-heart tags go right (into the dark void
 * beside the heart) and the two RIGHT-heart tags go left — while staying clear of the
 * section text panel, which owns roughly the left quarter of the screen.
 */
const LABEL_SPECS: ValveLabelSpec[] = [
  {
    key: 'mitral',
    counterpart: 'aortic',
    name: 'Mitral valve',
    mechanism:
      'Two big leaflets, tethered. Cords (chordae) tie their free edges down to the ' +
      'ventricle wall, so pressure cannot blow them inside out.',
    point: [0.23, -0.64, -0.04],
    offsetPx: [330, 40],
    accent: LEFT_ACCENT,
  },
  {
    key: 'aortic',
    counterpart: 'mitral',
    name: 'Aortic valve',
    mechanism:
      'Three cusps, untethered. Backflow catches in their pockets and presses them ' +
      'together. The harder it pushes back, the tighter they seal.',
    point: [0.10, -0.33, 0.12],
    offsetPx: [360, -150],
    accent: LEFT_ACCENT,
  },
  {
    key: 'tricuspid',
    counterpart: 'pulmonary',
    name: 'Tricuspid valve',
    mechanism:
      'The same tethered design as the mitral, on the right. Three leaflets instead ' +
      'of two, holding back a far gentler pressure.',
    point: [-0.08, -0.71, 0.35],
    offsetPx: [-300, 90],
    accent: RIGHT_ACCENT,
  },
  {
    key: 'pulmonary',
    counterpart: 'tricuspid',
    name: 'Pulmonary valve',
    mechanism:
      'The same three-cusp design as the aortic, on the right. The low-pressure ' +
      'exit door out to the lungs.',
    point: [0.31, -0.10, 0.38],
    offsetPx: [-330, -70],
    accent: RIGHT_ACCENT,
  },
];

const INTRO_HINT =
  'Throw the switch and watch the two pairs trade places. Click any valve to study it.';

/**
 * THE SWITCH'S TWO POSITIONS — and they are the two valve PAIRS, not two phases of the
 * cycle, because the pairs are what §3 is about.
 *
 * ⚠️ BOTH PHASES ARE DERIVED FROM THE ENGINE'S OWN EVENT TABLE, never hand-keyed. Cardiac
 * timing lives in exactly one place (CLAUDE.md), and these must also follow the reader's
 * knobs: afterload alone moves the start of ejection from 0.24 to 0.31, and a hard-coded
 * 0.34 would drift out of the ejection window entirely at the stiff end of the travel.
 *
 * WAY IN parks at the midpoint of the whole AV-open stretch rather than of the `filling`
 * phase alone. The AV valves stay open through filling AND atrial systole, so the honest
 * middle of "the way in is open" spans `filling → isovolumetric-contraction`, which wraps
 * past the end of the beat. WAY OUT parks mid-ejection, which needs no wrap.
 */
const WAY_IN = {
  label: 'The way in',
  detail: 'mitral + tricuspid',
  color: '#5fd6c0',
  phase: (clock: BeatClock): number => {
    const p = clock.getEvents().phaseStart;
    // The AV-open window runs from the start of filling to the start of the sealed
    // window, crossing the end of the beat; +1 unwraps it before taking the midpoint.
    const start = p.filling;
    const end = p['isovolumetric-contraction'] + 1;
    return start + 0.5 * (end - start);
  },
};

const WAY_OUT = {
  label: 'The way out',
  detail: 'aortic + pulmonary',
  color: '#ffd24a',
  phase: (clock: BeatClock): number => {
    const p = clock.getEvents().phaseStart;
    return p.ejection + 0.5 * (p['isovolumetric-relaxation'] - p.ejection);
  },
};

export function createSection3(): SectionConfig {
  let labels: ValveLabels | null = null;
  let valveSwitch: PhaseSwitch | null = null;
  let unsubFrame: (() => void) | null = null;
  let detachPick: (() => void) | null = null;
  let active = false;

  /** The four valve meshes, for the click-to-isolate raycast. */
  const valveMeshes: { mesh: THREE.Mesh; valve: Valve }[] = [];

  /** The atria roof the AV valves — hidden while this section is on screen. */
  let atriaMeshes: THREE.Object3D[] = [];
  const setAtriaVisible = (v: boolean): void => {
    for (const m of atriaMeshes) m.visible = v;
  };

  /** Restored on the way out — the controls are shared scene state. */
  let priorMinDistance: number | null = null;

  /** Which valve is being studied (null = all four in view). */
  let isolated: Valve | null = null;

  /**
   * Peak load each valve holds back while shut, mmHg — re-measured from the engine
   * on EVERY entrance, never cached from init.
   *
   * §8 hands the reader contractility and afterload knobs whose values PERSIST
   * globally (one heart, one operating point). Afterload alone moves the aortic
   * valve's peak load 72 → 144 mmHg, so a number captured at init would be wrong by
   * a factor of two for a reader who scrolled back. This is the documented staleness
   * trap that §1, §4, §6, sealed and doors all guard against the same way.
   */
  const peakLoad: Record<Valve, number> = { mitral: 0, aortic: 0, tricuspid: 0, pulmonary: 0 };

  /** Instantaneous pressure difference across each valve (positive = holding back). */
  const loadsAt = (s: {
    pressures: Record<string, number>;
  }): Record<Valve, number> => ({
    mitral: s.pressures['LV']! - s.pressures['LA']!,
    tricuspid: s.pressures['RV']! - s.pressures['RA']!,
    aortic: s.pressures['SysArt']! - s.pressures['LV']!,
    pulmonary: s.pressures['PulArt']! - s.pressures['RV']!,
  });

  const readEngine = (ctx: SectionContext): void => {
    const engine = ctx.clock.getEngine();
    for (const v of Object.keys(peakLoad) as Valve[]) peakLoad[v] = 0;
    const N = 240;
    for (let i = 0; i < N; i++) {
      const s = engine.sample(i / N);
      const dp = loadsAt(s);
      for (const v of Object.keys(peakLoad) as Valve[]) {
        // Only while SHUT: the load a sealing strategy actually has to survive.
        if (!s.valves[v].open && dp[v] > peakLoad[v]) peakLoad[v] = dp[v];
      }
    }
  };

  // Panel controls, built once in init.
  let hintEl: HTMLParagraphElement | null = null;
  let compareEl: HTMLParagraphElement | null = null;
  let backBtn: HTMLButtonElement | null = null;

  /**
   * The comparison line, written from the freshly measured numbers rather than
   * hard-coded — so it stays true after the reader moves a knob.
   */
  const compareText = (): string =>
    `The shut mitral holds back ${peakLoad.mitral.toFixed(0)} mmHg. The shut aortic ` +
    `holds back ${peakLoad.aortic.toFixed(0)}. Near-identical loads, solved two ` +
    `completely different ways.`;

  /** Frame a single valve: pull back along the current view direction from it. */
  const isolateFraming = (valve: Valve): CameraFraming => {
    const target = new THREE.Vector3(...VALVE_CENTER[valve]);
    // Keep the section's established viewing direction so the isolate reads as a
    // push-in on the same scene, not a jump to an unrelated angle.
    const dir = new THREE.Vector3(...FRAMING.position)
      .sub(new THREE.Vector3(...FRAMING.target))
      .normalize();
    const pos = target.clone().addScaledVector(dir, ISOLATE_DISTANCE);
    return { position: [pos.x, pos.y, pos.z], target: [target.x, target.y, target.z] };
  };

  const setIsolated = (valve: Valve | null, ctx: SectionContext): void => {
    isolated = valve;
    labels?.setEmphasis(valve);
    if (backBtn) backBtn.style.display = valve ? 'inline-block' : 'none';
    if (hintEl) {
      hintEl.textContent = valve
        ? 'Turn the dial and watch just this one. The chip reads what the pressure ' +
          'across it is doing.'
        : INTRO_HINT;
    }
    easeCameraTo(ctx.scene, valve ? isolateFraming(valve) : FRAMING, { duration: 1.1 });
  };

  /** Click (not drag) on a valve → isolate it. */
  const enablePicking = (ctx: SectionContext): void => {
    const dom = ctx.scene.renderer.domElement;
    const ray = new THREE.Raycaster();
    const ndc = new THREE.Vector2();
    let downX = 0;
    let downY = 0;
    let downT = 0;

    const onDown = (e: PointerEvent): void => {
      downX = e.clientX;
      downY = e.clientY;
      downT = performance.now();
    };
    const onUp = (e: PointerEvent): void => {
      if (!active) return;
      // Ignore drags (that's an orbit) and long holds.
      if (Math.hypot(e.clientX - downX, e.clientY - downY) > 5) return;
      if (performance.now() - downT > 500) return;
      const rect = dom.getBoundingClientRect();
      ndc.set(
        ((e.clientX - rect.left) / rect.width) * 2 - 1,
        -((e.clientY - rect.top) / rect.height) * 2 + 1,
      );
      ray.setFromCamera(ndc, ctx.scene.camera);
      const hits = ray.intersectObjects(
        valveMeshes.filter((v) => v.mesh.visible).map((v) => v.mesh),
        false,
      );
      const hit = hits[0];
      if (!hit) return;
      const found = valveMeshes.find((v) => v.mesh === hit.object);
      if (!found) return;
      // Clicking the valve already being studied backs out to all four, so the
      // reader can always undo the push-in with the same gesture that caused it.
      setIsolated(found.valve === isolated ? null : found.valve, ctx);
    };

    dom.addEventListener('pointerdown', onDown);
    dom.addEventListener('pointerup', onUp);
    detachPick = () => {
      dom.removeEventListener('pointerdown', onDown);
      dom.removeEventListener('pointerup', onUp);
    };
  };

  const buildPanelControls = (ctx: SectionContext): void => {
    // `.section-extra`, not `.section-content` — the panel's `More` reveal is appended
    // after that slot, and an instruction must outrank the long version of the prose.
    const content = ctx.panel.querySelector('.section-extra');
    if (!content || content.querySelector('.valves-controls')) return;
    const wrap = document.createElement('div');
    wrap.className = 'valves-controls keystone-controls';

    hintEl = document.createElement('p');
    hintEl.className = 'keystone-hint';
    hintEl.textContent = INTRO_HINT;

    compareEl = document.createElement('p');
    compareEl.className = 'keystone-hint';
    compareEl.style.opacity = '0.85';
    compareEl.textContent = compareText();

    backBtn = document.createElement('button');
    backBtn.className = 'keystone-toggle';
    backBtn.type = 'button';
    backBtn.textContent = '◂  Show all four';
    backBtn.style.display = 'none';
    backBtn.addEventListener('click', () => setIsolated(null, ctx));

    wrap.append(hintEl, compareEl, backBtn);
    content.appendChild(wrap);
  };

  return {
    id: 'valve-plane',
    title: 'The four valves',
    // The last clause used to be "— and the heart solves that one problem two
    // entirely different ways", which is SPEC §3's *Aha* and is also what
    // `compareText()` already delivers live, with the two real mmHg loads in it.
    // The copy names the oddity and stops.
    //
    // ⚠️ THE `more` DELIBERATELY DOES NOT SAY "the same load". That is the reframed
    // thesis (HANDOFF: mitral 116 vs aortic 104 mmHg, a DESIGN contrast rather than a
    // load contrast) and `compareText()` states it live with the measured numbers in it.
    blurb:
      'Four one-way doors, and not one of them has a motor. Pressure alone pushes ' +
      'each one open and slams it shut.',
    more: [
      'Two of the four guard the way in. Two guard the way out. They are not built ' +
        'the same way at all.',
      'Cords, pockets, two leaflets or three. Click a valve and it will tell you ' +
        'which, and what it is holding back.',
    ],
    framing: { position: [...FRAMING.position], target: [...FRAMING.target] },
    cutaway: VALVES_CUTAWAY,
    focus: FOCUS,

    init: (ctx: SectionContext) => {
      const heart = ctx.scene.getHeart();
      if (heart) {
        heart.traverse((obj) => {
          const mesh = obj as THREE.Mesh;
          if (!mesh.isMesh) return;
          const n = normalize(mesh.name);
          const valve = VALVE_BY_MESH[n];
          if (valve) valveMeshes.push({ mesh, valve });
          if (n === 'atria') atriaMeshes.push(mesh);
        });
      }

      labels = new ValveLabels(ctx.scene, LABEL_SPECS, {
        frame: ctx.scene.getHeartFrame(),
        bounds: { left: LABEL_LEFT_BOUND },
      });
      valveSwitch = new PhaseSwitch(ctx.clock, {
        positions: [WAY_IN, WAY_OUT],
        initial: 0,
        onSettle: () => {
          if (hintEl && !isolated) hintEl.textContent = INTRO_HINT;
        },
      });

      readEngine(ctx);
      buildPanelControls(ctx);
      enablePicking(ctx);

      // One per-frame driver: push the solver's live valve states into the labels.
      // Nothing here advances the clock — the reader's dial does that (SPEC §4's
      // direct-manipulation contract; nothing autoplays).
      unsubFrame = ctx.scene.onFrame((dt) => {
        if (!active) return;
        // The throw lives here: the switch eases the CLOCK and the leaflets follow the
        // solver. Nothing in this file touches a leaflet morph (DRIVEN MOTION).
        valveSwitch?.update(dt);
        if (!labels) return;
        const s = ctx.clock.sample();
        const dp = loadsAt(s);
        for (const v of Object.keys(VALVE_CENTER) as Valve[]) {
          labels.setState(v, { open: s.valves[v].open, loadMmHg: Math.max(0, dp[v]) });
        }
      });
    },

    enter: (ctx: SectionContext) => {
      const { scene, panel } = ctx;
      const search = new URLSearchParams(window.location.search);
      const headless = search.get('intro') === '0';
      panel.classList.add('is-active');
      document.body.classList.add('keystone-active'); // suppress the hero-only chrome
      active = true;

      // The operating point may have moved since init (the knobs are global and
      // persist) — re-measure before anything reads a load.
      readEngine(ctx);
      if (compareEl) compareEl.textContent = compareText();

      setAtriaVisible(false); // the atria roof the AV valves
      if (priorMinDistance === null) {
        priorMinDistance = scene.controls.minDistance;
        // Scaled like the framing it exists to permit — see ui/uiScale.ts.
        scene.controls.minDistance = scaleDistance(VALVES_MIN_DISTANCE);
      }

      isolated = null;
      labels?.setEmphasis(null);
      if (backBtn) backBtn.style.display = 'none';
      if (hintEl) hintEl.textContent = INTRO_HINT;
      labels?.show();

      // Dev shortcut: ?valve=mitral opens straight into the isolated study of one
      // valve. Same purpose as §4's ?keystone=machine — headless cannot click, and
      // it lets a specific valve be reviewed without hunting for it in the cut.
      const wanted = search.get('valve');
      if (wanted && wanted in VALVE_CENTER) {
        isolated = wanted as Valve;
        labels?.setEmphasis(isolated);
        if (backBtn) backBtn.style.display = 'inline-block';
      }
      /**
       * Dev shortcut `?valveswitch=out` — opens in the thrown position.
       *
       * ⚠️ There is no other way to review the second state. A throw takes ~1.15 s and
       * headless gets about 13 frames, so a screenshot of a thrown switch is otherwise
       * unobtainable; same reason `?valve=` and `?keystone=machine` exist.
       */
      if (valveSwitch) {
        valveSwitch.throwTo(search.get('valveswitch') === 'out' ? 1 : 0);
        // The switch's two positions are derived from the engine's own phase table, so a
        // re-solve relocates them; `settleNow` re-reads them and parks with no travel,
        // which is also what makes the entrance land on a valid instant immediately.
        valveSwitch.settleNow();
        valveSwitch.show();
      }

      // Own the reveal: the valves are behind the anterior wall until it dissolves.
      scene.getCutaway()?.set(VALVES_CUTAWAY, { animate: !headless });

      if (headless) {
        // Snap to whichever framing this entrance actually wants — the isolate
        // framing when ?valve= asked for one, since Edge can't advance the tween.
        const shot = isolated ? isolateFraming(isolated) : FRAMING;
        {
          const snap = scaleFraming(shot);
          scene.camera.position.set(...snap.position);
          scene.controls.target.set(...snap.target);
        }
        scene.controls.enabled = true;
        scene.controls.update();
      }
    },

    exit: (ctx: SectionContext) => {
      active = false;
      ctx.panel.classList.remove('is-active');
      document.body.classList.remove('keystone-active');
      labels?.hide();
      valveSwitch?.hide();
      setAtriaVisible(true); // leave the shared heart whole
      if (priorMinDistance !== null) {
        ctx.scene.controls.minDistance = priorMinDistance;
        priorMinDistance = null;
      }
      ctx.scene.getCutaway()?.set(0, { animate: true });
    },

    dispose: (ctx: SectionContext) => {
      active = false;
      unsubFrame?.();
      unsubFrame = null;
      detachPick?.();
      detachPick = null;
      labels?.dispose();
      labels = null;
      valveSwitch?.dispose();
      valveSwitch = null;
      setAtriaVisible(true); // never leave the shared heart missing its atria
      atriaMeshes = [];
      valveMeshes.length = 0;
      if (priorMinDistance !== null) {
        ctx.scene.controls.minDistance = priorMinDistance;
        priorMinDistance = null;
      }
    },
  };
}
