import * as THREE from 'three';

/**
 * A PLACEHOLDER heart-like form for Phase 0 "first light".
 *
 * This is deliberately NOT the final anatomy. Sourcing and vetting a real,
 * imaging-derived, accuracy-defensible model (BodyParts3D / Z-Anatomy, or a
 * CC-Attribution fallback) is a Phase 3 task (BUILD_PLAN §3, SPEC.md §5) and
 * must not be picked here.
 *
 * We shape a subdivided icosphere into a tapered ventricular mass with a
 * rounded base and a pointed apex — an organic lump rather than a valentine,
 * so it honours "realistic, not cartoon" even as a stand-in. All warping is
 * deterministic (trig-based), so the form is stable across reloads.
 */
export function createPlaceholderHeart(): THREE.Mesh {
  const geometry = new THREE.IcosahedronGeometry(1, 5);
  shapeIntoHeartMass(geometry);
  geometry.computeVertexNormals();

  // Matte living-muscle look: deep crimson, high roughness, a whisper of
  // clearcoat for a moist-tissue sheen — never photoreal (SPEC.md §5).
  const material = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#7c2b2b'),
    roughness: 0.72,
    metalness: 0.0,
    clearcoat: 0.18,
    clearcoatRoughness: 0.6,
    sheen: 0.25,
    sheenColor: new THREE.Color('#b05050'),
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'placeholder-heart';
  mesh.castShadow = true;
  mesh.receiveShadow = true;

  // The real heart sits obliquely in the chest: apex down, forward, and to the
  // subject's left. A gentle tilt reads as anatomy rather than a floating egg.
  mesh.rotation.set(0.12, 0.5, 0.22);
  mesh.scale.setScalar(1.35);

  return mesh;
}

/**
 * Warps unit-sphere vertices into a heart-like mass, in place.
 * Coordinate convention: +y up, apex toward -y.
 */
function shapeIntoHeartMass(geometry: THREE.BufferGeometry): void {
  const pos = geometry.getAttribute('position') as THREE.BufferAttribute;
  const v = new THREE.Vector3();

  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i);

    // t: 0 at the bottom pole, 1 at the top pole.
    const t = (v.y + 1) / 2;

    // Horizontal taper: broad, rounded top narrowing to a point at the apex.
    // pow keeps the base full while the apex pinches toward zero.
    const taper = Math.pow(THREE.MathUtils.clamp(t, 0, 1), 0.62);
    // Keep a little girth right at the very tip so the apex is rounded, not sharp.
    const horizontal = 0.08 + 0.92 * taper;

    // Azimuth around the vertical axis, used for the subtle two-lobe crease.
    const azimuth = Math.atan2(v.z, v.x);

    // A shallow anterior interventricular groove: a crease down the front,
    // strongest across the mid-body, fading out at top and apex.
    const grooveDepth = 0.09 * Math.sin(Math.PI * t) * Math.max(0, Math.cos(azimuth));
    const bilobe = 1 - grooveDepth;

    // Slightly fuller on the left/posterior to break the symmetry.
    const asym = 1 + 0.05 * Math.sin(azimuth + 0.6) * t;

    const r = horizontal * bilobe * asym;
    v.x *= r;
    v.z *= r;

    // Vertical: a touch taller than wide, and let the top dome out.
    v.y *= 1.22;
    v.y += 0.06 * Math.pow(THREE.MathUtils.clamp(t, 0, 1), 3); // subtle crown

    pos.setXYZ(i, v.x, v.y, v.z);
  }

  pos.needsUpdate = true;
}
