import * as THREE from 'three';

/**
 * Cinematic Anatomical lighting (SPEC §5 + art direction). A dramatic warm key
 * with a strong warm rim gives the realistic tissue its moist, gallery-lit read,
 * while a dim cool fill just barely opens the shadow side and a low hemisphere
 * keeps blacks from dying. Contrast is deliberately high — the heart is the hero
 * and the void stays dark around it. Pairs with the warm env map (environment.ts)
 * that supplies the wet specular reflections.
 *
 * Returns the group so callers can add/remove the whole rig at once.
 */
export function createLighting(): THREE.Group {
  const rig = new THREE.Group();
  rig.name = 'lighting';

  // Low, warm ambient floor — deep but not dead black in the shadows.
  const hemi = new THREE.HemisphereLight(0xffe9d6, 0x140b08, 0.18);
  rig.add(hemi);

  // Key: the dramatic modelling light, high and to the left, warm.
  const key = new THREE.DirectionalLight(0xffe6d2, 3.0);
  key.position.set(-4.5, 6.5, 4.5);
  key.castShadow = true;
  key.shadow.mapSize.set(2048, 2048);
  key.shadow.camera.near = 1;
  key.shadow.camera.far = 25;
  key.shadow.bias = -0.0005;
  rig.add(key);

  // Fill: dim and cool, opposite side, just enough to keep the shadow readable.
  const fill = new THREE.DirectionalLight(0xbcd0ff, 0.22);
  fill.position.set(5, 1, 3);
  rig.add(fill);

  // Rim: strong and warm, behind and above, carving the moist silhouette out
  // of the void — the signature of the cinematic look.
  const rim = new THREE.DirectionalLight(0xffd9bf, 2.4);
  rim.position.set(1.5, 4.5, -6);
  rig.add(rim);

  return rig;
}
