import * as THREE from 'three';

/**
 * A dim, warm image-based environment for the heart's PBR materials
 * (art-direction: "Cinematic Anatomical"). Without an environment, the moist
 * tissue reads flat — its wet specular highlights need something to reflect.
 * This is a cheap procedural gradient (warm key band over a deep warm-black
 * ground), PMREM-filtered into an env map. Kept dim so it lifts the speculars
 * without washing out the dramatic key/rim lighting.
 */
export function createHeartEnvironment(renderer: THREE.WebGLRenderer): THREE.Texture {
  const size = 128;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  const g = ctx.createLinearGradient(0, 0, 0, size);
  g.addColorStop(0.0, '#241713'); // warm-dark sky
  g.addColorStop(0.34, '#5c3b30'); // warm key band (the brightest reflection)
  g.addColorStop(0.58, '#1a1210');
  g.addColorStop(1.0, '#080605'); // dark ground
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);

  const tex = new THREE.CanvasTexture(canvas);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.colorSpace = THREE.SRGBColorSpace;

  const pmrem = new THREE.PMREMGenerator(renderer);
  const env = pmrem.fromEquirectangular(tex).texture;
  pmrem.dispose();
  tex.dispose();
  return env;
}
