import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { scaleDistance } from '../ui/uiScale.ts';

/**
 * The shared orbit floor, at the reference window. Exported so the sections that lower it for a
 * close framing (§3, §4) restore THIS rather than re-keying a literal 3 — and so all of them
 * pass through `scaleDistance` together.
 */
export const DEFAULT_MIN_DISTANCE = 3;

/**
 * Smooth orbit controls for the placeholder heart. Damping makes the motion
 * feel weighty and calm rather than snappy — the tactile "you drive it" feel
 * the direct-manipulation contract asks for (SPEC.md §4).
 *
 * Zoom and pan are bounded so the reader can't lose the heart in the void.
 */
export function createControls(
  camera: THREE.Camera,
  domElement: HTMLElement,
): OrbitControls {
  const controls = new OrbitControls(camera, domElement);

  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.rotateSpeed = 0.6;

  controls.enablePan = false; // keep the heart centred for now
  // The scroll wheel is reserved for progressing through the sections (page scroll),
  // NOT dollying the 3D heart — zoom is driven by the on-screen +/- buttons instead
  // (setupZoomControls in main.ts). With enableZoom off, OrbitControls ignores the
  // wheel without preventing default, so the wheel scrolls the page.
  controls.enableZoom = false;
  // ⚠️ SCALED WITH THE FRAMINGS THEY BOUND. These are distances measured against the same
  // 1600 × 1000 window every section's framing was, and `OrbitControls.update()` re-clamps to
  // them every frame — so a floor left unscaled would quietly overrule the resolution control
  // for any section framed near it. See `ui/uiScale.ts`.
  controls.minDistance = scaleDistance(DEFAULT_MIN_DISTANCE);
  controls.maxDistance = scaleDistance(16); // headroom to zoom out from the wide hero (~10.5)

  // Allow full vertical orbit but stop just shy of the poles to avoid gimbal flip.
  controls.minPolarAngle = 0.15;
  controls.maxPolarAngle = Math.PI - 0.15;

  controls.target.set(0, 0, 0);
  controls.update();

  return controls;
}
