import gsap from 'gsap';
import * as THREE from 'three';
import type { HeartScene } from '../scene/index.ts';
import type { CameraFraming } from './types.ts';
import { frameDistanceScale } from '../ui/uiScale.ts';

/**
 * ⚠️ EVERY SECTION'S FRAMING PASSES THROUGH HERE, WHICH IS WHY THE RESOLUTION SCALE IS APPLIED
 * HERE AND NOWHERE ELSE. A section declares the pose it wants at the reference 1600 × 1000
 * window; this stretches the camera's DISTANCE from the target so the heart keeps the same size
 * relative to the chrome at any other window. See `ui/uiScale.ts` for why a distance is the
 * right thing to scale.
 *
 * ⚠️ THE TARGET AND THE VIEW DIRECTION ARE LEFT ALONE. Only the distance along the existing
 * direction changes, so a framing's composition — what is centred, what is cropped, which way
 * the heart faces — is exactly what its author chose. Moving the target instead would rotate
 * every section's view, which is the mistake §6 already paid for once.
 *
 * ⚠️ AT THE REFERENCE WINDOW THIS IS THE IDENTITY. `frameDistanceScale()` returns 1, so
 * `position` comes out bit-for-bit as declared. Sections that snap the camera themselves
 * (the `?intro=0` headless paths) bypass this, which is why `scaleFraming` is exported.
 */
export function scaleFraming(framing: CameraFraming): CameraFraming {
  const k = frameDistanceScale();
  if (Math.abs(k - 1) < 1e-6) return framing;
  const target = new THREE.Vector3(...framing.target);
  const position = new THREE.Vector3(...framing.position);
  const offset = position.clone().sub(target).multiplyScalar(k);
  const scaled = target.clone().add(offset);
  return { position: [scaled.x, scaled.y, scaled.z], target: [...framing.target] };
}

/**
 * Light entrance framing (SPEC §5): ease the ONE shared camera to a section's
 * mark, then hand control back to the reader (OrbitControls re-enabled). The
 * camera and controls are shared state — we tween a scalar proxy and write it
 * onto them each frame so OrbitControls' damping stays consistent.
 */
export interface FramingOptions {
  duration?: number;
  onComplete?: () => void;
  /** Skip the tween and snap (used for the first section on load). */
  immediate?: boolean;
}

export function easeCameraTo(
  scene: HeartScene,
  framing: CameraFraming,
  opts: FramingOptions = {},
): gsap.core.Tween | null {
  const { duration = 1.6, onComplete, immediate = false } = opts;
  const cam = scene.camera;
  const ctrl = scene.controls;
  const scaled = scaleFraming(framing);
  const [px, py, pz] = scaled.position;
  const [tx, ty, tz] = scaled.target;

  if (immediate) {
    cam.position.set(px, py, pz);
    ctrl.target.set(tx, ty, tz);
    ctrl.update();
    onComplete?.();
    return null;
  }

  // Freeze user control during the ease so the reader and the tween don't fight.
  ctrl.enabled = false;
  const s = {
    px: cam.position.x, py: cam.position.y, pz: cam.position.z,
    tx: ctrl.target.x, ty: ctrl.target.y, tz: ctrl.target.z,
  };
  return gsap.to(s, {
    px, py, pz, tx, ty, tz,
    duration,
    ease: 'power2.inOut',
    overwrite: true,
    onUpdate() {
      cam.position.set(s.px, s.py, s.pz);
      ctrl.target.set(s.tx, s.ty, s.tz);
      ctrl.update();
    },
    onComplete() {
      ctrl.enabled = true; // hand control back to the reader
      onComplete?.();
    },
  });
}
