import * as THREE from 'three';
import type { HeartScene } from '../index.ts';

/**
 * THE FOCUS SYSTEM — one reusable way for a section to say "look HERE".
 *
 * WHY IT EXISTS. Every section in this piece teaches exactly one thing, but the frame
 * is full of beautiful competing detail: a moist PBR heart, four swinging valves,
 * glowing liquid, pressure columns, an ECG strip. The atrial kick is the section that
 * proved the problem — its whole lesson is a pale watermark ring on the surface of the
 * left ventricular pool, a few pixels of it, and a reader looking at the frame simply
 * never found it. That is not a copy problem and it is not a §6 problem. Every section
 * needs to be able to point.
 *
 * WHAT IT DOES. Two devices, both declarative, both driven from a world anchor:
 *
 *  1. A SPOTLIGHT: everything outside a soft circle around the subject is darkened.
 *     The circle tracks the anchor's projected screen position every frame, so it
 *     survives the camera easing in, the reader orbiting, and a section's heart turn.
 *  2. A one-shot ATTENTION PULSE: a ring that expands out of the subject and fades,
 *     twice, on entrance. The spotlight says where to settle; the pulse says where to
 *     go first.
 *
 * WHY IN THE DOM AND NOT IN WEBGL. Three cheaper-than-postprocessing options were on
 * the table (a per-section keylight, per-mesh dimming, depth of field). A screen-space
 * mask beats all of them here for one reason: the subject is often NOT anatomy. §6's
 * subject is an overlay ring; §5's is a conduction path that is deliberately drawn
 * ignoring depth. Lighting and per-mesh dimming can only address meshes, and per-mesh
 * dimming additionally has to fight the fact that this model's 12 meshes SHARE ONE PBR
 * MATERIAL (write to `mesh.material` on one and you have written to all of them). A
 * mask over the canvas is blind to all of that, and it cannot break the heart.
 *
 * ⚠️ LAYERING. The mask is `position: fixed; z-index: 0`, appended to `<body>` after
 * `#app`. Equal z-index means DOM order decides, so it paints OVER the canvas and UNDER
 * `#sections` (z-index 1) and all the HUD chrome (z-index 3–6). Darkening the anatomy
 * while leaving the prose and the controls at full strength is the entire point — do not
 * "fix" this by raising it.
 *
 * ⚠️ PERFORMANCE. Both elements are moved with `transform: translate3d(...)` only, which
 * the compositor handles without a repaint. The mask's radial-gradient background is a
 * repaint, so it is rebuilt ONLY when the projected radius actually changes materially
 * (i.e. while zooming), not every frame.
 */

/** What a section declares. Everything but `anchor` and `radius` has a sane default. */
export interface FocusSpec {
  /**
   * The point the reader should be looking at. In HEART-FRAME coordinates by default,
   * which is what every measured anchor in this project already is — so it follows a
   * section's `heartRotationY` for free. Use `space: 'world'` for HUD furniture that
   * deliberately does not turn (the manometer columns).
   */
  anchor: [number, number, number];
  space?: 'heart' | 'world';
  /**
   * Radius of the fully-clear area, in WORLD units, projected to pixels each frame.
   * World rather than pixels so zooming in on the subject keeps the spotlight on the
   * subject instead of cropping it.
   */
  radius: number;
  /** How dark it gets well outside the circle. 0–1. */
  strength?: number;
  /** Where the darkening reaches full strength, as a multiple of `radius`. */
  feather?: number;
  /** Fire the attention pulse on entrance. */
  pulse?: boolean;
  /** Pulse colour; defaults to the warm ivory the rest of the HUD uses. */
  color?: string;
  /**
   * Seconds to wait after `enter()` before the spotlight fades up. The camera ease and
   * the cutaway dissolve both run about a second, and darkening the frame while it is
   * still moving reads as a glitch rather than as an instruction.
   */
  delay?: number;
}

const DEFAULTS = {
  strength: 0.58,
  feather: 2.3,
  pulse: true,
  color: '#ffd9b8',
  delay: 0.75,
};

/** Fade in/out time constant for the whole overlay, seconds. */
const FADE = 0.55;
/** How many attention pulses fire on entrance, and how long each takes. */
const PULSE_COUNT = 2;
const PULSE_SECONDS = 1.25;
/** Rebuild the gradient only past this fractional change in radius (see the class doc). */
const RADIUS_EPSILON = 0.03;

export class FocusOverlay {
  private readonly scene: HeartScene;
  private readonly mask: HTMLDivElement;
  private readonly ring: HTMLDivElement;

  private spec: FocusSpec | null = null;
  /** 0 → fully off, 1 → fully applied. */
  private presence = 0;
  private target = 0;
  private wait = 0;
  /** Baked gradient state, so the repaint only happens when the radius really moves. */
  private bakedRadiusPx = -1;
  private bakedStrength = -1;
  private side = 0;
  /** Pulse animation: seconds elapsed, and how many are left to fire. */
  private pulseT = 0;
  private pulsesLeft = 0;

  private readonly anchor = new THREE.Vector3();
  private readonly probe = new THREE.Vector3();
  private readonly camRight = new THREE.Vector3();
  private readonly ndc = new THREE.Vector3();
  /**
   * Dev affordance `?focus=now`: skip every entrance delay.
   *
   * ⚠️ THIS EXISTS BECAUSE HEADLESS VERIFICATION NEEDS IT. A headless Edge run gives the
   * page well under a second of animation time before the screenshot lands — measured at
   * about 13 rAF frames, regardless of `--virtual-time-budget`. The default 0.75 s wait
   * therefore never elapses, the mask never fades up, and the focus system looks
   * completely broken in every review render while working perfectly in the browser.
   * That cost a full diagnostic pass to discover; do not remove this hook.
   */
  private readonly instant = new URLSearchParams(window.location.search).get('focus') === 'now';
  private readonly onResize = () => this.measure();

  constructor(scene: HeartScene) {
    this.scene = scene;

    this.mask = document.createElement('div');
    this.mask.className = 'focus-mask';
    document.body.appendChild(this.mask);

    this.ring = document.createElement('div');
    this.ring.className = 'focus-ring';
    document.body.appendChild(this.ring);

    this.measure();
    window.addEventListener('resize', this.onResize);
  }

  /**
   * Point the focus at a subject, or clear it with `null`. Cross-fades either way, so a
   * section that declares no focus visibly hands the whole frame back.
   */
  set(spec: FocusSpec | null): void {
    this.spec = spec;
    this.target = spec ? 1 : 0;
    if (!spec) {
      // Never leave a pending delay behind, or the hand-back stalls.
      this.wait = 0;
      this.pulsesLeft = 0;
      return;
    }
    this.wait = this.instant ? 0 : (spec.delay ?? DEFAULTS.delay);
    if (spec.pulse ?? DEFAULTS.pulse) {
      this.pulsesLeft = PULSE_COUNT;
      this.pulseT = 0;
    }
  }

  /**
   * Size the mask from the viewport.
   *
   * It is a square of side 4×the viewport diagonal, with a `closest-side` radial
   * gradient — so the gradient's own radius is 2×the diagonal, and no matter where on
   * screen the subject sits (worst case a corner, 1.5 diagonals from the far corner) the
   * dark region still covers the whole viewport. That is what lets the element be moved
   * with a pure transform instead of being re-laid-out.
   */
  private measure(): void {
    const diag = Math.hypot(window.innerWidth, window.innerHeight);
    this.side = diag * 4;
    this.mask.style.width = `${this.side}px`;
    this.mask.style.height = `${this.side}px`;
    this.bakedRadiusPx = -1; // the gradient's stops are fractions of the new side
  }

  /** Rebuild the gradient. A repaint — see the class doc for why it is rate-limited. */
  private bake(radiusPx: number, strength: number): void {
    const half = this.side / 2;
    const clear = Math.max(0.0005, radiusPx / half);
    const dark = Math.min(1, clear * (this.spec?.feather ?? DEFAULTS.feather));
    this.mask.style.background =
      `radial-gradient(circle closest-side, ` +
      `rgba(0,0,0,0) 0%, rgba(0,0,0,0) ${(clear * 100).toFixed(3)}%, ` +
      `rgba(0,0,0,${strength.toFixed(3)}) ${(dark * 100).toFixed(3)}%, ` +
      `rgba(0,0,0,${strength.toFixed(3)}) 100%)`;
    this.bakedRadiusPx = radiusPx;
    this.bakedStrength = strength;
  }

  update(dt: number): void {
    // Hold the fade back until the entrance has finished moving.
    if (this.wait > 0) {
      this.wait = Math.max(0, this.wait - dt);
      if (this.wait > 0 && this.presence <= 0) return;
    }

    const k = 1 - Math.exp(-dt / (FADE / 3));
    this.presence += (this.target - this.presence) * k;
    if (this.presence < 0.004 && this.target === 0) {
      this.presence = 0;
      this.mask.style.opacity = '0';
      this.ring.style.opacity = '0';
      return;
    }

    const spec = this.spec;
    if (!spec) return;

    const px = this.project(spec);
    if (!px) {
      // Subject is behind the camera — darkening the frame with no visible hole would
      // just read as the lights going out. Step aside until it comes back.
      this.mask.style.opacity = '0';
      this.ring.style.opacity = '0';
      return;
    }

    const radiusPx = px.radius;
    const strength = (spec.strength ?? DEFAULTS.strength);
    if (
      Math.abs(radiusPx - this.bakedRadiusPx) > RADIUS_EPSILON * Math.max(1, this.bakedRadiusPx) ||
      strength !== this.bakedStrength
    ) {
      this.bake(radiusPx, strength);
    }

    const half = this.side / 2;
    this.mask.style.transform = `translate3d(${(px.x - half).toFixed(1)}px, ${(px.y - half).toFixed(1)}px, 0)`;
    this.mask.style.opacity = this.presence.toFixed(3);

    this.updatePulse(dt, px.x, px.y, radiusPx, spec.color ?? DEFAULTS.color);
  }

  /**
   * Anchor → screen pixels, plus the world radius projected to pixels.
   *
   * The radius is measured by projecting a SECOND point one radius to the camera's right
   * and taking the screen distance, rather than by any focal-length arithmetic — that
   * way it stays correct under whatever the camera is doing without this file having to
   * know anything about it.
   */
  private project(spec: FocusSpec): { x: number; y: number; radius: number } | null {
    const cam = this.scene.camera;
    this.anchor.set(spec.anchor[0], spec.anchor[1], spec.anchor[2]);
    if ((spec.space ?? 'heart') === 'heart') {
      this.anchor.applyMatrix4(this.scene.getHeartFrame().matrixWorld);
    }

    // A point one world radius to the camera's right, in world space.
    this.camRight.setFromMatrixColumn(cam.matrixWorld, 0);
    this.probe.copy(this.anchor).addScaledVector(this.camRight, spec.radius);

    const rect = this.scene.renderer.domElement.getBoundingClientRect();
    const a = this.ndc.copy(this.anchor).project(cam);
    if (a.z > 1) return null;
    const b = this.probe.project(cam);

    const toPx = (v: THREE.Vector3): { x: number; y: number } => ({
      x: rect.left + ((v.x + 1) / 2) * rect.width,
      y: rect.top + ((1 - v.y) / 2) * rect.height,
    });
    const pa = toPx(a);
    const pb = toPx(b);
    return { x: pa.x, y: pa.y, radius: Math.max(24, Math.hypot(pb.x - pa.x, pb.y - pa.y)) };
  }

  /** The one-shot ring: expands out of the subject, fades, repeats, then retires. */
  private updatePulse(dt: number, x: number, y: number, radiusPx: number, color: string): void {
    if (this.pulsesLeft <= 0 || this.wait > 0) {
      this.ring.style.opacity = '0';
      return;
    }
    this.pulseT += dt;
    if (this.pulseT >= PULSE_SECONDS) {
      this.pulseT = 0;
      this.pulsesLeft -= 1;
      if (this.pulsesLeft <= 0) {
        this.ring.style.opacity = '0';
        return;
      }
    }
    const t = this.pulseT / PULSE_SECONDS;
    // Ease out, so it leaves the subject fast and then drifts — the shape of something
    // being pointed at rather than something throbbing.
    const eased = 1 - (1 - t) * (1 - t) * (1 - t);
    const size = radiusPx * (0.55 + 1.35 * eased);
    this.ring.style.width = `${(size * 2).toFixed(1)}px`;
    this.ring.style.height = `${(size * 2).toFixed(1)}px`;
    this.ring.style.borderColor = color;
    this.ring.style.transform = `translate3d(${(x - size).toFixed(1)}px, ${(y - size).toFixed(1)}px, 0)`;
    this.ring.style.opacity = ((1 - eased) * 0.85 * this.presence).toFixed(3);
  }

  dispose(): void {
    window.removeEventListener('resize', this.onResize);
    this.mask.remove();
    this.ring.remove();
  }
}
