/**
 * Accuracy anchors — the validation targets from PHYSICS.md §7.
 *
 * SINGLE SOURCE OF TRUTH. These values are simultaneously (a) the clamp targets
 * the solver is tuned/bounded to and (b) the assertions the Vitest harness
 * checks. They are transcribed directly from PHYSICS.md §7; if that table
 * changes, change it here and nowhere else.
 */

export interface AnchorRange {
  /** Inclusive lower bound of the acceptable physiological range. */
  min: number;
  /** Inclusive upper bound. */
  max: number;
  /** The nominal resting textbook value within the range. */
  target: number;
  /** Human-readable unit, for messages. */
  unit: string;
}

/** Left heart / systemic — full fidelity (PHYSICS.md §7). */
export const ANCHORS = {
  edv: { min: 110, max: 130, target: 120, unit: 'mL' },
  esv: { min: 40, max: 60, target: 50, unit: 'mL' },
  strokeVolume: { min: 60, max: 80, target: 70, unit: 'mL' },
  // Ejection fraction as a fraction (0–1); PHYSICS.md gives 50–65%.
  ejectionFraction: { min: 0.5, max: 0.65, target: 0.58, unit: '' },
  peakLVPressure: { min: 110, max: 130, target: 120, unit: 'mmHg' },
  aorticSystolic: { min: 110, max: 130, target: 120, unit: 'mmHg' },
  aorticDiastolic: { min: 70, max: 85, target: 80, unit: 'mmHg' },
  meanLAPressure: { min: 6, max: 14, target: 10, unit: 'mmHg' },
  heartRateBpm: { min: 60, max: 100, target: 75, unit: 'bpm' },
  cycleLengthSeconds: { min: 0.6, max: 1.0, target: 0.8, unit: 's' },
  cardiacOutput: { min: 4, max: 6, target: 5, unit: 'L/min' },

  // Right heart / pulmonary — simplified but plausible (PHYSICS.md §7).
  peakRVPressure: { min: 20, max: 30, target: 25, unit: 'mmHg' },
  pulmonarySystolic: { min: 20, max: 30, target: 25, unit: 'mmHg' },
  pulmonaryDiastolic: { min: 8, max: 15, target: 10, unit: 'mmHg' },
  meanRAPressure: { min: 0, max: 8, target: 4, unit: 'mmHg' },
} as const satisfies Record<string, AnchorRange>;

export type AnchorKey = keyof typeof ANCHORS;

/**
 * Approximate phase durations within the ~0.8 s beat (PHYSICS.md §7). Filling
 * is "the remainder of diastole" — checked as > 0 rather than to a fixed value.
 */
export const PHASE_DURATIONS_SECONDS = {
  'atrial-systole': { target: 0.1 },
  'isovolumetric-contraction': { target: 0.05 },
  ejection: { target: 0.3 },
  'isovolumetric-relaxation': { target: 0.08 },
} as const;
