import type {
  ActiveChamber,
  CardiacPhase,
  CycleEvents,
  CycleMetrics,
  ConductionLandmark,
  ElectricalWaveState,
  EngineParams,
  EngineState,
  Knobs,
  Valve,
  ValveState,
} from './types.ts';
import { DEFAULT_KNOBS, DEFAULT_PARAMS, KNOB_RANGES } from './defaults.ts';
import { COMPARTMENTS, derive, rk4Step, type Volumes } from './solver.ts';

/** Preload (mean venous filling pressure) → modeled blood volume, mL per mmHg.
 *  More filling volume → higher EDV → larger stroke volume (Frank–Starling). */
const PRELOAD_VOLUME_GAIN = 70;

/** How close a per-frame marker must sit to its event to fire, in cycle phase. */
const MARKER_WINDOW = 0.008;

/**
 * Conduction transit times in SECONDS (SPEC.md §6 §5) — the fixed part of the
 * path. These are tissue transit times: they do not scale with heart rate and
 * they do not scale with the AV delay.
 *
 * The AV node's stall is deliberately absent from this list. It is the one
 * VARIABLE element, and it is derived from `avDelay` — which is exactly what the
 * AV node is physiologically: the adjustable delay line in the path.
 *
 * ⚠️ WHY THIS IS DERIVED AND NOT A TABLE. Until §5 was built these six segments
 * were hard-coded phase constants with the stall pinned at 0.15 → 0.20, while the
 * *solver* took its ventricular activation start from `avDelay / cycleLength`.
 * At the default 0.16 s those two happen to give the same 0.20, so they agreed —
 * by coincidence. Move the delay and the muscle re-timed while the light did not,
 * which silently breaks §5's whole premise that the muscle contracts just behind
 * the glow. Cardiac timing lives in ONE place (CLAUDE.md); this is that place.
 */
const SA_DISCHARGE_SECONDS = 0.015;
/** Atrial depolarisation — the P wave. 15 + 95 ms ≈ a normal 110 ms P wave. */
const ATRIAL_SWEEP_SECONDS = 0.095;
/** His bundle down the interventricular septum. */
const SEPTUM_SECONDS = 0.024;
/** Purkinje network reaching the apex. */
const APEX_SECONDS = 0.032;
/** Ventricular walls depolarising apex → base. */
const VENTRICLE_SECONDS = 0.144;

/**
 * How long a landmark stays lit behind the wavefront, seconds. Purely the visual
 * tail that makes the sweep readable as a travelling wave rather than a set of
 * independent blinks — repolarisation itself is out of scope (black box).
 */
const CONDUCTION_TAIL_SECONDS = 0.1;

/** One landmark's window within the beat, as cycle phases. */
export interface ConductionSegment {
  landmark: ConductionLandmark;
  start: number;
  end: number;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/**
 * Build the conduction schedule for the current delay and cycle length.
 *
 * The atrial half runs on fixed transit times; the AV node absorbs all of the
 * variation (its stall runs from the end of atrial depolarisation to `avDelay`);
 * the ventricular half then follows at fixed transit times from `avDelay`.
 *
 * ⚠️ SEGMENTS CAN OVERLAP, ON PURPOSE. Below an ~0.11 s delay there is no time
 * left for a stall, so the septum starts while the atria are still depolarising —
 * and the av-node segment collapses to zero length. That is not a degenerate case
 * to guard against, it is SPEC §5's lesson made literal: the ventricles firing
 * before the atria have finished. Consumers read `levels`, which is per-landmark
 * and therefore overlap-safe.
 */
function conductionSchedule(avDelaySeconds: number, cycleLength: number): ConductionSegment[] {
  const toPhase = (seconds: number) => seconds / cycleLength;
  const saEnd = toPhase(SA_DISCHARGE_SECONDS);
  const atriaEnd = saEnd + toPhase(ATRIAL_SWEEP_SECONDS);
  // The ventricles fire one AV delay after the atria — the same quantity the
  // solver uses for `chambers.LV.activationStart`, from the same knob.
  const ventricularStart = toPhase(avDelaySeconds);
  const septumEnd = ventricularStart + toPhase(SEPTUM_SECONDS);
  const apexEnd = septumEnd + toPhase(APEX_SECONDS);
  return [
    { landmark: 'sa-node', start: 0, end: saEnd },
    { landmark: 'atria', start: saEnd, end: atriaEnd },
    // Zero-length (or negative, clamped) once the delay is shorter than atrial
    // depolarisation: the node no longer holds the impulse at all.
    { landmark: 'av-node', start: atriaEnd, end: Math.max(atriaEnd, ventricularStart) },
    { landmark: 'septum', start: ventricularStart, end: septumEnd },
    { landmark: 'apex', start: septumEnd, end: apexEnd },
    { landmark: 'ventricles', start: apexEnd, end: apexEnd + toPhase(VENTRICLE_SECONDS) },
  ];
}

/**
 * Excitation of one landmark at `phase`: 0 before the front arrives, ramping to
 * 1 as the front crosses it, then decaying over the tail.
 *
 * A zero-length segment (the collapsed AV stall) skips straight to the decay, so
 * it flashes and is gone — which is the honest depiction of a node that held the
 * impulse for no time at all.
 */
function excitationAt(phase: number, seg: ConductionSegment, tailPhase: number): number {
  if (phase < seg.start) return 0;
  const span = seg.end - seg.start;
  if (span > 1e-9 && phase < seg.end) return (phase - seg.start) / span;
  const since = phase - Math.max(seg.start, seg.end);
  if (since >= tailPhase) return 0;
  return 1 - since / tailPhase;
}

/**
 * The cardiac physics engine (PHYSICS.md §1–8) — and the master clock the whole
 * piece reads (SPEC.md §4). Lumped-parameter closed loop: time-varying
 * elastance chambers + three-element Windkessel + ideal-diode valves, integrated
 * with fixed-step RK4.
 *
 * Usage: set knobs, `runToSteadyState()`, then read via `sample(phase)`,
 * `getEvents()`, `getCycleMetrics()` (the scrub path) or `step()` + `getState()`
 * (the live path).
 */
export class CardiacEngine {
  private params: EngineParams;
  private knobs: Knobs;

  private volumes: Volumes;
  private time = 0;

  /** The canonical steady-state beat, recorded phase 0 → 1. */
  private beat: Array<{ phase: number; volumes: Volumes }> = [];
  private events: CycleEvents | null = null;
  private metrics: CycleMetrics | null = null;

  constructor(overrides: Partial<EngineParams> = {}) {
    this.params = { ...structuredClone(DEFAULT_PARAMS), ...structuredClone(overrides) };
    this.knobs = { ...DEFAULT_KNOBS };
    // `avDelay` is knob-owned, and `applyKnobsToParams` below writes it — so a
    // param override of it would be silently discarded. Seed the knob from it
    // instead, keeping `new CardiacEngine({ avDelay })` working as a way to pin
    // the delay (the harness and the probes both do this).
    if (overrides.avDelay !== undefined) {
      const range = KNOB_RANGES.avDelay;
      this.knobs.avDelay = clamp(overrides.avDelay, range.min, range.max);
    }
    this.applyKnobsToParams();
    this.volumes = this.initialVolumes();
  }

  // ---- Configuration -------------------------------------------------------

  getParams(): Readonly<EngineParams> {
    return this.params;
  }

  getKnobs(): Readonly<Knobs> {
    return this.knobs;
  }

  /**
   * The conduction path's landmark windows for the current operating point, as
   * cycle phases.
   *
   * Exposed so that Section 5's ECG can place its P wave and QRS complex on the
   * engine's OWN timings rather than re-deriving them. An ECG that hand-keyed
   * where the QRS goes would drift out of agreement with the muscle the moment
   * the reader touched the AV-delay knob — which is precisely the class of bug
   * this schedule was made derived to kill. Timing lives in one place.
   */
  getConductionSchedule(): ConductionSegment[] {
    return conductionSchedule(this.params.avDelay, this.params.cycleLength);
  }

  /**
   * Update one or more knobs, each clamped to its physiological range
   * (PHYSICS.md §6), then map onto parameters. Invalidates the cached solve.
   */
  setKnobs(next: Partial<Knobs>): void {
    for (const key of Object.keys(next) as (keyof Knobs)[]) {
      const value = next[key];
      if (value === undefined) continue;
      const range = KNOB_RANGES[key];
      this.knobs[key] = clamp(value, range.min, range.max);
    }
    this.applyKnobsToParams();
    this.invalidate();
  }

  private applyKnobsToParams(): void {
    const p = this.params;
    p.chambers.LV.eMax = this.knobs.contractility;
    p.sysArt.rSys = this.knobs.afterload;
    p.cycleLength = 60 / this.knobs.heartRate;
    p.avDelay = this.knobs.avDelay;
    // Keep the AV delay fixed in seconds as HR changes: the ventricles fire a
    // fixed interval after the atria, so the phase-fraction tracks the period.
    //
    // This is the SAME quantity `conductionSchedule()` derives the AV stall from,
    // read from the same knob — which is what keeps the muscle and the conduction
    // glow in lockstep at every delay. Do not re-key either one independently.
    const ventricularStart = p.avDelay / p.cycleLength;
    p.chambers.LV.activationStart = ventricularStart;
    p.chambers.RV.activationStart = ventricularStart;
    // Preload sets the modeled blood volume (Frank–Starling).
    p.totalBloodVolume =
      DEFAULT_PARAMS.totalBloodVolume +
      PRELOAD_VOLUME_GAIN * (this.knobs.preload - DEFAULT_KNOBS.preload);
  }

  // ---- Simulation ----------------------------------------------------------

  /** Reset integrator state: fresh volume distribution, phase 0. */
  reset(): void {
    this.volumes = this.initialVolumes();
    this.time = 0;
  }

  /** Advance real time by `dtSeconds`, RK4-substepping at the internal dt. */
  step(dtSeconds: number): void {
    const p = this.params;
    const T = p.cycleLength;
    const subSteps = Math.max(1, Math.round(dtSeconds / p.dt));
    const dt = dtSeconds / subSteps;
    const dPhase = dt / T;
    for (let i = 0; i < subSteps; i++) {
      const phase = (this.time / T) % 1;
      this.volumes = rk4Step(this.volumes, p, dt, phase, dPhase);
      this.time += dt;
    }
  }

  /** Instantaneous state at the current time (live path). */
  getState(): EngineState {
    this.ensureSolved();
    const phase = (this.time / this.params.cycleLength) % 1;
    return this.buildState(this.volumes, phase);
  }

  /** Steady-state snapshot at normalized cycle phase (scrub path). */
  sample(cyclePhase01: number): EngineState {
    this.ensureSolved();
    const phase = cyclePhase01 - Math.floor(cyclePhase01);
    const record = this.recordAt(phase);
    return this.buildState(record.volumes, phase);
  }

  /**
   * Integrate to a periodic steady state at the current operating point, then
   * record the canonical beat and derive its events + metrics.
   */
  runToSteadyState(opts: { maxBeats?: number; tolerance?: number } = {}): void {
    const maxBeats = opts.maxBeats ?? 80;
    const tolerance = opts.tolerance ?? 0.02; // mL, beat-to-beat EDV/ESV drift

    const p = this.params;
    const T = p.cycleLength;
    const stepsPerBeat = Math.max(1, Math.round(T / p.dt));
    const dt = T / stepsPerBeat;
    const dPhase = 1 / stepsPerBeat;

    this.reset();

    let prevEdv = Infinity;
    let prevEsv = Infinity;
    for (let b = 0; b < maxBeats; b++) {
      let minLV = Infinity;
      let maxLV = -Infinity;
      for (let i = 0; i < stepsPerBeat; i++) {
        this.volumes = rk4Step(this.volumes, p, dt, i * dPhase, dPhase);
        if (this.volumes.LV < minLV) minLV = this.volumes.LV;
        if (this.volumes.LV > maxLV) maxLV = this.volumes.LV;
      }
      if (Math.abs(maxLV - prevEdv) < tolerance && Math.abs(minLV - prevEsv) < tolerance) {
        break;
      }
      prevEdv = maxLV;
      prevEsv = minLV;
    }

    this.recordBeat(stepsPerBeat, dt, dPhase);
    this.events = this.computeEvents();
    this.metrics = this.computeMetrics();
    this.time = 0;
  }

  getCycleMetrics(): CycleMetrics {
    this.ensureSolved();
    return this.metrics as CycleMetrics;
  }

  getEvents(): CycleEvents {
    this.ensureSolved();
    return this.events as CycleEvents;
  }

  // ---- Internals -----------------------------------------------------------

  private ensureSolved(): void {
    if (this.beat.length === 0 || this.events === null || this.metrics === null) {
      this.runToSteadyState();
    }
  }

  private invalidate(): void {
    this.beat = [];
    this.events = null;
    this.metrics = null;
  }

  /** Initial volume distribution summing exactly to total blood volume. */
  private initialVolumes(): Volumes {
    const p = this.params;
    const guess: Volumes = {
      LA: 50,
      LV: 120,
      SysArt: p.sysArt.v0 + 150,
      SysVein: 0,
      RA: 50,
      RV: 120,
      PulArt: p.pulArt.v0 + 60,
      PulVein: p.pulVein.v0 + 60,
    };
    let sum = 0;
    for (const c of COMPARTMENTS) if (c !== 'SysVein') sum += guess[c];
    guess.SysVein = p.totalBloodVolume - sum;
    return guess;
  }

  /** Integrate one beat from the converged state, storing ~1000 snapshots. */
  private recordBeat(stepsPerBeat: number, dt: number, dPhase: number): void {
    const p = this.params;
    const stride = Math.max(1, Math.floor(stepsPerBeat / 1000));
    this.beat = [];
    let v = this.volumes;
    for (let i = 0; i < stepsPerBeat; i++) {
      const phase = i / stepsPerBeat;
      if (i % stride === 0) this.beat.push({ phase, volumes: { ...v } });
      v = rk4Step(v, p, dt, phase, dPhase);
    }
    this.volumes = v; // ≈ phase-0 state, ready for the live path
  }

  /** Nearest recorded snapshot to `phase` (0 → 1). */
  private recordAt(phase: number): { phase: number; volumes: Volumes } {
    const n = this.beat.length;
    const idx = clamp(Math.round(phase * n), 0, n - 1);
    return this.beat[idx] ?? { phase, volumes: this.volumes };
  }

  private computeEvents(): CycleEvents {
    const valve = {} as Record<Valve, { open: number; close: number }>;
    for (const v of ['mitral', 'aortic', 'tricuspid', 'pulmonary'] as Valve[]) {
      valve[v] = { open: 0, close: 0 };
    }

    const found = {
      mitral: { open: false, close: false },
      aortic: { open: false, close: false },
      tricuspid: { open: false, close: false },
      pulmonary: { open: false, close: false },
    } as Record<Valve, { open: boolean; close: boolean }>;

    let prev: Record<Valve, boolean> | null = null;
    for (const record of this.beat) {
      const { valveOpen } = derive(record.volumes, this.params, record.phase);
      if (prev) {
        for (const v of ['mitral', 'aortic', 'tricuspid', 'pulmonary'] as Valve[]) {
          if (!prev[v] && valveOpen[v] && !found[v].open) {
            valve[v].open = record.phase;
            found[v].open = true;
          }
          if (prev[v] && !valveOpen[v] && !found[v].close) {
            valve[v].close = record.phase;
            found[v].close = true;
          }
        }
      }
      prev = { ...valveOpen };
    }

    return {
      valve,
      s1Phase: valve.mitral.close, // AV-valve closure ("lub")
      s2Phase: valve.aortic.close, // semilunar closure ("dub")
      phaseStart: {
        'atrial-systole': 0,
        'isovolumetric-contraction': valve.mitral.close,
        ejection: valve.aortic.open,
        'isovolumetric-relaxation': valve.aortic.close,
        filling: valve.mitral.open,
      },
    };
  }

  private computeMetrics(): CycleMetrics {
    const T = this.params.cycleLength;
    let minLV = Infinity;
    let maxLV = -Infinity;
    let peakLV = -Infinity;
    let aoSys = -Infinity;
    let aoDia = Infinity;
    let peakRV = -Infinity;
    let paSys = -Infinity;
    let paDia = Infinity;
    let sumLA = 0;
    let sumRA = 0;

    for (const record of this.beat) {
      const { pressures } = derive(record.volumes, this.params, record.phase);
      const lv = record.volumes.LV;
      if (lv < minLV) minLV = lv;
      if (lv > maxLV) maxLV = lv;
      if (pressures.LV > peakLV) peakLV = pressures.LV;
      if (pressures.SysArt > aoSys) aoSys = pressures.SysArt;
      if (pressures.SysArt < aoDia) aoDia = pressures.SysArt;
      if (pressures.RV > peakRV) peakRV = pressures.RV;
      if (pressures.PulArt > paSys) paSys = pressures.PulArt;
      if (pressures.PulArt < paDia) paDia = pressures.PulArt;
      sumLA += pressures.LA;
      sumRA += pressures.RA;
    }

    const n = this.beat.length || 1;
    const edv = maxLV;
    const esv = minLV;
    const strokeVolume = edv - esv;
    const heartRateBpm = 60 / T;

    return {
      edv,
      esv,
      strokeVolume,
      ejectionFraction: strokeVolume / edv,
      peakLVPressure: peakLV,
      aorticSystolic: aoSys,
      aorticDiastolic: aoDia,
      meanLAPressure: sumLA / n,
      peakRVPressure: peakRV,
      pulmonarySystolic: paSys,
      pulmonaryDiastolic: paDia,
      meanRAPressure: sumRA / n,
      heartRateBpm,
      cycleLengthSeconds: T,
      cardiacOutput: (strokeVolume * heartRateBpm) / 1000,
    };
  }

  /** Assemble a full EngineState frame from raw volumes at a cycle phase. */
  private buildState(volumes: Volumes, cyclePhase: number): EngineState {
    const { pressures, activation, valveFlow, valveOpen } = derive(
      volumes,
      this.params,
      cyclePhase,
    );

    const valves = {} as Record<Valve, ValveState>;
    for (const v of ['mitral', 'aortic', 'tricuspid', 'pulmonary'] as Valve[]) {
      valves[v] = {
        open: valveOpen[v],
        openFraction: valveOpen[v] ? 1 : 0,
        flow: valveFlow[v],
      };
    }

    const ev = this.events as CycleEvents;
    return {
      time: this.time,
      cyclePhase,
      phase: this.classifyPhase(cyclePhase, ev, valveOpen),
      volumes: { ...volumes },
      pressures,
      valves,
      activation: activation as Record<ActiveChamber, number>,
      electricalWave: electricalWaveAt(cyclePhase, this.params.avDelay, this.params.cycleLength),
      markers: {
        s1: phaseNear(cyclePhase, ev.s1Phase),
        s2: phaseNear(cyclePhase, ev.s2Phase),
      },
    };
  }

  /**
   * Classify the phase from the *actual* left-valve state (so the label always
   * agrees with the reported valve booleans), using the aortic-open event only
   * to tell the pre-ejection sealed phase from the post-ejection one.
   */
  private classifyPhase(
    phase: number,
    ev: CycleEvents,
    valveOpen: Record<Valve, boolean>,
  ): CardiacPhase {
    const beforeEjection = phase < ev.valve.aortic.open;
    if (valveOpen.aortic) return 'ejection';
    if (valveOpen.mitral) return beforeEjection ? 'atrial-systole' : 'filling';
    return beforeEjection ? 'isovolumetric-contraction' : 'isovolumetric-relaxation';
  }
}

/** True when `phase` is within the marker window of `target` (wrap-aware). */
function phaseNear(phase: number, target: number): boolean {
  let d = Math.abs(phase - target);
  d = Math.min(d, 1 - d);
  return d <= MARKER_WINDOW;
}

/**
 * Map a cycle phase onto the electrical wave: per-landmark excitation, plus the
 * leading edge of the front for consumers that want a single answer.
 *
 * The front is the furthest-along segment that has already started, so it stays
 * meaningful when segments overlap at a short AV delay.
 */
function electricalWaveAt(
  phase: number,
  avDelaySeconds: number,
  cycleLength: number,
): ElectricalWaveState {
  const schedule = conductionSchedule(avDelaySeconds, cycleLength);
  const tailPhase = CONDUCTION_TAIL_SECONDS / cycleLength;
  const n = schedule.length;

  const levels = {} as Record<ConductionLandmark, number>;
  let frontIndex = 0;
  for (let i = 0; i < n; i++) {
    const seg = schedule[i] as ConductionSegment;
    levels[seg.landmark] = clamp(excitationAt(phase, seg, tailPhase), 0, 1);
    if (phase >= seg.start) frontIndex = i;
  }

  const front = schedule[frontIndex] as ConductionSegment;
  const span = front.end - front.start;
  const segmentProgress = span > 1e-9 ? clamp((phase - front.start) / span, 0, 1) : 1;
  // After the last landmark the front sits at the end of the path: the ventricles
  // are fully activated for the rest of the beat (repolarisation is out of scope).
  return {
    progress: clamp((frontIndex + segmentProgress) / n, 0, 1),
    landmark: front.landmark,
    segmentProgress,
    levels,
  };
}

/** Thrown only by not-yet-built surfaces (none remain in the core solver). */
export class NotImplementedError extends Error {
  constructor(what: string) {
    super(`${what} is not implemented yet.`);
    this.name = 'NotImplementedError';
  }
}
