import * as THREE from 'three';

/**
 * Blood dots inside the left ventricle (SPEC §6 §7, the rework) — the pump's blood
 * made visible so you can just watch where it goes. They replace the abstract
 * pressure arrows.
 *
 * The motion is a real cardiac read, not random jitter:
 *  - FILLING (mitral open): dots stream IN from the mitral doorway and settle into a
 *    swirling vortex — the LV genuinely fills with a diastolic vortex. The visible
 *    dot count rises with LV volume, so you literally watch it fill.
 *  - SEALED (both shut): the dots have nowhere to go — they circle in place, packing
 *    tighter and speeding up as the pressure climbs. Trapped.
 *  - EJECTION (aortic open): dots stream OUT the aortic doorway; the count falls with
 *    the emptying volume.
 *
 * Driven each frame from the clock sample: `update(dt, {fill01, pressure01,
 * aorticOpen, mitralOpen})`. A single THREE.Points cloud with a small custom shader
 * so each droplet is a distinct glowing core that can fade in/out smoothly.
 */
export interface TrappedBloodOptions {
  /** LV cavity centre (world), with the ventricular wall relaxed. */
  center: THREE.Vector3;
  /**
   * Where that centre has travelled to once the wall is fully contracted — measured
   * from the wall's own morph, see `CavitySpec.centerSystole`. Omit and the cloud stays
   * put, which is what made the blood slide out through the muscle: the wall genuinely
   * contracts now, and anything living inside the chamber has to be carried by it.
   */
  centerSystole?: THREE.Vector3;
  /** Cloud radius at rest (world units). */
  radius: number;
  /** LV→aorta exit direction (unit) — where dots stream out in ejection. */
  aorticDir: THREE.Vector3;
  /** LV→LA direction (unit) — the mitral doorway dots stream in from. */
  mitralDir: THREE.Vector3;
  count?: number;
  color?: string;
  /** Pixel-size scale for a droplet (gl_PointSize = perDotSize · scale / depth). */
  sizeScale?: number;
  /**
   * Opacity multiplier for dots that are swirling *inside* the chamber (as opposed
   * to streaming through an open valve). Default 1 = the full in-chamber vortex, which
   * is what the sealed-ventricle view wants ("trapped, nowhere to go").
   *
   * A section that shows chamber volume some other way — e.g. "the doors open" uses a
   * `LiquidVolume` body for the blood in the cavity — can turn this down so the dots
   * stop competing with it and read purely as FLOW THROUGH THE DOORWAY.
   */
  chamberAlpha?: number;
}

type Mode = 0 | 1 | 2 | 3; // 0 parked · 1 active(swirl) · 2 entering · 3 exiting

interface Dot {
  ox: number; oy: number; oz: number; // offset from centre
  pr: number;   // preferred planar (perp-to-axis) orbit radius
  mode: Mode;
  size: number; // per-dot base size (distinctness)
  alpha: number;
}

function makeRng(seed: number): () => number {
  let s = seed >>> 0;
  return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 0xffffffff; };
}

const VERT = /* glsl */ `
  attribute float aAlpha;
  attribute float aSize;
  varying float vAlpha;
  uniform float uScale;
  void main() {
    vAlpha = aAlpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * uScale / max(0.001, -mv.z);
    gl_Position = projectionMatrix * mv;
  }
`;
const FRAG = /* glsl */ `
  precision mediump float;
  uniform vec3 uColor;
  varying float vAlpha;
  void main() {
    vec2 c = gl_PointCoord - 0.5;
    float d = length(c);
    float mask = smoothstep(0.5, 0.16, d);   // soft round edge
    float core = smoothstep(0.32, 0.0, d);   // subtle bright centre → distinct droplet
    vec3 col = uColor + core * 0.28;
    gl_FragColor = vec4(col, mask * vAlpha * 0.92);
    if (gl_FragColor.a < 0.01) discard;
  }
`;

export class TrappedBlood {
  readonly points: THREE.Points;

  /** Live cavity centre — lerped between the two wall poses every frame, not a constant. */
  private readonly center = new THREE.Vector3();
  private readonly centerDiastole: THREE.Vector3;
  private readonly centerSystole: THREE.Vector3;
  private wall = 0;
  private readonly baseRadius: number;
  private readonly aortic: THREE.Vector3;    // LV→aorta (out)
  private readonly inflow: THREE.Vector3;     // LA→LV (in), = -mitralDir
  private readonly axis: THREE.Vector3;       // vortex spin axis
  private readonly inletDir: THREE.Vector3;   // LV→LA (where the mitral doorway sits)
  private readonly dots: Dot[] = [];
  private readonly N: number;
  private readonly positions: Float32Array;
  private readonly alphas: Float32Array;
  private readonly sizes: Float32Array;
  private readonly geom: THREE.BufferGeometry;
  private readonly mat: THREE.ShaderMaterial;
  private readonly rng: () => number;
  private readonly sizeScale: number;
  private chamberAlpha: number;
  private streamTimer = 0;

  // scratch
  private readonly v = new THREE.Vector3();
  private readonly kxv = new THREE.Vector3();

  constructor(opts: TrappedBloodOptions) {
    this.centerDiastole = opts.center.clone();
    this.centerSystole = (opts.centerSystole ?? opts.center).clone();
    this.center.copy(this.centerDiastole);
    this.baseRadius = opts.radius;
    this.aortic = opts.aorticDir.clone().normalize();
    this.inletDir = opts.mitralDir.clone().normalize();       // LV→LA
    this.inflow = this.inletDir.clone().negate();              // LA→LV
    // Vortex axis ⟂ to the inflow/outflow plane → a swirl you read side-on.
    this.axis = new THREE.Vector3().crossVectors(this.aortic, this.inflow).normalize();
    if (this.axis.lengthSq() < 1e-6) this.axis.set(0, 0, 1);
    this.rng = makeRng(0x9e3779b9);

    this.sizeScale = opts.sizeScale ?? 60;
    this.chamberAlpha = opts.chamberAlpha ?? 1;
    this.N = opts.count ?? 56;
    this.positions = new Float32Array(this.N * 3);
    this.alphas = new Float32Array(this.N);
    this.sizes = new Float32Array(this.N);
    for (let i = 0; i < this.N; i++) {
      const d: Dot = { ox: 0, oy: 0, oz: 0, pr: 0, mode: 1, size: 0, alpha: 1 };
      this.placeInside(d);
      d.size = 0.8 + 0.5 * this.rng(); // small per-dot multiplier (distinctness)
      this.dots.push(d);
    }

    this.geom = new THREE.BufferGeometry();
    this.geom.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    this.geom.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
    this.geom.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
    this.mat = new THREE.ShaderMaterial({
      vertexShader: VERT,
      fragmentShader: FRAG,
      uniforms: {
        uColor: { value: new THREE.Color(opts.color ?? '#ff4436') },
        uScale: { value: 1.0 },
      },
      transparent: true,
      depthWrite: false,
      depthTest: true,
      blending: THREE.NormalBlending, // overlapping droplets stay DISTINCT (don't sum to white)
    });
    this.points = new THREE.Points(this.geom, this.mat);
    this.points.frustumCulled = false;
    this.points.visible = false;
    this.writeAll();
  }

  private placeInside(d: Dot): void {
    // Random point biased to a shell so they read as an orbiting vortex, not a blob.
    const pr = this.baseRadius * (0.35 + 0.6 * this.rng());
    const ang = this.rng() * Math.PI * 2;
    const along = (this.rng() * 2 - 1) * this.baseRadius * 0.6;
    // Build an in-plane basis ⟂ to axis.
    const e1 = new THREE.Vector3(1, 0, 0);
    if (Math.abs(this.axis.x) > 0.9) e1.set(0, 1, 0);
    e1.crossVectors(this.axis, e1).normalize();
    const e2 = new THREE.Vector3().crossVectors(this.axis, e1);
    d.ox = e1.x * Math.cos(ang) * pr + e2.x * Math.sin(ang) * pr + this.axis.x * along;
    d.oy = e1.y * Math.cos(ang) * pr + e2.y * Math.sin(ang) * pr + this.axis.y * along;
    d.oz = e1.z * Math.cos(ang) * pr + e2.z * Math.sin(ang) * pr + this.axis.z * along;
    d.pr = pr;
    d.mode = 1;
    d.alpha = 1;
  }

  /** Rotate a dot's offset around the vortex axis (Rodrigues) — coherent swirl. */
  private swirl(d: Dot, angle: number): void {
    this.v.set(d.ox, d.oy, d.oz);
    const c = Math.cos(angle), s = Math.sin(angle);
    this.kxv.crossVectors(this.axis, this.v);
    const kdotv = this.axis.dot(this.v);
    d.ox = this.v.x * c + this.kxv.x * s + this.axis.x * kdotv * (1 - c);
    d.oy = this.v.y * c + this.kxv.y * s + this.axis.y * kdotv * (1 - c);
    d.oz = this.v.z * c + this.kxv.z * s + this.axis.z * kdotv * (1 - c);
  }

  private countVisible(): number {
    let n = 0;
    for (const d of this.dots) if (d.mode !== 0) n++;
    return n;
  }

  private enterFromMitral(d: Dot): void {
    // Spawn just outside the mitral doorway, drift inward into the swirl.
    const jitter = this.baseRadius * 0.25;
    d.ox = this.inletDir.x * this.baseRadius * 1.25 + (this.rng() - 0.5) * jitter;
    d.oy = this.inletDir.y * this.baseRadius * 1.25 + (this.rng() - 0.5) * jitter;
    d.oz = this.inletDir.z * this.baseRadius * 1.25 + (this.rng() - 0.5) * jitter;
    d.pr = this.baseRadius * (0.4 + 0.5 * this.rng());
    d.mode = 2;
    d.alpha = 0;
  }

  /**
   * Advance the flow. `fill01` (0 at ESV → 1 at EDV) sets how many dots are in the
   * chamber; `pressure01` tightens + speeds the sealed swirl; the valve flags open a
   * doorway so dots stream in (mitral) or out (aortic).
   */
  update(
    dt: number,
    s: {
      fill01: number;
      pressure01: number;
      aorticOpen: boolean;
      mitralOpen: boolean;
      /**
       * How far the ventricular wall is through its contraction (0 → 1) — the rig's own
       * morph weight, via `HeartScene.getWallInfluence()`. The dots live inside the
       * chamber, so the muscle has to carry them.
       */
      wall01?: number;
    },
  ): void {
    if (!this.points.visible) return;
    const p = THREE.MathUtils.clamp(s.pressure01, 0, 1);
    this.wall = THREE.MathUtils.lerp(this.wall, THREE.MathUtils.clamp(s.wall01 ?? 0, 0, 1), Math.min(1, dt * 9));
    this.center.lerpVectors(this.centerDiastole, this.centerSystole, this.wall);
    const fill = THREE.MathUtils.clamp(s.fill01, 0, 1);
    const effR = this.baseRadius * (1 - 0.26 * p);
    const along = effR * 0.62;
    const omega = (0.7 + 1.3 * p) * dt; // swirl speed rises with pressure
    const minVisible = 8;
    const targetVisible = Math.round(THREE.MathUtils.lerp(minVisible, this.N, fill));

    // Grow/shrink the visible pool toward the volume, streaming through the open door.
    this.streamTimer -= dt;
    if (this.streamTimer <= 0) {
      this.streamTimer = 0.035;
      const vis = this.countVisible();
      if (vis < targetVisible && s.mitralOpen) {
        const parked = this.dots.find((d) => d.mode === 0);
        if (parked) this.enterFromMitral(parked);
      } else if (vis > targetVisible && s.aorticOpen) {
        // Send the active dot nearest the aortic outlet out the door.
        let best: Dot | null = null; let bestProj = -Infinity;
        for (const d of this.dots) {
          if (d.mode !== 1) continue;
          const proj = d.ox * this.aortic.x + d.oy * this.aortic.y + d.oz * this.aortic.z;
          if (proj > bestProj) { bestProj = proj; best = d; }
        }
        if (best) best.mode = 3;
      }
    }

    const exitSpeed = 2.4;
    const exitDist = this.baseRadius * 3.0;
    const enterSpeed = 1.8;

    for (const d of this.dots) {
      if (d.mode === 0) { d.alpha = 0; continue; }

      if (d.mode === 3) { // exiting up the aorta
        d.ox += this.aortic.x * exitSpeed * dt;
        d.oy += this.aortic.y * exitSpeed * dt;
        d.oz += this.aortic.z * exitSpeed * dt;
        const dist = Math.hypot(d.ox, d.oy, d.oz);
        d.alpha = THREE.MathUtils.clamp((exitDist - dist) / (exitDist - effR), 0, 1);
        if (dist > exitDist) { d.mode = 0; d.alpha = 0; }
        continue;
      }

      if (d.mode === 2) { // entering from the mitral, easing into the swirl
        d.ox += this.inflow.x * enterSpeed * dt;
        d.oy += this.inflow.y * enterSpeed * dt;
        d.oz += this.inflow.z * enterSpeed * dt;
        d.alpha = Math.min(1, d.alpha + dt * 3);
        this.swirl(d, omega * 0.6);
        if (Math.hypot(d.ox, d.oy, d.oz) < effR * 0.85) d.mode = 1;
        continue;
      }

      // Active: coherent swirl + a gentle spring back to the preferred orbit radius,
      // contained within the (pressure-tightened) sealed walls.
      this.swirl(d, omega);
      // planar radius (perp to axis)
      const adot = d.ox * this.axis.x + d.oy * this.axis.y + d.oz * this.axis.z;
      let px = d.ox - this.axis.x * adot, py = d.oy - this.axis.y * adot, pz = d.oz - this.axis.z * adot;
      let pr = Math.hypot(px, py, pz);
      const targetPr = Math.min(d.pr, effR);
      if (pr > 1e-4) {
        const k = THREE.MathUtils.lerp(pr, targetPr, Math.min(1, dt * 2.5)) / pr;
        px *= k; py *= k; pz *= k; pr *= k;
      }
      const clampedAlong = THREE.MathUtils.clamp(adot, -along, along);
      d.ox = px + this.axis.x * clampedAlong;
      d.oy = py + this.axis.y * clampedAlong;
      d.oz = pz + this.axis.z * clampedAlong;
      d.alpha = Math.min(1, d.alpha + dt * 3);
    }

    this.writeAll();
    (this.mat.uniforms.uScale as { value: number }).value = this.sizeScale;
  }

  private writeAll(): void {
    const pos = this.positions, al = this.alphas, sz = this.sizes;
    for (let i = 0; i < this.dots.length; i++) {
      const d = this.dots[i]!;
      pos[i * 3] = this.center.x + d.ox;
      pos[i * 3 + 1] = this.center.y + d.oy;
      pos[i * 3 + 2] = this.center.z + d.oz;
      // Dots swirling inside the chamber (mode 1) can be dialled down so a section
      // showing cavity volume as liquid keeps the dots reading as doorway FLOW only.
      al[i] = d.mode === 1 ? d.alpha * this.chamberAlpha : d.alpha;
      sz[i] = d.size;
    }
    (this.geom.getAttribute('position') as THREE.BufferAttribute).needsUpdate = true;
    (this.geom.getAttribute('aAlpha') as THREE.BufferAttribute).needsUpdate = true;
    (this.geom.getAttribute('aSize') as THREE.BufferAttribute).needsUpdate = true;
  }

  /** Live-tune the in-chamber dot opacity (see `chamberAlpha`). */
  setChamberAlpha(a: number): void {
    this.chamberAlpha = THREE.MathUtils.clamp(a, 0, 1);
  }

  show(): void { this.points.visible = true; }
  hide(): void { this.points.visible = false; }

  dispose(): void {
    this.geom.dispose();
    this.mat.dispose();
  }
}
