import * as THREE from 'three';
import type { HeartScene } from '../index.ts';

/**
 * Chamber labels (SPEC §2 "The four chambers"). Crisp DOM tags pinned to
 * world-space points on the heart, following the hybrid overlay approach
 * (project a 3D anchor to screen each frame, like the manometer readouts).
 *
 * The multi-view mechanic: no single view shows all four chambers — the left
 * atrium sits at the back and the right ventricle wraps the front. So each label
 * carries an OUTWARD normal, and its opacity tracks how squarely that face turns
 * toward the camera. Orbit the heart and the front tags (RA/RV/LV) fade as you
 * turn away while the left-atrium tag rises into view around the back. Honest
 * about the anatomy: you have to turn the heart to meet all four.
 *
 * Right heart = venous blue, left heart = arterial red (the §1 through-line).
 */
export interface ChamberLabelSpec {
  /** Full chamber name, e.g. "Left ventricle". */
  name: string;
  /** Optional plain-language descriptor shown small under the name. */
  sublabel?: string;
  /** World-space point the tag pins to (on the chamber's surface). */
  anchor: [number, number, number];
  /** Outward surface normal (world) — the tag shows when this faces the camera. */
  normal: [number, number, number];
  /** Leader-dot colour (CSS). Right heart blue, left heart red. */
  accent: string;
}

interface Label {
  spec: ChamberLabelSpec;
  anchor: THREE.Vector3;
  normal: THREE.Vector3;
  el: HTMLDivElement;
}

export class ChamberLabels {
  private readonly scene: HeartScene;
  private readonly dom: HTMLDivElement;
  private readonly labels: Label[] = [];
  private unframe: (() => void) | null = null;
  private visible = false;
  /** Wall-clock time show() was called, for the entrance fade (time-based so it is
   *  robust to frame count / headless virtual time). */
  private showAt = 0;

  constructor(scene: HeartScene, specs: ChamberLabelSpec[]) {
    this.scene = scene;

    this.dom = document.createElement('div');
    this.dom.className = 'chamber-label-layer';
    this.dom.style.cssText =
      'position:fixed;inset:0;pointer-events:none;z-index:5;display:none';
    document.body.appendChild(this.dom);

    for (const spec of specs) {
      const el = document.createElement('div');
      el.style.cssText =
        'position:absolute;display:flex;align-items:center;gap:8px;white-space:nowrap;' +
        'transform:translate(0,-50%);will-change:left,top,opacity';
      el.innerHTML =
        `<span style="flex:0 0 auto;width:10px;height:10px;border-radius:50%;` +
        `background:${spec.accent};box-shadow:0 0 10px ${spec.accent},0 0 3px #fff"></span>` +
        `<span style="display:block;padding:5px 11px 6px;border-radius:8px;` +
        `background:rgba(10,7,6,.6);backdrop-filter:blur(3px);` +
        `border:1px solid ${spec.accent}66;box-shadow:0 4px 14px rgba(0,0,0,.5)">` +
        `<span style="display:block;color:#f7f1ea;font:600 15px/1.15 var(--font-display,Georgia,serif);` +
        `letter-spacing:.01em">${spec.name}</span>` +
        (spec.sublabel
          ? `<span style="display:block;margin-top:2px;color:#f7f1ea;opacity:.72;` +
            `font:400 10.5px/1.3 var(--font-body,sans-serif);letter-spacing:.02em">${spec.sublabel}</span>`
          : '') +
        `</span>`;
      this.dom.appendChild(el);
      this.labels.push({
        spec,
        anchor: new THREE.Vector3(...spec.anchor),
        normal: new THREE.Vector3(...spec.normal).normalize(),
        el,
      });
    }
  }

  show(): void {
    if (this.visible) return;
    this.visible = true;
    this.showAt = performance.now();
    this.dom.style.display = 'block';
    this.unframe = this.scene.onFrame(() => this.update());
    this.update();
  }

  hide(): void {
    if (!this.visible) return;
    this.visible = false;
    this.dom.style.display = 'none';
    this.unframe?.();
    this.unframe = null;
  }

  private update(): void {
    // Ease the master reveal in (≈0.6s) so tags fade up on entrance.
    const reveal = THREE.MathUtils.clamp((performance.now() - this.showAt) / 600, 0, 1);

    const camera = this.scene.camera;
    const canvas = this.scene.renderer.domElement;
    const rect = canvas.getBoundingClientRect();
    const ndc = new THREE.Vector3();
    const toCam = new THREE.Vector3();

    for (const lbl of this.labels) {
      // How squarely this face turns toward the camera (1 = dead-on, <0 = away).
      toCam.copy(camera.position).sub(lbl.anchor).normalize();
      const facing = lbl.normal.dot(toCam);
      // Fade in over a generous arc so a chamber reads well before it's dead-on,
      // and fades out as it rotates to the far side.
      const faceFade = THREE.MathUtils.smoothstep(facing, 0.0, 0.45);

      ndc.copy(lbl.anchor).project(camera);
      const behind = ndc.z > 1;
      const opacity = behind ? 0 : faceFade * reveal;
      lbl.el.style.opacity = `${opacity}`;
      if (opacity < 0.01) {
        lbl.el.style.display = 'none';
        continue;
      }
      lbl.el.style.display = 'flex';
      lbl.el.style.left = `${rect.left + (ndc.x * 0.5 + 0.5) * rect.width}px`;
      lbl.el.style.top = `${rect.top + (-ndc.y * 0.5 + 0.5) * rect.height}px`;
    }
  }

  dispose(): void {
    this.hide();
    this.dom.remove();
  }
}
