import type { EngineParams, KnobRange, Knobs } from './types.ts';
import { ANCHORS } from './anchors.ts';

/**
 * Reader-facing knob ranges (PHYSICS.md §6). Every reader input is clamped to
 * these bounds so no interaction can drive the model out of physiological
 * range. Defaults sit at the resting operating point.
 *
 * NOTE: these are the *interaction* clamps. The solver coefficients that make
 * the default operating point actually land on the §7 anchors are tuned when
 * the ODE integration is implemented (Phase 1 proper) — the numbers below are
 * plausible starting points, not final-tuned values.
 */
export const KNOB_RANGES: Record<keyof Knobs, KnobRange> = {
  // LV end-systolic elastance E_es, mmHg/mL.
  contractility: { min: 1.0, max: 6.0, default: 2.8 },
  // Mean systemic-venous filling pressure, mmHg.
  preload: { min: 2, max: 12, default: 7 },
  // Systemic vascular resistance R_sys, mmHg·s/mL.
  afterload: { min: 0.6, max: 1.6, default: 1.0 },
  // Heart rate, bpm (T = 60 / HR → 0.6–1.0 s, matching the §7 cycle range).
  heartRate: {
    min: ANCHORS.heartRateBpm.min,
    max: ANCHORS.heartRateBpm.max,
    default: ANCHORS.heartRateBpm.target,
  },
  // AV conduction delay (the PR interval), seconds. Default 0.16 s sits mid-band
  // of the normal 0.12–0.20 s PR interval; 0.32 s is a marked delay.
  //
  // The floor is 0, below any real PR interval, and that is the point: SPEC §5's
  // control exists to show what the delay BUYS. At 0 the mitral shuts at cycle
  // phase 0.004, so the whole atrial contraction lands against a closed door —
  // measured EDV falls 119.3 → 111.5 mL and stroke volume 71.5 → 66.5 mL while
  // peak left-atrial pressure RISES 8.6 → 10.0 mmHg. The atrium works harder and
  // delivers less. See the §5 notes in HANDOFF.md for the full sweep.
  avDelay: { min: 0, max: 0.32, default: 0.16 },
};

export const DEFAULT_KNOBS: Knobs = {
  contractility: KNOB_RANGES.contractility.default,
  preload: KNOB_RANGES.preload.default,
  afterload: KNOB_RANGES.afterload.default,
  heartRate: KNOB_RANGES.heartRate.default,
  avDelay: KNOB_RANGES.avDelay.default,
};

/**
 * Default model parameters at the resting operating point.
 *
 * PROVISIONAL COEFFICIENTS. These are literature-plausible starting values to
 * fix the *shape* of the parameter set for review. Final tuning to hit the §7
 * anchors happens when the solver is implemented; the harness (engine.test.ts)
 * is what proves the tuning is correct.
 */
export const DEFAULT_PARAMS: EngineParams = {
  // Cycle phase 0 = atrial-systole onset. Atria fire first (start 0); the
  // ventricles fire after the AV delay (activationStart is recomputed as
  // avDelay/cycleLength so the delay stays fixed in seconds as HR changes).
  chambers: {
    // Left ventricle — full fidelity, the contractility knob lives on eMax.
    LV: {
      eMin: 0.06,
      eMax: KNOB_RANGES.contractility.default,
      v0: 5,
      activationStart: 0.2, // ≈ avDelay / cycleLength (0.16 / 0.8)
      activationDuration: 0.42,
    },
    // Left atrium — weak, fires first (the atrial kick).
    LA: {
      eMin: 0.16,
      eMax: 0.3,
      v0: 4,
      activationStart: 0.0,
      activationDuration: 0.17,
    },
    // Right ventricle — moderate, simplified.
    RV: {
      eMin: 0.05,
      eMax: 0.42,
      v0: 5,
      activationStart: 0.2,
      activationDuration: 0.42,
    },
    // Right atrium — weak, simplified.
    RA: {
      eMin: 0.14,
      eMax: 0.25,
      v0: 4,
      activationStart: 0.0,
      activationDuration: 0.17,
    },
  },

  // Systemic arteries — three-element Windkessel (PHYSICS.md §3).
  sysArt: {
    zc: 0.01,
    ca: 1.4,
    rSys: KNOB_RANGES.afterload.default,
    v0: 700,
  },
  // Systemic veins — large passive compliance, the preload reservoir.
  sysVein: { compliance: 100, v0: 2500 },
  // Pulmonary side — deliberately coarse (single compliance + resistance).
  pulArt: { compliance: 4.0, v0: 90 },
  pulVein: { compliance: 8.0, v0: 200 },

  valveResistance: 0.006,
  pulResistance: 0.08,
  venousReturnResistance: 0.025,
  pulVenousReturnResistance: 0.01,

  // Mirrors KNOB_RANGES.avDelay.default. The knob is the source of truth —
  // `applyKnobsToParams` writes this on every knob change — so do not tune the
  // delay here.
  avDelay: KNOB_RANGES.avDelay.default,
  cycleLength: 60 / KNOB_RANGES.heartRate.default, // 0.8 s at 75 bpm
  totalBloodVolume: 4850,

  dt: 0.0001, // 0.1 ms RK4 sub-step (PHYSICS.md §8)
};
