import * as THREE from 'three';
import type { BeatClock } from '../clock/index.ts';
import type { CardiacEngine, Valve } from '../engine/index.ts';

/**
 * Driven motion (BUILD_PLAN §3; MODEL_FIT.md Phase A): bind the anatomical
 * heart's morph targets to the engine, through the master clock.
 *
 * The purchased base model (3D4SCI) decomposes into ONE ventricular mesh and ONE
 * atrial mesh (plus the cutaway cover pieces), not four separate chambers — so we
 * drive a *pragmatic* beat rather than a per-chamber wall rig (see MODEL_FIT.md):
 *
 *  - A `ventricle_systole` morph (on the ventricular wall + the cover pieces'
 *    ventricular region) is driven by LV volume, normalized over the beat.
 *  - An `atrial_systole` morph (atrial wall + cover pieces' atrial region) is
 *    driven by LA volume. Ventricles and atria therefore contract in their own
 *    phases off the one clock.
 *  - Each valve mesh carries BOTH an `open` and a `closed` morph, harvested from
 *    the frames the anatomist actually sculpted them at (see
 *    `.work/build_heart_v3.py`). Their weights are the engine's valve open/close
 *    events, ramped so leaflets swing rather than snap.
 *
 * ⚠️ WHY TWO VALVE MORPHS AND NOT ONE. This used to be a single `closed` morph
 * whose zero meant "whatever the base pose is", and the base pose was silently
 * wrong: the model was baked at source frame 10, which is PEAK SYSTOLE, so the
 * mitral sat 1% open and the tricuspid 0% open — fully shut — and the rig then
 * treated that as the OPEN end of the travel. The AV valves therefore went from
 * shut to more-shut and never opened at all. Driving `open` and `closed`
 * explicitly means the rendered state no longer depends on what the base pose
 * happens to be, so the bug cannot come back if the model is ever re-exported.
 *
 * ONE HEART, ONE CLOCK made physical: the geometry reads the solver; it never
 * animates itself. Scrub the clock and the heart beats.
 */

/** Valve mesh (normalized name) → the engine valve it renders. */
const VALVE_BY_MESH: Record<string, Valve> = {
  aorticvalve: 'aortic',
  pulmonaryvalve: 'pulmonary',
  mitralvalve: 'mitral',
  tricuspidvalve: 'tricuspid',
};

/** Ramp width, in cycle phase, over which a valve swings open↔closed. */
const VALVE_RAMP = 0.04;

/**
 * Fraction closed (1) → open (0) at `phase`, given the valve's open/close event
 * phases. The valve is open on the cyclic interval [openP, closeP); we ramp in
 * and out over VALVE_RAMP and smoothstep it so motion eases at the ends.
 */
function valveClosedness(phase: number, openP: number, closeP: number): number {
  const cyc = (x: number): number => ((x % 1) + 1) % 1;
  const duration = cyc(closeP - openP);
  if (duration < 1e-6) return 1;
  const since = cyc(phase - openP);
  if (since >= duration) return 1;
  const rw = Math.min(VALVE_RAMP, duration / 2);
  let openness = Math.min(since / rw, (duration - since) / rw, 1);
  openness = openness * openness * (3 - 2 * openness);
  return 1 - openness;
}

// Normalize a mesh name to lowercase alphanumerics. GLTFLoader sanitizes node
// names (whitespace → underscore); stripping non-letters survives that and any
// re-export naming drift ("Aortic_valve" / "AorticValve" → "aorticvalve").
const normalize = (name: string): string => name.toLowerCase().replace(/[^a-z0-9]/g, '');

type ChamberDriver = 'ventricle' | 'atrium';

interface MorphBinding {
  mesh: THREE.Mesh;
  index: number;
  driver: ChamberDriver;
}

/** The two morph slots a valve mesh exposes. */
export interface ValveMorphs {
  openIndex: number;
  closedIndex: number;
}

interface ValveBinding extends ValveMorphs {
  mesh: THREE.Mesh;
  valve: Valve;
}

/**
 * Locate a valve mesh's `open`/`closed` morph slots, or null if it has neither.
 *
 * Shared so that a section driving a leaflet by hand (§4's diode rule) poses it
 * through exactly the same two morphs the rig uses, and cannot drift from it.
 */
export function findValveMorphs(mesh: THREE.Mesh): ValveMorphs | null {
  const dict = mesh.morphTargetDictionary;
  if (!dict || !mesh.morphTargetInfluences) return null;
  if (!('open' in dict) || !('closed' in dict)) return null;
  return { openIndex: dict['open'], closedIndex: dict['closed'] };
}

/**
 * Pose a valve at `closed` (0 open → 1 shut). The two weights are complementary,
 * so a mid-value blends the anatomist's open and shut sculpts and the leaflet
 * reads as mid-swing rather than as either extreme.
 */
export function setValvePose(mesh: THREE.Mesh, morphs: ValveMorphs, closed: number): void {
  const influences = mesh.morphTargetInfluences;
  if (!influences) return;
  const c = THREE.MathUtils.clamp(closed, 0, 1);
  influences[morphs.closedIndex] = c;
  influences[morphs.openIndex] = 1 - c;
}

export interface HeartBinding {
  unsubscribe: () => void;
  /** Diagnostics: what the traverse actually matched. */
  meshNames: string[];
  /** One label per bound chamber morph, e.g. ['ventricle','atrium',…]. */
  boundChambers: string[];
  boundLeaflets: number;
  sampleInfluence: () => number | null;
}

/**
 * The normalized contraction weight the rig drives a chamber's morph with, at an
 * arbitrary phase.
 *
 * ⚠️ THIS MUST STAY IN LOCKSTEP WITH `update()` BELOW — same normalization, same 200
 * samples. It exists because §6 needs the weight the atrium had at ONE past instant (the
 * moment its squeeze began) in order to freeze a reference pose there, and re-deriving
 * that normalization in a section would let the two drift apart silently. The rig keeps
 * its own cached min/max rather than calling this, because `update()` runs every frame
 * and this walks the beat; the shapes are deliberately identical so a change to one is
 * an obvious prompt to change the other.
 *
 * Weight 0 = the chamber at its fullest over the beat (relaxed), 1 = at its emptiest.
 */
export function contractionWeightAt(
  engine: CardiacEngine,
  chamber: 'LV' | 'LA',
  phase: number,
): number {
  const SAMPLES = 200;
  let min = Infinity;
  let max = -Infinity;
  for (let i = 0; i < SAMPLES; i++) {
    const v = engine.sample(i / SAMPLES).volumes[chamber];
    min = Math.min(min, v);
    max = Math.max(max, v);
  }
  const span = max - min;
  if (span <= 1e-6) return 0;
  return THREE.MathUtils.clamp((max - engine.sample(phase).volumes[chamber]) / span, 0, 1);
}

export function bindHeartToClock(heart: THREE.Group, clock: BeatClock): HeartBinding {
  const morphs: MorphBinding[] = [];
  const valves: ValveBinding[] = [];
  const meshNames: string[] = [];

  heart.traverse((obj) => {
    const mesh = obj as THREE.Mesh;
    if (!mesh.isMesh) return;
    meshNames.push(mesh.name);
    const dict = mesh.morphTargetDictionary;
    if (!dict || !mesh.morphTargetInfluences) return;

    if ('ventricle_systole' in dict) {
      morphs.push({ mesh, index: dict['ventricle_systole'], driver: 'ventricle' });
    }
    if ('atrial_systole' in dict) {
      morphs.push({ mesh, index: dict['atrial_systole'], driver: 'atrium' });
    }

    const valve = VALVE_BY_MESH[normalize(mesh.name)];
    const valveMorphs = valve ? findValveMorphs(mesh) : null;
    if (valve && valveMorphs) {
      valves.push({ mesh, valve, ...valveMorphs });
    }
  });

  // Normalize each contraction against its chamber's own volume range over one
  // beat: end-diastole (max volume) → weight 0 (relaxed), end-systole (min) → 1.
  const engine = clock.getEngine();
  let lvMin = Infinity, lvMax = -Infinity, laMin = Infinity, laMax = -Infinity;
  const SAMPLES = 200;
  for (let i = 0; i < SAMPLES; i++) {
    const s = engine.sample(i / SAMPLES);
    lvMin = Math.min(lvMin, s.volumes.LV); lvMax = Math.max(lvMax, s.volumes.LV);
    laMin = Math.min(laMin, s.volumes.LA); laMax = Math.max(laMax, s.volumes.LA);
  }
  const lvSpan = lvMax - lvMin;
  const laSpan = laMax - laMin;

  let lastVentW = 0;
  const update = (): void => {
    const state = clock.sample();
    const ventW = lvSpan > 1e-6 ? THREE.MathUtils.clamp((lvMax - state.volumes.LV) / lvSpan, 0, 1) : 0;
    const atrW = laSpan > 1e-6 ? THREE.MathUtils.clamp((laMax - state.volumes.LA) / laSpan, 0, 1) : 0;
    lastVentW = ventW;

    for (const m of morphs) {
      const influences = m.mesh.morphTargetInfluences;
      if (influences) influences[m.index] = m.driver === 'ventricle' ? ventW : atrW;
    }

    if (valves.length > 0) {
      const events = clock.getEvents();
      const phase = clock.getPhase();
      for (const v of valves) {
        const ev = events.valve[v.valve];
        setValvePose(v.mesh, v, valveClosedness(phase, ev.open, ev.close));
      }
    }
  };

  const unsubscribe = clock.subscribe(update);
  return {
    unsubscribe,
    meshNames,
    boundChambers: morphs.map((m) => m.driver),
    boundLeaflets: valves.length,
    sampleInfluence: () => lastVentW,
  };
}
