import * as THREE from 'three';
import type { HeartScene } from '../index.ts';

/**
 * The atrial wall lighting up as it contracts (SPEC §6, atrial systole).
 *
 * The atria already MOVE on the clock — `heartRig` drives the model's `atrial_systole`
 * morph from left-atrial volume — but that motion was flagged early as understated on
 * this model, and in a section whose entire subject is the atrium squeezing, "did that
 * just move?" is not good enough. This adds the other half of the read: the wall glows
 * as it works, driven by the solver's own normalized atrial activation.
 *
 * DRIVEN, NOT KEYFRAMED. The glow is `EngineState.activation.LA` — the same e_n(t)
 * twitch that generates the atrium's pressure in the elastance model. So the light IS
 * the contraction, not an animation timed to look like it: it rises and falls with the
 * solver, and it is dark for the ~89% of the beat when the atrium is passive.
 *
 * SPEC §6 also mentions the P wave firing here. That is deliberately NOT built: §5 owns
 * the electrical wave, the conduction path and the ECG, and two sections owning the same
 * visual is how a piece drifts. This shows only the muscle's own activation — which the
 * engine hands over as a plain number — and leaves the wave that triggers it to §5.
 *
 * WHY IT SWAPS THE MATERIAL RATHER THAN TINTING IT IN PLACE. The model ships ONE shared
 * PBR material across all twelve meshes (see heartModel.ts), so writing `emissive` on
 * the atria's material would light the ventricles, the valves and the great vessels too.
 * This takes a clone, hands it to the atrial mesh for as long as the section is on
 * screen, and puts the original reference back on the way out — the same
 * borrow-and-restore contract `InnerCap` is handled under. Textures are shared by
 * reference by `Material.clone()`, so the clone costs nothing.
 */

/**
 * How hard the wall glows at full activation.
 *
 * ⚠️ 0.22, down from 0.85 — and the first value was not merely "a bit bright", it broke
 * the section's realism outright. THIS MODEL'S ATRIAL TEXTURE IS A MAUVE-PURPLE, not the
 * red of the ventricles. Adding a red emissive on top of purple lands on hot magenta, so
 * at 0.85 the atrium turned into a saturated pink plastic mass that dominated the frame
 * and read as a UI highlight rather than as muscle — exactly the cartoon look the piece
 * exists to avoid. Diagnosed by comparing a frame with the glow lit against one at
 * ejection where activation is 0 and the wall shows its true mauve.
 *
 * At 0.22 the glow warms and lifts the wall as it works without moving its hue off the
 * anatomy. If it ever needs re-tuning, judge it against a frame where activation is zero
 * — the contraction has to read as the SAME tissue, brighter.
 */
const PEAK_INTENSITY = 0.22;

/** The glow colour — a warm arterial red, so a working atrium reads as muscle under
 *  load rather than as a highlighted UI element. Kept red rather than corrected toward
 *  the wall's mauve: at the low intensity above it warms correctly, and a mauve glow
 *  would read as the wall being lit from outside rather than working. */
const GLOW_COLOR = '#ff5a3c';

export interface AtrialGlowOptions {
  /**
   * Which mesh to borrow, by name. Defaults to the atria — §6's case, and the
   * reason the class is named for them.
   *
   * §5 reuses this same borrow-and-restore machinery for `Ventricles`, so that the
   * two conduction landmarks which DO have meshes can light as muscle while the
   * other four are carried by `ConductionPath`. Kept as an option rather than
   * split into a second class because the mechanism — clone the one shared PBR
   * material, drive `emissiveIntensity`, hand the original back on exit — is
   * identical, and duplicating it would mean two places to get the restore
   * contract wrong.
   *
   * ⚠️ Re-tune `intensity` per mesh. The atria's texture is mauve-purple and the
   * ventricles' is red, so the same emissive lands very differently on each (see
   * PEAK_INTENSITY below for how badly that went the first time).
   */
  match?: RegExp;
  /** Peak emissive intensity at full activation. */
  intensity?: number;
  /** Glow colour. */
  color?: string;
  /**
   * Make the atrial wall partly see-through while the section is on screen, so the
   * blood inside it can be seen. Off by default: it changes what the anatomy looks
   * like, which is an art call a section has to opt into.
   */
  translucency?: number;
}

interface Borrowed {
  mesh: THREE.Mesh;
  /** The material the mesh arrived with, put back verbatim on release. */
  original: THREE.Material | THREE.Material[];
  /** What gets handed over — shaped like `original` (single or array). */
  replacement: THREE.Material | THREE.Material[];
  /** The same clones, flat, for driving the glow. */
  clones: THREE.MeshStandardMaterial[];
}

export class AtrialGlow {
  private readonly borrowed: Borrowed[] = [];
  private readonly intensity: number;
  private readonly translucency: number;
  private held = false;
  /** Smoothed activation, so a scrub jump eases instead of strobing. */
  private lit = 0;

  constructor(scene: HeartScene, opts: AtrialGlowOptions = {}) {
    this.intensity = opts.intensity ?? PEAK_INTENSITY;
    this.translucency = opts.translucency ?? 0;
    const glow = new THREE.Color(opts.color ?? GLOW_COLOR);
    const match = opts.match ?? /atria/i;

    scene.scene.traverse((o) => {
      const mesh = o as THREE.Mesh;
      // `Atria` is a single mesh carrying BOTH atria, which suits §6: the two
      // atria contract together on the same activation, and showing only the left one
      // would quietly imply otherwise. `Ventricles` is likewise one mesh for both.
      if (!mesh.isMesh || !match.test(mesh.name)) return;

      const original = mesh.material;
      const list = Array.isArray(original) ? original : [original];
      const clones: THREE.MeshStandardMaterial[] = [];
      for (const m of list) {
        const c = (m as THREE.MeshStandardMaterial).clone();
        c.emissive = glow.clone();
        c.emissiveIntensity = 0;
        // Let the glow follow the albedo texture instead of washing the wall in flat
        // colour — the muscle keeps its surface detail while it lights up.
        if (c.map) c.emissiveMap = c.map;
        if (this.translucency > 0) {
          c.transparent = true;
          c.opacity = 1 - this.translucency;
          c.depthWrite = false;
          c.needsUpdate = true;
        }
        clones.push(c);
      }
      if (!clones.length) return;
      const replacement: THREE.Material | THREE.Material[] =
        Array.isArray(original) ? clones : (clones[0] as THREE.MeshStandardMaterial);
      this.borrowed.push({ mesh, original, replacement, clones });
    });
  }

  /** True if an atrial mesh was actually found — worth checking, since this binds by
   *  mesh name and the model's names have lied before. */
  get bound(): boolean {
    return this.borrowed.length > 0;
  }

  /** Hand the clones to the atrial mesh. Call on `enter`. */
  show(): void {
    if (this.held) return;
    this.held = true;
    for (const b of this.borrowed) b.mesh.material = b.replacement;
  }

  /** Give the shared heart its own material back, exactly as found. Call on `exit`. */
  hide(): void {
    if (!this.held) return;
    this.held = false;
    this.lit = 0;
    for (const b of this.borrowed) {
      b.mesh.material = b.original;
      for (const c of b.clones) c.emissiveIntensity = 0;
    }
  }

  /**
   * Drive the glow from the solver's normalized atrial activation (0 → 1).
   *
   * Eased rather than applied raw: the reader can jump the scrubber anywhere, and a step
   * from 0 to 1 between two frames reads as a flash rather than as a muscle contracting.
   */
  update(dt: number, activation01: number): void {
    if (!this.held) return;
    const target = THREE.MathUtils.clamp(activation01, 0, 1);
    // Toward a bright target fast (a twitch is quick), away from it more gently — the
    // asymmetry is how real muscle reads, and it keeps the afterglow from flickering.
    const rate = target > this.lit ? 14 : 6;
    this.lit = THREE.MathUtils.lerp(this.lit, target, Math.min(1, dt * rate));
    for (const b of this.borrowed) {
      for (const c of b.clones) c.emissiveIntensity = this.lit * this.intensity;
    }
  }

  dispose(): void {
    this.hide();
    for (const b of this.borrowed) for (const c of b.clones) c.dispose();
    this.borrowed.length = 0;
  }
}
