import type { ChamberParams } from './types.ts';

/**
 * The normalized activation function e_n(t) that shapes time-varying elastance
 * (PHYSICS.md §2). We use a smooth two-cosine "twitch": a raised-cosine rise to
 * a peak, then a raised-cosine fall back to zero, and zero outside the active
 * window. This is a standard, numerically robust elastance driver; the exact
 * shape is tuned so the model reproduces the §7 anchors, and the harness
 * validates the result regardless of the precise coefficients.
 *
 * `cyclePhase`, `activationStart`, and `activationDuration` are all fractions of
 * one beat (0 → 1). Activation may begin late in the cycle and wrap; we handle
 * the wrap so a chamber can, e.g., start its twitch at phase 0.95.
 */

/** Fraction of the active window spent rising to the peak (rest is the fall). */
const RISE_FRACTION = 0.5;

/** Normalized activation e_n ∈ [0, 1] at `cyclePhase` for one chamber's timing. */
export function normalizedActivation(
  cyclePhase: number,
  activationStart: number,
  activationDuration: number,
): number {
  if (activationDuration <= 0) return 0;

  // Time since this chamber's activation began, wrapped into [0, 1).
  let tau = cyclePhase - activationStart;
  tau -= Math.floor(tau); // modulo 1, robust for any sign

  if (tau >= activationDuration) return 0;

  const peak = RISE_FRACTION * activationDuration;
  if (tau <= peak) {
    return 0.5 * (1 - Math.cos((Math.PI * tau) / peak));
  }
  return 0.5 * (1 + Math.cos((Math.PI * (tau - peak)) / (activationDuration - peak)));
}

/**
 * Instantaneous elastance E(t) = E_min + (E_max − E_min)·e_n for one active
 * chamber, plus the activation value itself (which the scene/overlays surface).
 */
export function chamberElastance(
  params: ChamberParams,
  cyclePhase: number,
): { elastance: number; activation: number } {
  const activation = normalizedActivation(
    cyclePhase,
    params.activationStart,
    params.activationDuration,
  );
  return {
    elastance: params.eMin + (params.eMax - params.eMin) * activation,
    activation,
  };
}
